[33] = { ["key"] = "shadowfang_keep", ["order"] = { 2748, 2750, 2751, 2752, 2753, 2754, 2755 }, ["layout"] = "linear_with_side", ["alias"] = {  }, ["name"] = "Крепость Темного Клыка", ["events"] = { { ["id"] = "dm_shadowfang_keep_prolog", ["k"] = "prolog", ["trig"] = "prolog", ["track"] = { ["hash"] = "6e4cfb29", ["text"] = "Вы в Крепости Темного Клыка. Когда-то здесь жил барон Сильверлейн, и с этих стен его стража смотрела на Серебряный бор. Потом пришла Плеть, и верховный маг Аругал из Даларана решил, что против мертвецов нужны звери. Он призвал воргенов из иного мира — и не удержал их. Воргены растерзали людей барона, а сам Аругал повредился рассудком, назвал зверей своими детьми и сделал крепость их логовом.", ["duration"] = 32.5, ["cues"] = { { 0, "Вы в Крепости Тёмного Клыка." }, { 2.33, "Когда-то здесь жил барон Сильверлейн, и с этих стен его стража смотрела на Серебряный бор." }, { 9.78, "Потом пришла Плеть, и верховный маг Аругал из Даларана решил, что против мертвецов нужны звери." }, { 17.75, "Он призвал воргенов из иного мира — и не удержал их." }, { 22.11, "Воргены растерзали людей барона, а сам Аругал повредился рассудком, назвал зверей своими детьми и сделал крепость их логовом." } } } }, { ["id"] = "dm_shadowfang_keep_prolog_repeat", ["k"] = "prolog", ["trig"] = "repeat", ["track"] = { ["hash"] = "53f17eb0", ["text"] = "Снова Крепость Темного Клыка. Вой во дворе всё тот же — Аругал не устаёт звать новых детей.", ["duration"] = 8.2, ["cues"] = { { 0, "Снова Крепость Тёмного Клыка." }, { 2.77, "Вой во дворе всё тот же — Аругал не устаёт звать новых детей." } } } }, { ["q"] = 1098, ["prio"] = 0, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_shadowfang_keep_hook_1098", ["track"] = { ["hash"] = "aa991ab1", ["text"] = "Верховный палач Хадрик давно ждёт вестей от двух разведчиков — стражей смерти Адаманта и Винсента. Оба ушли в крепость и не вернулись. Ищите их в самом начале пути.", ["duration"] = 13.4, ["cues"] = { { 0, "Верховный палач Хадрик давно ждёт вестей от двух разведчиков — стражей смерти Адаманта и Винсента." }, { 8.05, "Оба ушли в крепость и не вернулись." }, { 11, "Ищите их в самом начале пути." } } } }, { ["q"] = 1014, ["prio"] = 1, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_shadowfang_keep_hook_1014", ["track"] = { ["hash"] = "6cf79121", ["text"] = "Далар Ткач Рассвета ждёт голову Аругала. Пока безумный маг жив, Серебряный бор не принадлежит Темной Госпоже.", ["duration"] = 9.4, ["cues"] = { { 0, "Далар Ткач Рассвета ждёт голову Аругала." }, { 3.63, "Пока безумный маг жив, Серебряный бор не принадлежит Тёмной Госпоже." } } } }, { ["q"] = 1013, ["prio"] = 2, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_shadowfang_keep_hook_1013", ["track"] = { ["hash"] = "d0affb4c", ["text"] = "Хранитель Бел'дугур мечтает о книге Ура — трудах даларанского мага об иных мирах. Она стоит где-то здесь, на одной из полок.", ["duration"] = 10.5, ["cues"] = { { 0, "Хранитель Бел'дугур мечтает о книге Ура — трудах даларанского мага об иных мирах." }, { 6.99, "Она стоит где-то здесь, на одной из полок." } } } }, { ["prio"] = 3, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_shadowfang_keep_hook_alliance", ["faction"] = "Alliance", ["track"] = { ["hash"] = "8eba2aa2", ["text"] = "Это земли Отрекшихся, Альянс, и спасибо от них не дождёшься. Но воргены Аругала не разбирают, чьё мясо рвать.", ["duration"] = 9.3, ["cues"] = { { 0, "Это земли Отрёкшихся, Альянс, и спасибо от них не дождёшься." }, { 5.2, "Но воргены Аругала не разбирают, чьё мясо рвать." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_shadowfang_keep_rethilgore_pull", ["enc"] = 2748, ["track"] = { ["hash"] = "794188ce", ["text"] = "Ретилгор, тюремщик Аругала и самый свирепый из стражей камер, рычит и бросается на вас. Когда-то эти коридоры охраняли люди барона. Теперь здесь сторожат звери, и сторожат по-звериному: тех, кому не повезло умереть сразу, держат за решёткой.", ["duration"] = 19.5, ["cues"] = { { 0, "Ретилгор, тюремщик Аругала и самый свирепый из стражей камер, рычит и бросается на вас." }, { 7.15, "Когда-то эти коридоры охраняли люди барона." }, { 10.83, "Теперь здесь сторожат звери, и сторожат по-звериному: тех, кому не повезло умереть сразу, держат за решёткой." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_shadowfang_keep_rethilgore", ["enc"] = 2748, ["track"] = { ["hash"] = "9883596c", ["text"] = "Ретилгор затихает у решёток. В камерах ещё живы пленники Аругала. Выпустите узника: тот, кто просидел здесь столько дней, знает, как открыть дверь во двор. Воздух за ней пахнет не свободой, а псиной.", ["duration"] = 15.5, ["cues"] = { { 0, "Ретилгор затихает у решёток." }, { 2.24, "В камерах ещё живы пленники Аругала." }, { 5.2, "Выпустите узника: тот, кто просидел здесь столько дней, знает, как открыть дверь во двор." }, { 12.13, "Воздух за ней пахнет не свободой, а псиной." } } } }, { ["q"] = 1098, ["follows"] = "dm_shadowfang_keep_rethilgore", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_shadowfang_keep_hook_1098_vincent", ["track"] = { ["hash"] = "1a7576d5", ["text"] = "Страж смерти Адамант — в камере, живой. Винсенту повезло меньше: его тело — у лестницы во двор. Хадрику будет что доложить.", ["duration"] = 11.4, ["cues"] = { { 0, "Страж смерти Адамант — в камере, живой." }, { 3.73, "Винсенту повезло меньше: его тело — у лестницы во двор." }, { 8.98, "Хадрику будет что доложить." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_shadowfang_keep_razorclaw_pull", ["enc"] = 2749, ["track"] = { ["hash"] = "0be7644f", ["text"] = "Остроклык Мясник, ворген с тесаком, ревёт и замахивается так, будто перед ним не бойцы, а туши на крюках. Своё прозвище он заслужил не в бою. Мясник привык, что мясо не сопротивляется, — покажите ему, что он ошибся.", ["duration"] = 17.8, ["cues"] = { { 0, "Остроклык Мясник, ворген с тесаком, ревёт и замахивается так, будто перед ним не бойцы, а туши на крюках." }, { 8.85, "Своё прозвище он заслужил не в бою." }, { 11.82, "Мясник привык, что мясо не сопротивляется, — покажите ему, что он ошибся." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_shadowfang_keep_razorclaw", ["enc"] = 2749, ["track"] = { ["hash"] = "5c8ebc27", ["text"] = "Остроклык Мясник рухнул, и тесак звякнул о камень. Аругал зовёт воргенов своими детьми. Если так, этот сын пошёл не в отца: в нём не было ни ума, ни магии, только голод. Больше он ни для кого ничего не нарубит.", ["duration"] = 18.1, ["cues"] = { { 0, "Остроклык Мясник рухнул, и тесак звякнул о камень." }, { 4.44, "Аругал зовёт воргенов своими детьми." }, { 7.64, "Если так, этот сын пошёл не в отца: в нём не было ни ума, ни магии, только голод." }, { 14.65, "Больше он ни для кого ничего не нарубит." } } } }, { ["role"] = "main", ["k"] = "pod", ["trig"] = "after", ["id"] = "dm_shadowfang_keep_silverlaine_intro", ["enc"] = 2750, ["pos"] = 3, ["track"] = { ["hash"] = "f49c27ff", ["text"] = "Дальше — обеденный зал. Здесь барон Сильверлейн принимал гостей, пока в его дом не пришли воргены. Барон погиб в собственной крепости, но так её и не покинул: его дух до сих пор сидит во главе стола. Призраки слуг бродят по коридорам, будто ждут приказа подавать. Гостям барон не рад. Особенно живым.", ["duration"] = 24.7, ["cues"] = { { 0, "Дальше — обеденный зал." }, { 1.96, "Здесь барон Сильверлейн принимал гостей, пока в его дом не пришли воргены." }, { 8.22, "Барон погиб в собственной крепости, но так её и не покинул: его дух до сих пор сидит во главе стола." }, { 16.51, "Призраки слуг бродят по коридорам, будто ждут приказа подавать." }, { 21.78, "Гостям барон не рад." }, { 23.52, "Особенно живым." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_shadowfang_keep_silverlaine_pull", ["enc"] = 2750, ["track"] = { ["hash"] = "4dd32bd3", ["text"] = "Барон поднимается из-за стола, и по залу тянет могильным холодом. Его пелена тени ложится на плечи бойца, и целебные чары соскальзывают с него, как вода с камня, — пока тень не сорвана.", ["duration"] = 15.4, ["cues"] = { { 0, "Барон поднимается из-за стола, и по залу тянет могильным холодом." }, { 5.52, "Его пелена тени ложится на плечи бойца, и целебные чары соскальзывают с него, как вода с камня, — пока тень не сорвана." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_shadowfang_keep_silverlaine", ["enc"] = 2750, ["track"] = { ["hash"] = "26c9431b", ["text"] = "Дух барона Сильверлейна тает над пустым столом. Его земли выстояли против Плети, но не выстояли против помощи из Даларана. Может быть, теперь барон наконец уйдёт туда, куда уходят мёртвые. Пустой зал гудит эхом, а над столом всё ещё висит холод.", ["duration"] = 21.4, ["cues"] = { { 0, "Дух барона Сильверлейна тает над пустым столом." }, { 4.18, "Его земли выстояли против Плети, но не выстояли против помощи из Даларана." }, { 10.8, "Может быть, теперь барон наконец уйдёт туда, куда уходят мёртвые." }, { 16.55, "Пустой зал гудит эхом, а над столом всё ещё висит холод." } } } }, { ["role"] = "main", ["k"] = "pod", ["trig"] = "after", ["id"] = "dm_shadowfang_keep_springvale_intro", ["enc"] = 2751, ["pos"] = 4, ["track"] = { ["hash"] = "7df71efc", ["text"] = "Выше по коридорам несёт службу командир Спрингвейл. При жизни он был рыцарем и защищал эти земли. Смерть не освободила его от присяги: мертвец держит пост так, словно гарнизон крепости всё ещё жив и ждёт его приказов. Пленных он не берёт — устав этого не требует. Живые для него просто нарушители.", ["duration"] = 24.3, ["cues"] = { { 0, "Выше по коридорам несёт службу командир Спрингвейл." }, { 4.28, "При жизни он был рыцарем и защищал эти земли." }, { 8.11, "Смерть не освободила его от присяги: мертвец держит пост так, словно гарнизон крепости всё ещё жив и ждёт его приказов." }, { 17.87, "Пленных он не берёт — устав этого не требует." }, { 21.62, "Живые для него просто нарушители." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_shadowfang_keep_springvale_pull", ["enc"] = 2751, ["track"] = { ["hash"] = "5047b3f6", ["text"] = "Командир Спрингвейл поднимает оружие, как на смотре. Он сражается по уставу, которого больше нет, за крепость, которой больше нет. Но бьёт он по-настоящему.", ["duration"] = 12.6, ["cues"] = { { 0, "Командир Спрингвейл поднимает оружие, как на смотре." }, { 4.34, "Он сражается по уставу, которого больше нет, за крепость, которой больше нет." }, { 10.7, "Но бьёт он по-настоящему." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_shadowfang_keep_springvale", ["enc"] = 2751, ["track"] = { ["hash"] = "3f344e3b", ["text"] = "Командир Спрингвейл падает, и доспех его звенит о камень. Оружие выпало из рук, которые держали его дольше, чем положено живым. Ещё один страж этой крепости наконец сдал пост. Никто не скажет ему «вольно», но, наверное, ему это уже и не нужно.", ["duration"] = 19.4, ["cues"] = { { 0, "Командир Спрингвейл падает, и доспех его звенит о камень." }, { 4.68, "Оружие выпало из рук, которые держали его дольше, чем положено живым." }, { 10.3, "Ещё один страж этой крепости наконец сдал пост." }, { 14.04, "Никто не скажет ему «вольно», но, наверное, ему это уже и не нужно." } } } }, { ["role"] = "main", ["k"] = "pod", ["trig"] = "after", ["id"] = "dm_shadowfang_keep_odo_intro", ["enc"] = 2752, ["pos"] = 5, ["track"] = { ["hash"] = "08fc0d72", ["text"] = "Дальше путь лежит по крепостной стене, под открытым небом. Там бродит Одо Слепой Страж — слепой ворген. Видеть ему и не нужно: он слышит каждый шаг по камню и чует живых издалека. Ветер на стене воет так, что вой Одо легко с ним спутать.", ["duration"] = 19.9, ["cues"] = { { 0, "Дальше путь лежит по крепостной стене, под открытым небом." }, { 4.94, "Там бродит Одо Слепой Страж — слепой ворген." }, { 8.75, "Видеть ему и не нужно: он слышит каждый шаг по камню и чует живых издалека." }, { 15.21, "Ветер на стене воет так, что вой Одо легко с ним спутать." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_shadowfang_keep_odo_pull", ["enc"] = 2752, ["track"] = { ["hash"] = "1b47cadb", ["text"] = "Одо Слепой Страж запрокидывает голову и воет. Слепота не сделала его слабее — она просто избавила его от лишнего. Он найдёт вас по запаху, где бы вы ни стояли.", ["duration"] = 13.3, ["cues"] = { { 0, "Одо Слепой Страж запрокидывает голову и воет." }, { 3.89, "Слепота не сделала его слабее — она просто избавила его от лишнего." }, { 9.77, "Он найдёт вас по запаху, где бы вы ни стояли." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_shadowfang_keep_odo", ["enc"] = 2752, ["track"] = { ["hash"] = "54a9f000", ["text"] = "Одо затихает у зубцов стены. Отсюда, сверху, Серебряный бор как на ладони: тёмные сосны и туман до самого горизонта. Слепой страж давно ничего этого не видит. Может, и к лучшему: где-то в этом тумане бродят его родичи.", ["duration"] = 19, ["cues"] = { { 0, "Одо затихает у зубцов стены." }, { 2.6, "Отсюда, сверху, Серебряный бор как на ладони: тёмные сосны и туман до самого горизонта." }, { 10.15, "Слепой страж давно ничего этого не видит." }, { 13.85, "Может, и к лучшему: где-то в этом тумане бродят его родичи." } } } }, { ["role"] = "main", ["k"] = "pod", ["trig"] = "after", ["id"] = "dm_shadowfang_keep_fenrus_intro", ["enc"] = 2753, ["pos"] = 6, ["track"] = { ["hash"] = "b6efa8f9", ["text"] = "Дальше, в башне, устроил логово Фенрус Пожиратель — огромный волк, страшнее всех здешних воргов. В его комнате до сих пор стоят книжные полки: когда-то здесь читали, а теперь грызут кости. Пол в его логове хрустит под ногами, и это не сухие ветки. Фенрус не колдует и не думает. Он ест.", ["duration"] = 26.1, ["cues"] = { { 0, "Дальше, в башне, устроил логово Фенрус Пожиратель — огромный волк, страшнее всех здешних воргов." }, { 8.86, "В его комнате до сих пор стоят книжные полки: когда-то здесь читали, а теперь грызут кости." }, { 17.3, "Пол в его логове хрустит под ногами, и это не сухие ветки." }, { 22.77, "Фенрус не колдует и не думает." }, { 25.58, "Он ест." } } } }, { ["q"] = 1013, ["follows"] = "dm_shadowfang_keep_fenrus_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_shadowfang_keep_hook_1013_book", ["track"] = { ["hash"] = "e2f47734", ["text"] = "Книга Ура стоит на полке в комнате Фенруса. Её легко забыть в пылу драки — не забудьте.", ["duration"] = 7.4, ["cues"] = { { 0, "Книга Ура стоит на полке в комнате Фенруса." }, { 3.8, "Её легко забыть в пылу драки — не забудьте." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_shadowfang_keep_fenrus_pull", ["enc"] = 2753, ["track"] = { ["hash"] = "7926ea7a", ["text"] = "Фенрус бросается из темноты, и с клыков его капает слюна. Слюна эта ядовита: кого он укусит, того отрава будет точить и после боя — медленно и упрямо, как сам волк.", ["duration"] = 15.7, ["cues"] = { { 0, "Фенрус бросается из темноты, и с клыков его капает слюна." }, { 5.57, "Слюна эта ядовита: кого он укусит, того отрава будет точить и после боя — медленно и упрямо, как сам волк." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_shadowfang_keep_fenrus", ["enc"] = 2753, ["track"] = { ["hash"] = "89bacd1c", ["text"] = "Фенрус Пожиратель рухнул на свои же кости. Книги на полках уцелели — волку они были ни к чему. Зато кости вокруг рассказывают о нём больше любой летописи. Говорят, Аругал чувствует смерть каждого из своих детей. Если так, он уже знает, что вы здесь.", ["duration"] = 22, ["cues"] = { { 0, "Фенрус Пожиратель рухнул на свои же кости." }, { 3.83, "Книги на полках уцелели — волку они были ни к чему." }, { 8.53, "Зато кости вокруг рассказывают о нём больше любой летописи." }, { 13.87, "Говорят, Аругал чувствует смерть каждого из своих детей." }, { 18.89, "Если так, он уже знает, что вы здесь." } } } }, { ["role"] = "main", ["k"] = "pod", ["trig"] = "after", ["id"] = "dm_shadowfang_keep_nandos_intro", ["enc"] = 2754, ["pos"] = 7, ["track"] = { ["hash"] = "fa75c627", ["text"] = "У покоев Аругала стоит Командир воргенов Нандос — вожак стаи. Он не дерётся один: стоит ему подать голос, и стая отзовётся из всех углов башни. Воргены слушаются Аругала, но идут они за Нандосом. Пройти к магу можно только мимо него, и Нандос это знает. В башне пахнет мокрой шерстью и страхом.", ["duration"] = 26.2, ["cues"] = { { 0, "У покоев Аругала стоит Командир воргенов Нандос — вожак стаи." }, { 5.58, "Он не дерётся один: стоит ему подать голос, и стая отзовётся из всех углов башни." }, { 12.76, "Воргены слушаются Аругала, но идут они за Нандосом." }, { 17.39, "Пройти к магу можно только мимо него, и Нандос это знает." }, { 22.73, "В башне пахнет мокрой шерстью и страхом." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_shadowfang_keep_nandos_pull", ["enc"] = 2754, ["track"] = { ["hash"] = "b07e2038", ["text"] = "Нандос вскидывает голову и зовёт стаю, одного зверя за другим: бесцветного ворга, слюнявого ворга, а там и жутеволка. Каждый вой приводит нового — и горе тем, вокруг кого стая успеет сомкнуться.", ["duration"] = 17.5, ["cues"] = { { 0, "Нандос вскидывает голову и зовёт стаю, одного зверя за другим: бесцветного ворга, слюнявого ворга, а там и жутеволка." }, { 10.64, "Каждый вой приводит нового — и горе тем, вокруг кого стая успеет сомкнуться." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_shadowfang_keep_nandos", ["enc"] = 2754, ["track"] = { ["hash"] = "710efae7", ["text"] = "Нандос затихает, и вой стаи обрывается разом. Без вожака воргены — просто звери в чужом замке, и звери эти растеряны. Те, что ещё бродят по коридорам, теперь сами по себе. Стая держалась на его голосе, а голос умолк. Башня впервые за долгое время молчит.", ["duration"] = 23.7, ["cues"] = { { 0, "Нандос затихает, и вой стаи обрывается разом." }, { 4.27, "Без вожака воргены — просто звери в чужом замке, и звери эти растеряны." }, { 11.04, "Те, что ещё бродят по коридорам, теперь сами по себе." }, { 15.98, "Стая держалась на его голосе, а голос умолк." }, { 20.25, "Башня впервые за долгое время молчит." } } } }, { ["role"] = "final", ["k"] = "pod", ["trig"] = "after", ["id"] = "dm_shadowfang_keep_arugal_intro", ["enc"] = 2755, ["pos"] = 8, ["track"] = { ["hash"] = "2b542dc3", ["text"] = "Верховный маг Аругал ждёт в своих покоях. Когда-то он был уважаемым магом Кирин-Тора и хотел спасти Лордерон от Плети. А вместо этого призвал на него ещё одно проклятие. Говорят, вина свела его с ума: теперь он зовёт воргенов своими детьми и бережёт их, как отец. Отрекшиеся давно хотят его смерти: пока маг жив, Серебряный бор им не принадлежит.", ["duration"] = 28.8, ["cues"] = { { 0, "Верховный маг Аругал ждёт в своих покоях." }, { 3.48, "Когда-то он был уважаемым магом Кирин-Тора и хотел спасти Лордерон от Плети." }, { 9.98, "А вместо этого призвал на него ещё одно проклятие." }, { 14.29, "Говорят, вина свела его с ума: теперь он зовёт воргенов своими детьми и бережёт их, как отец." }, { 22.15, "Отрёкшиеся давно хотят его смерти: пока маг жив, Серебряный бор им не принадлежит." } } } }, { ["q"] = 1014, ["follows"] = "dm_shadowfang_keep_arugal_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_shadowfang_keep_hook_1014_pod", ["track"] = { ["hash"] = "a30a8dac", ["text"] = "Именно его голову ждёт Далар Ткач Рассвета.", ["duration"] = 4.1, ["cues"] = { { 0, "Именно его голову ждёт Далар Ткач Рассвета." } } } }, { ["role"] = "final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_shadowfang_keep_arugal_pull", ["enc"] = 2755, ["track"] = { ["hash"] = "28a178a4", ["text"] = "Аругал вскидывает руки, и тени в зале оживают. Он исчезает и возникает в другом углу, а его проклятие обращает человека в зверя — и тот, кто только что был вам другом, скалится на своих, пока чары не спадут.", ["duration"] = 17, ["cues"] = { { 0, "Аругал вскидывает руки, и тени в зале оживают." }, { 3.94, "Он исчезает и возникает в другом углу, а его проклятие обращает человека в зверя — и тот, кто только что был вам другом, скалится на своих, пока чары не спадут." } } } }, { ["role"] = "final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_shadowfang_keep_arugal", ["enc"] = 2755, ["track"] = { ["hash"] = "96edce67", ["text"] = "Верховный маг Аругал падает, и в покоях становится тихо. Воргены ещё долго будут бродить по Серебряному бору: отозвать их больше некому. Даларан хотел защитить Лордерон, а оставил ему новую рану. Но безумец, открывший дверь, больше никого не позовёт.", ["duration"] = 22.6, ["cues"] = { { 0, "Верховный маг Аругал падает, и в покоях становится тихо." }, { 5.15, "Воргены ещё долго будут бродить по Серебряному бору: отозвать их больше некому." }, { 12.42, "Даларан хотел защитить Лордерон, а оставил ему новую рану." }, { 17.9, "Но безумец, открывший дверь, больше никого не позовёт." } } } }, { ["q"] = 1014, ["follows"] = "dm_shadowfang_keep_arugal", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_shadowfang_keep_fin_1014", ["track"] = { ["hash"] = "099f467e", ["text"] = "Голову Аругала — Далару Ткачу Рассвета, в Гробницу. Серебряный бор сегодня стал чуть больше землёй Отрекшихся.", ["duration"] = 9.8, ["cues"] = { { 0, "Голову Аругала — Далару Ткачу Рассвета, в Гробницу." }, { 4.83, "Серебряный бор сегодня стал чуть больше землёй Отрёкшихся." } } } } }, ["bosses"] = { { ["id"] = 2748, ["npcs"] = { 3914 }, ["name"] = "Rethilgore", ["required"] = nil, ["token"] = "rethilgore", ["names335"] = { "Rethilgore" } }, { ["id"] = 2749, ["npcs"] = { 3886 }, ["name"] = "Razorclaw the Butcher", ["required"] = nil, ["token"] = "razorclaw", ["names335"] = { "Razorclaw the Butcher" } }, { ["id"] = 2750, ["npcs"] = { 3887 }, ["name"] = "Baron Silverlaine", ["required"] = nil, ["token"] = "silverlaine", ["names335"] = { "Baron Silverlaine" } }, { ["id"] = 2751, ["npcs"] = { 4278 }, ["name"] = "Commander Springvale", ["required"] = nil, ["token"] = "springvale", ["names335"] = { "Commander Springvale" } }, { ["id"] = 2752, ["npcs"] = { 4279 }, ["name"] = "Odo the Blindwatcher", ["required"] = nil, ["token"] = "odo", ["names335"] = { "Odo the Blindwatcher" } }, { ["id"] = 2753, ["npcs"] = { 4274 }, ["name"] = "Fenrus the Devourer", ["required"] = nil, ["token"] = "fenrus", ["names335"] = { "Fenrus the Devourer" } }, { ["id"] = 2754, ["npcs"] = { 3927 }, ["name"] = "Wolf Master Nandos", ["required"] = nil, ["token"] = "nandos", ["names335"] = { "Wolf Master Nandos" } }, { ["id"] = 2755, ["npcs"] = { 4275 }, ["name"] = "Archmage Arugal", ["required"] = nil, ["token"] = "arugal", ["names335"] = { "Archmage Arugal" } } } },
[34] = { ["key"] = "stockade", ["order"] = {  }, ["layout"] = "hub", ["alias"] = {  }, ["name"] = "Тюрьма Штормграда", ["events"] = { { ["id"] = "dm_stockade_prolog", ["k"] = "prolog", ["trig"] = "prolog", ["track"] = { ["hash"] = "1a83ba37", ["text"] = "Вы в Тюрьме Штормграда — каменном мешке под каналами столицы. Здесь держат воров, убийц, мятежников и самых опасных преступников королевства. Недавно узники из Братства Справедливости подняли бунт: стражу выбили, камеры распахнуты, а тюремщик Телвотер удерживает один только вход. Верховодит мятежом Базиль Тредд, правая рука ван Клифа. Телвотер очень не хочет, чтобы об этом узнали наверху, — так что разбираться придётся вам, и без лишнего шума.", ["duration"] = 36.7, ["cues"] = { { 0, "Вы в Тюрьме Штормграда — каменном мешке под каналами столицы." }, { 5.1, "Здесь держат воров, убийц, мятежников и самых опасных преступников королевства." }, { 11.69, "Недавно узники из Братства Справедливости подняли бунт: стражу выбили, камеры распахнуты, а тюремщик Телвотер удерживает один только вход." }, { 23.16, "Верховодит мятежом Базиль Тредд, правая рука ван Клифа." }, { 27.81, "Телвотер очень не хочет, чтобы об этом узнали наверху, — так что разбираться придётся вам, и без лишнего шума." } } } }, { ["id"] = "dm_stockade_prolog_repeat", ["k"] = "prolog", ["trig"] = "repeat", ["track"] = { ["hash"] = "4f9f484f", ["text"] = "Снова Тюрьма Штормграда. Камеры пустовали недолго: Братство уже подняло новых узников.", ["duration"] = 7.8, ["cues"] = { { 0, "Снова Тюрьма Штормграда." }, { 2.26, "Камеры пустовали недолго: Братство уже подняло новых узников." } } } }, { ["q"] = 391, ["prio"] = 0, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_stockade_hook_391", ["track"] = { ["hash"] = "6c8b663c", ["text"] = "Тюремщик Телвотер ждёт голову Базиля Тредда. Он вам не доверяет — но сейчас ему больше не на кого положиться.", ["duration"] = 8.8, ["cues"] = { { 0, "Тюремщик Телвотер ждёт голову Базиля Тредда." }, { 3.7, "Он вам не доверяет — но сейчас ему больше не на кого положиться." } } } }, { ["q"] = 387, ["prio"] = 1, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_stockade_hook_387", ["track"] = { ["hash"] = "2ee8ddf9", ["text"] = "Телвотер велел проучить бунтовщиков: десять узников, восемь каторжников и восемь мятежников из Братства. Тут их хватит с лихвой.", ["duration"] = 10.4, ["cues"] = { { 0, "Телвотер велел проучить бунтовщиков: десять узников, восемь каторжников и восемь мятежников из Братства." }, { 8.56, "Тут их хватит с лихвой." } } } }, { ["q"] = 388, ["prio"] = 2, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_stockade_hook_388", ["track"] = { ["hash"] = "e85a0aaa", ["text"] = "Никова Раскол ждёт десять красных шерстяных бандан — в память о внуке, которого здесь ударили ножом в спину. Для неё это не трофеи, а долг.", ["duration"] = 11.4, ["cues"] = { { 0, "Никова Раскол ждёт десять красных шерстяных бандан — в память о внуке, которого здесь ударили ножом в спину." }, { 9.11, "Для неё это не трофеи, а долг." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stockade_targorr_pull", ["enc"] = 2756, ["track"] = { ["hash"] = "6fced97b", ["text"] = "Таргорр Ужасный, орк из клана Черной горы и бывший старший палач Гат'Илзогга, скалится и поднимает оружие: для палача любой бой — просто работа. Его приговорили к смерти, но кто-то из знати запретил казнь. Он рубит размеренно, как дрова, и ждёт, кто из вас первым дрогнет.", ["duration"] = 23.8, ["cues"] = { { 0, "Таргорр Ужасный, орк из клана Чёрной горы и бывший старший палач Гат'Илзогга, скалится и поднимает оружие: для палача любой бой — просто работа." }, { 12.84, "Его приговорили к смерти, но кто-то из знати запретил казнь." }, { 18.22, "Он рубит размеренно, как дрова, и ждёт, кто из вас первым дрогнет." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stockade_targorr", ["enc"] = 2756, ["track"] = { ["hash"] = "474ca8c2", ["text"] = "Таргорр Ужасный рухнул на камни, и приговор, который так и не исполнили, всё-таки исполнен. Этот орк пытал защитников Штормграда, и всё равно кто-то в знатных домах спас его от плахи. Зачем знати живой палач старой Орды? Ответа в тюрьме нет, но вопрос стоит запомнить.", ["duration"] = 22.6, ["cues"] = { { 0, "Таргорр Ужасный рухнул на камни, и приговор, который так и не исполнили, всё-таки исполнен." }, { 7.65, "Этот орк пытал защитников Штормграда, и всё равно кто-то в знатных домах спас его от плахи." }, { 15.45, "Зачем знати живой палач старой Орды?" }, { 18.74, "Ответа в тюрьме нет, но вопрос стоит запомнить." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stockade_kam_pull", ["enc"] = 2757, ["track"] = { ["hash"] = "5f8be768", ["text"] = "Кам Гневливый пригибается за щитом и рычит проклятия Стальгорну. Дворфы этого клана дерутся упрямо и зло, будто каждый бой — продолжение старой войны со Стальгорном.", ["duration"] = 13.6, ["cues"] = { { 0, "Кам Гневливый пригибается за щитом и рычит проклятия Стальгорну." }, { 5.32, "Дворфы этого клана дерутся упрямо и зло, будто каждый бой — продолжение старой войны со Стальгорном." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stockade_kam", ["enc"] = 2757, ["track"] = { ["hash"] = "58040a6b", ["text"] = "Кам Гневливый затих. Говорят, это он устроил нападение на мост Тандола, и на его совести гибель дворфов Стальгорна. Штормград держал его за решёткой и не торопился с приговором. Стальгорн ждать не стал. У дворфов память длинная, а счёт к Черному Железу — ещё длиннее.", ["duration"] = 22.4, ["cues"] = { { 0, "Кам Гневливый затих." }, { 1.8, "Говорят, это он устроил нападение на мост Тандола, и на его совести гибель дворфов Стальгорна." }, { 9.91, "Штормград держал его за решёткой и не торопился с приговором." }, { 15.14, "Стальгорн ждать не стал." }, { 17.09, "У дворфов память длинная, а счёт к Чёрному Железу — ещё длиннее." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stockade_hamhock_pull", ["enc"] = 2758, ["track"] = { ["hash"] = "da045123", ["text"] = "Хрупконог, огр-маг, наливается кровожадностью, и удары его становятся всё чаще и злее. Чары держатся на нём крепко, и пока их никто не сорвал, раны от его кулаков множатся быстрее, чем их успевают залечить.", ["duration"] = 16.9, ["cues"] = { { 0, "Хрупконог, огр-маг, наливается кровожадностью, и удары его становятся всё чаще и злее." }, { 7.14, "Чары держатся на нём крепко, и пока их никто не сорвал, раны от его кулаков множатся быстрее, чем их успевают залечить." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stockade_hamhock", ["enc"] = 2758, ["track"] = { ["hash"] = "a47776ef", ["text"] = "Хрупконог тяжело оседает, и в камере сразу становится просторнее. Двухголовый огр-маг — не лучший сосед по тюрьме, а бунт дал ему то, чего не давала решётка: драку. Теперь в Тюрьме Штормграда одним буйным узником меньше.", ["duration"] = 18.3, ["cues"] = { { 0, "Хрупконог тяжело оседает, и в камере сразу становится просторнее." }, { 5.53, "Двухголовый огр-маг — не лучший сосед по тюрьме, а бунт дал ему то, чего не давала решётка: драку." }, { 13.71, "Теперь в Тюрьме Штормграда одним буйным узником меньше." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stockade_dextren_pull", ["enc"] = 2759, ["track"] = { ["hash"] = "d6b94f5f", ["text"] = "Декстрен Вард встречает вас ухмылкой гробокопателя. Он продавал тела с кладбищ Сумеречного леса некроманту и знает о смерти больше, чем хотелось бы, — только свою встречать не спешит.", ["duration"] = 13.8, ["cues"] = { { 0, "Декстрен Вард встречает вас ухмылкой гробокопателя." }, { 3.86, "Он продавал тела с кладбищ Сумеречного леса некроманту и знает о смерти больше, чем хотелось бы, — только свою встречать не спешит." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stockade_dextren", ["enc"] = 2759, ["track"] = { ["hash"] = "5e567554", ["text"] = "Декстрен Вард затихает на холодном полу. Совет Темнолесья приговорил его к смерти, но знатные дома Штормграда забрали его в тюрьму, подальше от плахи. Темнолесье сочтёт приговор исполненным. А в знатных домах, похоже, не впервые спасают тех, кого следовало казнить.", ["duration"] = 21.2, ["cues"] = { { 0, "Декстрен Вард затихает на холодном полу." }, { 3.27, "Совет Темнолесья приговорил его к смерти, но знатные дома Штормграда забрали его в тюрьму, подальше от плахи." }, { 12.2, "Темнолесье сочтёт приговор исполненным." }, { 15.32, "А в знатных домах, похоже, не впервые спасают тех, кого следовало казнить." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stockade_bazil_pull", ["enc"] = 2760, ["track"] = { ["hash"] = "0cf2be85", ["text"] = "Базиль Тредд встречает вас ухмылкой: лейтенант ван Клифа привык драться грязно. Когда станет туго, он швырнёт дымовую шашку, и кто окажется в дыму, на несколько мгновений станет беспомощен, — а дым не разбирает, сколько вас стоит рядом.", ["duration"] = 17.4, ["cues"] = { { 0, "Базиль Тредд встречает вас ухмылкой: лейтенант ван Клифа привык драться грязно." }, { 5.95, "Когда станет туго, он швырнёт дымовую шашку, и кто окажется в дыму, на несколько мгновений станет беспомощен, — а дым не разбирает, сколько вас стоит рядом." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stockade_bazil", ["enc"] = 2760, ["track"] = { ["hash"] = "a302c7ae", ["text"] = "Базиль Тредд падает, и бунт лишается головы. Он был не просто узником, а лейтенантом ван Клифа, и даже за решёткой знал о планах Братства больше всех. Только откуда у запертых узников оружие и вести с воли? Кто-то снаружи держал эту дверь приоткрытой.", ["duration"] = 20.9, ["cues"] = { { 0, "Базиль Тредд падает, и бунт лишается головы." }, { 3.73, "Он был не просто узником, а лейтенантом ван Клифа, и даже за решёткой знал о планах Братства больше всех." }, { 12.42, "Только откуда у запертых узников оружие и вести с воли?" }, { 17.23, "Кто-то снаружи держал эту дверь приоткрытой." } } } } }, ["bosses"] = { { ["id"] = 2756, ["npcs"] = { 1696 }, ["name"] = "Targorr the Dread", ["required"] = nil, ["token"] = "targorr", ["names335"] = { "Targorr the Dread" } }, { ["id"] = 2757, ["npcs"] = { 1666 }, ["name"] = "Kam Deepfury", ["required"] = nil, ["token"] = "kam", ["names335"] = { "Kam Deepfury" } }, { ["id"] = 2758, ["npcs"] = { 1717 }, ["name"] = "Hamhock", ["required"] = nil, ["token"] = "hamhock", ["names335"] = { "Hamhock" } }, { ["id"] = 2759, ["npcs"] = { 1663 }, ["name"] = "Dextren Ward", ["required"] = nil, ["token"] = "dextren", ["names335"] = { "Dextren Ward" } }, { ["id"] = 2760, ["npcs"] = { 1716 }, ["name"] = "Bazil Thredd", ["required"] = nil, ["token"] = "bazil", ["names335"] = { "Bazil Thredd" } } } },
[36] = { ["key"] = "deadmines", ["order"] = { 2741, 2742, 2743, 2745, 2747 }, ["layout"] = "linear_with_side", ["alias"] = {  }, ["name"] = "Мертвые копи", ["events"] = { { ["id"] = "dm_deadmines_prolog", ["k"] = "prolog", ["trig"] = "prolog", ["track"] = { ["hash"] = "eb6613b3", ["text"] = "Вы в Мертвых копях. Когда-то это были богатейшие золотые копи людских земель. Их бросили, когда Орда сожгла Штормград в Первой войне, и с тех пор их зовут мёртвыми. Теперь здесь хозяйничает Братство Справедливости — разбойники в красных банданах, что держат в страхе весь Западный Край. Ополчение Гриана Камнегрива годами искало их логово, а оно всё это время было под руинами Луноречья. Впереди стучат кирки, скрипят лебёдки и гудят горны. Внизу что-то строят — и очень не хотят, чтобы вы узнали, что именно.", ["duration"] = 40, ["cues"] = { { 0, "Вы в Мёртвых копях." }, { 1.5, "Когда-то это были богатейшие золотые копи людских земель." }, { 6.2, "Их бросили, когда Орда сожгла Штормград в Первой войне, и с тех пор их зовут мёртвыми." }, { 12.98, "Теперь здесь хозяйничает Братство Справедливости — разбойники в красных банданах, что держат в страхе весь Западный Край." }, { 22.39, "Ополчение Гриана Камнегрива годами искало их логово, а оно всё это время было под руинами Луноречья." }, { 30.45, "Впереди стучат кирки, скрипят лебёдки и гудят горны." }, { 34.66, "Внизу что-то строят — и очень не хотят, чтобы вы узнали, что именно." } } } }, { ["id"] = "dm_deadmines_prolog_repeat", ["k"] = "prolog", ["trig"] = "repeat", ["track"] = { ["hash"] = "4880b92e", ["text"] = "Снова Мертвые копи. Братство помнит вас — и, судя по стуку кирок, уже наняло новых людей. Внизу по-прежнему строят то, что не должен увидеть Штормград.", ["duration"] = 12.3, ["cues"] = { { 0, "Снова Мёртвые копи." }, { 1.62, "Братство помнит вас — и, судя по стуку кирок, уже наняло новых людей." }, { 7.45, "Внизу по-прежнему строят то, что не должен увидеть Штормград." } } } }, { ["q"] = 168, ["prio"] = 0, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_deadmines_hook_168", ["track"] = { ["hash"] = "f023e90f", ["text"] = "Дикий Чертополохх ждёт вестей о шахтёрах, погибших под завалом: их карточки Союза шахтёров и значок его брата. Мёртвым это уже не поможет. Их семьям — поможет.", ["duration"] = 14.2, ["cues"] = { { 0, "Дикий Чертополохх ждёт вестей о шахтёрах, погибших под завалом: их карточки Союза шахтёров и значок его брата." }, { 9.9, "Мёртвым это уже не поможет." }, { 12.44, "Их семьям — поможет." } } } }, { ["q"] = 214, ["prio"] = 1, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_deadmines_hook_214", ["track"] = { ["hash"] = "ba70604a", ["text"] = "Разведчице Риэле нужны красные шёлковые банданы — знак старших в Братстве. Здесь их хватит.", ["duration"] = 7.3, ["cues"] = { { 0, "Разведчице Риэле нужны красные шёлковые банданы — знак старших в Братстве." }, { 6.1, "Здесь их хватит." } } } }, { ["prio"] = 2, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_deadmines_hook_horde", ["faction"] = "Horde", ["track"] = { ["hash"] = "b2d83125", ["text"] = "Это не ваша война, Орда, и Штормград не скажет вам спасибо. Но у Братства хорошая сталь и полные сундуки.", ["duration"] = 9.3, ["cues"] = { { 0, "Это не ваша война, Орда, и Штормград не скажет вам спасибо." }, { 5.41, "Но у Братства хорошая сталь и полные сундуки." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_deadmines_rhahkzor_pull", ["enc"] = 2741, ["track"] = { ["hash"] = "73168534", ["text"] = "Перед вами Рак'Зор — огр, которого Братство поставило бригадиром над шахтёрами: огры не задают вопросов, пока им платят. Он ревёт про награду за ваши головы и заносит кулак размером с наковальню. Тот, кто примет его удар, на миг забудет, где верх, а где низ.", ["duration"] = 20.2, ["cues"] = { { 0, "Перед вами Рак'Зор — огр, которого Братство поставило бригадиром над шахтёрами: огры не задают вопросов, пока им платят." }, { 9.58, "Он ревёт про награду за ваши головы и заносит кулак размером с наковальню." }, { 15.49, "Тот, кто примет его удар, на миг забудет, где верх, а где низ." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_deadmines_rhahkzor", ["enc"] = 2741, ["track"] = { ["hash"] = "34e429e3", ["text"] = "Рак'Зор рухнул на землю, и опоры штрека перестали дрожать. Огры не воюют за идею — только за золото, и золота у Братства, похоже, хватает. А кирки впереди не смолкли ни на миг: внизу работают и днём, и ночью. Кто-то очень торопится закончить то, что строят.", ["duration"] = 21.3, ["cues"] = { { 0, "Рак'Зор рухнул на землю, и опоры штрека перестали дрожать." }, { 4.96, "Огры не воюют за идею — только за золото, и золота у Братства, похоже, хватает." }, { 11.66, "А кирки впереди не смолкли ни на миг: внизу работают и днём, и ночью." }, { 17.37, "Кто-то очень торопится закончить то, что строят." } } } }, { ["q"] = 2040, ["follows"] = "dm_deadmines_rhahkzor", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_deadmines_hook_2040", ["track"] = { ["hash"] = "a7f3b486", ["text"] = "Шони Молшунье нужно сердце гоблинского резака, чтобы гномы пробились к Гномрегану. Ищите его в машине на лесопилке впереди.", ["duration"] = 9.8, ["cues"] = { { 0, "Шони Молшунье нужно сердце гоблинского резака, чтобы гномы пробились к Гномрегану." }, { 6.63, "Ищите его в машине на лесопилке впереди." } } } }, { ["sub"] = "Мачтовая мастерская", ["role"] = "main", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_deadmines_sneed_intro", ["enc"] = 2742, ["pos"] = 2, ["track"] = { ["hash"] = "4854c74a", ["text"] = "Мачтовая мастерская. Здесь пахнет свежей смолой и машинным маслом: Братство валит лес и тащит брёвна под землю. Заправляет здесь гоблин Снид. Братство щедро платит гоблинам за мастерство, и Снид отрабатывает каждую монету — из кабины крошшера, железного великана с пилами вместо рук. Странно одно: мачты, которые здесь тешут, слишком длинные для шахты.", ["duration"] = 28.6, ["cues"] = { { 0, "Мачтовая мастерская." }, { 1.71, "Здесь пахнет свежей смолой и машинным маслом: Братство валит лес и тащит брёвна под землю." }, { 9.13, "Заправляет здесь гоблин Снид." }, { 11.5, "Братство щедро платит гоблинам за мастерство, и Снид отрабатывает каждую монету — из кабины крошшера, железного великана с пилами вместо рук." }, { 23.08, "Странно одно: мачты, которые здесь тешут, слишком длинные для шахты." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_deadmines_sneed_pull", ["enc"] = 2742, ["track"] = { ["hash"] = "ff7b78b0", ["text"] = "Пилы взвывают, и крошшер прёт прямо на вас. От его рёва у бывалых бойцов подгибаются колени, а железные лапы так и норовят вырвать оружие из рук. Но гоблины строят быстро, а не надёжно: развалится машина — и Снида выставит из кабины прямо к вам.", ["duration"] = 19.3, ["cues"] = { { 0, "Пилы взвывают, и крошшер прёт прямо на вас." }, { 3.47, "От его рёва у бывалых бойцов подгибаются колени, а железные лапы так и норовят вырвать оружие из рук." }, { 11.56, "Но гоблины строят быстро, а не надёжно: развалится машина — и Снида выставит из кабины прямо к вам." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_deadmines_sneed", ["enc"] = 2742, ["track"] = { ["hash"] = "b32c593f", ["text"] = "Крошшер со скрежетом оседает, и Снид затихает рядом со своей машиной. На стенах — чертежи: мачты, шпангоуты, обшивка борта. Братство строит не крепость и не склад. Оно строит корабль — здесь, под землёй, вдали от глаз Штормграда.", ["duration"] = 20.7, ["cues"] = { { 0, "Крошшер со скрежетом оседает, и Снид затихает рядом со своей машиной." }, { 6.41, "На стенах — чертежи: мачты, шпангоуты, обшивка борта." }, { 11.4, "Братство строит не крепость и не склад." }, { 14.98, "Оно строит корабль — здесь, под землёй, вдали от глаз Штормграда." } } } }, { ["q"] = 92753, ["follows"] = "dm_deadmines_sneed", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_deadmines_hook_92753", ["track"] = { ["hash"] = "478b8672", ["text"] = "Горн, о котором говорила Альба Светлая Луна, где-то в этих копях. Найдите его и заложите взрывчатку — Альба ждёт у выхода.", ["duration"] = 9.7, ["cues"] = { { 0, "Горн, о котором говорила Альба Светлая Луна, где-то в этих копях." }, { 5.31, "Найдите его и заложите взрывчатку — Альба ждёт у выхода." } } } }, { ["role"] = "rare", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_deadmines_johnson_pull", ["enc"] = 3676, ["track"] = { ["hash"] = "7c434948", ["text"] = "Из бокового забоя с киркой наперевес выходит шахтёр Джонсон. Встречается он не каждой группе — кости выпали редкой стороной. Кирка у него старая, но бьёт туда, где броня тоньше всего.", ["duration"] = 14.3, ["cues"] = { { 0, "Из бокового забоя с киркой наперевес выходит шахтёр Джонсон." }, { 4.75, "Встречается он не каждой группе — кости выпали редкой стороной." }, { 9.79, "Кирка у него старая, но бьёт туда, где броня тоньше всего." } } } }, { ["role"] = "rare", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_deadmines_johnson", ["enc"] = 3676, ["track"] = { ["hash"] = "35d1ea65", ["text"] = "Шахтёр Джонсон затихает в забое, где, должно быть, провёл полжизни. Когда-то такие, как он, добывали здесь золото для королевства. Потом королевство про них забыло. А Братство — нет.", ["duration"] = 14.3, ["cues"] = { { 0, "Шахтёр Джонсон затихает в забое, где, должно быть, провёл полжизни." }, { 5.36, "Когда-то такие, как он, добывали здесь золото для королевства." }, { 10.36, "Потом королевство про них забыло." }, { 13.08, "А Братство — нет." } } } }, { ["sub"] = "Гоблинский цех", ["role"] = "main", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_deadmines_gilnid_intro", ["enc"] = 2743, ["pos"] = 4, ["track"] = { ["hash"] = "57e611d9", ["text"] = "Гоблинский цех. Жар бьёт в лицо, по желобам текут огненные реки. Здесь плавят руду и льют то, без чего не обойдётся ни один военный корабль: пушки, якоря, цепи. Хозяин цеха — Гилнид, маленький и злой гоблин-плавильщик. Говорят, дым здешних печей уходит в трещины и травит поля Западного Края.", ["duration"] = 26.9, ["cues"] = { { 0, "Гоблинский цех." }, { 1.42, "Жар бьёт в лицо, по желобам текут огненные реки." }, { 5.94, "Здесь плавят руду и льют то, без чего не обойдётся ни один военный корабль: пушки, якоря, цепи." }, { 14.74, "Хозяин цеха — Гилнид, маленький и злой гоблин-плавильщик." }, { 20.09, "Говорят, дым здешних печей уходит в трещины и травит поля Западного Края." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_deadmines_gilnid_pull", ["enc"] = 2743, ["track"] = { ["hash"] = "e7b37fe1", ["text"] = "Гилнид свистит, и из-за печей лезут подмастерья с клещами и молотами. Гоблины не дерутся честно — они дерутся гурьбой, и пока гурьба цела, хозяин чувствует себя неуязвимым. А сам Гилнид не прочь плеснуть расплавленным металлом: такие ожоги сами не проходят.", ["duration"] = 20.2, ["cues"] = { { 0, "Гилнид свистит, и из-за печей лезут подмастерья с клещами и молотами." }, { 5.52, "Гоблины не дерутся честно — они дерутся гурьбой, и пока гурьба цела, хозяин чувствует себя неуязвимым." }, { 13.73, "А сам Гилнид не прочь плеснуть расплавленным металлом: такие ожоги сами не проходят." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_deadmines_gilnid", ["enc"] = 2743, ["track"] = { ["hash"] = "e85c7be0", ["text"] = "Гилнид затихает у своих тиглей, а печи гудят дальше: им всё равно, жив ли хозяин. Вокруг остывают пушечные стволы и звенья цепей толщиной в руку. Разбойникам столько оружия ни к чему. Это оружие для войны.", ["duration"] = 18.2, ["cues"] = { { 0, "Гилнид затихает у своих тиглей, а печи гудят дальше: им всё равно, жив ли хозяин." }, { 7.25, "Вокруг остывают пушечные стволы и звенья цепей толщиной в руку." }, { 12.98, "Разбойникам столько оружия ни к чему." }, { 16.33, "Это оружие для войны." } } } }, { ["sub"] = "Потайная бухта", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_deadmines_greenskin_intro", ["enc"] = 2744, ["pos"] = 5, ["track"] = { ["hash"] = "e819190a", ["text"] = "Потайная бухта. За воротами открывается подземная гавань: чёрная вода, своды, теряющиеся во мраке, и корабль. Настоящий, под красным флагом Братства, с пушками по бортам. Зачем разбойникам военный корабль, лучше спросить у того, кто стоит у штурвала. А на нижней палубе командует капитан Зеленямс — гоблин, купивший титул вместе с треуголкой.", ["duration"] = 28.7, ["cues"] = { { 0, "Потайная бухта." }, { 1.37, "За воротами открывается подземная гавань: чёрная вода, своды, теряющиеся во мраке, и корабль." }, { 9.22, "Настоящий, под красным флагом Братства, с пушками по бортам." }, { 14.32, "Зачем разбойникам военный корабль, лучше спросить у того, кто стоит у штурвала." }, { 21.1, "А на нижней палубе командует капитан Зеленямс — гоблин, купивший титул вместе с треуголкой." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_deadmines_greenskin_pull", ["enc"] = 2744, ["track"] = { ["hash"] = "63efdfb1", ["text"] = "Капитан выхватывает саблю и гарпун. Сабля ходит широко — тесниться перед ним всё равно что стоять под мельничным крылом. А гарпун капитан макает в яд, и кого он зацепит, того отрава будет жечь ещё долго.", ["duration"] = 16.2, ["cues"] = { { 0, "Капитан выхватывает саблю и гарпун." }, { 2.9, "Сабля ходит широко — тесниться перед ним всё равно что стоять под мельничным крылом." }, { 9.72, "А гарпун капитан макает в яд, и кого он зацепит, того отрава будет жечь ещё долго." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_deadmines_greenskin", ["enc"] = 2744, ["track"] = { ["hash"] = "2a36e63c", ["text"] = "Треуголка капитана катится по палубе и исчезает в чёрной воде. Гоблины служат тому, кто платит, — а платили здесь щедро: доски, пушки, порох, целая команда. Откуда у разбойников из Западного Края такие деньги?", ["duration"] = 17.4, ["cues"] = { { 0, "Треуголка капитана катится по палубе и исчезает в чёрной воде." }, { 5.21, "Гоблины служат тому, кто платит, — а платили здесь щедро: доски, пушки, порох, целая команда." }, { 13.14, "Откуда у разбойников из Западного Края такие деньги?" } } } }, { ["role"] = "main", ["k"] = "pod", ["trig"] = "after", ["id"] = "dm_deadmines_smite_intro", ["enc"] = 2745, ["pos"] = 6, ["track"] = { ["hash"] = "87b012bc", ["text"] = "Палубой выше ждёт старпом — Мистер Каюк. Таурен на разбойничьем корабле, среди людей и гоблинов. Как он сюда попал, никто не знает, но ван Клиф доверяет ему больше всех. Говорят, у Каюка есть сундук с оружием на любой случай.", ["duration"] = 18.3, ["cues"] = { { 0, "Палубой выше ждёт старпом — Мистер Каюк." }, { 3.4, "Таурен на разбойничьем корабле, среди людей и гоблинов." }, { 7.98, "Как он сюда попал, никто не знает, но ван Клиф доверяет ему больше всех." }, { 13.89, "Говорят, у Каюка есть сундук с оружием на любой случай." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_deadmines_smite_pull", ["enc"] = 2745, ["track"] = { ["hash"] = "13517d29", ["text"] = "Каюк ревёт и поднимает оружие. Старпом не любит затяжных драк: почуяв, что дело плохо, он грохнет копытом в палубу так, что ноги подкосятся, и отвернётся к сундуку за чем-нибудь потяжелее — и не единожды. Спина у таурена широкая. Грех не воспользоваться.", ["duration"] = 20.1, ["cues"] = { { 0, "Каюк ревёт и поднимает оружие." }, { 2.48, "Старпом не любит затяжных драк: почуяв, что дело плохо, он грохнет копытом в палубу так, что ноги подкосятся, и отвернётся к сундуку за чем-нибудь потяжелее — и не единожды." }, { 16.29, "Спина у таурена широкая." }, { 18.33, "Грех не воспользоваться." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_deadmines_smite", ["enc"] = 2745, ["track"] = { ["hash"] = "8185f35a", ["text"] = "Великан опускается на колени, и палуба гудит, как барабан. Каюк дрался за ван Клифа до конца — такую верность не купишь ни за какое золото.", ["duration"] = 11.7, ["cues"] = { { 0, "Великан опускается на колени, и палуба гудит, как барабан." }, { 4.96, "Каюк дрался за ван Клифа до конца — такую верность не купишь ни за какое золото." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_deadmines_cookie_pull", ["enc"] = 2746, ["track"] = { ["hash"] = "7e77fe10", ["text"] = "Мурлок в поварском колпаке размахивает половником. Это Пирожок, корабельный кок, и стоит ему откусить свою пышку — раны затягиваются прямо на глазах. Кто успеет выбить пышку у него из рук, тот и выиграет этот обед.", ["duration"] = 16.6, ["cues"] = { { 0, "Мурлок в поварском колпаке размахивает половником." }, { 3.93, "Это Пирожок, корабельный кок, и стоит ему откусить свою пышку — раны затягиваются прямо на глазах." }, { 11.73, "Кто успеет выбить пышку у него из рук, тот и выиграет этот обед." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_deadmines_cookie", ["enc"] = 2746, ["track"] = { ["hash"] = "d1506b6d", ["text"] = "Половник звякает о палубу, котёл остывает. Что Пирожок варил для команды Братства, лучше не знать.", ["duration"] = 7.8, ["cues"] = { { 0, "Половник звякает о палубу, котёл остывает." }, { 3.44, "Что Пирожок варил для команды Братства, лучше не знать." } } } }, { ["role"] = "final", ["k"] = "pod", ["trig"] = "after", ["id"] = "dm_deadmines_vancleef_intro", ["enc"] = 2747, ["pos"] = 8, ["track"] = { ["hash"] = "22c5d3f5", ["text"] = "У штурвала стоит человек в красной маске — Эдвин ван Клиф. Когда-то он был мастером Гильдии каменщиков и отстраивал Штормград из пепла после Первой войны: стены, башни, собор. Когда работа была закончена, знать отказалась платить. Каменщики взбунтовались, и их изгнали из города. Ван Клиф ушёл в Западный Край, собрал обманутых и голодных и дал им общее имя — Братство Справедливости.", ["duration"] = 30.8, ["cues"] = { { 0, "У штурвала стоит человек в красной маске — Эдвин ван Клиф." }, { 4.77, "Когда-то он был мастером Гильдии каменщиков и отстраивал Штормград из пепла после Первой войны: стены, башни, собор." }, { 14.3, "Когда работа была закончена, знать отказалась платить." }, { 18.78, "Каменщики взбунтовались, и их изгнали из города." }, { 22.66, "Ван Клиф ушёл в Западный Край, собрал обманутых и голодных и дал им общее имя — Братство Справедливости." } } } }, { ["q"] = 166, ["follows"] = "dm_deadmines_vancleef_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_deadmines_hook_166", ["track"] = { ["hash"] = "dea4cb5f", ["text"] = "Именно его голову ждёт Гриан Камнегрив.", ["duration"] = 3.6, ["cues"] = { { 0, "Именно его голову ждёт Гриан Камнегрив." } } } }, { ["role"] = "final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_deadmines_vancleef_pull", ["enc"] = 2747, ["track"] = { ["hash"] = "6700f1d9", ["text"] = "Ван Клиф обнажает два клинка, и они мелькают быстрее, чем успеваешь моргнуть. Он не кричит и не грозит — он считает. Когда станет жарко, он позовёт своих людей, и бой решит тот, кто встретит их первым.", ["duration"] = 16.1, ["cues"] = { { 0, "Ван Клиф обнажает два клинка, и они мелькают быстрее, чем успеваешь моргнуть." }, { 6.27, "Он не кричит и не грозит — он считает." }, { 9.37, "Когда станет жарко, он позовёт своих людей, и бой решит тот, кто встретит их первым." } } } }, { ["role"] = "final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_deadmines_vancleef", ["enc"] = 2747, ["track"] = { ["hash"] = "0ea93ba9", ["text"] = "Эдвин ван Клиф падает, и маска наконец соскальзывает с его лица. Обычное лицо. Усталое. Лицо каменщика, который построил чужой город и не получил за это ни медяка. Корабль так и не выйдет из бухты, а Братство без головы — просто люди в красных банданах, которым некуда идти. Но кто-то дал каменщику золото на корабль, пушки и наёмников. Кто-то в Штормграде.", ["duration"] = 29.9, ["cues"] = { { 0, "Эдвин ван Клиф падает, и маска наконец соскальзывает с его лица." }, { 5.47, "Обычное лицо." }, { 6.68, "Усталое." }, { 7.44, "Лицо каменщика, который построил чужой город и не получил за это ни медяка." }, { 13.9, "Корабль так и не выйдет из бухты, а Братство без головы — просто люди в красных банданах, которым некуда идти." }, { 23.24, "Но кто-то дал каменщику золото на корабль, пушки и наёмников." }, { 28.33, "Кто-то в Штормграде." } } } }, { ["q"] = 166, ["follows"] = "dm_deadmines_vancleef", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_deadmines_fin_166", ["track"] = { ["hash"] = "a39c707d", ["text"] = "Голову ван Клифа — Гриану Камнегриву, на Сторожевой холм. Западный Край давно ждёт этой вести.", ["duration"] = 7.8, ["cues"] = { { 0, "Голову ван Клифа — Гриану Камнегриву, на Сторожевой холм." }, { 4.8, "Западный Край давно ждёт этой вести." } } } }, { ["role"] = "final", ["k"] = "bag", ["trig"] = "bag", ["id"] = "dm_deadmines_letter", ["item"] = 2874, ["track"] = { ["hash"] = "40f30d32", ["text"] = "При нём было неотосланное письмо — архитектору Баросу Алекстону, в Штормград. Отнесите его по адресу. Некоторые письма должны дойти, даже если опоздали.", ["duration"] = 12.3, ["cues"] = { { 0, "При нём было неотосланное письмо — архитектору Баросу Алекстону, в Штормград." }, { 6.24, "Отнесите его по адресу." }, { 8.22, "Некоторые письма должны дойти, даже если опоздали." } } } } }, ["bosses"] = { { ["id"] = 2741, ["npcs"] = { 644 }, ["name"] = "Rhahk'zor", ["required"] = nil, ["token"] = "rhahkzor", ["names335"] = { "Rhahk'Zor" } }, { ["id"] = 2742, ["npcs"] = { 642, 643 }, ["name"] = "Sneed", ["required"] = { 643 }, ["token"] = "sneed", ["names335"] = { "Sneed's Shredder", "Sneed" } }, { ["id"] = 3676, ["npcs"] = { 3586 }, ["name"] = "johnson", ["required"] = nil, ["token"] = "johnson", ["names335"] = { "Miner Johnson" } }, { ["id"] = 2743, ["npcs"] = { 1763 }, ["name"] = "Gilnid", ["required"] = nil, ["token"] = "gilnid", ["names335"] = { "Gilnid" } }, { ["id"] = 2744, ["npcs"] = { 647 }, ["name"] = "Captain Greenskin", ["required"] = nil, ["token"] = "greenskin", ["names335"] = { "Captain Greenskin" } }, { ["id"] = 2745, ["npcs"] = { 646 }, ["name"] = "Mr. Smite", ["required"] = nil, ["token"] = "smite", ["names335"] = { "Mr. Smite" } }, { ["id"] = 2746, ["npcs"] = { 645 }, ["name"] = "Cookie", ["required"] = nil, ["token"] = "cookie", ["names335"] = { "Cookie" } }, { ["id"] = 2747, ["npcs"] = { 639 }, ["name"] = "Edwin VanCleef", ["required"] = nil, ["token"] = "vancleef", ["names335"] = { "Edwin VanCleef" } } } },
[43] = { ["key"] = "wailing_caverns", ["order"] = { 585, 586, 588, 590, 592 }, ["layout"] = "hub", ["alias"] = {  }, ["name"] = "Пещеры Стенаний", ["events"] = { { ["id"] = "dm_wailing_caverns_prolog", ["k"] = "prolog", ["trig"] = "prolog", ["track"] = { ["hash"] = "dc3dd992", ["text"] = "Вы в Пещерах Стенаний. Ветер и пар рвутся из трещин в камне, и пещеры воют на разные голоса — отсюда и имя. Когда-то сюда спустился ночной эльф Наралекс, друид, который хотел через Изумрудный Сон вернуть Степям зелень. Сон обернулся кошмаром. Наралекс спит до сих пор, а его ученики, Друиды Клыка, приняли этот кошмар за волю природы. Звери здесь меняются на глазах, вода гниёт, и порча уже просачивается в оазисы наверху. Пещеры держат четверо Друидов Клыка, и пока жив хоть один из них, Наралекса не разбудить.", ["duration"] = 44.1, ["cues"] = { { 0, "Вы в Пещерах Стенаний." }, { 1.95, "Ветер и пар рвутся из трещин в камне, и пещеры воют на разные голоса — отсюда и имя." }, { 9.35, "Когда-то сюда спустился ночной эльф Наралекс, друид, который хотел через Изумрудный Сон вернуть Степям зелень." }, { 19, "Сон обернулся кошмаром." }, { 21.03, "Наралекс спит до сих пор, а его ученики, Друиды Клыка, приняли этот кошмар за волю природы." }, { 28.97, "Звери здесь меняются на глазах, вода гниёт, и порча уже просачивается в оазисы наверху." }, { 36.53, "Пещеры держат четверо Друидов Клыка, и пока жив хоть один из них, Наралекса не разбудить." } } } }, { ["id"] = "dm_wailing_caverns_prolog_repeat", ["k"] = "prolog", ["trig"] = "repeat", ["track"] = { ["hash"] = "0e3a8c29", ["text"] = "Снова Пещеры Стенаний. Вой всё тот же, а Друиды Клыка, похоже, нашли себе новых учеников.", ["duration"] = 7.8, ["cues"] = { { 0, "Снова Пещеры Стенаний." }, { 2.06, "Вой всё тот же, а Друиды Клыка, похоже, нашли себе новых учеников." } } } }, { ["q"] = 914, ["prio"] = 0, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_wailing_caverns_hook_914", ["track"] = { ["hash"] = "a98f083c", ["text"] = "Нара Буйногривая ждёт камни четырёх Друидов Клыка: Анакондры, Кобрана, Питонаса и Серпентиса. Каждый носит свой камень при себе.", ["duration"] = 11.7, ["cues"] = { { 0, "Нара Буйногривая ждёт камни четырёх Друидов Клыка: Анакондры, Кобрана, Питонаса и Серпентиса." }, { 8.59, "Каждый носит свой камень при себе." } } } }, { ["q"] = 1487, ["prio"] = 1, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_wailing_caverns_hook_1487", ["track"] = { ["hash"] = "84cf31b5", ["text"] = "Эбру просит проредить искажённое зверьё: загадочных опустошителей, гадюк, шаркунов и страхозубов. Здесь их больше, чем хотелось бы.", ["duration"] = 10.6, ["cues"] = { { 0, "Эбру просит проредить искажённое зверьё: загадочных опустошителей, гадюк, шаркунов и страхозубов." }, { 8.06, "Здесь их больше, чем хотелось бы." } } } }, { ["q"] = 962, ["prio"] = 2, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_wailing_caverns_hook_962", ["track"] = { ["hash"] = "5f6864d0", ["text"] = "Аптекарь Зама ждёт десять змеецветов. Они растут по всем пещерам — смотрите под ноги, а не только по сторонам.", ["duration"] = 8.6, ["cues"] = { { 0, "Аптекарь Зама ждёт десять змеецветов." }, { 3, "Они растут по всем пещерам — смотрите под ноги, а не только по сторонам." } } } }, { ["q"] = 1486, ["prio"] = 3, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_wailing_caverns_hook_1486", ["track"] = { ["hash"] = "20472549", ["text"] = "Налпаку нужны двадцать искажённых шкур. Их дают здешние искажённые звери — не проходите мимо.", ["duration"] = 7.3, ["cues"] = { { 0, "Налпаку нужны двадцать искажённых шкур." }, { 3.13, "Их дают здешние искажённые звери — не проходите мимо." } } } }, { ["prio"] = 4, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_wailing_caverns_hook_alliance", ["faction"] = "Alliance", ["track"] = { ["hash"] = "4f8456e1", ["text"] = "Это земли Орды, Альянс, и спасибо здесь вам не скажут. Но кошмар не спрашивает, под чьим знаменем вы пришли, и однажды он доберётся и до ваших лесов.", ["duration"] = 11.9, ["cues"] = { { 0, "Это земли Орды, Альянс, и спасибо здесь вам не скажут." }, { 4.52, "Но кошмар не спрашивает, под чьим знаменем вы пришли, и однажды он доберётся и до ваших лесов." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_wailing_caverns_anacondra_pull", ["enc"] = 585, ["track"] = { ["hash"] = "43f53d0d", ["text"] = "Леди Анакондра поднимает руки, и змеи у её ног вскидывают головы. Её шёпот валит в сон того, на кого упадёт её взгляд, а стоит ей заговорить о целении — раны на ней затягиваются, будто их и не было.", ["duration"] = 17, ["cues"] = { { 0, "Леди Анакондра поднимает руки, и змеи у её ног вскидывают головы." }, { 5.79, "Её шёпот валит в сон того, на кого упадёт её взгляд, а стоит ей заговорить о целении — раны на ней затягиваются, будто их и не было." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_wailing_caverns_anacondra", ["enc"] = 585, ["track"] = { ["hash"] = "0196e852", ["text"] = "Леди Анакондра падает, и змеи у её ног расползаются по щелям. Она пришла сюда целительницей, как и все ученики Наралекса. Друиды Клыка не считают себя злодеями — они уверены, что лечат Степи. Кошмар учителя стал её сном, а потом и её верой. Одним голосом в этом вое стало меньше.", ["duration"] = 24.2, ["cues"] = { { 0, "Леди Анакондра падает, и змеи у её ног расползаются по щелям." }, { 5.32, "Она пришла сюда целительницей, как и все ученики Наралекса." }, { 10.48, "Друиды Клыка не считают себя злодеями — они уверены, что лечат Степи." }, { 16.66, "Кошмар учителя стал её сном, а потом и её верой." }, { 20.8, "Одним голосом в этом вое стало меньше." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_wailing_caverns_cobrahn_pull", ["enc"] = 586, ["track"] = { ["hash"] = "7d7f8bf6", ["text"] = "Лорд Кобран шипит, и его тело вытягивается и покрывается чешуёй: друид сам становится змеем. Яд его укуса не уходит сам, а шипящий голос умеет и усыпить бойца, и затянуть собственные раны.", ["duration"] = 16.3, ["cues"] = { { 0, "Лорд Кобран шипит, и его тело вытягивается и покрывается чешуёй: друид сам становится змеем." }, { 8.04, "Яд его укуса не уходит сам, а шипящий голос умеет и усыпить бойца, и затянуть собственные раны." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_wailing_caverns_cobrahn", ["enc"] = 586, ["track"] = { ["hash"] = "6bf7e75e", ["text"] = "Лорд Кобран затихает на камнях. Друиды принимают облик зверя, чтобы понять природу изнутри. Кобран так и не нашёл дороги обратно: в этих пещерах змеиная шкура стала ему роднее собственной. Кошмар Наралекса умеет уговаривать. Тело, которое Кобран столько лет держал в змеином облике, наконец успокоилось.", ["duration"] = 25.1, ["cues"] = { { 0, "Лорд Кобран затихает на камнях." }, { 2.61, "Друиды принимают облик зверя, чтобы понять природу изнутри." }, { 7.68, "Кобран так и не нашёл дороги обратно: в этих пещерах змеиная шкура стала ему роднее собственной." }, { 15.73, "Кошмар Наралекса умеет уговаривать." }, { 18.71, "Тело, которое Кобран столько лет держал в змеином облике, наконец успокоилось." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_wailing_caverns_kresh_pull", ["enc"] = 587, ["track"] = { ["hash"] = "e11c2504", ["text"] = "Из ручья поднимается Криг — черепаха таких размеров, что панцирь его легко принять за валун. Он медлителен, но упрям, как сама пещера, и бить его придётся долго.", ["duration"] = 14.2, ["cues"] = { { 0, "Из ручья поднимается Криг — черепаха таких размеров, что панцирь его легко принять за валун." }, { 8.29, "Он медлителен, но упрям, как сама пещера, и бить его придётся долго." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_wailing_caverns_kresh", ["enc"] = 587, ["track"] = { ["hash"] = "962fa078", ["text"] = "Криг затихает, и его панцирь снова похож на обычный валун. Черепахи живут долго. Криг, наверное, помнил эти пещеры ещё до Наралекса, когда вода здесь была чистой и никто не выл в темноте. Теперь ручей снова принадлежит только воде.", ["duration"] = 19, ["cues"] = { { 0, "Криг затихает, и его панцирь снова похож на обычный валун." }, { 4.89, "Черепахи живут долго." }, { 6.74, "Криг, наверное, помнил эти пещеры ещё до Наралекса, когда вода здесь была чистой и никто не выл в темноте." }, { 15.49, "Теперь ручей снова принадлежит только воде." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_wailing_caverns_pythas_pull", ["enc"] = 588, ["track"] = { ["hash"] = "b4f8c97b", ["text"] = "Лорд Питонас поднимает руки, и воздух вокруг него густеет. Как и все Друиды Клыка, он одним словом укладывает бойца в сон и одним словом залечивает свои раны — и тянет эти слова нараспев, словно знает, что никто не посмеет его перебить.", ["duration"] = 19.4, ["cues"] = { { 0, "Лорд Питонас поднимает руки, и воздух вокруг него густеет." }, { 4.86, "Как и все Друиды Клыка, он одним словом укладывает бойца в сон и одним словом залечивает свои раны — и тянет эти слова нараспев, словно знает, что никто не посмеет его перебить." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_wailing_caverns_pythas", ["enc"] = 588, ["track"] = { ["hash"] = "4c624e88", ["text"] = "Лорд Питонас оседает на землю. Порча течёт через эти пещеры, как кровь по жилам, и вода здесь давно не чистая. Друиды Клыка верили, что перекраивают Степи по воле природы. Природа, похоже, с ними не согласилась. Змеи в пещерах всё так же шипят, но хозяев у них стало на одного меньше.", ["duration"] = 23, ["cues"] = { { 0, "Лорд Питонас оседает на землю." }, { 2.51, "Порча течёт через эти пещеры, как кровь по жилам, и вода здесь давно не чистая." }, { 9.01, "Друиды Клыка верили, что перекраивают Степи по воле природы." }, { 14.03, "Природа, похоже, с ними не согласилась." }, { 17.28, "Змеи в пещерах всё так же шипят, но хозяев у них стало на одного меньше." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_wailing_caverns_skum_pull", ["enc"] = 589, ["track"] = { ["hash"] = "8ca2dd1f", ["text"] = "Из воды выползает Шкам — громовой ящер, которого кошмар раздул до чудовищных размеров. Он мечет молнии, и те перескакивают с одного бойца на другого — горе тем, кто стоит плечом к плечу.", ["duration"] = 15.4, ["cues"] = { { 0, "Из воды выползает Шкам — громовой ящер, которого кошмар раздул до чудовищных размеров." }, { 7.27, "Он мечет молнии, и те перескакивают с одного бойца на другого — горе тем, кто стоит плечом к плечу." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_wailing_caverns_skum", ["enc"] = 589, ["track"] = { ["hash"] = "071c6f0f", ["text"] = "Шкам затихает. Громовые ящеры водятся в Степях повсюду, но такого, как он, вырастил только кошмар Наралекса. Даже молнии в нём были чужие — подарок кошмара. А шкура искажена не меньше, чем у прочего здешнего зверья.", ["duration"] = 18.1, ["cues"] = { { 0, "Шкам затихает." }, { 1.22, "Громовые ящеры водятся в Степях повсюду, но такого, как он, вырастил только кошмар Наралекса." }, { 9.12, "Даже молнии в нём были чужие — подарок кошмара." }, { 13.22, "А шкура искажена не меньше, чем у прочего здешнего зверья." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_wailing_caverns_serpentis_pull", ["enc"] = 590, ["track"] = { ["hash"] = "a3e0abb4", ["text"] = "Лорд Серпентис взмахивает руками, и шипение заполняет пещеру. Его дремота валит бойца с ног посреди боя, а целебные слова поднимают его самого, сколько бы ран вы ему ни нанесли, — пока чей-то удар не оборвёт их на полуслове.", ["duration"] = 17.4, ["cues"] = { { 0, "Лорд Серпентис взмахивает руками, и шипение заполняет пещеру." }, { 4.78, "Его дремота валит бойца с ног посреди боя, а целебные слова поднимают его самого, сколько бы ран вы ему ни нанесли, — пока чей-то удар не оборвёт их на полуслове." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_wailing_caverns_serpentis", ["enc"] = 590, ["track"] = { ["hash"] = "969e7631", ["text"] = "Лорд Серпентис падает, и его змеи уползают в темноту. Друиды Клыка поклялись исцелить Степи, а сами растили в пещерах чудовищ. Самое страшное в кошмаре то, что спящий верит, будто всё идёт как надо. Серпентис был уверен, что служит природе, до последнего вздоха.", ["duration"] = 23.5, ["cues"] = { { 0, "Лорд Серпентис падает, и его змеи уползают в темноту." }, { 4.88, "Друиды Клыка поклялись исцелить Степи, а сами растили в пещерах чудовищ." }, { 11.56, "Самое страшное в кошмаре то, что спящий верит, будто всё идёт как надо." }, { 17.98, "Серпентис был уверен, что служит природе, до последнего вздоха." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_wailing_caverns_verdan_pull", ["enc"] = 591, ["track"] = { ["hash"] = "310be4db", ["text"] = "Вердан Вечноживущий поднимается из зарослей и шагает к вам — исполинское болотное чудище, напоённое кошмаром до последней лозы. Когда из-под камней рвутся его хваткие лозы, достаётся всем, кто стоит рядом.", ["duration"] = 17.1, ["cues"] = { { 0, "Вердан Вечноживущий поднимается из зарослей и шагает к вам — исполинское болотное чудище, напоённое кошмаром до последней лозы." }, { 10.63, "Когда из-под камней рвутся его хваткие лозы, достаётся всем, кто стоит рядом." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_wailing_caverns_verdan", ["enc"] = 591, ["track"] = { ["hash"] = "af1f8ac8", ["text"] = "Вердан Вечноживущий валится наземь, и лозы его медленно опадают. Имя оказалось хвастовством. Хотя друиды сказали бы, что в природе ничто не умирает до конца, — а в этих пещерах такие слова звучат как угроза.", ["duration"] = 17.9, ["cues"] = { { 0, "Вердан Вечноживущий валится наземь, и лозы его медленно опадают." }, { 5.69, "Имя оказалось хвастовством." }, { 8.1, "Хотя друиды сказали бы, что в природе ничто не умирает до конца, — а в этих пещерах такие слова звучат как угроза." } } } }, { ["encs"] = { 585, 586, 588, 590 }, ["role"] = "final", ["k"] = "pod", ["trig"] = "afterAll", ["id"] = "dm_wailing_caverns_mutanus_intro", ["enc"] = 592, ["pos"] = 8, ["track"] = { ["hash"] = "044b5ae9", ["text"] = "Друиды Клыка мертвы, все четверо, и Послушник Наралекса у входа может наконец начать обряд. Он проведёт вас к своему учителю: Наралекс спит в дальнем зале, где кошмар гуще всего. Тихо обряд не пройдёт — кошмар пошлёт своих тварей, а за ними и того, кто сторожит сон. Берегите Послушника: без него Наралекса не разбудить.", ["duration"] = 28.6, ["cues"] = { { 0, "Друиды Клыка мертвы, все четверо, и Послушник Наралекса у входа может наконец начать обряд." }, { 8.4, "Он проведёт вас к своему учителю: Наралекс спит в дальнем зале, где кошмар гуще всего." }, { 16.16, "Тихо обряд не пройдёт — кошмар пошлёт своих тварей, а за ними и того, кто сторожит сон." }, { 23.99, "Берегите Послушника: без него Наралекса не разбудить." } } } }, { ["role"] = "final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_wailing_caverns_mutanus_pull", ["enc"] = 592, ["track"] = { ["hash"] = "171d6ad3", ["text"] = "Из воды поднимается Мутанус Пожиратель — исполинский бледный мурлок, которого вылепил кошмар Наралекса. Его рёв обращает в бегство то одного бойца, то другого, громовой грохот бьёт по всем вокруг, а когда он заводит песнь кошмара, тот, кого она настигнет, проваливается в чужой страшный сон.", ["duration"] = 23.8, ["cues"] = { { 0, "Из воды поднимается Мутанус Пожиратель — исполинский бледный мурлок, которого вылепил кошмар Наралекса." }, { 8.6, "Его рёв обращает в бегство то одного бойца, то другого, громовой грохот бьёт по всем вокруг, а когда он заводит песнь кошмара, тот, кого она настигнет, проваливается в чужой страшный сон." } } } }, { ["role"] = "final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_wailing_caverns_mutanus", ["enc"] = 592, ["track"] = { ["hash"] = "ac0d0d49", ["text"] = "Мутанус Пожиратель падает, и вой пещер на миг стихает. Наралекс открывает глаза и видит, что натворил его сон: искажённых зверей, гнилую воду, погибших учеников. Изумрудный Сон велик, и кошмар в нём не кончился. Но Степи сегодня могут вздохнуть свободнее.", ["duration"] = 22.5, ["cues"] = { { 0, "Мутанус Пожиратель падает, и вой пещер на миг стихает." }, { 4.83, "Наралекс открывает глаза и видит, что натворил его сон: искажённых зверей, гнилую воду, погибших учеников." }, { 14.34, "Изумрудный Сон велик, и кошмар в нём не кончился." }, { 18.69, "Но Степи сегодня могут вздохнуть свободнее." } } } }, { ["q"] = 914, ["follows"] = "dm_wailing_caverns_mutanus", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_wailing_caverns_fin_914", ["track"] = { ["hash"] = "4f3873ea", ["text"] = "Камни Друидов Клыка — Наре Буйногривой, на Громовой Утёс. Пусть хоть кто-то в Степях узнает, чем кончился сон Наралекса.", ["duration"] = 10.5, ["cues"] = { { 0, "Камни Друидов Клыка — Наре Буйногривой, на Громовой Утёс." }, { 5.16, "Пусть хоть кто-то в Степях узнает, чем кончился сон Наралекса." } } } }, { ["role"] = "final", ["k"] = "bag", ["trig"] = "bag", ["id"] = "dm_wailing_caverns_shard", ["item"] = 10441, ["track"] = { ["hash"] = "efae688e", ["text"] = "С Мутануса выпал светящийся осколок: ярко-зелёный, а в глубине клубится дым. Отнесите его в Кабестан — там найдётся тот, кто знает, что это такое.", ["duration"] = 12.2, ["cues"] = { { 0, "С Мутануса выпал светящийся осколок: ярко-зелёный, а в глубине клубится дым." }, { 6.51, "Отнесите его в Кабестан — там найдётся тот, кто знает, что это такое." } } } } }, ["bosses"] = { { ["id"] = 585, ["npcs"] = { 3671 }, ["name"] = "Lady Anacondra", ["required"] = nil, ["token"] = "anacondra", ["names335"] = { "Lady Anacondra" } }, { ["id"] = 586, ["npcs"] = { 3669 }, ["name"] = "Lord Cobrahn", ["required"] = nil, ["token"] = "cobrahn", ["names335"] = { "Lord Cobrahn" } }, { ["id"] = 587, ["npcs"] = { 3653 }, ["name"] = "Kresh", ["required"] = nil, ["token"] = "kresh", ["names335"] = { "Kresh" } }, { ["id"] = 588, ["npcs"] = { 3670 }, ["name"] = "Lord Pythas", ["required"] = nil, ["token"] = "pythas", ["names335"] = { "Lord Pythas" } }, { ["id"] = 589, ["npcs"] = { 3674 }, ["name"] = "Skum", ["required"] = nil, ["token"] = "skum", ["names335"] = { "Skum" } }, { ["id"] = 590, ["npcs"] = { 3673 }, ["name"] = "Lord Serpentis", ["required"] = nil, ["token"] = "serpentis", ["names335"] = { "Lord Serpentis" } }, { ["id"] = 591, ["npcs"] = { 5775 }, ["name"] = "Verdan the Everliving", ["required"] = nil, ["token"] = "verdan", ["names335"] = { "Verdan the Everliving" } }, { ["id"] = 592, ["npcs"] = { 3654 }, ["name"] = "Mutanus the Devourer", ["required"] = nil, ["token"] = "mutanus", ["names335"] = { "Mutanus the Devourer" } } } },
[47] = { ["key"] = "razorfen_kraul", ["order"] = { 2778 }, ["layout"] = "branching", ["alias"] = {  }, ["name"] = "Лабиринты Иглошкурых", ["events"] = { { ["id"] = "dm_razorfen_kraul_prolog", ["k"] = "prolog", ["trig"] = "prolog", ["track"] = { ["hash"] = "53d139f4", ["text"] = "Вы в Лабиринтах Иглошкурых — в сердце колючих зарослей на юге Степей. Десять тысяч лет назад здесь пал Агамагган, полубог-вепрь, бившийся с Пылающим Легионом, и там, где пролилась его кровь, из земли полезли исполинские терновые лозы. Иглошкурые считают себя его детьми и чтут эти заросли как святыню. Ходы здесь петляют, перекрещиваются и уходят друг над другом, так что заблудиться проще, чем кажется. А где-то в глубине сидит старая ведьма, которой подчиняется весь этот колючий народ.", ["duration"] = 41, ["cues"] = { { 0, "Вы в Лабиринтах Иглошкурых — в сердце колючих зарослей на юге Степей." }, { 5.9, "Десять тысяч лет назад здесь пал Агамагган, полубог-вепрь, бившийся с Пылающим Легионом, и там, где пролилась его кровь, из земли полезли исполинские терновые лозы." }, { 19.68, "Иглошкурые считают себя его детьми и чтут эти заросли как святыню." }, { 25.42, "Ходы здесь петляют, перекрещиваются и уходят друг над другом, так что заблудиться проще, чем кажется." }, { 33.84, "А где-то в глубине сидит старая ведьма, которой подчиняется весь этот колючий народ." } } } }, { ["id"] = "dm_razorfen_kraul_prolog_repeat", ["k"] = "prolog", ["trig"] = "repeat", ["track"] = { ["hash"] = "fcb3a09a", ["text"] = "Снова Лабиринты Иглошкурых. Колючки успели затянуть старые тропы, но дорогу вы помните.", ["duration"] = 8, ["cues"] = { { 0, "Снова Лабиринты Иглошкурых." }, { 2.58, "Колючки успели затянуть старые тропы, но дорогу вы помните." } } } }, { ["q"] = 1102, ["prio"] = 0, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_razorfen_kraul_hook_1102", ["track"] = { ["hash"] = "4b381336", ["text"] = "Ольд Каменное Копье из Громового Утеса ждёт сердце Чарлги. Эти земли были священны для его народа, и он хочет спокойно умереть, зная, что ведьмы больше нет.", ["duration"] = 13.3, ["cues"] = { { 0, "Ольд Каменное Копьё из Громового Утёса ждёт сердце Чарлги." }, { 4.89, "Эти земли были священны для его народа, и он хочет спокойно умереть, зная, что ведьмы больше нет." } } } }, { ["q"] = 1101, ["prio"] = 1, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_razorfen_kraul_hook_1101", ["track"] = { ["hash"] = "2abc7334", ["text"] = "Фалфиндел в Таланааре ждёт медальон Чарлги. Храбрый дворф Хмурень погиб, чтобы эта весть дошла, — пусть не зря.", ["duration"] = 9.2, ["cues"] = { { 0, "Фалфиндел в Таланааре ждёт медальон Чарлги." }, { 3.68, "Храбрый дворф Хмурень погиб, чтобы эта весть дошла, — пусть не зря." } } } }, { ["q"] = 1221, ["prio"] = 2, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_razorfen_kraul_hook_1221", ["track"] = { ["hash"] = "408147a9", ["text"] = "Мебок Миззрикс из Кабестана ждёт корни синелиста. Выпустите шмыгуноса, подгоните его палочкой — и пусть нюхает.", ["duration"] = 8.5, ["cues"] = { { 0, "Мебок Миззрикс из Кабестана ждёт корни синелиста." }, { 3.86, "Выпустите шмыгуноса, подгоните его палочкой — и пусть нюхает." } } } }, { ["q"] = 1109, ["prio"] = 3, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_razorfen_kraul_hook_1109", ["track"] = { ["hash"] = "3dbe048d", ["text"] = "Мастер-аптекарь Фаранелл ждёт гуано летучих мышей Лабиринтов. Мыши гнездятся в дальних пещерах, так что запаситесь терпением и крепким носом.", ["duration"] = 11, ["cues"] = { { 0, "Мастер-аптекарь Фаранелл ждёт гуано летучих мышей Лабиринтов." }, { 4.92, "Мыши гнездятся в дальних пещерах, так что запаситесь терпением и крепким носом." } } } }, { ["prio"] = 4, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_razorfen_kraul_hook_alliance", ["faction"] = "Alliance", ["track"] = { ["hash"] = "b47ced8a", ["text"] = "Это земли Орды, Альянс. Но Чарлга не разбирает флагов: её воинство бросается на всех, кто подходит к зарослям.", ["duration"] = 9.3, ["cues"] = { { 0, "Это земли Орды, Альянс." }, { 2.17, "Но Чарлга не разбирает флагов: её воинство бросается на всех, кто подходит к зарослям." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_razorfen_kraul_roogug_pull", ["enc"] = 2773, ["track"] = { ["hash"] = "f62e2de5", ["text"] = "Ругуг, шаман иглошкурых, взывает к земле, и рядом из камня поднимается грохотун. Пока земляной слуга на ногах, бой идёт на два фронта, а камень, в отличие от шамана, не знает усталости.", ["duration"] = 15.6, ["cues"] = { { 0, "Ругуг, шаман иглошкурых, взывает к земле, и рядом из камня поднимается грохотун." }, { 6.92, "Пока земляной слуга на ногах, бой идёт на два фронта, а камень, в отличие от шамана, не знает усталости." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_razorfen_kraul_roogug", ["enc"] = 2773, ["track"] = { ["hash"] = "9ec3077b", ["text"] = "Ругуг падает в колючки, и каменный слуга рассыпается вслед за ним. Шаманы иглошкурых говорят с землёй так же, как шаманы Орды, только земля отвечает им злее. В этих зарослях даже камень на стороне хозяев, и здесь очень быстро учишься уважать каждый шорох.", ["duration"] = 21, ["cues"] = { { 0, "Ругуг падает в колючки, и каменный слуга рассыпается вслед за ним." }, { 5.45, "Шаманы иглошкурых говорят с землёй так же, как шаманы Орды, только земля отвечает им злее." }, { 12.91, "В этих зарослях даже камень на стороне хозяев, и здесь очень быстро учишься уважать каждый шорох." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_razorfen_kraul_aggem_pull", ["enc"] = 2774, ["track"] = { ["hash"] = "20a7ecbc", ["text"] = "Аггем Терновое Проклятие зовёт на помощь духов вепрей, а раны латает цепным исцелением — долгой молитвой, которую он читает так, будто её никто не посмеет прервать. Пока дух-вепрь рядом, хозяин дерётся не один.", ["duration"] = 18.2, ["cues"] = { { 0, "Аггем Терновое Проклятие зовёт на помощь духов вепрей, а раны латает цепным исцелением — долгой молитвой, которую он читает так, будто её никто не посмеет прервать." }, { 14.33, "Пока дух-вепрь рядом, хозяин дерётся не один." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_razorfen_kraul_aggem", ["enc"] = 2774, ["track"] = { ["hash"] = "e6201f37", ["text"] = "Аггем затихает, и призрачные вепри тают в воздухе. Для иглошкурых вепрь — не зверь, а родня: они верят, что произошли от Агамаггана. Погонщики вроде Аггема у них и жрецы, и укротители разом. Без него стадо в загонах станет только злее: вепри помнят руку хозяина и не прощают тех, кто её отнял.", ["duration"] = 25.2, ["cues"] = { { 0, "Аггем затихает, и призрачные вепри тают в воздухе." }, { 4.46, "Для иглошкурых вепрь — не зверь, а родня: они верят, что произошли от Агамаггана." }, { 11.35, "Погонщики вроде Аггема у них и жрецы, и укротители разом." }, { 16.36, "Без него стадо в загонах станет только злее: вепри помнят руку хозяина и не прощают тех, кто её отнял." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_razorfen_kraul_jargba_pull", ["enc"] = 2775, ["track"] = { ["hash"] = "e45f9d91", ["text"] = "Джаргба шепчет на мёртвом наречии, и чужая воля впивается в разум одного из вас. Подчинённый товарищ поднимет оружие на своих — а чары держат его ровно до тех пор, пока жив сам Джаргба.", ["duration"] = 15.4, ["cues"] = { { 0, "Джаргба шепчет на мёртвом наречии, и чужая воля впивается в разум одного из вас." }, { 6.8, "Подчинённый товарищ поднимет оружие на своих — а чары держат его ровно до тех пор, пока жив сам Джаргба." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_razorfen_kraul_jargba", ["enc"] = 2775, ["track"] = { ["hash"] = "8a3453ee", ["text"] = "Вестник смерти Джаргба падает, и шёпот обрывается. Его культ говорит со смертью, а не с землёй, и для иглошкурых это что-то новое. Старые шаманы так не умели. Кто-то научил их говорить с мёртвыми, и учитель, похоже, пришёл совсем не из Степей. Такие уроки даром не дают — за них потом платят.", ["duration"] = 24.2, ["cues"] = { { 0, "Вестник смерти Джаргба падает, и шёпот обрывается." }, { 4.26, "Его культ говорит со смертью, а не с землёй, и для иглошкурых это что-то новое." }, { 10.87, "Старые шаманы так не умели." }, { 13.22, "Кто-то научил их говорить с мёртвыми, и учитель, похоже, пришёл совсем не из Степей." }, { 20.22, "Такие уроки даром не дают — за них потом платят." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_razorfen_kraul_ramtusk_pull", ["enc"] = 2776, ["track"] = { ["hash"] = "3ee9ee88", ["text"] = "Властитель Злоклык бьёт тяжело и прицельно, а по бокам у него стоят копейщики. Когда они раскручиваются в крутящемся заряде, сталь режет всех, кто оказался рядом, а удары самого властителя выдержит не всякий щит.", ["duration"] = 16.2, ["cues"] = { { 0, "Властитель Злоклык бьёт тяжело и прицельно, а по бокам у него стоят копейщики." }, { 6.06, "Когда они раскручиваются в крутящемся заряде, сталь режет всех, кто оказался рядом, а удары самого властителя выдержит не всякий щит." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_razorfen_kraul_ramtusk", ["enc"] = 2776, ["track"] = { ["hash"] = "648029c7", ["text"] = "Злоклык рухнул, и боевые кличи в ходах смолкают. Его копейщики дрались за него до последнего, но и они не устояли. Иглошкурые плодятся быстро, а вот вожаков среди них немного, и нового Лабиринтам придётся поискать.", ["duration"] = 17.1, ["cues"] = { { 0, "Злоклык рухнул, и боевые кличи в ходах смолкают." }, { 4.01, "Его копейщики дрались за него до последнего, но и они не устояли." }, { 9.33, "Иглошкурые плодятся быстро, а вот вожаков среди них немного, и нового Лабиринтам придётся поискать." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_razorfen_kraul_agathelos_pull", ["enc"] = 2777, ["track"] = { ["hash"] = "2e16aab4", ["text"] = "Агателос Свирепый, огромный вепрь, рвётся вперёд. Тот, кто встанет у него на пути, принимает удар за ударом, а когда зверь впадает в исступление, клыки бьют ещё чаще, и каждый удар норовит достать до кости.", ["duration"] = 17.4, ["cues"] = { { 0, "Агателос Свирепый, огромный вепрь, рвётся вперёд." }, { 4.11, "Тот, кто встанет у него на пути, принимает удар за ударом, а когда зверь впадает в исступление, клыки бьют ещё чаще, и каждый удар норовит достать до кости." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_razorfen_kraul_agathelos", ["enc"] = 2777, ["track"] = { ["hash"] = "f655ba3a", ["text"] = "Агателос Свирепый валится в пыль, и колючки вокруг будто притихают. Вепри для иглошкурых — родня и святыня, но этого зверя, похоже, побаивались даже они. Теперь бояться некого.", ["duration"] = 14.8, ["cues"] = { { 0, "Агателос Свирепый валится в пыль, и колючки вокруг будто притихают." }, { 5.69, "Вепри для иглошкурых — родня и святыня, но этого зверя, похоже, побаивались даже они." }, { 12.98, "Теперь бояться некого." } } } }, { ["role"] = "final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_razorfen_kraul_charlga_pull", ["enc"] = 2778, ["track"] = { ["hash"] = "501fb5a1", ["text"] = "Чарлга Остробок, старая ведьма, что повелевает нечестивым воинством Лабиринтов, встречает вас цепным ударом — молнии скачут от одного к другому, пока заклинание не сорвут. Шип маны выжигает силы у заклинателей, а «Чистота» временами делает старуху неуязвимой, и тогда её не берут ни сталь, ни чары.", ["duration"] = 24.6, ["cues"] = { { 0, "Чарлга Остробок, старая ведьма, что повелевает нечестивым воинством Лабиринтов, встречает вас цепным ударом — молнии скачут от одного к другому, пока заклинание не сорвут." }, { 14.32, "Шип маны выжигает силы у заклинателей, а «Чистота» временами делает старуху неуязвимой, и тогда её не берут ни сталь, ни чары." } } } }, { ["role"] = "final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_razorfen_kraul_charlga", ["enc"] = 2778, ["track"] = { ["hash"] = "9552124a", ["text"] = "Чарлга Остробок падает, и в Лабиринтах становится тихо. Без её воли иглошкурые разбредутся по своим норам, и Степи вздохнут свободнее. Говорили, что карга вела переговоры с Плетью, и, похоже, говорили не зря. Мёртвые давно присматриваются к детям Агамаггана.", ["duration"] = 21.8, ["cues"] = { { 0, "Чарлга Остробок падает, и в Лабиринтах становится тихо." }, { 4.8, "Без её воли иглошкурые разбредутся по своим норам, и Степи вздохнут свободнее." }, { 11.54, "Говорили, что карга вела переговоры с Плетью, и, похоже, говорили не зря." }, { 17.81, "Мёртвые давно присматриваются к детям Агамаггана." } } } }, { ["q"] = 1102, ["follows"] = "dm_razorfen_kraul_charlga", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_razorfen_kraul_fin_1102", ["track"] = { ["hash"] = "97d86ed2", ["text"] = "Сердце Чарлги — Ольду Каменному Копью в Громовой Утес. Он ждал этого много лет.", ["duration"] = 7.5, ["cues"] = { { 0, "Сердце Чарлги — Ольду Каменному Копью в Громовой Утёс." }, { 5.33, "Он ждал этого много лет." } } } }, { ["q"] = 1101, ["follows"] = "dm_razorfen_kraul_charlga", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_razorfen_kraul_fin_1101", ["track"] = { ["hash"] = "31244cc1", ["text"] = "Медальон Чарлги — Фалфинделу в Таланаар. Жертва Хмурня была не напрасной.", ["duration"] = 6.7, ["cues"] = { { 0, "Медальон Чарлги — Фалфинделу в Таланаар." }, { 3.78, "Жертва Хмурня была не напрасной." } } } }, { ["q"] = 1142, ["follows"] = "dm_razorfen_kraul_charlga", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_razorfen_kraul_fin_1142", ["track"] = { ["hash"] = "3d1e8f42", ["text"] = "Подвеску Трешалы украл кто-то из иглошкурых. Если её ещё нет в вашей сумке, проверяйте добычу: Гералат просил вернуть её жене в Дарнасс.", ["duration"] = 10.3, ["cues"] = { { 0, "Подвеску Трешалы украл кто-то из иглошкурых." }, { 3.44, "Если её ещё нет в вашей сумке, проверяйте добычу: Гералат просил вернуть её жене в Дарнасс." } } } }, { ["q"] = 1144, ["follows"] = "dm_razorfen_kraul_charlga", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_razorfen_kraul_fin_1144", ["track"] = { ["hash"] = "023e56bf", ["text"] = "Импортер Вилликс ждёт, что вы выведете его из Лабиринтов. Гоблин обещал хорошо заплатить — и, кажется, впервые в жизни не торгуется.", ["duration"] = 10.1, ["cues"] = { { 0, "Импортер Вилликс ждёт, что вы выведете его из Лабиринтов." }, { 4.41, "Гоблин обещал хорошо заплатить — и, кажется, впервые в жизни не торгуется." } } } }, { ["role"] = "final", ["k"] = "bag", ["trig"] = "bag", ["id"] = "dm_razorfen_kraul_scroll", ["item"] = 17008, ["track"] = { ["hash"] = "7eb9a7e2", ["text"] = "При карге нашёлся маленький свиток — письмо посланника Малкина. Плеть обещает карге безграничную власть над Степью в обмен на свободу действий в этих землях. Отнесите его Вариматрасу в Подгород.", ["duration"] = 14.8, ["cues"] = { { 0, "При карге нашёлся маленький свиток — письмо посланника Малкина." }, { 4.89, "Плеть обещает карге безграничную власть над Степью в обмен на свободу действий в этих землях." }, { 12.09, "Отнесите его Вариматрасу в Подгород." } } } } }, ["bosses"] = { { ["id"] = 2773, ["npcs"] = { 6168 }, ["name"] = "Roogug", ["required"] = nil, ["token"] = "roogug", ["names335"] = { "Roogug" } }, { ["id"] = 2774, ["npcs"] = { 4424 }, ["name"] = "Aggem Thorncurse", ["required"] = nil, ["token"] = "aggem", ["names335"] = { "Aggem Thorncurse" } }, { ["id"] = 2775, ["npcs"] = { 4428 }, ["name"] = "Death Speaker Jargba", ["required"] = nil, ["token"] = "jargba", ["names335"] = { "Death Speaker Jargba" } }, { ["id"] = 2776, ["npcs"] = { 4420 }, ["name"] = "Overlord Ramtusk", ["required"] = nil, ["token"] = "ramtusk", ["names335"] = { "Overlord Ramtusk" } }, { ["id"] = 2777, ["npcs"] = { 4422 }, ["name"] = "Agathelos the Raging", ["required"] = nil, ["token"] = "agathelos", ["names335"] = { "Agathelos the Raging" } }, { ["id"] = 2778, ["npcs"] = { 4421 }, ["name"] = "Charlga Razorflank", ["required"] = nil, ["token"] = "charlga", ["names335"] = { "Charlga Razorflank" } } } },
[48] = { ["key"] = "blackfathom_deeps", ["order"] = { 2911, 2910 }, ["layout"] = "linear_with_side", ["alias"] = { [2761] = 2916, [2762] = 2915, [2710] = 2913, [2763] = 2914, [2891] = 2910, [2764] = 2913, [2697] = 2916, [2765] = 2912, [2766] = 2911, [2699] = 2915, [2767] = 2910, [2825] = 2911 }, ["name"] = "Непроглядная Пучина", ["events"] = { { ["id"] = "dm_blackfathom_deeps_prolog", ["k"] = "prolog", ["trig"] = "prolog", ["track"] = { ["hash"] = "cdd65281", ["text"] = "Вы в Непроглядной Пучине. Когда-то здесь стоял храм Элуны, и ночные эльфы молились у лунного колодца. Потом из глубин просочилась порча Древнего бога, колодец был осквернён, а храм лежит в руинах, наполовину под водой. Теперь в затопленных залах хозяйничают наги и культисты Сумеречного Молота. Вода здесь чёрная, и не всё, что в ней плавает, вы успеете заметить.", ["duration"] = 30.2, ["cues"] = { { 0, "Вы в Непроглядной Пучине." }, { 2.14, "Когда-то здесь стоял храм Элуны, и ночные эльфы молились у лунного колодца." }, { 8.55, "Потом из глубин просочилась порча Древнего бога, колодец был осквернён, а храм лежит в руинах, наполовину под водой." }, { 18.33, "Теперь в затопленных залах хозяйничают наги и культисты Сумеречного Молота." }, { 24.74, "Вода здесь чёрная, и не всё, что в ней плавает, вы успеете заметить." } } } }, { ["id"] = "dm_blackfathom_deeps_prolog_repeat", ["k"] = "prolog", ["trig"] = "repeat", ["track"] = { ["hash"] = "1faa23c9", ["text"] = "Снова Непроглядная Пучина. Вода всё так же черна, а культисты Сумеречного Молота, похоже, успели прислать замену.", ["duration"] = 9.4, ["cues"] = { { 0, "Снова Непроглядная Пучина." }, { 2.27, "Вода всё так же черна, а культисты Сумеречного Молота, похоже, успели прислать замену." } } } }, { ["q"] = 1198, ["prio"] = 0, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_blackfathom_deeps_hook_1198", ["track"] = { ["hash"] = "bac04f3c", ["text"] = "Страж Талрид из ордена Серебряного Рассвета ушёл сюда на разведку и пропал. Ищите его у Пруда Аск'ара, где в озере живёт огромная черепаха.", ["duration"] = 11.8, ["cues"] = { { 0, "Страж Талрид из ордена Серебряного Рассвета ушёл сюда на разведку и пропал." }, { 6.42, "Ищите его у Пруда Аск'ара, где в озере живёт огромная черепаха." } } } }, { ["q"] = 6921, ["prio"] = 1, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_blackfathom_deeps_hook_6921", ["track"] = { ["hash"] = "962a7dbb", ["text"] = "Дже'неу Санкри ждёт глубинный сердечник из Руин святилища Луны. Он спрятан в глубинном камне под водой — придётся нырять.", ["duration"] = 9.8, ["cues"] = { { 0, "Дже'неу Санкри ждёт глубинный сердечник из Руин святилища Луны." }, { 5.25, "Он спрятан в глубинном камне под водой — придётся нырять." } } } }, { ["q"] = 971, ["prio"] = 2, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_blackfathom_deeps_hook_971", ["track"] = { ["hash"] = "727a7030", ["text"] = "Геррик Костохват ищет манускрипт Лоргалиса — древние знания, которым лучше бы лежать на дне. Манускрипт лежит в старом сундуке у Пруда Аск'ара, где живёт черепаха.", ["duration"] = 12.8, ["cues"] = { { 0, "Геррик Костохват ищет манускрипт Лоргалиса — древние знания, которым лучше бы лежать на дне." }, { 7.37, "Манускрипт лежит в старом сундуке у Пруда Аск'ара, где живёт черепаха." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackfathom_deeps_ghamoo_pull", ["enc"] = 2916, ["track"] = { ["hash"] = "4451a7d3", ["text"] = "Гхаму-ра поднимается из воды — черепаха, чей панцирь не возьмёт и топор. Она топчет всё на своём пути, и под её ноги может угодить любой из вас, а не только тот, кто стоит впереди.", ["duration"] = 14.1, ["cues"] = { { 0, "Гхаму-ра поднимается из воды — черепаха, чей панцирь не возьмёт и топор." }, { 5.71, "Она топчет всё на своём пути, и под её ноги может угодить любой из вас, а не только тот, кто стоит впереди." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackfathom_deeps_ghamoo", ["enc"] = 2916, ["track"] = { ["hash"] = "a287b662", ["text"] = "Гхаму-ра затихает. Черепахи жили в этих водах задолго до культа, но порча Древнего бога, что просочилась в храм, не пощадила никого — ни камень, ни воду, ни тех, кто в ней живёт. Озеро снова тихое, но прозрачной вода в нём так и не стала.", ["duration"] = 20.1, ["cues"] = { { 0, "Гхаму-ра затихает." }, { 1.63, "Черепахи жили в этих водах задолго до культа, но порча Древнего бога, что просочилась в храм, не пощадила никого — ни камень, ни воду, ни тех, кто в ней живёт." }, { 15.12, "Озеро снова тихое, но прозрачной вода в нём так и не стала." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackfathom_deeps_sarevess_pull", ["enc"] = 2915, ["track"] = { ["hash"] = "9b9f8b99", ["text"] = "Леди Саревесс вскидывает руки, и вода у её ног вскипает. Наги колдуют так же легко, как дерутся: на кого падут её чары, тот станет медлительным, будто идёт по пояс в иле, и сам эту тяжесть не стряхнёт.", ["duration"] = 17, ["cues"] = { { 0, "Леди Саревесс вскидывает руки, и вода у её ног вскипает." }, { 4.88, "Наги колдуют так же легко, как дерутся: на кого падут её чары, тот станет медлительным, будто идёт по пояс в иле, и сам эту тяжесть не стряхнёт." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackfathom_deeps_sarevess", ["enc"] = 2915, ["track"] = { ["hash"] = "e3e9cdac", ["text"] = "Леди Саревесс падает. Наги — потомки высокорождённых, ушедших под воду десять тысяч лет назад. Здесь они в союзе с Сумеречным Молотом и вместе с культом копят силу старинных обрядов. Что нагам нужно в храме Элуны, которой молились их предки? Может быть, прощение. А может быть, наоборот.", ["duration"] = 24.5, ["cues"] = { { 0, "Леди Саревесс падает." }, { 1.93, "Наги — потомки высокорождённых, ушедших под воду десять тысяч лет назад." }, { 8.11, "Здесь они в союзе с Сумеречным Молотом и вместе с культом копят силу старинных обрядов." }, { 15.68, "Что нагам нужно в храме Элуны, которой молились их предки?" }, { 20.78, "Может быть, прощение." }, { 22.63, "А может быть, наоборот." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackfathom_deeps_gelihast_pull", ["enc"] = 2914, ["track"] = { ["hash"] = "d76c75da", ["text"] = "Гелихаст, вожак мурлоков, булькает боевой клич, и его племя отвечает со всех сторон. Он швыряет сеть в того, кто стоит впереди: пока боец в путах, ему не уйти и не догнать.", ["duration"] = 13.9, ["cues"] = { { 0, "Гелихаст, вожак мурлоков, булькает боевой клич, и его племя отвечает со всех сторон." }, { 6.89, "Он швыряет сеть в того, кто стоит впереди: пока боец в путах, ему не уйти и не догнать." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackfathom_deeps_gelihast", ["enc"] = 2914, ["track"] = { ["hash"] = "a48e9b7b", ["text"] = "Гелихаст затихает, и мурлоки разбегаются по лужам. Храм Элуны осквернён, но не весь: неподалёку стоит древний камень, который ещё хранит благословение Пучины. Коснитесь его — Пучина помнит, как благословлять тех, кто пришёл не с порчей.", ["duration"] = 19.9, ["cues"] = { { 0, "Гелихаст затихает, и мурлоки разбегаются по лужам." }, { 4.39, "Храм Элуны осквернён, но не весь: неподалёку стоит древний камень, который ещё хранит благословение Пучины." }, { 13.49, "Коснитесь его — Пучина помнит, как благословлять тех, кто пришёл не с порчей." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackfathom_deeps_lorgus_pull", ["enc"] = 2913, ["track"] = { ["hash"] = "a4a6ca5d", ["text"] = "Лоргус Джетт, шаман Сумеречного Молота, перехватывает тяжёлый двуручный молот. Он верит, что Древние боги вернутся, а за такую веру дерутся до последнего вздоха.", ["duration"] = 13.2, ["cues"] = { { 0, "Лоргус Джетт, шаман Сумеречного Молота, перехватывает тяжёлый двуручный молот." }, { 6.45, "Он верит, что Древние боги вернутся, а за такую веру дерутся до последнего вздоха." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackfathom_deeps_lorgus", ["enc"] = 2913, ["track"] = { ["hash"] = "91ccc256", ["text"] = "Лоргус Джетт падает. Он был шаманом, но служил не духам, а Древним богам — богам хаоса и разрушения, побеждённым давным-давно. Сумеречный Молот не понимает духов природы, и стихии платят ему тем же. В Руинах святилища Луны им теперь станет спокойнее.", ["duration"] = 21.4, ["cues"] = { { 0, "Лоргус Джетт падает." }, { 1.79, "Он был шаманом, но служил не духам, а Древним богам — богам хаоса и разрушения, побеждённым давным-давно." }, { 10.8, "Сумеречный Молот не понимает духов природы, и стихии платят ему тем же." }, { 17.01, "В Руинах святилища Луны им теперь станет спокойнее." } } } }, { ["role"] = "side", ["k"] = "bag", ["trig"] = "bag", ["id"] = "dm_blackfathom_deeps_globe", ["item"] = 16782, ["track"] = { ["hash"] = "d9fb4089", ["text"] = "Барон Акванис рассыпался брызгами, а на камнях осталась странная сфера с мутной водой внутри. Отнесите её Дже'неу Санкри в форт Зорам'гар — он поймёт, что питало эту тварь.", ["duration"] = 13.8, ["cues"] = { { 0, "Барон Акванис рассыпался брызгами, а на камнях осталась странная сфера с мутной водой внутри." }, { 7.69, "Отнесите её Дже'неу Санкри в форт Зорам'гар — он поймёт, что питало эту тварь." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackfathom_deeps_serrakis_pull", ["enc"] = 2912, ["track"] = { ["hash"] = "b338e61c", ["text"] = "Из глубины поднимается Старина Серракис — морское чудище, хозяин подводных руин. Драться придётся под водой, а воздуха в груди хватит не навсегда: глубина терпелива и ждёт тех, кто погонится за ним слишком далеко.", ["duration"] = 18.5, ["cues"] = { { 0, "Из глубины поднимается Старина Серракис — морское чудище, хозяин подводных руин." }, { 7.17, "Драться придётся под водой, а воздуха в груди хватит не навсегда: глубина терпелива и ждёт тех, кто погонится за ним слишком далеко." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackfathom_deeps_serrakis", ["enc"] = 2912, ["track"] = { ["hash"] = "a5228067", ["text"] = "Старина Серракис уходит в тёмную воду и больше не поднимается. Он жил в этих руинах задолго до наг и культа, и для него все гости были одинаковы — съедобны. Теперь в подводных залах станет немного тише — и немного безопаснее.", ["duration"] = 19.4, ["cues"] = { { 0, "Старина Серракис уходит в тёмную воду и больше не поднимается." }, { 5.41, "Он жил в этих руинах задолго до наг и культа, и для него все гости были одинаковы — съедобны." }, { 13.48, "Теперь в подводных залах станет немного тише — и немного безопаснее." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackfathom_deeps_kelris_pull", ["enc"] = 2911, ["track"] = { ["hash"] = "6c0524df", ["text"] = "Повелитель сумрака Келрис, глава Сумеречного Молота в Пучине, поднимает руки над алтарём, и тени в зале сгущаются. Его чары валят в глубокий сон всех, кто стоит рядом, прямо посреди боя, — и спящий проснётся лишь от удара, пусть даже дружеского.", ["duration"] = 20.6, ["cues"] = { { 0, "Повелитель сумрака Келрис, глава Сумеречного Молота в Пучине, поднимает руки над алтарём, и тени в зале сгущаются." }, { 9.75, "Его чары валят в глубокий сон всех, кто стоит рядом, прямо посреди боя, — и спящий проснётся лишь от удара, пусть даже дружеского." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackfathom_deeps_kelris", ["enc"] = 2911, ["track"] = { ["hash"] = "d32aee7d", ["text"] = "Келрис падает у алтаря. На алтаре — четыре чаши для огня. Зажгите их, и дверь в глубину откроется, только огонь позовёт и тех, кто сторожит путь. Сумеречный Молот готовил этот обряд для себя: культисты верили, что огонь откроет им путь к богам. Он откроет путь вам.", ["duration"] = 22.5, ["cues"] = { { 0, "Келрис падает у алтаря." }, { 2.17, "На алтаре — четыре чаши для огня." }, { 5.12, "Зажгите их, и дверь в глубину откроется, только огонь позовёт и тех, кто сторожит путь." }, { 12.4, "Сумеречный Молот готовил этот обряд для себя: культисты верили, что огонь откроет им путь к богам." }, { 20.93, "Он откроет путь вам." } } } }, { ["q"] = 1200, ["follows"] = "dm_blackfathom_deeps_kelris", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackfathom_deeps_hook_1200", ["track"] = { ["hash"] = "f0dbe4bd", ["text"] = "Голову Келриса — рассветному дозорному Селгорму в Дарнасс. Талрид будет рад узнать, что его весть дошла.", ["duration"] = 8.2, ["cues"] = { { 0, "Голову Келриса — рассветному дозорному Селгорму в Дарнасс." }, { 4.69, "Талрид будет рад узнать, что его весть дошла." } } } }, { ["q"] = 6561, ["follows"] = "dm_blackfathom_deeps_kelris", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackfathom_deeps_hook_6561", ["track"] = { ["hash"] = "34a0e996", ["text"] = "Голову Келриса — Башане Рунический Тотем, на Громовой Утёс.", ["duration"] = 5.2, ["cues"] = { { 0, "Голову Келриса — Башане Рунический Тотем, на Громовой Утёс." } } } }, { ["q"] = 971, ["follows"] = "dm_blackfathom_deeps_kelris", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackfathom_deeps_hook_971_kelris", ["track"] = { ["hash"] = "bcc6b1d3", ["text"] = "Манускрипт Лоргалиса для Геррика Костохвата лежит в старом сундуке у Пруда Аск'ара. Если его ещё нет в вашей сумке, не уходите из Пучины без него.", ["duration"] = 11.7, ["cues"] = { { 0, "Манускрипт Лоргалиса для Геррика Костохвата лежит в старом сундуке у Пруда Аск'ара." }, { 6.75, "Если его ещё нет в вашей сумке, не уходите из Пучины без него." } } } }, { ["q"] = 6565, ["follows"] = "dm_blackfathom_deeps_kelris", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackfathom_deeps_hook_6565", ["track"] = { ["hash"] = "fe685061", ["text"] = "Дже'неу Санкри ждёт вестей о Лоргусе Джетте — шамане Сумеречного Молота, чей план нельзя дать довести до конца.", ["duration"] = 8.9, ["cues"] = { { 0, "Дже'неу Санкри ждёт вестей о Лоргусе Джетте — шамане Сумеречного Молота, чей план нельзя дать довести до конца." } } } }, { ["role"] = "final", ["k"] = "pod", ["trig"] = "after", ["id"] = "dm_blackfathom_deeps_akumai_intro", ["enc"] = 2910, ["pos"] = 8, ["track"] = { ["hash"] = "3ec0ac3d", ["text"] = "За дверью — логово Аку'май. Это многоглавый зверь из глубин, слуга Древнего бога: он поднялся, когда порча отравила лунный колодец, и с тех пор храм принадлежит ему. Наги и Сумеречный Молот поклоняются ему как вестнику того, кто спит ещё глубже. Зажгите все четыре огня на алтаре и будьте готовы к тем, кто придёт на свет.", ["duration"] = 28.6, ["cues"] = { { 0, "За дверью — логово Аку'май." }, { 2.52, "Это многоглавый зверь из глубин, слуга Древнего бога: он поднялся, когда порча отравила лунный колодец, и с тех пор храм принадлежит ему." }, { 14.85, "Наги и Сумеречный Молот поклоняются ему как вестнику того, кто спит ещё глубже." }, { 21.99, "Зажгите все четыре огня на алтаре и будьте готовы к тем, кто придёт на свет." } } } }, { ["role"] = "final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackfathom_deeps_akumai_pull", ["enc"] = 2910, ["track"] = { ["hash"] = "6658a153", ["text"] = "Аку'май поднимается из чёрной воды и шипит. Из его пастей ползёт ядовитое облако, и горе тому, кто в нём задержится. А когда зверь впадает в неистовую ярость, его клыки обрушиваются на стоящего перед ним куда чаще прежнего.", ["duration"] = 18.6, ["cues"] = { { 0, "Аку'май поднимается из чёрной воды и шипит." }, { 3.65, "Из его пастей ползёт ядовитое облако, и горе тому, кто в нём задержится." }, { 9.74, "А когда зверь впадает в неистовую ярость, его клыки обрушиваются на стоящего перед ним куда чаще прежнего." } } } }, { ["role"] = "final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_blackfathom_deeps_akumai", ["enc"] = 2910, ["track"] = { ["hash"] = "a381b0dc", ["text"] = "Аку'май оседает в чёрную воду, и Пучина затихает. Храм Элуны не очистить за один день: порча ушла глубоко в камень. Но слуга Древнего бога мёртв, и наги потеряли то, чему поклонялись. А тот, кто спит под всем этим, подождёт. Он умеет ждать. Над водой поднимаются пузыри, и тьма в глубине на миг кажется не такой густой.", ["duration"] = 28.7, ["cues"] = { { 0, "Аку'май оседает в чёрную воду, и Пучина затихает." }, { 4.56, "Храм Элуны не очистить за один день: порча ушла глубоко в камень." }, { 10.62, "Но слуга Древнего бога мёртв, и наги потеряли то, чему поклонялись." }, { 16.85, "А тот, кто спит под всем этим, подождёт." }, { 20.33, "Он умеет ждать." }, { 21.75, "Над водой поднимаются пузыри, и тьма в глубине на миг кажется не такой густой." } } } }, { ["role"] = "final", ["k"] = "bag", ["trig"] = "qlog", ["id"] = "dm_blackfathom_deeps_pearl", ["quests"] = { 78916, 78917 }, ["track"] = { ["hash"] = "d6edeb2e", ["text"] = "В утробе Аку'май блеснула огромная жемчужина, полная чистой силы Бездны. Если вы из Альянса, несите её рассветному дозорному Селгорму в Дарнасс, если из Орды — Башане Рунический Тотем на Громовой Утёс.", ["duration"] = 17.5, ["cues"] = { { 0, "В утробе Аку'май блеснула огромная жемчужина, полная чистой силы Бездны." }, { 6.47, "Если вы из Альянса, несите её рассветному дозорному Селгорму в Дарнасс, если из Орды — Башане Рунический Тотем на Громовой Утёс." } } } } }, ["bosses"] = { { ["id"] = 2916, ["npcs"] = { 4887 }, ["name"] = "Ghamoo-ra", ["required"] = nil, ["token"] = "ghamoo", ["names335"] = { "Ghamoo-ra" } }, { ["id"] = 2915, ["npcs"] = { 4831 }, ["name"] = "Lady Sarevess", ["required"] = nil, ["token"] = "sarevess", ["names335"] = { "Lady Sarevess" } }, { ["id"] = 2914, ["npcs"] = { 6243 }, ["name"] = "Gelihast", ["required"] = nil, ["token"] = "gelihast", ["names335"] = { "Gelihast" } }, { ["id"] = 2913, ["npcs"] = { 12902 }, ["name"] = "Lorgus Jett", ["required"] = nil, ["token"] = "lorgus", ["names335"] = { "Lorgus Jett" } }, { ["id"] = 2912, ["npcs"] = { 4830 }, ["name"] = "Old Serra'kis", ["required"] = nil, ["token"] = "serrakis", ["names335"] = { "Old Serra'kis" } }, { ["id"] = 2911, ["npcs"] = { 4832 }, ["name"] = "Twilight Lord Kelris", ["required"] = nil, ["token"] = "kelris", ["names335"] = { "Twilight Lord Kelris" } }, { ["id"] = 2910, ["npcs"] = { 4829 }, ["name"] = "Aku'mai", ["required"] = nil, ["token"] = "akumai", ["names335"] = { "Aku'mai" } } } },
[70] = { ["key"] = "uldaman", ["order"] = { 554 }, ["layout"] = "hub", ["alias"] = {  }, ["name"] = "Ульдаман", ["events"] = { { ["id"] = "dm_uldaman_prolog", ["k"] = "prolog", ["trig"] = "prolog", ["track"] = { ["hash"] = "bf9b0abe", ["text"] = "Вы в Ульдамане — хранилище титанов, погребённом в толще земли с древнейших времён. Дворфы Стальгорна раскопали его и разбудили то, что здесь спало: троггов, первую, неудачную попытку титанов вылепить жизнь из камня. Говорят, в самой глубине лежат диски Норганнона — летопись того, как титаны сотворили дворфов. За ними сюда пришёл и клан Черного Железа, чтобы бросить древние тайны к ногам Рагнароса. А охраняют диски каменные стражи, которые до сих пор помнят своих создателей.", ["duration"] = 40.3, ["cues"] = { { 0, "Вы в Ульдамане — хранилище титанов, погребённом в толще земли с древнейших времён." }, { 6.86, "Дворфы Стальгорна раскопали его и разбудили то, что здесь спало: троггов, первую, неудачную попытку титанов вылепить жизнь из камня." }, { 18.04, "Говорят, в самой глубине лежат диски Норганнона — летопись того, как титаны сотворили дворфов." }, { 26.21, "За ними сюда пришёл и клан Чёрного Железа, чтобы бросить древние тайны к ногам Рагнароса." }, { 33.85, "А охраняют диски каменные стражи, которые до сих пор помнят своих создателей." } } } }, { ["id"] = "dm_uldaman_prolog_repeat", ["k"] = "prolog", ["trig"] = "repeat", ["track"] = { ["hash"] = "ee1714b4", ["text"] = "Снова Ульдаман. Трогги заняли расчищенные вами ходы так, будто их никто и не трогал.", ["duration"] = 7, ["cues"] = { { 0, "Снова Ульдаман." }, { 1.35, "Трогги заняли расчищенные вами ходы так, будто их никто и не трогал." } } } }, { ["q"] = 2398, ["prio"] = 0, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_uldaman_hook_2398", ["track"] = { ["hash"] = "432b81e7", ["text"] = "Геолог Грозовая Вершина просит найти Бейлога: его отряд застрял в глубине раскопа, когда нагрянули трогги. Ищите дворфов на Втором раскопе.", ["duration"] = 10.6, ["cues"] = { { 0, "Геолог Грозовая Вершина просит найти Бейлога: его отряд застрял в глубине раскопа, когда нагрянули трогги." }, { 8.26, "Ищите дворфов на Втором раскопе." } } } }, { ["q"] = 2240, ["prio"] = 1, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_uldaman_hook_2240", ["track"] = { ["hash"] = "42afaedc", ["text"] = "Бейлог просил найти чертог Хаз'Мула за огромной запертой дверью — как её открыть, он записал в дневнике. Рассказа об увиденном ждёт геолог Грозовая Вершина в Стальгорне.", ["duration"] = 12.9, ["cues"] = { { 0, "Бейлог просил найти чертог Хаз'Мула за огромной запертой дверью — как её открыть, он записал в дневнике." }, { 8.13, "Рассказа об увиденном ждёт геолог Грозовая Вершина в Стальгорне." } } } }, { ["q"] = 2200, ["prio"] = 2, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_uldaman_hook_2200", ["track"] = { ["hash"] = "d7b31b3c", ["text"] = "Талваш де Киссель говорил об убитом паладине, последнем владельце ожерелья. Его останки лежат здесь, в первом зале.", ["duration"] = 8.8, ["cues"] = { { 0, "Талваш де Киссель говорил об убитом паладине, последнем владельце ожерелья." }, { 5.83, "Его останки лежат здесь, в первом зале." } } } }, { ["q"] = 2284, ["prio"] = 3, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_uldaman_hook_2284", ["track"] = { ["hash"] = "be59a3af", ["text"] = "Дран Дрофферс ждёт рубин, сапфир и топаз от ожерелья, а подсказка, где их искать, — у останков паладина, что лежат здесь, в первом зале.", ["duration"] = 11, ["cues"] = { { 0, "Дран Дрофферс ждёт рубин, сапфир и топаз от ожерелья, а подсказка, где их искать, — у останков паладина, что лежат здесь, в первом зале." } } } }, { ["q"] = 2201, ["prio"] = 4, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_uldaman_hook_2201", ["track"] = { ["hash"] = "e87f8a39", ["text"] = "По записям паладина, рубин из ожерелья укрыт в забаррикадированной Кузне Теней, топаз спрятан в урне у троггов, недалеко от дворфов Альянса, а сапфир присвоил себе Гримлок. Найдёте все три — свяжитесь с Талвашем де Кисселем через фиал Видения.", ["duration"] = 18.3, ["cues"] = { { 0, "По записям паладина, рубин из ожерелья укрыт в забаррикадированной Кузне Теней, топаз спрятан в урне у троггов, недалеко от дворфов Альянса, а сапфир присвоил себе Гримлок." }, { 13.18, "Найдёте все три — свяжитесь с Талвашем де Кисселем через фиал Видения." } } } }, { ["q"] = 2339, ["prio"] = 5, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_uldaman_hook_2339", ["track"] = { ["hash"] = "cb456e6e", ["text"] = "Джаркал Замшелый Клык ждёт в Каргате три самоцвета и источник энергии. По записям паладина, рубин спрятан у Кузни Теней, топаз — в урне у троггов, сапфир забрал Гримлок, а источник энергии стоит искать у самого могучего конструкта в глубине.", ["duration"] = 20.5, ["cues"] = { { 0, "Джаркал Замшелый Клык ждёт в Каргате три самоцвета и источник энергии." }, { 5.9, "По записям паладина, рубин спрятан у Кузни Теней, топаз — в урне у троггов, сапфир забрал Гримлок, а источник энергии стоит искать у самого могучего конструкта в глубине." } } } }, { ["q"] = 709, ["prio"] = 6, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_uldaman_hook_709", ["track"] = { ["hash"] = "0e95e9f9", ["text"] = "Тельдарин Заблудший боится даже произнести это имя вслух, но просил найти табличку Рьюн'эха. Она где-то в глубине, в древнем сундуке, который старше любой работы дворфов.", ["duration"] = 13.8, ["cues"] = { { 0, "Тельдарин Заблудший боится даже произнести это имя вслух, но просил найти табличку Рьюн'эха." }, { 7.54, "Она где-то в глубине, в древнем сундуке, который старше любой работы дворфов." } } } }, { ["q"] = 1139, ["prio"] = 7, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_uldaman_hook_1139", ["track"] = { ["hash"] = "2646d36b", ["text"] = "Советник Белграм ждёт табличку Воли — камень, на котором, по легендам, титаны высекли слова, вдыхающие жизнь. Её нужно забрать раньше, чем до неё доберётся Кузня Теней.", ["duration"] = 13, ["cues"] = { { 0, "Советник Белграм ждёт табличку Воли — камень, на котором, по легендам, титаны высекли слова, вдыхающие жизнь." }, { 8.52, "Её нужно забрать раньше, чем до неё доберётся Кузня Теней." } } } }, { ["q"] = 2418, ["prio"] = 8, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_uldaman_hook_2418", ["track"] = { ["hash"] = "b5613537", ["text"] = "Ригглфаззу нужны дентриевые и энелиевые камни Силы — по восемь каждого. За такими камнями в Ульдаман и пришла Кузня Теней.", ["duration"] = 10.8, ["cues"] = { { 0, "Ригглфаззу нужны дентриевые и энелиевые камни Силы — по восемь каждого." }, { 6.4, "За такими камнями в Ульдаман и пришла Кузня Теней." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_uldaman_revelosh_pull", ["enc"] = 547, ["track"] = { ["hash"] = "ee0c1ef3", ["text"] = "Ревелош, вожак здешних троггов, тащит к себе всё, что блестит и пахнет древностью, — а сейчас визжит и вскидывает лапы, и между пальцами трещат молнии. Его цепная молния перескакивает с одного на другого, и чем теснее вы стоите, тем дальше бежит разряд.", ["duration"] = 19.9, ["cues"] = { { 0, "Ревелош, вожак здешних троггов, тащит к себе всё, что блестит и пахнет древностью, — а сейчас визжит и вскидывает лапы, и между пальцами трещат молнии." }, { 12.03, "Его цепная молния перескакивает с одного на другого, и чем теснее вы стоите, тем дальше бежит разряд." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_uldaman_revelosh_res", ["enc"] = 547, ["track"] = { ["hash"] = "6daad9ae", ["text"] = "Ревелош падает. Трогги тащат в свои норы всё, что блестит, не понимая, что держат в лапах, — а ведь они и сами творение титанов, первое и неудачное. В добыче Ревелоша — Стержень Тсола: половина посоха, которым открывают запечатанный чертог.", ["duration"] = 19.7, ["cues"] = { { 0, "Ревелош падает." }, { 1.34, "Трогги тащат в свои норы всё, что блестит, не понимая, что держат в лапах, — а ведь они и сами творение титанов, первое и неудачное." }, { 12.26, "В добыче Ревелоша — Стержень Тсола: половина посоха, которым открывают запечатанный чертог." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_uldaman_dwarves_pull", ["enc"] = 548, ["track"] = { ["hash"] = "00608c86", ["text"] = "Трое дворфов — Бейлог, Эрик «Быстрый» и Олаф — встают плечом к плечу: лук, разбег и щит. Это отряд Лиги Исследователей, застрявший в глубине раскопа, и Орде свои находки они не отдадут.", ["duration"] = 16.2, ["cues"] = { { 0, "Трое дворфов — Бейлог, Эрик «Быстрый» и Олаф — встают плечом к плечу: лук, разбег и щит." }, { 7.77, "Это отряд Лиги Исследователей, застрявший в глубине раскопа, и Орде свои находки они не отдадут." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_uldaman_dwarves_res", ["enc"] = 548, ["track"] = { ["hash"] = "14ba6be8", ["text"] = "Последний из троих опускает оружие. Они искали здесь славу и золото, а нашли троггов, тьму и вас. На столе в их лагере — дневник Бейлога и сундук, а в сундуке Медальон Гни'кива: вторая половина посоха.", ["duration"] = 18.2, ["cues"] = { { 0, "Последний из троих опускает оружие." }, { 3.3, "Они искали здесь славу и золото, а нашли троггов, тьму и вас." }, { 8.91, "На столе в их лагере — дневник Бейлога и сундук, а в сундуке Медальон Гни'кива: вторая половина посоха." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_uldaman_ironaya_pull", ["enc"] = 549, ["track"] = { ["hash"] = "5f9751eb", ["text"] = "Дверь чертога открыта, и каменная великанша Иронайа шагает из ниши: никто не украдёт тайн Создателей. Её удар по дуге сметает всех, кто стоит перед ней, а когда она топнет, земля оглушит каждого рядом.", ["duration"] = 16.5, ["cues"] = { { 0, "Дверь чертога открыта, и каменная великанша Иронайа шагает из ниши: никто не украдёт тайн Создателей." }, { 8.28, "Её удар по дуге сметает всех, кто стоит перед ней, а когда она топнет, земля оглушит каждого рядом." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_uldaman_ironaya_res", ["enc"] = 549, ["track"] = { ["hash"] = "b82ec252", ["text"] = "Иронайа замирает и снова становится камнем — теперь уже навсегда. Титаны оставили её беречь тайны Ульдамана, и она берегла их, даже когда о Создателях здесь не помнил уже никто. Запечатанный чертог больше никто не стережёт.", ["duration"] = 19, ["cues"] = { { 0, "Иронайа замирает и снова становится камнем — теперь уже навсегда." }, { 5.68, "Титаны оставили её беречь тайны Ульдамана, и она берегла их, даже когда о Создателях здесь не помнил уже никто." }, { 15.28, "Запечатанный чертог больше никто не стережёт." } } } }, { ["sub"] = "Пещера Эхомок", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_uldaman_obsidian_pod", ["enc"] = 1887, ["pos"] = 4, ["track"] = { ["hash"] = "6859dfdd", ["text"] = "Пещера Эхомок. Здесь копает Черное Железо: дворфы Кузни Теней долбят стены в поисках древних камней силы. Пещеру сторожит Обсидиановый часовой — исполинский страж из чёрного стекла. Кого он охраняет теперь, когда хозяев давно нет, не скажет никто.", ["duration"] = 20.6, ["cues"] = { { 0, "Пещера Эхомок." }, { 1.28, "Здесь копает Чёрное Железо: дворфы Кузни Теней долбят стены в поисках древних камней силы." }, { 8.96, "Пещеру сторожит Обсидиановый часовой — исполинский страж из чёрного стекла." }, { 15.14, "Кого он охраняет теперь, когда хозяев давно нет, не скажет никто." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_uldaman_obsidian_pull", ["enc"] = 1887, ["track"] = { ["hash"] = "f11bba13", ["text"] = "Часовой оживает с хрустом, и по чёрному стеклу пробегают блики. Заклинания он отражает обратно в того, кто их сотворил. А под ударами от него откалываются осколки, и каждый встаёт и идёт в бой сам.", ["duration"] = 16, ["cues"] = { { 0, "Часовой оживает с хрустом, и по чёрному стеклу пробегают блики." }, { 5.28, "Заклинания он отражает обратно в того, кто их сотворил." }, { 9.89, "А под ударами от него откалываются осколки, и каждый встаёт и идёт в бой сам." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_uldaman_obsidian_res", ["enc"] = 1887, ["track"] = { ["hash"] = "dee34678", ["text"] = "Обсидиановый часовой рассыпается грудой чёрного стекла. Титаны строили своих стражей на века, но и века когда-нибудь кончаются. В осколках ещё дрожат блики — всё, что осталось от древнего сторожа.", ["duration"] = 16.6, ["cues"] = { { 0, "Обсидиановый часовой рассыпается грудой чёрного стекла." }, { 4.74, "Титаны строили своих стражей на века, но и века когда-нибудь кончаются." }, { 10.97, "В осколках ещё дрожат блики — всё, что осталось от древнего сторожа." } } } }, { ["sub"] = "Храмовый зал", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_uldaman_keeper_pod", ["enc"] = 551, ["pos"] = 5, ["track"] = { ["hash"] = "93cbe5a0", ["text"] = "Храмовый зал. Колонны, ниши, каменные фигуры вдоль стен — здесь когда-то чтили Создателей. Среди каменных слуг бродит Древний каменный хранитель. Его поставили беречь погребённый город — и он бережёт, хотя хозяева не возвращаются уже тысячи лет.", ["duration"] = 21.2, ["cues"] = { { 0, "Храмовый зал." }, { 1.19, "Колонны, ниши, каменные фигуры вдоль стен — здесь когда-то чтили Создателей." }, { 7.86, "Среди каменных слуг бродит Древний каменный хранитель." }, { 12.7, "Его поставили беречь погребённый город — и он бережёт, хотя хозяева не возвращаются уже тысячи лет." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_uldaman_keeper_pull", ["enc"] = 551, ["track"] = { ["hash"] = "803cd924", ["text"] = "Хранитель поворачивает к вам тяжёлую голову, и с пола поднимается песок. Песчаные бури кружат по залу и цепляются к тем, кто окажется рядом, — и заклинателю в такой буре приходится хуже всех.", ["duration"] = 15.4, ["cues"] = { { 0, "Хранитель поворачивает к вам тяжёлую голову, и с пола поднимается песок." }, { 5.84, "Песчаные бури кружат по залу и цепляются к тем, кто окажется рядом, — и заклинателю в такой буре приходится хуже всех." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_uldaman_keeper_res", ["enc"] = 551, ["track"] = { ["hash"] = "013bcc7c", ["text"] = "Древний каменный хранитель замирает и медленно гаснет, как остывающий горн. Он исполнил долг до конца — без хозяев, без смены, без надежды на отдых. Никто больше не скажет, какой порядок он берёг все эти тысячи лет.", ["duration"] = 19.8, ["cues"] = { { 0, "Древний каменный хранитель замирает и медленно гаснет, как остывающий горн." }, { 7.04, "Он исполнил долг до конца — без хозяев, без смены, без надежды на отдых." }, { 13.73, "Никто больше не скажет, какой порядок он берёг все эти тысячи лет." } } } }, { ["sub"] = "Третий раскоп", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_uldaman_galgann_pod", ["enc"] = 552, ["pos"] = 6, ["track"] = { ["hash"] = "beb4260a", ["text"] = "Третий раскоп. Здесь лагерь Кузни Теней — дворфов Черного Железа, служащих Рагнаросу. Ими командует Галганн Огнемолот, огненный маг и верный слуга императора Тауриссана. Его люди перерывают Ульдаман в поисках древних тайн для своего огненного владыки. Черное Железо и Стальгорн — один народ, расколотый давней войной, и в Ульдамане эта война продолжается.", ["duration"] = 29.3, ["cues"] = { { 0, "Третий раскоп." }, { 1.27, "Здесь лагерь Кузни Теней — дворфов Чёрного Железа, служащих Рагнаросу." }, { 7.12, "Ими командует Галганн Огнемолот, огненный маг и верный слуга императора Тауриссана." }, { 14.08, "Его люди перерывают Ульдаман в поисках древних тайн для своего огненного владыки." }, { 20.9, "Чёрное Железо и Стальгорн — один народ, расколотый давней войной, и в Ульдамане эта война продолжается." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_uldaman_galgann_pull", ["enc"] = 552, ["track"] = { ["hash"] = "127c540c", ["text"] = "Галганн клянётся бородой Тауриссана, и его геологи хватаются за кирки и заклинания: в воздухе свистят огненные шипы и кнуты пламени. А сам Огнемолот бьёт кольцом огня по всем, кто подошёл вплотную.", ["duration"] = 16.2, ["cues"] = { { 0, "Галганн клянётся бородой Тауриссана, и его геологи хватаются за кирки и заклинания: в воздухе свистят огненные шипы и кнуты пламени." }, { 11.1, "А сам Огнемолот бьёт кольцом огня по всем, кто подошёл вплотную." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_uldaman_galgann_res", ["enc"] = 552, ["track"] = { ["hash"] = "3188b7a2", ["text"] = "Галганн Огнемолот падает, и пламя в его руках гаснет. Черное Железо будет копать дальше: Тауриссан не отступается от того, что считает своим, а Рагнарос не устаёт требовать. Но этот раскоп остался без хозяина.", ["duration"] = 18.4, ["cues"] = { { 0, "Галганн Огнемолот падает, и пламя в его руках гаснет." }, { 4.88, "Чёрное Железо будет копать дальше: Тауриссан не отступается от того, что считает своим, а Рагнарос не устаёт требовать." }, { 15.36, "Но этот раскоп остался без хозяина." } } } }, { ["sub"] = "Каменный свод", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_uldaman_grimlok_pod", ["enc"] = 553, ["pos"] = 7, ["track"] = { ["hash"] = "f7bad3ff", ["text"] = "Каменный свод. Пещера, полная троггов и их добычи, а посреди неё — Гримлок со своей свитой. Вождь троггов держит власть не столько силой, сколько страхом: при нём ручной василиск, и тот, кто посмеет спорить, рискует обратиться в камень. Гримлок зовёт себя королём — и здесь с ним никто не спорит.", ["duration"] = 25, ["cues"] = { { 0, "Каменный свод." }, { 1.25, "Пещера, полная троггов и их добычи, а посреди неё — Гримлок со своей свитой." }, { 7.88, "Вождь троггов держит власть не столько силой, сколько страхом: при нём ручной василиск, и тот, кто посмеет спорить, рискует обратиться в камень." }, { 20.21, "Гримлок зовёт себя королём — и здесь с ним никто не спорит." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_uldaman_grimlok_pull", ["enc"] = 553, ["track"] = { ["hash"] = "aeef3c1a", ["text"] = "Трогг ревёт, что он здесь король, и вокруг него трещат молнии. Его цепной удар перескакивает с одного на другого, свиту охватывает кровожадность, а взгляд василиска сковывает хрустальным сном — это чары, и сами они не рассеются.", ["duration"] = 18.9, ["cues"] = { { 0, "Трогг ревёт, что он здесь король, и вокруг него трещат молнии." }, { 5.16, "Его цепной удар перескакивает с одного на другого, свиту охватывает кровожадность, а взгляд василиска сковывает хрустальным сном — это чары, и сами они не рассеются." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_uldaman_grimlok_res", ["enc"] = 553, ["track"] = { ["hash"] = "edd2bb38", ["text"] = "Гримлок падает, и вся его власть уходит вместе с ним. У троггов нет наследников — есть только следующий, самый большой и самый злой. Пройдёт немного времени, и кто-то другой назовёт себя королём Каменного свода. Король умер, да здравствует король.", ["duration"] = 20.8, ["cues"] = { { 0, "Гримлок падает, и вся его власть уходит вместе с ним." }, { 4.56, "У троггов нет наследников — есть только следующий, самый большой и самый злой." }, { 11.21, "Пройдёт немного времени, и кто-то другой назовёт себя королём Каменного свода." }, { 17.86, "Король умер, да здравствует король." } } } }, { ["sub"] = "Трон Каз'горота", ["role"] = "final", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_uldaman_archaedas_pod", ["enc"] = 554, ["pos"] = 8, ["track"] = { ["hash"] = "f7b07bfa", ["text"] = "Трон Каз'горота — самый глубокий зал Ульдамана. Вдоль стен застыли каменные воины, а в центре стоит исполин Аркедас, хранитель дисков Норганнона. Он спит тысячи лет, но стоит тронуть алтарь — и страж проснётся, а с ним проснутся и все, кого он стережёт. За его спиной — то, ради чего сюда шли и дворфы, и Черное Железо.", ["duration"] = 26.7, ["cues"] = { { 0, "Трон Каз'горота — самый глубокий зал Ульдамана." }, { 4.03, "Вдоль стен застыли каменные воины, а в центре стоит исполин Аркедас, хранитель дисков Норганнона." }, { 12.39, "Он спит тысячи лет, но стоит тронуть алтарь — и страж проснётся, а с ним проснутся и все, кого он стережёт." }, { 21.22, "За его спиной — то, ради чего сюда шли и дворфы, и Чёрное Железо." } } } }, { ["role"] = "final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_uldaman_archaedas_pull", ["enc"] = 554, ["track"] = { ["hash"] = "7d621e63", ["text"] = "Аркедас открывает глаза, и камень вдоль стен оживает: он будит глиняных землестражей, а следом и тюремщиков подземелья, и чем дольше бой, тем больше камня встаёт против вас. А когда страж ударит по полу, дрожь земли оглушит всех рядом.", ["duration"] = 19.4, ["cues"] = { { 0, "Аркедас открывает глаза, и камень вдоль стен оживает: он будит глиняных землестражей, а следом и тюремщиков подземелья, и чем дольше бой, тем больше камня встаёт против вас." }, { 14.35, "А когда страж ударит по полу, дрожь земли оглушит всех рядом." } } } }, { ["role"] = "final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_uldaman_archaedas_fin", ["enc"] = 554, ["track"] = { ["hash"] = "d045d1aa", ["text"] = "Аркедас замирает, и каменные воины вдоль стен снова становятся просто камнем. За троном ждут диски Норганнона и их каменный страж: он помнит, как титаны лепили из камня первых дворфов и как их творения начали обращаться в плоть. Тайна, ради которой дворфы раскапывали Ульдаман, теперь открыта — вам.", ["duration"] = 24.9, ["cues"] = { { 0, "Аркедас замирает, и каменные воины вдоль стен снова становятся просто камнем." }, { 6.54, "За троном ждут диски Норганнона и их каменный страж: он помнит, как титаны лепили из камня первых дворфов и как их творения начали обращаться в плоть." }, { 19.02, "Тайна, ради которой дворфы раскапывали Ульдаман, теперь открыта — вам." } } } }, { ["q"] = 2204, ["follows"] = "dm_uldaman_archaedas_fin", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_uldaman_fin_2204", ["track"] = { ["hash"] = "fa46d928", ["text"] = "Талваш де Киссель велел добыть источник силы для ожерелья у самого могучего создания Ульдамана — сильнее стража здесь не было никого. С источником возвращайтесь к Талвашу в Стальгорн.", ["duration"] = 14.1, ["cues"] = { { 0, "Талваш де Киссель велел добыть источник силы для ожерелья у самого могучего создания Ульдамана — сильнее стража здесь не было никого." }, { 10.5, "С источником возвращайтесь к Талвашу в Стальгорн." } } } }, { ["q"] = 2339, ["follows"] = "dm_uldaman_archaedas_fin", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_uldaman_fin_2339", ["track"] = { ["hash"] = "905a7341", ["text"] = "Джаркал велел искать источник энергии для ожерелья у самого могучего конструкта в глубине Ульдамана — сильнее стража здесь не было никого. С ним и самоцветами возвращайтесь к Джаркалу в Каргат.", ["duration"] = 14, ["cues"] = { { 0, "Джаркал велел искать источник энергии для ожерелья у самого могучего конструкта в глубине Ульдамана — сильнее стража здесь не было никого." }, { 10.21, "С ним и самоцветами возвращайтесь к Джаркалу в Каргат." } } } } }, ["bosses"] = { { ["id"] = 547, ["npcs"] = { 6910 }, ["name"] = "Revelosh", ["required"] = nil, ["token"] = "revelosh", ["names335"] = { "Revelosh" } }, { ["id"] = 548, ["npcs"] = { 6906, 6907, 6908 }, ["name"] = "dwarves", ["required"] = { 6906, 6907, 6908 }, ["token"] = "dwarves", ["names335"] = { "Baelog", "Eric \\\"The Swift\\\"", "Olaf" } }, { ["id"] = 549, ["npcs"] = { 7228 }, ["name"] = "Ironaya", ["required"] = nil, ["token"] = "ironaya", ["names335"] = { "Ironaya" } }, { ["id"] = 1887, ["npcs"] = { 7023 }, ["name"] = "obsidian", ["required"] = nil, ["token"] = "obsidian", ["names335"] = { "Obsidian Sentinel" } }, { ["id"] = 551, ["npcs"] = { 7206 }, ["name"] = "Ancient Stone Keeper", ["required"] = nil, ["token"] = "keeper", ["names335"] = { "Ancient Stone Keeper" } }, { ["id"] = 552, ["npcs"] = { 7291 }, ["name"] = "Galgann Firehammer", ["required"] = nil, ["token"] = "galgann", ["names335"] = { "Galgann Firehammer" } }, { ["id"] = 553, ["npcs"] = { 4854 }, ["name"] = "Grimlok", ["required"] = nil, ["token"] = "grimlok", ["names335"] = { "Grimlok" } }, { ["id"] = 554, ["npcs"] = { 2748 }, ["name"] = "Archaedas", ["required"] = nil, ["token"] = "archaedas", ["names335"] = { "Archaedas" } } } },
[90] = { ["key"] = "gnomeregan", ["order"] = { 2772 }, ["layout"] = "branching", ["alias"] = { [2925] = 2768, [2940] = 2772, [2899] = 2771, [2928] = 2769, [2927] = 2770 }, ["name"] = "Гномреган", ["events"] = { { ["id"] = "dm_gnomeregan_prolog", ["k"] = "prolog", ["trig"] = "prolog", ["track"] = { ["hash"] = "1386f8db", ["text"] = "Вы в Гномрегане — бывшей столице гномов, чуде инженерной мысли под снегами Дун Морога. Когда из глубин хлынули трогги, Главный механик Меггакрут приказал выпустить в город радиоактивные отходы. Троггов это не остановило, а только изменило: теперь они светятся зелёным и злее прежнего. Выжившие гномы бежали в Стальгорн, а те, кто остался, сошли с ума вместе со своими машинами. Город до сих пор гудит, лязгает и воет сиренами, будто не знает, что его уже потеряли.", ["duration"] = 38.5, ["cues"] = { { 0, "Вы в Гномрегане — бывшей столице гномов, чуде инженерной мысли под снегами Дун Морога." }, { 7.2, "Когда из глубин хлынули трогги, Главный механик Меггакрут приказал выпустить в город радиоактивные отходы." }, { 16.13, "Троггов это не остановило, а только изменило: теперь они светятся зелёным и злее прежнего." }, { 23.71, "Выжившие гномы бежали в Стальгорн, а те, кто остался, сошли с ума вместе со своими машинами." }, { 31.36, "Город до сих пор гудит, лязгает и воет сиренами, будто не знает, что его уже потеряли." } } } }, { ["id"] = "dm_gnomeregan_prolog_repeat", ["k"] = "prolog", ["trig"] = "repeat", ["track"] = { ["hash"] = "653acd83", ["text"] = "Снова Гномреган. Сирены всё так же воют, а трогги так и не научились бояться.", ["duration"] = 7.2, ["cues"] = { { 0, "Снова Гномреган." }, { 1.65, "Сирены всё так же воют, а трогги так и не научились бояться." } } } }, { ["q"] = 2929, ["prio"] = 0, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_gnomeregan_hook_2929", ["track"] = { ["hash"] = "0a2345ef", ["text"] = "Главный механик Меггакрут ждёт вести о смерти Термоштепселя. Для него это не поручение, а долг перед всем гномьим народом.", ["duration"] = 9.7, ["cues"] = { { 0, "Главный механик Меггакрут ждёт вести о смерти Термоштепселя." }, { 4.88, "Для него это не поручение, а долг перед всем гномьим народом." } } } }, { ["q"] = 2841, ["prio"] = 1, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_gnomeregan_hook_2841", ["track"] = { ["hash"] = "b8f83162", ["text"] = "Ногг из Оргриммара хочет чертежи новой гномьей машины. Код от сейфа знает только Термоштепсель — значит, разговора с ним не избежать.", ["duration"] = 10.2, ["cues"] = { { 0, "Ногг из Оргриммара хочет чертежи новой гномьей машины." }, { 4.31, "Код от сейфа знает только Термоштепсель — значит, разговора с ним не избежать." } } } }, { ["q"] = 2930, ["prio"] = 2, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_gnomeregan_hook_2930", ["track"] = { ["hash"] = "00f00402", ["text"] = "Главный механик Чугунотрубз ждёт призматическую перфокарту. Терминалы допуска стоят по пути, от простых к самым секретным, — не пропустите ни одного.", ["duration"] = 11.6, ["cues"] = { { 0, "Главный механик Чугунотрубз ждёт призматическую перфокарту." }, { 4.66, "Терминалы допуска стоят по пути, от простых к самым секретным, — не пропустите ни одного." } } } }, { ["prio"] = 3, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_gnomeregan_hook_horde", ["faction"] = "Horde", ["track"] = { ["hash"] = "1488c992", ["text"] = "Это не ваш город, Орда, и спасибо здесь вам никто не скажет. Но гномьи чертежи и детали в Оргриммаре ценят на вес золота.", ["duration"] = 9.6, ["cues"] = { { 0, "Это не ваш город, Орда, и спасибо здесь вам никто не скажет." }, { 4.88, "Но гномьи чертежи и детали в Оргриммаре ценят на вес золота." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_gnomeregan_grubbis_pull", ["enc"] = 2768, ["track"] = { ["hash"] = "353a7bde", ["text"] = "Из пролома вываливается Грязнюк — вожак троггов, а у его ног щёлкает пастью ручной василиск. Трогги не строят планов: они просто лезут, пока не кончатся. Этот кончится последним.", ["duration"] = 14.7, ["cues"] = { { 0, "Из пролома вываливается Грязнюк — вожак троггов, а у его ног щёлкает пастью ручной василиск." }, { 7.62, "Трогги не строят планов: они просто лезут, пока не кончатся." }, { 12.78, "Этот кончится последним." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_gnomeregan_grubbis", ["enc"] = 2768, ["track"] = { ["hash"] = "0aebac44", ["text"] = "Грязнюк падает, и в пещерах становится тише. Гномы считали троггов тупыми тварями из-под земли, но именно эти твари выгнали их из лучшего города Азерота. А радиация, которой их хотели убить, сделала троггов только сильнее. Подрывница своё дело сделала — этот пролом больше никто не откроет.", ["duration"] = 24.2, ["cues"] = { { 0, "Грязнюк падает, и в пещерах становится тише." }, { 3.73, "Гномы считали троггов тупыми тварями из-под земли, но именно эти твари выгнали их из лучшего города Азерота." }, { 12.9, "А радиация, которой их хотели убить, сделала троггов только сильнее." }, { 18.65, "Подрывница своё дело сделала — этот пролом больше никто не откроет." } } } }, { ["sub"] = "Машинный зал", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_gnomeregan_hall_intro", ["enc"] = 2769, ["pos"] = 2, ["track"] = { ["hash"] = "7e26ffc1", ["text"] = "Машинный зал. Огромные шестерни застыли на полпути, а внизу, на облучённом дне, светится зелёная жижа. Там ползает Липкая муть — радиоактивные отходы, которые ожили сами по себе. Рядом, в пещерах троггов, гномка-подрывница всё ещё пытается завалить ходы, откуда лезут твари. Если ей помочь, трогги полезут все разом, и их вожак вместе с ними.", ["duration"] = 28.5, ["cues"] = { { 0, "Машинный зал." }, { 1.14, "Огромные шестерни застыли на полпути, а внизу, на облучённом дне, светится зелёная жижа." }, { 8.41, "Там ползает Липкая муть — радиоактивные отходы, которые ожили сами по себе." }, { 14.77, "Рядом, в пещерах троггов, гномка-подрывница всё ещё пытается завалить ходы, откуда лезут твари." }, { 22.88, "Если ей помочь, трогги полезут все разом, и их вожак вместе с ними." } } } }, { ["q"] = 2926, ["follows"] = "dm_gnomeregan_hall_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_gnomeregan_hook_2926", ["track"] = { ["hash"] = "002ae167", ["text"] = "Оззи Триггервольт ждёт радиоактивный осадок. Собирать его нужно с живых облучённых троггов — с мёртвых он уже не возьмётся.", ["duration"] = 9, ["cues"] = { { 0, "Оззи Триггервольт ждёт радиоактивный осадок." }, { 3.36, "Собирать его нужно с живых облучённых троггов — с мёртвых он уже не возьмётся." } } } }, { ["q"] = 2962, ["follows"] = "dm_gnomeregan_hall_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_gnomeregan_hook_2962", ["track"] = { ["hash"] = "fafcabd2", ["text"] = "Оззи нужен образец посильнее: облучённые слизнюки, шнырюки и ужасники светятся ярче троггов. Образец быстро распадается, так что обратно не мешкайте.", ["duration"] = 12.8, ["cues"] = { { 0, "Оззи нужен образец посильнее: облучённые слизнюки, шнырюки и ужасники светятся ярче троггов." }, { 8.09, "Образец быстро распадается, так что обратно не мешкайте." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_gnomeregan_fallout_pull", ["enc"] = 2769, ["track"] = { ["hash"] = "20af165c", ["text"] = "Липкая муть вздымается из лужи и плюётся ядовитым градом во всё живое вокруг. Яд въедается в каждого и сам не уходит — эта лужа хочет, чтобы вы гнили медленно.", ["duration"] = 14.2, ["cues"] = { { 0, "Липкая муть вздымается из лужи и плюётся ядовитым градом во всё живое вокруг." }, { 6.92, "Яд въедается в каждого и сам не уходит — эта лужа хочет, чтобы вы гнили медленно." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_gnomeregan_fallout", ["enc"] = 2769, ["track"] = { ["hash"] = "6044e39d", ["text"] = "Липкая муть растекается по дну и медленно гаснет. Это не зверь и не демон — просто отходы, которые гномы когда-то сами выпустили в свой город. Самое страшное в Гномрегане сделано руками его же хозяев. А пятно на полу будет светиться ещё долго после того, как вы уйдёте.", ["duration"] = 23, ["cues"] = { { 0, "Липкая муть растекается по дну и медленно гаснет." }, { 4.2, "Это не зверь и не демон — просто отходы, которые гномы когда-то сами выпустили в свой город." }, { 12.22, "Самое страшное в Гномрегане сделано руками его же хозяев." }, { 17.28, "А пятно на полу будет светиться ещё долго после того, как вы уйдёте." } } } }, { ["sub"] = "Пусковая установка", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_gnomeregan_launch_intro", ["enc"] = 2770, ["pos"] = 3, ["track"] = { ["hash"] = "d9bc2ce0", ["text"] = "Пусковая установка. Круглый зал с площадкой посередине: отсюда гномы когда-то запускали свои машины. Теперь над кольцевой галереей стоит «Электрошокер-6000» — охранная машина, которая всё ещё сторожит то, чего больше нет. Его можно обойти стороной. Но с него снимают Ключ от мастерской, а на его площадке стоит терминал, нужный тем, кто пришёл сюда за данными.", ["duration"] = 27.9, ["cues"] = { { 0, "Пусковая установка." }, { 1.52, "Круглый зал с площадкой посередине: отсюда гномы когда-то запускали свои машины." }, { 7.76, "Теперь над кольцевой галереей стоит «Электрошокер-шесть тысяч» — охранная машина, которая всё ещё сторожит то, чего больше нет." }, { 17.47, "Его можно обойти стороной." }, { 19.61, "Но с него снимают Ключ от мастерской, а на его площадке стоит терминал, нужный тем, кто пришёл сюда за данными." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_gnomeregan_electro_pull", ["enc"] = 2770, ["track"] = { ["hash"] = "5c173911", ["text"] = "Машина трещит разрядами и тянет к вам катушки. Мегавольт и цепной удар она копит с нарастающим гулом, а того, кто стоит к ней ближе всех, «Электрошокер» то и дело бьёт током так, что сводит пальцы.", ["duration"] = 15.8, ["cues"] = { { 0, "Машина трещит разрядами и тянет к вам катушки." }, { 3.8, "Мегавольт и цепной удар она копит с нарастающим гулом, а того, кто стоит к ней ближе всех, «Электрошокер» то и дело бьёт током так, что сводит пальцы." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_gnomeregan_electro", ["enc"] = 2770, ["track"] = { ["hash"] = "3d37188d", ["text"] = "«Электрошокер-6000» искрит в последний раз и замирает. Гномы строили его, чтобы защищать город, а он годами защищал руины от тех, кто хотел их вернуть. Машине всё равно, кому служить. В этом она, пожалуй, честнее некоторых жителей Гномрегана. Катушки остывают, и в зале впервые за долгое время слышно эхо ваших шагов.", ["duration"] = 26.3, ["cues"] = { { 0, "«Электрошокер-шесть тысяч» искрит в последний раз и замирает." }, { 4.9, "Гномы строили его, чтобы защищать город, а он годами защищал руины от тех, кто хотел их вернуть." }, { 12.8, "Машине всё равно, кому служить." }, { 15.43, "В этом она, пожалуй, честнее некоторых жителей Гномрегана." }, { 20.26, "Катушки остывают, и в зале впервые за долгое время слышно эхо ваших шагов." } } } }, { ["sub"] = "Инженерные лаборатории", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_gnomeregan_labs_intro", ["enc"] = 2771, ["pos"] = 4, ["track"] = { ["hash"] = "9119e7d5", ["text"] = "Инженерные лаборатории. Здесь гномы чертили и испытывали самые смелые свои изобретения, а теперь бродят обезумевшие механики и патрули сторожевых машин. На верхнем уступе стоит «Толпогон 9-60» — железный великан, построенный, чтобы разгонять толпы. Толп здесь давно нет, но ему об этом никто не сказал.", ["duration"] = 25, ["cues"] = { { 0, "Инженерные лаборатории." }, { 1.87, "Здесь гномы чертили и испытывали самые смелые свои изобретения, а теперь бродят обезумевшие механики и патрули сторожевых машин." }, { 12.16, "На верхнем уступе стоит «Толпогон девять шестьдесят» — железный великан, построенный, чтобы разгонять толпы." }, { 20.87, "Толп здесь давно нет, но ему об этом никто не сказал." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_gnomeregan_pummeler_pull", ["enc"] = 2771, ["track"] = { ["hash"] = "aa2db562", ["text"] = "«Толпогон» тяжело разворачивается и вскидывает железные кулаки. Кто жмётся к нему гурьбой, всей гурьбой и получит массовую зуботычину, а удар по дуге сметает всех, кто оказался перед машиной.", ["duration"] = 14.8, ["cues"] = { { 0, "«Толпогон» тяжело разворачивается и вскидывает железные кулаки." }, { 4.98, "Кто жмётся к нему гурьбой, всей гурьбой и получит массовую зуботычину, а удар по дуге сметает всех, кто оказался перед машиной." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_gnomeregan_pummeler", ["enc"] = 2771, ["track"] = { ["hash"] = "e190e9a4", ["text"] = "«Толпогон 9-60» замирает с лязгом, будто у него разом кончился завод. Гномы гордились тем, что их машины умнее троггов. Но машина без хозяина бьёт любого, кто окажется рядом, и своих тоже. В Гномрегане это поняли слишком поздно.", ["duration"] = 19.8, ["cues"] = { { 0, "«Толпогон девять шестьдесят» замирает с лязгом, будто у него разом кончился завод." }, { 6.88, "Гномы гордились тем, что их машины умнее троггов." }, { 10.96, "Но машина без хозяина бьёт любого, кто окажется рядом, и своих тоже." }, { 16.58, "В Гномрегане это поняли слишком поздно." } } } }, { ["sub"] = "Двор Механиков", ["role"] = "final", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_gnomeregan_therma_intro", ["enc"] = 2772, ["pos"] = 5, ["track"] = { ["hash"] = "c1063446", ["text"] = "Двор Механиков. Когда-то здесь собирались лучшие умы Гномрегана, а теперь правит Анжинер Термоштепсель. Меггакрут доверял ему, но, когда город пал, Термоштепсель не ушёл со своим народом, а остался здесь править. Ради чего — власти, богатства? Всё это он и так со временем получил бы.", ["duration"] = 23.3, ["cues"] = { { 0, "Двор Механиков." }, { 1.28, "Когда-то здесь собирались лучшие умы Гномрегана, а теперь правит Анжинер Термоштепсель." }, { 8.56, "Меггакрут доверял ему, но, когда город пал, Термоштепсель не ушёл со своим народом, а остался здесь править." }, { 17.5, "Ради чего — власти, богатства?" }, { 20.13, "Всё это он и так со временем получил бы." } } } }, { ["q"] = 2929, ["follows"] = "dm_gnomeregan_therma_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_gnomeregan_hook_2929_pod", ["track"] = { ["hash"] = "ec694e02", ["text"] = "Именно его смерти ждёт Меггакрут.", ["duration"] = 3.3, ["cues"] = { { 0, "Именно его смерти ждёт Меггакрут." } } } }, { ["role"] = "final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_gnomeregan_therma_pull", ["enc"] = 2772, ["track"] = { ["hash"] = "571b9ddb", ["text"] = "Анжинер Термоштепсель, которому Меггакрут когда-то доверял, грохочет в своей машине и отшвыривает тех, кто подошёл слишком близко. По стенам оживают раздатчики, и к вам ковыляют ходячие бомбы. У каждого раздатчика сбоку есть кнопка — анжинер очень надеется, что вы её не заметите.", ["duration"] = 20.4, ["cues"] = { { 0, "Анжинер Термоштепсель, которому Меггакрут когда-то доверял, грохочет в своей машине и отшвыривает тех, кто подошёл слишком близко." }, { 9.57, "По стенам оживают раздатчики, и к вам ковыляют ходячие бомбы." }, { 14.12, "У каждого раздатчика сбоку есть кнопка — анжинер очень надеется, что вы её не заметите." } } } }, { ["role"] = "final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_gnomeregan_therma", ["enc"] = 2772, ["track"] = { ["hash"] = "ff758b19", ["text"] = "Термоштепсель падает, и Двор Механиков затихает. Король пустого места так и не дождался подданных: всё его царство — трогги, слизь и сумасшедшие машины. Гномы вернутся сюда не завтра, радиация никуда не делась. Но предатель больше не сидит на их троне, и это уже начало.", ["duration"] = 23.5, ["cues"] = { { 0, "Термоштепсель падает, и Двор Механиков затихает." }, { 4.2, "Король пустого места так и не дождался подданных: всё его царство — трогги, слизь и сумасшедшие машины." }, { 13.23, "Гномы вернутся сюда не завтра, радиация никуда не делась." }, { 18.37, "Но предатель больше не сидит на их троне, и это уже начало." } } } }, { ["q"] = 2929, ["follows"] = "dm_gnomeregan_therma", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_gnomeregan_fin_2929", ["track"] = { ["hash"] = "995c63bc", ["text"] = "Возвращайтесь к Меггакруту в Стальгорн, в Город Механиков. Эту весть он ждал дольше всех.", ["duration"] = 7.4, ["cues"] = { { 0, "Возвращайтесь к Меггакруту в Стальгорн, в Город Механиков." }, { 4.99, "Эту весть он ждал дольше всех." } } } }, { ["q"] = 2841, ["follows"] = "dm_gnomeregan_therma", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_gnomeregan_fin_2841", ["track"] = { ["hash"] = "132b93fd", ["text"] = "Код от сейфа был при нём, а сейф с чертежами стоит здесь же, в зале. Ногг в Оргриммаре заждался.", ["duration"] = 7.7, ["cues"] = { { 0, "Код от сейфа был при нём, а сейф с чертежами стоит здесь же, в зале." }, { 5.55, "Ногг в Оргриммаре заждался." } } } } }, ["bosses"] = { { ["id"] = 2768, ["npcs"] = { 7361 }, ["name"] = "Grubbis", ["required"] = nil, ["token"] = "grubbis", ["names335"] = { "Grubbis" } }, { ["id"] = 2769, ["npcs"] = { 7079 }, ["name"] = "Viscous Fallout", ["required"] = nil, ["token"] = "fallout", ["names335"] = { "Viscous Fallout" } }, { ["id"] = 2770, ["npcs"] = { 6235 }, ["name"] = "Electrocutioner 6000", ["required"] = nil, ["token"] = "electro", ["names335"] = { "Electrocutioner 6000" } }, { ["id"] = 2771, ["npcs"] = { 6229 }, ["name"] = "Crowd Pummeler 9-60", ["required"] = nil, ["token"] = "pummeler", ["names335"] = { "Crowd Pummeler 9-60" } }, { ["id"] = 2772, ["npcs"] = { 7800 }, ["name"] = "Mekgineer Thermaplugg", ["required"] = nil, ["token"] = "therma", ["names335"] = { "Mekgineer Thermaplugg" } } } },
[109] = { ["key"] = "sunken_temple", ["order"] = { 3589, 3584 }, ["layout"] = "linear_with_side", ["alias"] = { [2956] = 3583, [486] = 3588, [487] = 3587, [488] = 3589, [490] = 3586, [491] = 3585, [492] = 3583, [493] = 3584, [2959] = 3584, [2952] = 3582, [2814] = 3582 }, ["name"] = "Затонувший храм", ["events"] = { { ["id"] = "dm_sunken_temple_prolog", ["k"] = "prolog", ["trig"] = "prolog", ["track"] = { ["hash"] = "9c777dc9", ["text"] = "Вы в Затонувшем храме — святилище Атал'Хаккара под водами Болота Печали. Больше тысячи лет назад жрецы Атал'ай пытались призвать в мир Хаккара, бога крови, и за это были изгнаны из империи Гурубаши. Здесь, в болотах, они построили ему новый храм, но Изера, Аспект зелёных драконов, узнала об их замысле и утопила храм в трясине. Это не остановило Атал'ай: в темноте под водой их ритуалам никто не мешает. А зелёные драконы, оставленные сторожить храм, сами начали сходить с ума.", ["duration"] = 40.9, ["cues"] = { { 0, "Вы в Затонувшем храме — святилище Атал'Хаккара под водами Болота Печали." }, { 6.22, "Больше тысячи лет назад жрецы Атал'ай пытались призвать в мир Хаккара, бога крови, и за это были изгнаны из империи Гурубаши." }, { 17.18, "Здесь, в болотах, они построили ему новый храм, но Изера, Аспект зелёных драконов, узнала об их замысле и утопила храм в трясине." }, { 28.21, "Это не остановило Атал'ай: в темноте под водой их ритуалам никто не мешает." }, { 34.74, "А зелёные драконы, оставленные сторожить храм, сами начали сходить с ума." } } } }, { ["id"] = "dm_sunken_temple_prolog_repeat", ["k"] = "prolog", ["trig"] = "repeat", ["track"] = { ["hash"] = "68054ea6", ["text"] = "Снова Затонувший храм. Вода всё так же сочится сквозь своды, а Атал'ай всё так же молятся своему богу.", ["duration"] = 9, ["cues"] = { { 0, "Снова Затонувший храм." }, { 2.05, "Вода всё так же сочится сквозь своды, а Атал'ай всё так же молятся своему богу." } } } }, { ["q"] = 3528, ["prio"] = 0, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_sunken_temple_hook_3528", ["track"] = { ["hash"] = "5ce26c8e", ["text"] = "Йе'кинья доверил вам яйцо Хаккара. В Святилище Падшего Бога им можно разбудить мёртвого бога — и поймать его сущность.", ["duration"] = 10.1, ["cues"] = { { 0, "Йе'кинья доверил вам яйцо Хаккара." }, { 3.02, "В Святилище Падшего Бога им можно разбудить мёртвого бога — и поймать его сущность." } } } }, { ["q"] = 3446, ["prio"] = 1, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_sunken_temple_hook_3446", ["track"] = { ["hash"] = "7f46f6d2", ["text"] = "Марвон Клепальщик видел здесь круглый зал с шестью галереями и змеями из камня. Положите его знак на алтарь внизу — может быть, храм откроет свои тайны.", ["duration"] = 12.5, ["cues"] = { { 0, "Марвон Клепальщик видел здесь круглый зал с шестью галереями и змеями из камня." }, { 6.58, "Положите его знак на алтарь внизу — может быть, храм откроет свои тайны." } } } }, { ["q"] = 1475, ["prio"] = 2, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_sunken_temple_hook_1475", ["track"] = { ["hash"] = "60b97cf0", ["text"] = "Брохан Бочкопуз ждёт десять табличек Атал'ай. С ними он вернётся в Лигу исследователей героем.", ["duration"] = 7.6, ["cues"] = { { 0, "Брохан Бочкопуз ждёт десять табличек Атал'ай." }, { 3.8, "С ними он вернётся в Лигу исследователей героем." } } } }, { ["q"] = 1445, ["prio"] = 3, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_sunken_temple_hook_1445", ["track"] = { ["hash"] = "e66eb7fd", ["text"] = "Фел'зерулу в Каменоре нужны двадцать фетишей Хаккара. Орда хочет понять, какую силу Атал'ай вкладывают в свои амулеты.", ["duration"] = 9.2, ["cues"] = { { 0, "Фел'зерулу в Каменоре нужны двадцать фетишей Хаккара." }, { 4.19, "Орда хочет понять, какую силу Атал'ай вкладывают в свои амулеты." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_sunken_temple_avatar_pull", ["enc"] = 3583, ["track"] = { ["hash"] = "646f5bc2", ["text"] = "Вечный огонь гаснет, и из него встаёт Аватара Хаккара — тень бога крови, обретшая плоть. Её проклятие путает слова на языке заклинателей, а тот, кого она сведёт с ума, обернётся против своих.", ["duration"] = 17.5, ["cues"] = { { 0, "Вечный огонь гаснет, и из него встаёт Аватара Хаккара — тень бога крови, обретшая плоть." }, { 8.21, "Её проклятие путает слова на языке заклинателей, а тот, кого она сведёт с ума, обернётся против своих." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_sunken_temple_avatar_res", ["enc"] = 3583, ["track"] = { ["hash"] = "8832fb12", ["text"] = "Аватара Хаккара распадается, и в святилище снова темно. Это была лишь тень бога, малая часть его силы, — но и её хватило бы, чтобы Атал'ай поверили в чудо. Сам Хаккар всё ещё ищет дорогу в мир, и не только здесь. Вечный огонь в святилище больше не вспыхнет.", ["duration"] = 21.7, ["cues"] = { { 0, "Аватара Хаккара распадается, и в святилище снова темно." }, { 4.77, "Это была лишь тень бога, малая часть его силы, — но и её хватило бы, чтобы Атал'ай поверили в чудо." }, { 13.3, "Сам Хаккар всё ещё ищет дорогу в мир, и не только здесь." }, { 17.99, "Вечный огонь в святилище больше не вспыхнет." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_sunken_temple_atal_pull", ["enc"] = 3582, ["track"] = { ["hash"] = "534f140f", ["text"] = "Посреди ямы встаёт Атал'аларион — громадный тролль, которого жрецы приставили стеречь свой идол. Его изгнание кончилось, и он сокрушает всё, что подошло слишком близко.", ["duration"] = 13.8, ["cues"] = { { 0, "Посреди ямы встаёт Атал'аларион — громадный тролль, которого жрецы приставили стеречь свой идол." }, { 8.02, "Его изгнание кончилось, и он сокрушает всё, что подошло слишком близко." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_sunken_temple_atal_res", ["enc"] = 3582, ["track"] = { ["hash"] = "9e1058a1", ["text"] = "Атал'аларион падает, и эхо ещё долго гуляет по яме. Жрецы Атал'ай поставили его стеречь свой идол, и он стерёг, пока круг статуй молчал. Каменные змеи на галереях смотрят на вас пустыми глазами. Тайна круга больше не тайна.", ["duration"] = 20.1, ["cues"] = { { 0, "Атал'аларион падает, и эхо ещё долго гуляет по яме." }, { 4.71, "Жрецы Атал'ай поставили его стеречь свой идол, и он стерёг, пока круг статуй молчал." }, { 12.36, "Каменные змеи на галереях смотрят на вас пустыми глазами." }, { 17.56, "Тайна круга больше не тайна." } } } }, { ["sub"] = "Обитель Избранного", ["role"] = "main", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_sunken_temple_jammalan_pod", ["enc"] = 3589, ["pos"] = 3, ["track"] = { ["hash"] = "8ad1fa1b", ["text"] = "Обитель Избранного. Здесь живёт Джаммал'ан Пророк, духовный вождь Атал'ай, а рядом с ним — его прислужник Огом Презренный. Джаммал'ан изгнал всех, кто сомневался в его видении, и вокруг него остались только верные. Он знает, что вы пришли, и встречает вас не как гостей, а как жертвы, достойные Хаккара.", ["duration"] = 25, ["cues"] = { { 0, "Обитель Избранного." }, { 1.67, "Здесь живёт Джаммал'ан Пророк, духовный вождь Атал'ай, а рядом с ним — его прислужник Огом Презренный." }, { 10.17, "Джаммал'ан изгнал всех, кто сомневался в его видении, и вокруг него остались только верные." }, { 17.91, "Он знает, что вы пришли, и встречает вас не как гостей, а как жертвы, достойные Хаккара." } } } }, { ["q"] = 1446, ["follows"] = "dm_sunken_temple_jammalan_pod", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_sunken_temple_hook_1446", ["track"] = { ["hash"] = "8f6d36cc", ["text"] = "Изгнанник племени Атал'ай ждёт голову Джаммал'ана. Это пророк изгнал его — за то, что тот посмел усомниться.", ["duration"] = 9.8, ["cues"] = { { 0, "Изгнанник племени Атал'ай ждёт голову Джаммал'ана." }, { 4.63, "Это пророк изгнал его — за то, что тот посмел усомниться." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_sunken_temple_jammalan_pull", ["enc"] = 3589, ["track"] = { ["hash"] = "c08b4f24", ["text"] = "Джаммал'ан, уверовавший, что Хаккар дарует Атал'ай бессмертие, воздевает руки — и камень под ногами вспыхивает огненным столбом, сжигая того, кто замешкается. Его проклятие обращает одного из вас против своих, а Огом за его спиной шлёт стрелы Тьмы.", ["duration"] = 19.5, ["cues"] = { { 0, "Джаммал'ан, уверовавший, что Хаккар дарует Атал'ай бессмертие, воздевает руки — и камень под ногами вспыхивает огненным столбом, сжигая того, кто замешкается." }, { 12.52, "Его проклятие обращает одного из вас против своих, а Огом за его спиной шлёт стрелы Тьмы." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_sunken_temple_jammalan_res", ["enc"] = 3589, ["track"] = { ["hash"] = "73f98046", ["text"] = "Джаммал'ан Пророк падает, так и не увидев, как сбывается его видение. Он обещал племени бессмертие, а привёл его на дно болота, в храм, из которого нет выхода. Его последователи ещё молятся, но молятся уже в пустоту. Атал'ай без пророка — просто тролли во тьме.", ["duration"] = 20.5, ["cues"] = { { 0, "Джаммал'ан Пророк падает, так и не увидев, как сбывается его видение." }, { 5.55, "Он обещал племени бессмертие, а привёл его на дно болота, в храм, из которого нет выхода." }, { 12.55, "Его последователи ещё молятся, но молятся уже в пустоту." }, { 17.1, "Атал'ай без пророка — просто тролли во тьме." } } } }, { ["q"] = 3528, ["follows"] = "dm_sunken_temple_jammalan_res", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_sunken_temple_jammalan_3528", ["track"] = { ["hash"] = "4050b256", ["text"] = "Не забудьте о яйце Хаккара: в Святилище Падшего Бога можно призвать аватару и поймать её сущность. Йе'кинья ждёт её в Танарисе.", ["duration"] = 11.3, ["cues"] = { { 0, "Не забудьте о яйце Хаккара: в Святилище Падшего Бога можно призвать аватару и поймать её сущность." }, { 8.93, "Йе'кинья ждёт её в Танарисе." } } } }, { ["q"] = 3447, ["follows"] = "dm_sunken_temple_jammalan_res", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_sunken_temple_jammalan_3447", ["track"] = { ["hash"] = "9c555b0b", ["text"] = "Марвон Клепальщик уверен, что круг статуй хранит ключ к сокровищам Атал'ай. Разгадайте огни у главного алтаря — и тайна камня откроется.", ["duration"] = 11.3, ["cues"] = { { 0, "Марвон Клепальщик уверен, что круг статуй хранит ключ к сокровищам Атал'ай." }, { 6.29, "Разгадайте огни у главного алтаря — и тайна камня откроется." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_sunken_temple_dreamscythe_pull", ["enc"] = 3588, ["track"] = { ["hash"] = "e81e4446", ["text"] = "Жнец Снов расправляет крылья, и порыв от их взмаха отбрасывает тех, кто стоит перед ним. Его кислотное дыхание растекается по камню, и горе тем, кто окажется у него перед пастью.", ["duration"] = 14.2, ["cues"] = { { 0, "Жнец Снов расправляет крылья, и порыв от их взмаха отбрасывает тех, кто стоит перед ним." }, { 7.01, "Его кислотное дыхание растекается по камню, и горе тем, кто окажется у него перед пастью." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_sunken_temple_dreamscythe_res", ["enc"] = 3588, ["track"] = { ["hash"] = "6bd71a3a", ["text"] = "Жнец Снов падает, и его крылья больше не поднимутся. Когда-то он сторожил храм по воле Изеры, чтобы никто не вернул Хаккара в мир. Кошмар превратил стража в чудовище. Возможно, вы сделали то, о чём он сам когда-то попросил бы.", ["duration"] = 19.2, ["cues"] = { { 0, "Жнец Снов падает, и его крылья больше не поднимутся." }, { 4.53, "Когда-то он сторожил храм по воле Изеры, чтобы никто не вернул Хаккара в мир." }, { 11.24, "Кошмар превратил стража в чудовище." }, { 14.36, "Возможно, вы сделали то, о чём он сам когда-то попросил бы." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_sunken_temple_weaver_pull", ["enc"] = 3587, ["track"] = { ["hash"] = "57a045f1", ["text"] = "Ткачик бросается в бой, и от взмаха его крыльев отлетает тот, кто стоит впереди. Он ловок и зол, а его кислота обжигает всех, кто окажется перед пастью.", ["duration"] = 12.2, ["cues"] = { { 0, "Ткачик бросается в бой, и от взмаха его крыльев отлетает тот, кто стоит впереди." }, { 6.57, "Он ловок и зол, а его кислота обжигает всех, кто окажется перед пастью." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_sunken_temple_weaver_res", ["enc"] = 3587, ["track"] = { ["hash"] = "6da4569d", ["text"] = "Ткачик затихает. Зелёные драконы приходят из Изумрудного Сна — мира, где всё живое видит свои сны. Этот видел только кошмары. Может быть, теперь он наконец отдохнёт. Его кислота ещё шипит на камнях, но и она скоро остынет.", ["duration"] = 19.4, ["cues"] = { { 0, "Ткачик затихает." }, { 1.51, "Зелёные драконы приходят из Изумрудного Сна — мира, где всё живое видит свои сны." }, { 8.57, "Этот видел только кошмары." }, { 11.03, "Может быть, теперь он наконец отдохнёт." }, { 14.44, "Его кислота ещё шипит на камнях, но и она скоро остынет." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_sunken_temple_morphaz_pull", ["enc"] = 3586, ["track"] = { ["hash"] = "bc88622f", ["text"] = "Морфаз выступает из темноты — один из стражей Эраникуса. Взмах его крыльев отбрасывает тех, кто стоит перед ним, а кислотное дыхание настигает всех, кто встретит его лицом к лицу.", ["duration"] = 14.4, ["cues"] = { { 0, "Морфаз выступает из темноты — один из стражей Эраникуса." }, { 4.63, "Взмах его крыльев отбрасывает тех, кто стоит перед ним, а кислотное дыхание настигает всех, кто встретит его лицом к лицу." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_sunken_temple_morphaz_res", ["enc"] = 3586, ["track"] = { ["hash"] = "a4b5996d", ["text"] = "Морфаз тяжело опускается на камни, крылья вздрагивают в последний раз и замирают. Он охранял покой своего повелителя до последнего, даже когда этот покой стал кошмаром. Драконья верность переживает разум, и это страшнее любой порчи.", ["duration"] = 19.2, ["cues"] = { { 0, "Морфаз тяжело опускается на камни, крылья вздрагивают в последний раз и замирают." }, { 6.73, "Он охранял покой своего повелителя до последнего, даже когда этот покой стал кошмаром." }, { 13.97, "Драконья верность переживает разум, и это страшнее любой порчи." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_sunken_temple_hazzas_pull", ["enc"] = 3585, ["track"] = { ["hash"] = "b2ae9f50", ["text"] = "Хаззас бросается в бой, защищая своего повелителя. Его крылья отбрасывают стоящих перед ним, а кислота разъедает всё, на что попадёт, — и больше всех достаётся тем, кто окажется перед пастью.", ["duration"] = 14.6, ["cues"] = { { 0, "Хаззас бросается в бой, защищая своего повелителя." }, { 3.98, "Его крылья отбрасывают стоящих перед ним, а кислота разъедает всё, на что попадёт, — и больше всех достаётся тем, кто окажется перед пастью." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_sunken_temple_hazzas_res", ["enc"] = 3585, ["track"] = { ["hash"] = "acfef21d", ["text"] = "Хаззас падает, и вокруг становится тихо. Он стерёг своего повелителя так долго, что, кажется, сам забыл, от кого и зачем. Кошмар оставил ему только эту службу, и теперь закончилась и она. Камни под ним ещё дымятся от его же кислоты.", ["duration"] = 19.7, ["cues"] = { { 0, "Хаззас падает, и вокруг становится тихо." }, { 3.54, "Он стерёг своего повелителя так долго, что, кажется, сам забыл, от кого и зачем." }, { 10.3, "Кошмар оставил ему только эту службу, и теперь закончилась и она." }, { 16.07, "Камни под ним ещё дымятся от его же кислоты." } } } }, { ["sub"] = "Чертог Спящего", ["role"] = "final", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_sunken_temple_eranikus_pod", ["enc"] = 3584, ["pos"] = 8, ["track"] = { ["hash"] = "f0a37a47", ["text"] = "Чертог Спящего. Здесь, в самом сердце храма, лежит зелёный дракон Эраникус: он пришёл, чтобы положить конец ритуалам троллей, и потерпел неудачу. Годы рядом с Хаккаром отравили его: связь с Изумрудным Сном слабеет, и кошмар поглощает его разум. То, что встретит вас, — лишь его тень, но и тени дракона хватит, чтобы похоронить здесь целый отряд.", ["duration"] = 30.2, ["cues"] = { { 0, "Чертог Спящего." }, { 1.44, "Здесь, в самом сердце храма, лежит зелёный дракон Эраникус: он пришёл, чтобы положить конец ритуалам троллей, и потерпел неудачу." }, { 12.85, "Годы рядом с Хаккаром отравили его: связь с Изумрудным Сном слабеет, и кошмар поглощает его разум." }, { 21.62, "То, что встретит вас, — лишь его тень, но и тени дракона хватит, чтобы похоронить здесь целый отряд." } } } }, { ["role"] = "final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_sunken_temple_eranikus_pull", ["enc"] = 3584, ["track"] = { ["hash"] = "57f3fc24", ["text"] = "Тень Эраникуса поднимает призрачную голову. Её дыхание жжёт кислотой, громовая поступь оглушает всех рядом, а кого она погрузит в дремоту, тот надолго выпадет из боя, кем бы он ни был.", ["duration"] = 15.7, ["cues"] = { { 0, "Тень Эраникуса поднимает призрачную голову." }, { 3.74, "Её дыхание жжёт кислотой, громовая поступь оглушает всех рядом, а кого она погрузит в дремоту, тот надолго выпадет из боя, кем бы он ни был." } } } }, { ["role"] = "final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_sunken_temple_eranikus_fin", ["enc"] = 3584, ["track"] = { ["hash"] = "ecb4c2d9", ["text"] = "Тень Эраникуса рассеивается, и в чертоге наступает настоящая тишина — не сон и не кошмар. Храм снова принадлежит болоту и тёмной воде. Но тень — не сам дракон: где-то Эраникус всё ещё бьётся в сетях кошмара. И Хаккар, бог крови, всё ещё ищет дорогу в мир.", ["duration"] = 23.5, ["cues"] = { { 0, "Тень Эраникуса рассеивается, и в чертоге наступает настоящая тишина — не сон и не кошмар." }, { 8.32, "Храм снова принадлежит болоту и тёмной воде." }, { 12.53, "Но тень — не сам дракон: где-то Эраникус всё ещё бьётся в сетях кошмара." }, { 19.22, "И Хаккар, бог крови, всё ещё ищет дорогу в мир." } } } }, { ["role"] = "final", ["k"] = "bag", ["trig"] = "qlog", ["id"] = "dm_sunken_temple_essence", ["quests"] = { 3373 }, ["track"] = { ["hash"] = "26c46b1a", ["text"] = "Среди праха лежит сущность Эраникуса — кристалл, в который дракон вдохнул частицу своей души. Коснитесь его, и вы услышите голос: дракон просит отнести кристалл в купель сущности, чтобы очистить разум от скверны.", ["duration"] = 17.8, ["cues"] = { { 0, "Среди праха лежит сущность Эраникуса — кристалл, в который дракон вдохнул частицу своей души." }, { 7.95, "Коснитесь его, и вы услышите голос: дракон просит отнести кристалл в купель сущности, чтобы очистить разум от скверны." } } } } }, ["bosses"] = { { ["id"] = 3583, ["npcs"] = { 8443 }, ["name"] = "Avatar of Hakkar", ["required"] = nil, ["token"] = "avatar", ["names335"] = { "Avatar of Hakkar" } }, { ["id"] = 3582, ["npcs"] = { 8580 }, ["name"] = "Atal'alarion", ["required"] = nil, ["token"] = "atal", ["names335"] = { "Atal'alarion" } }, { ["id"] = 3589, ["npcs"] = { 5710, 5711 }, ["name"] = "jammalan", ["required"] = { 5710, 5711 }, ["token"] = "jammalan", ["names335"] = { "Jammal'an the Prophet", "Ogom the Wretched" } }, { ["id"] = 3588, ["npcs"] = { 5721 }, ["name"] = "Dreamscythe", ["required"] = nil, ["token"] = "dreamscythe", ["names335"] = { "Dreamscythe" } }, { ["id"] = 3587, ["npcs"] = { 5720 }, ["name"] = "Weaver", ["required"] = nil, ["token"] = "weaver", ["names335"] = { "Weaver" } }, { ["id"] = 3586, ["npcs"] = { 5719 }, ["name"] = "Morphaz", ["required"] = nil, ["token"] = "morphaz", ["names335"] = { "Morphaz" } }, { ["id"] = 3585, ["npcs"] = { 5722 }, ["name"] = "Hazzas", ["required"] = nil, ["token"] = "hazzas", ["names335"] = { "Hazzas" } }, { ["id"] = 3584, ["npcs"] = { 5709 }, ["name"] = "Shade of Eranikus", ["required"] = nil, ["token"] = "eranikus", ["names335"] = { "Shade of Eranikus" } } } },
[129] = { ["key"] = "razorfen_downs", ["order"] = { 2784, 2785 }, ["layout"] = "branching", ["alias"] = {  }, ["name"] = "Курганы Иглошкурых", ["events"] = { { ["id"] = "dm_razorfen_downs_prolog", ["k"] = "prolog", ["trig"] = "prolog", ["track"] = { ["hash"] = "35b3e2f3", ["text"] = "Вы в Курганах Иглошкурых. По легенде, здесь пал полубог Агамагган, и из его крови поднялись эти исполинские шипы — святыня всех свинобразов. Теперь в святыне хозяйничает Плеть: жрецы племени Мертвой Головы служат личу Амненнару Хладовею, и здесь Плеть пополняет свои ряды. Живые Иглошкурые покорно ходят под рукой лича наравне с мертвецами. Отсюда нежить тянет руки ко всему Калимдору.", ["duration"] = 32.2, ["cues"] = { { 0, "Вы в Курганах Иглошкурых." }, { 2.13, "По легенде, здесь пал полубог Агамагган, и из его крови поднялись эти исполинские шипы — святыня всех свинобразов." }, { 11.71, "Теперь в святыне хозяйничает Плеть: жрецы племени Мёртвой Головы служат личу Амненнару Хладовею, и здесь Плеть пополняет свои ряды." }, { 22.74, "Живые Иглошкурые покорно ходят под рукой лича наравне с мертвецами." }, { 28.52, "Отсюда нежить тянет руки ко всему Калимдору." } } } }, { ["id"] = "dm_razorfen_downs_prolog_repeat", ["k"] = "prolog", ["trig"] = "repeat", ["track"] = { ["hash"] = "7e47a898", ["text"] = "Снова Курганы Иглошкурых. Шипы всё те же, а мертвецов между ними, кажется, только прибавилось.", ["duration"] = 8.2, ["cues"] = { { 0, "Снова Курганы Иглошкурых." }, { 2.32, "Шипы все те же, а мертвецов между ними, кажется, только прибавилось." } } } }, { ["q"] = 3341, ["prio"] = 0, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_razorfen_downs_hook_3341", ["track"] = { ["hash"] = "5ee71a89", ["text"] = "Эндрю Браунелл из Подгорода ждёт череп Амненнара Хладовея: у лича прямая связь с Нер'зулом, и её нужно оборвать.", ["duration"] = 9.3, ["cues"] = { { 0, "Эндрю Браунелл из Подгорода ждёт череп Амненнара Хладовея: у лича прямая связь с Нер'зулом, и её нужно оборвать." } } } }, { ["q"] = 3636, ["prio"] = 1, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_razorfen_downs_hook_3636", ["track"] = { ["hash"] = "64c69b33", ["text"] = "Архиепископ Бенедикт велит изгнать зло из этих холмов. А у зла здесь есть имя — Амненнар Хладовей.", ["duration"] = 9, ["cues"] = { { 0, "Архиепископ Бенедикт велит изгнать зло из этих холмов." }, { 5.15, "А у зла здесь есть имя — Амненнар Хладовей." } } } }, { ["q"] = 97196, ["prio"] = 2, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_razorfen_downs_hook_97196", ["track"] = { ["hash"] = "de075317", ["text"] = "Сутара Вольная Ловчая ждёт Око Хладовея — гадальный шар, через который лич следит за своими слугами. С ним Орда сможет выслеживать агентов Плети по всему Калимдору.", ["duration"] = 13.2, ["cues"] = { { 0, "Сутара Вольная Ловчая ждёт Око Хладовея — гадальный шар, через который лич следит за своими слугами." }, { 8.17, "С ним Орда сможет выслеживать агентов Плети по всему Калимдору." } } } }, { ["q"] = 96773, ["prio"] = 3, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_razorfen_downs_hook_96773", ["track"] = { ["hash"] = "584dbe3a", ["text"] = "Верховный маг Лан'далок хочет получить Око Хладовея, гадальный шар лича. Кирин-Тор щедро заплатит, чтобы понять, как он устроен.", ["duration"] = 10.6, ["cues"] = { { 0, "Верховный маг Лан'далок хочет получить Око Хладовея, гадальный шар лича." }, { 6.11, "Кирин-Тор щедро заплатит, чтобы понять, как он устроен." } } } }, { ["prio"] = 4, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_razorfen_downs_hook_alliance", ["faction"] = "Alliance", ["track"] = { ["hash"] = "ce92a5fd", ["text"] = "Это Степи Орды, Альянс, но Плети нет дела до флагов. Лич, который здесь окопался, одинаково опасен и для Оргриммара, и для Терамора.", ["duration"] = 11.3, ["cues"] = { { 0, "Это Степи Орды, Альянс, но Плети нет дела до флагов." }, { 4.7, "Лич, который здесь окопался, одинаково опасен и для Оргриммара, и для Терамора." } } } }, { ["role"] = "rare", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_razorfen_downs_plaguemaw_pull", ["enc"] = 2781, ["track"] = { ["hash"] = "995a9e45", ["text"] = "Ритуал почти завершён — и к идолу является Чумобрюх Гнилой, раздутый, гниющий заживо слуга Плети. От его гнилостной вони слабеют руки и ноги, а прикосновение оставляет в теле хворь, что точит силы, пока её не изгнать.", ["duration"] = 19.6, ["cues"] = { { 0, "Ритуал почти завершён — и к идолу является Чумобрюх Гнилой, раздутый, гниющий заживо слуга Плети." }, { 8.9, "От его гнилостной вони слабеют руки и ноги, а прикосновение оставляет в теле хворь, что точит силы, пока её не изгнать." } } } }, { ["role"] = "rare", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_razorfen_downs_plaguemaw_res", ["enc"] = 2781, ["track"] = { ["hash"] = "32c7da84", ["text"] = "Чумобрюх Гнилой падает, и огонь идола гаснет — навсегда. Свинобразы больше не будут пожирать здесь пленников из Степей. Белнистраз сдержал слово — и вы тоже.", ["duration"] = 14.2, ["cues"] = { { 0, "Чумобрюх Гнилой падает, и огонь идола гаснет — навсегда." }, { 5.24, "Свинобразы больше не будут пожирать здесь пленников из Степей." }, { 10.88, "Белнистраз сдержал слово — и вы тоже." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_razorfen_downs_tuten_pull", ["enc"] = 2780, ["track"] = { ["hash"] = "21be238c", ["text"] = "Третий удар гонга — и из темноты выползает Тутен'каш, мёртвый нерубский паук на службе Плети. Кто окажется перед его жвалами, того летящая паутина пригвоздит к полу. А его проклятие замедляет и руку, и заклинание, пока его не сорвут.", ["duration"] = 18.8, ["cues"] = { { 0, "Третий удар гонга — и из темноты выползает Тутен'каш, мёртвый нерубский паук на службе Плети." }, { 7.55, "Кто окажется перед его жвалами, того летящая паутина пригвоздит к полу." }, { 13.43, "А его проклятие замедляет и руку, и заклинание, пока его не сорвут." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_razorfen_downs_tuten_res", ["enc"] = 2780, ["track"] = { ["hash"] = "0aab8937", ["text"] = "Тутен'каш вздрагивает в последний раз и замирает, а паутина по углам зала обвисает. Нерубов Король-лич покорил первыми, ещё в Нордсколе, — и вот один из них служит Плети на другом краю света.", ["duration"] = 16.5, ["cues"] = { { 0, "Тутен'каш вздрагивает в последний раз и замирает, а паутина по углам зала обвисает." }, { 7.25, "Нерубов Король-лич покорил первыми, ещё в Нордсколе, — и вот один из них служит Плети на другом краю света." } } } }, { ["sub"] = "Груда костей", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_razorfen_downs_mordresh_pod", ["enc"] = 2782, ["pos"] = 3, ["track"] = { ["hash"] = "679202b5", ["text"] = "Груда костей. Посреди зала — гора черепов, а на ней, как на трибуне, стоит Мордреш Огненный Глаз и выкрикивает проповеди Плети. Внизу пляшет и ликует его паства — скелеты, которым всё равно, за что воевать, лишь бы воевать. Говорят, при жизни Мордреш был шаманом орков, а теперь в его глазницах горит чужое пламя.", ["duration"] = 26.8, ["cues"] = { { 0, "Груда костей." }, { 1.24, "Посреди зала — гора черепов, а на ней, как на трибуне, стоит Мордреш Огненный Глаз и выкрикивает проповеди Плети." }, { 10.92, "Внизу пляшет и ликует его паства — скелеты, которым всё равно, за что воевать, лишь бы воевать." }, { 19.13, "Говорят, при жизни Мордреш был шаманом орков, а теперь в его глазницах горит чужое пламя." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_razorfen_downs_mordresh_pull", ["enc"] = 2782, ["track"] = { ["hash"] = "b55ff114", ["text"] = "Мордреш обрывает проповедь и поворачивается к вам. В его ладонях зреют огненные шары, и каждый, что успеет сорваться с руки, бьёт больно, а тех, кто подберётся вплотную, он обдаёт кольцом огня.", ["duration"] = 15, ["cues"] = { { 0, "Мордреш обрывает проповедь и поворачивается к вам." }, { 3.94, "В его ладонях зреют огненные шары, и каждый, что успеет сорваться с руки, бьёт больно, а тех, кто подберётся вплотную, он обдаёт кольцом огня." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_razorfen_downs_mordresh_res", ["enc"] = 2782, ["track"] = { ["hash"] = "60eb69d0", ["text"] = "Мордреш Огненный Глаз валится с вершины своей груды, и пляска внизу обрывается. Без проповедника скелеты — просто кости. Плеть умеет так: берёт павших и делает из них своих глашатаев. Огонь в его глазницах гаснет последним, будто нехотя.", ["duration"] = 20.8, ["cues"] = { { 0, "Мордреш Огненный Глаз валится с вершины своей груды, и пляска внизу обрывается." }, { 7.09, "Без проповедника скелеты — просто кости." }, { 10.68, "Плеть умеет так: берёт павших и делает из них своих глашатаев." }, { 16.1, "Огонь в его глазницах гаснет последним, будто нехотя." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_razorfen_downs_glutton_pull", ["enc"] = 2784, ["track"] = { ["hash"] = "243fd3a5", ["text"] = "Обжора — поганище, сшитое из чужих тел, — с чавканьем разворачивается к вам. Пока он сыт, он просто бьёт. Но когда раны его разъярят, он впадает в исступление — и горе тому, кто стоит у него на пути: удары посыплются один за другим.", ["duration"] = 19.5, ["cues"] = { { 0, "Обжора — поганище, сшитое из чужих тел, — с чавканьем разворачивается к вам." }, { 6.38, "Пока он сыт, он просто бьёт." }, { 8.76, "Но когда раны его разъярят, он впадает в исступление — и горе тому, кто стоит у него на пути: удары посыплются один за другим." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_razorfen_downs_glutton_res", ["enc"] = 2784, ["track"] = { ["hash"] = "ab694598", ["text"] = "Обжора валится на бок, и от распоротого брюха несёт так, что слезятся глаза. Плеть шьёт таких из всего, что попадётся под руку, — и, судя по запаху, кормит тем же. В Лордероне поганища ходят целыми полками. Теперь Плеть привела такого и в Степи.", ["duration"] = 20.2, ["cues"] = { { 0, "Обжора валится на бок, и от распоротого брюха несёт так, что слезятся глаза." }, { 6.32, "Плеть шьёт таких из всего, что попадётся под руку, — и, судя по запаху, кормит тем же." }, { 13.39, "В Лордероне поганища ходят целыми полками." }, { 17.04, "Теперь Плеть привела такого и в Степи." } } } }, { ["q"] = 3525, ["follows"] = "dm_razorfen_downs_glutton_res", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_razorfen_downs_hook_3525", ["track"] = { ["hash"] = "2165ba7a", ["text"] = "Белнистраз всё ещё ждёт: идол свинобразов у входа должен погаснуть. Когда ритуал завершится, не спешите уходить — загляните в пламя его жаровни.", ["duration"] = 12.2, ["cues"] = { { 0, "Белнистраз всё ещё ждёт: идол свинобразов у входа должен погаснуть." }, { 5.73, "Когда ритуал завершится, не спешите уходить — загляните в пламя его жаровни." } } } }, { ["role"] = "rare", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_razorfen_downs_raggle_pull", ["enc"] = 2783, ["track"] = { ["hash"] = "bad8c2c7", ["text"] = "Из-за шипов выходит Круглорыл — свинобраз-заклинатель на службе Плети. Встречается он не каждой группе — вам выпало. Он умеет затягивать свои раны, а его чары подчиняют разум: тот, кто дрогнет, повернёт оружие против своих, пока морок не схлынет.", ["duration"] = 20.1, ["cues"] = { { 0, "Из-за шипов выходит Круглорыл — свинобраз-заклинатель на службе Плети." }, { 5.83, "Встречается он не каждой группе — вам выпало." }, { 9.53, "Он умеет затягивать свои раны, а его чары подчиняют разум: тот, кто дрогнет, повернёт оружие против своих, пока морок не схлынет." } } } }, { ["role"] = "rare", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_razorfen_downs_raggle_res", ["enc"] = 2783, ["track"] = { ["hash"] = "5648fe3d", ["text"] = "Круглорыл падает, и шипы вокруг на миг затихают. Лич не терпит непокорных, но и верных не бережёт. Кто встал под его знамёна, рано или поздно ложится здесь же.", ["duration"] = 13.8, ["cues"] = { { 0, "Круглорыл падает, и шипы вокруг на миг затихают." }, { 4.37, "Лич не терпит непокорных, но и верных не бережёт." }, { 8.66, "Кто встал под его знамёна, рано или поздно ложится здесь же." } } } }, { ["sub"] = "Тернистый серпантин", ["role"] = "final", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_razorfen_downs_amnennar_pod", ["enc"] = 2785, ["pos"] = 6, ["track"] = { ["hash"] = "fcd4965d", ["text"] = "Тернистый серпантин. Тропа витками уходит вверх, и на каждом — мертвецы. У подножия бродит Обжора, поганище Плети, а на вершине ждёт хозяин курганов — лич Амненнар Хладовей. Он слышит Нер'зула прямо в своей голове, и это через него свинобразы поддались воле Плети.", ["duration"] = 23.5, ["cues"] = { { 0, "Тернистый серпантин." }, { 1.85, "Тропа витками уходит вверх, и на каждом — мертвецы." }, { 6.44, "У подножия бродит Обжора, поганище Плети, а на вершине ждёт хозяин курганов — лич Амненнар Хладовей." }, { 15.38, "Он слышит Нер'зула прямо в своей голове, и это через него свинобразы поддались воле Плети." } } } }, { ["q"] = 3341, ["follows"] = "dm_razorfen_downs_amnennar_pod", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_razorfen_downs_pod_3341", ["track"] = { ["hash"] = "8af38c6c", ["text"] = "Именно его череп ждёт Эндрю Браунелл.", ["duration"] = 3.5, ["cues"] = { { 0, "Именно его череп ждёт Эндрю Браунелл." } } } }, { ["q"] = 3636, ["follows"] = "dm_razorfen_downs_amnennar_pod", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_razorfen_downs_pod_3636", ["track"] = { ["hash"] = "049e6a66", ["text"] = "Именно его смерти ждёт архиепископ Бенедикт.", ["duration"] = 3.8, ["cues"] = { { 0, "Именно его смерти ждёт архиепископ Бенедикт." } } } }, { ["q"] = 97196, ["follows"] = "dm_razorfen_downs_amnennar_pod", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_razorfen_downs_pod_97196", ["track"] = { ["hash"] = "b3115ecb", ["text"] = "Око Хладовея, гадальный шар лича, должно быть при нём.", ["duration"] = 5, ["cues"] = { { 0, "Око Хладовея, гадальный шар лича, должно быть при нём." } } } }, { ["q"] = 96773, ["follows"] = "dm_razorfen_downs_amnennar_pod", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_razorfen_downs_pod_96773", ["track"] = { ["hash"] = "b3115ecb", ["text"] = "Око Хладовея, гадальный шар лича, должно быть при нём.", ["duration"] = 5, ["cues"] = { { 0, "Око Хладовея, гадальный шар лича, должно быть при нём." } } } }, { ["role"] = "final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_razorfen_downs_amnennar_pull", ["enc"] = 2785, ["track"] = { ["hash"] = "c45d2cbc", ["text"] = "Лич поднимает руку, и воздух звенит от холода. Ледяные стрелы срываются с его пальцев одна за другой, вокруг сгущаются морозные призраки, а гнев его волной накрывает всех, кто стоит близко.", ["duration"] = 16, ["cues"] = { { 0, "Лич поднимает руку, и воздух звенит от холода." }, { 3.98, "Ледяные стрелы срываются с его пальцев одна за другой, вокруг сгущаются морозные призраки, а гнев его волной накрывает всех, кто стоит близко." } } } }, { ["role"] = "final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_razorfen_downs_amnennar_fin", ["enc"] = 2785, ["track"] = { ["hash"] = "b0e38668", ["text"] = "Амненнар Хладовей падает, и холод на вершине отступает. Связь с Нер'зулом, что тянулась отсюда через полмира, оборвана. Племя Мертвой Головы осталось без хозяина, а Плеть потеряла в Калимдоре глаза и уши — по крайней мере, эти.", ["duration"] = 18.9, ["cues"] = { { 0, "Амненнар Хладовей падает, и холод на вершине отступает." }, { 4.7, "Связь с Нер'зулом, что тянулась отсюда через полмира, оборвана." }, { 10.01, "Племя Мёртвой Головы осталось без хозяина, а Плеть потеряла в Калимдоре глаза и уши — по крайней мере, эти." } } } }, { ["q"] = 3341, ["follows"] = "dm_razorfen_downs_amnennar_fin", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_razorfen_downs_fin_3341", ["track"] = { ["hash"] = "2382df93", ["text"] = "Череп лича — Эндрю Браунеллу, в Подгород.", ["duration"] = 3.9, ["cues"] = { { 0, "Череп лича — Эндрю Браунеллу, в Подгород." } } } }, { ["q"] = 3636, ["follows"] = "dm_razorfen_downs_amnennar_fin", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_razorfen_downs_fin_3636", ["track"] = { ["hash"] = "3495103a", ["text"] = "Архиепископ Бенедикт ждёт вас в Штормграде с доброй вестью.", ["duration"] = 4.6, ["cues"] = { { 0, "Архиепископ Бенедикт ждёт вас в Штормграде с доброй вестью." } } } } }, ["bosses"] = { { ["id"] = 2781, ["npcs"] = { 7356 }, ["name"] = "plaguemaw", ["required"] = nil, ["token"] = "plaguemaw", ["names335"] = { "Plaguemaw the Rotting" } }, { ["id"] = 2780, ["npcs"] = { 7355 }, ["name"] = "Tuten'kash", ["required"] = nil, ["token"] = "tuten", ["names335"] = { "Tuten'kash" } }, { ["id"] = 2782, ["npcs"] = { 7357 }, ["name"] = "Mordresh Fire Eye", ["required"] = nil, ["token"] = "mordresh", ["names335"] = { "Mordresh Fire Eye" } }, { ["id"] = 2784, ["npcs"] = { 8567 }, ["name"] = "Glutton", ["required"] = nil, ["token"] = "glutton", ["names335"] = { "Glutton" } }, { ["id"] = 2783, ["npcs"] = { 7354 }, ["name"] = "raggle", ["required"] = nil, ["token"] = "raggle", ["names335"] = { "Ragglesnout" } }, { ["id"] = 2785, ["npcs"] = { 7358 }, ["name"] = "Amnennar the Coldbringer", ["required"] = nil, ["token"] = "amnennar", ["names335"] = { "Amnennar the Coldbringer" } } } },
[189] = { ["key"] = "scarlet_monastery", ["order"] = { 444, 2779, 447, 448, 450 }, ["layout"] = "wings", ["alias"] = {  }, ["name"] = "Монастырь Алого ордена", ["events"] = { { ["id"] = "dm_scarlet_monastery_prolog", ["k"] = "prolog", ["trig"] = "prolog", ["track"] = { ["hash"] = "efdac941", ["text"] = "Вы в Монастыре Алого ордена. Когда-то здесь молились священники Лордерона, а теперь это крепость фанатиков, которые после гибели королевства объявили войну всей нежити — и всем, кто им не по нраву. Они пытают пленных Отрекшихся и считают зачумлёнными всех, кто не принадлежит к ордену. Монастырь велик: у него четыре крыла — кладбище, библиотека, оружейная и собор. У каждого крыла свой хозяин, и ждёт он в самом его конце.", ["duration"] = 34.1, ["cues"] = { { 0, "Вы в Монастыре Алого ордена." }, { 2.36, "Когда-то здесь молились священники Лордерона, а теперь это крепость фанатиков, которые после гибели королевства объявили войну всей нежити — и всем, кто им не по нраву." }, { 16.01, "Они пытают пленных Отрёкшихся и считают зачумлёнными всех, кто не принадлежит к ордену." }, { 22.95, "Монастырь велик: у него четыре крыла — кладбище, библиотека, оружейная и собор." }, { 29.51, "У каждого крыла свой хозяин, и ждёт он в самом его конце." } } } }, { ["id"] = "dm_scarlet_monastery_prolog_repeat", ["k"] = "prolog", ["trig"] = "repeat", ["track"] = { ["hash"] = "490e2894", ["text"] = "Снова Монастырь Алого ордена. На место павших фанатиков уже встали новые, а хозяева крыльев ждут там же, где и в прошлый раз.", ["duration"] = 10, ["cues"] = { { 0, "Снова Монастырь Алого ордена." }, { 2.48, "На место павших фанатиков уже встали новые, а хозяева крыльев ждут там же, где и в прошлый раз." } } } }, { ["q"] = 1048, ["prio"] = 0, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_scarlet_monastery_hook_1048", ["track"] = { ["hash"] = "762257e1", ["text"] = "Вариматрас ждёт в Подгороде вестей о смерти верхушки монастыря: Верховного инквизитора Вайтмейн, командира Могрейна, Ирода и псаря Локси. Они в разных крыльях — за один заход не управиться.", ["duration"] = 14.6, ["cues"] = { { 0, "Вариматрас ждёт в Подгороде вестей о смерти верхушки монастыря: Верховного инквизитора Вайтмейн, командира Могрейна, Ирода и псаря Локси." }, { 10.65, "Они в разных крыльях — за один заход не управиться." } } } }, { ["q"] = 1053, ["prio"] = 1, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_scarlet_monastery_hook_1053", ["track"] = { ["hash"] = "e505641e", ["text"] = "Ролей Благочестивый из Южнобережья служил Алому ордену, пока не увидел, как в монастыре пытают невинных. Теперь он просит покончить с Вайтмейн, Могрейном, Иродом и Локси.", ["duration"] = 13.2, ["cues"] = { { 0, "Ролей Благочестивый из Южнобережья служил Алому ордену, пока не увидел, как в монастыре пытают невинных." }, { 8.19, "Теперь он просит покончить с Вайтмейн, Могрейном, Иродом и Локси." } } } }, { ["q"] = 1113, ["prio"] = 2, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_scarlet_monastery_hook_1113", ["track"] = { ["hash"] = "2584961f", ["text"] = "Мастер-аптекарь Фаранелл ждёт двадцать сердец Доблести — их носят в груди здешние фанатики. В Подгороде им найдут применение пострашнее костра.", ["duration"] = 11, ["cues"] = { { 0, "Мастер-аптекарь Фаранелл ждёт двадцать сердец Доблести — их носят в груди здешние фанатики." }, { 7.18, "В Подгороде им найдут применение пострашнее костра." } } } }, { ["prio"] = 3, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_scarlet_monastery_hook_alliance", ["faction"] = "Alliance", ["track"] = { ["hash"] = "828bed75", ["text"] = "Это земли Отрекшихся, Альянс, и до Подгорода отсюда ближе, чем до Южнобережья. Но Алый орден не делает различий: вас здесь встретят как врагов.", ["duration"] = 11.8, ["cues"] = { { 0, "Это земли Отрёкшихся, Альянс, и до Подгорода отсюда ближе, чем до Южнобережья." }, { 6.53, "Но Алый орден не делает различий: вас здесь встретят как врагов." } } } }, { ["sub"] = "Чертог Искупления", ["role"] = "main", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_scarlet_monastery_vishas_pod", ["enc"] = 444, ["pos"] = 1, ["track"] = { ["hash"] = "3ba87d68", ["text"] = "Чертог Искупления — так Алый орден называет свою пыточную. Сюда приводят пленных Отрекшихся и прочую нежить, чтобы «очистить» их болью. Хозяин чертога — дознаватель Вишас, главный палач монастыря, и своё ремесло он любит. Воррела Сенгутца он мучил неделями.", ["duration"] = 22.2, ["cues"] = { { 0, "Чертог Искупления — так Алый орден называет свою пыточную." }, { 5.17, "Сюда приводят пленных Отрёкшихся и прочую нежить, чтобы «очистить» их болью." }, { 11.83, "Хозяин чертога — дознаватель Вишас, главный палач монастыря, и своё ремесло он любит." }, { 19.27, "Воррела Сенгутца он мучил неделями." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scarlet_monastery_vishas_pull", ["enc"] = 444, ["track"] = { ["hash"] = "6070a8c5", ["text"] = "Вишас требует признаний, и в его пальцах вспыхивает пламя. Горе тому, кого он пометит: огонь въедается в кожу и жжёт ещё долго после того, как вспышка погаснет.", ["duration"] = 14.2, ["cues"] = { { 0, "Вишас требует признаний, и в его пальцах вспыхивает пламя." }, { 5.28, "Горе тому, кого он пометит: огонь въедается в кожу и жжёт ещё долго после того, как вспышка погаснет." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_scarlet_monastery_vishas_res", ["enc"] = 444, ["track"] = { ["hash"] = "e0292f79", ["text"] = "Дознаватель Вишас падает на пол собственной пыточной. Он обещал вырвать правду из кого угодно — из живого или из мёртвого. Алый орден верит, что боль очищает. Сегодня его дознаватель проверил это на себе.", ["duration"] = 17.6, ["cues"] = { { 0, "Дознаватель Вишас падает на пол собственной пыточной." }, { 4.62, "Он обещал вырвать правду из кого угодно — из живого или из мёртвого." }, { 10.56, "Алый орден верит, что боль очищает." }, { 13.69, "Сегодня его дознаватель проверил это на себе." } } } }, { ["q"] = 1051, ["follows"] = "dm_scarlet_monastery_vishas_res", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_scarlet_monastery_hook_1051", ["track"] = { ["hash"] = "4e49f97b", ["text"] = "Воррел Сенгутц, которого Вишас мучил неделями, хочет вернуть своё обручальное кольцо. Дознаватель отдал его жене, Нэнси, что живёт у озера Лордамер, — спрашивать придётся с неё.", ["duration"] = 14, ["cues"] = { { 0, "Воррел Сенгутц, которого Вишас мучил неделями, хочет вернуть своё обручальное кольцо." }, { 6.9, "Дознаватель отдал его жене, Нэнси, что живёт у озера Лордамер, — спрашивать придётся с неё." } } } }, { ["sub"] = "Гробница Доблести", ["role"] = "wing_final", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_scarlet_monastery_thalnos_pod", ["enc"] = 2779, ["pos"] = 2, ["track"] = { ["hash"] = "642f628c", ["text"] = "Гробница Доблести — склеп в конце кладбищенского крыла, полный беспокойных призраков и мертвецов. Её строили для доблестных, но покоя здесь нет никому. На самом дне ждёт волшебник крови Талнос — скелет, который правит здешними мертвецами и жаждет мести живым.", ["duration"] = 22.2, ["cues"] = { { 0, "Гробница Доблести — склеп в конце кладбищенского крыла, полный беспокойных призраков и мертвецов." }, { 8.38, "Её строили для доблестных, но покоя здесь нет никому." }, { 12.92, "На самом дне ждёт волшебник крови Талнос — скелет, который правит здешними мертвецами и жаждет мести живым." } } } }, { ["role"] = "wing_final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scarlet_monastery_thalnos_pull", ["enc"] = 2779, ["track"] = { ["hash"] = "4ec802e3", ["text"] = "Талнос поднимает костлявые руки, и мёртвые в склепе подхватывают его крик о мести. Под ногами то и дело вспыхивает огненный столп — кто в нём задержится, сгорит, — а тех, кто толпится рядом, волшебник обдаёт кольцом огня.", ["duration"] = 17.9, ["cues"] = { { 0, "Талнос поднимает костлявые руки, и мёртвые в склепе подхватывают его крик о мести." }, { 6.83, "Под ногами то и дело вспыхивает огненный столп — кто в нём задержится, сгорит, — а тех, кто толпится рядом, волшебник обдаёт кольцом огня." } } } }, { ["role"] = "wing_final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_scarlet_monastery_thalnos_fin", ["enc"] = 2779, ["track"] = { ["hash"] = "e8f38de8", ["text"] = "Волшебник крови Талнос падает грудой костей, и склеп затихает. Он жаждал мести живым — и не дождался. Кладбищенское крыло очищено — по-настоящему, а не так, как это делает орден.", ["duration"] = 16.2, ["cues"] = { { 0, "Волшебник крови Талнос падает грудой костей, и склеп затихает." }, { 5.8, "Он жаждал мести живым — и не дождался." }, { 9.36, "Кладбищенское крыло очищено — по-настоящему, а не так, как это делает орден." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scarlet_monastery_loksey_pull", ["enc"] = 446, ["track"] = { ["hash"] = "3f0fde9b", ["text"] = "Псарь Локси спускает свору. Ищейки Алого ордена идут на запах нежити, но живых рвут не хуже. Стоит хозяину рявкнуть — и в них вскипает кровожадность: собаки и сам Локси бьют всё быстрее и злее, и это бешенство само не уймётся.", ["duration"] = 19.2, ["cues"] = { { 0, "Псарь Локси спускает свору." }, { 2.4, "Ищейки Алого ордена идут на запах нежити, но живых рвут не хуже." }, { 8.05, "Стоит хозяину рявкнуть — и в них вскипает кровожадность: собаки и сам Локси бьют всё быстрее и злее, и это бешенство само не уймётся." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_scarlet_monastery_loksey_res", ["enc"] = 446, ["track"] = { ["hash"] = "25e1adbf", ["text"] = "Псарь Локси затихает среди своих собак. Он растил ищеек, по следу которых орден выслеживал врагов, и свора слушалась только его. Сегодня она осталась без хозяина.", ["duration"] = 14.2, ["cues"] = { { 0, "Псарь Локси затихает среди своих собак." }, { 3.52, "Он растил ищеек, по следу которых орден выслеживал врагов, и свора слушалась только его." }, { 11.35, "Сегодня она осталась без хозяина." } } } }, { ["sub"] = "Читальня", ["role"] = "wing_final", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_scarlet_monastery_doan_pod", ["enc"] = 447, ["pos"] = 4, ["track"] = { ["hash"] = "2d9b78c7", ["text"] = "Читальня — сердце библиотеки Алого ордена, где хранятся его книги и свитки. Здесь хозяйничает чародей Доан, хранитель здешних знаний. Чужим он их не отдаст: для него вы — осквернители тайн, которые он стережёт.", ["duration"] = 18, ["cues"] = { { 0, "Читальня — сердце библиотеки Алого ордена, где хранятся его книги и свитки." }, { 6.68, "Здесь хозяйничает чародей Доан, хранитель здешних знаний." }, { 11.71, "Чужим он их не отдаст: для него вы — осквернители тайн, которые он стережёт." } } } }, { ["q"] = 96800, ["follows"] = "dm_scarlet_monastery_doan_pod", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_scarlet_monastery_hook_96800", ["track"] = { ["hash"] = "565de258", ["text"] = "Волхв Ольвек ждёт книгу «Утерянная магия мастеров рун»: по его записям, Доан взял её в старой библиотеке Даларана ещё до Третьей войны и так и не вернул. Должник — перед вами.", ["duration"] = 14.9, ["cues"] = { { 0, "Волхв Ольвек ждёт книгу «Утерянная магия мастеров рун»: по его записям, Доан взял её в старой библиотеке Даларана ещё до Третьей войны и так и не вернул." }, { 13.09, "Должник — перед вами." } } } }, { ["q"] = 1160, ["follows"] = "dm_scarlet_monastery_doan_pod", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_scarlet_monastery_hook_1160", ["track"] = { ["hash"] = "96d590ad", ["text"] = "Парквел Финталлас ждёт книгу «Истоки угрозы нежити» — по ней орден учит своих паладинов истреблять Отрекшихся. Ищите её в здешней библиотеке.", ["duration"] = 11.2, ["cues"] = { { 0, "Парквел Финталлас ждёт книгу «Истоки угрозы нежити» — по ней орден учит своих паладинов истреблять Отрёкшихся." }, { 8.88, "Ищите её в здешней библиотеке." } } } }, { ["q"] = 1049, ["follows"] = "dm_scarlet_monastery_doan_pod", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_scarlet_monastery_hook_1049", ["track"] = { ["hash"] = "0dad753f", ["text"] = "Ведун Искатель Истины просит «Компендиум павших» — записи фанатиков о нежити. В Громовом Утесе хотят знать, что на самом деле скрывают их новые союзники.", ["duration"] = 12.7, ["cues"] = { { 0, "Ведун Искатель Истины просит «Компендиум павших» — записи фанатиков о нежити." }, { 6.59, "В Громовом Утёсе хотят знать, что на самом деле скрывают их новые союзники." } } } }, { ["q"] = 1050, ["follows"] = "dm_scarlet_monastery_doan_pod", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_scarlet_monastery_hook_1050", ["track"] = { ["hash"] = "bddaa354", ["text"] = "Библиотекарь Мая Белокожка мечтает о «Мифологии Титанов». Ходят слухи, что книга хранится здесь, в библиотеке монастыря.", ["duration"] = 9.5, ["cues"] = { { 0, "Библиотекарь Мая Белокожка мечтает о «Мифологии Титанов»." }, { 4.65, "Ходят слухи, что книга хранится здесь, в библиотеке монастыря." } } } }, { ["role"] = "wing_final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scarlet_monastery_doan_pull", ["enc"] = 447, ["track"] = { ["hash"] = "4a6f22a9", ["text"] = "Доан вскидывает руки, и воздух звенит от тайной магии. Заклинателей он глушит молчанием, неосторожных обращает в овец, а когда вокруг него сгущается чародейская сила — горе тем, кто окажется рядом: вблизи этот взрыв не пережить.", ["duration"] = 19.3, ["cues"] = { { 0, "Доан вскидывает руки, и воздух звенит от тайной магии." }, { 4.74, "Заклинателей он глушит молчанием, неосторожных обращает в овец, а когда вокруг него сгущается чародейская сила — горе тем, кто окажется рядом: вблизи этот взрыв не пережить." } } } }, { ["role"] = "wing_final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_scarlet_monastery_doan_fin", ["enc"] = 447, ["track"] = { ["hash"] = "44c1cc4f", ["text"] = "Чародей Доан падает, и в Читальне становится тихо. Он берёг тайны библиотеки от чужих рук — теперь стеречь их некому. Библиотечное крыло ваше.", ["duration"] = 12.9, ["cues"] = { { 0, "Чародей Доан падает, и в Читальне становится тихо." }, { 4.71, "Он берёг тайны библиотеки от чужих рук — теперь стеречь их некому." }, { 10.73, "Библиотечное крыло ваше." } } } }, { ["role"] = "wing_final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scarlet_monastery_herod_pull", ["enc"] = 448, ["track"] = { ["hash"] = "e04048f4", ["text"] = "Ирод, один из четырёх вождей монастыря, давно ждал достойного противника — и бросается на первого, кто подвернётся. Когда он закружится вихрем стали, горе тому, кто окажется внутри. А почуяв кровь, он впадает в исступление и бьёт всё чаще.", ["duration"] = 18.9, ["cues"] = { { 0, "Ирод, один из четырёх вождей монастыря, давно ждал достойного противника — и бросается на первого, кто подвернётся." }, { 9.12, "Когда он закружится вихрем стали, горе тому, кто окажется внутри." }, { 14.51, "А почуяв кровь, он впадает в исступление и бьёт всё чаще." } } } }, { ["role"] = "wing_final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_scarlet_monastery_herod_fin", ["enc"] = 448, ["track"] = { ["hash"] = "df0393a9", ["text"] = "Ирод падает, и в оружейной становится тихо. Один из вождей монастыря больше не встанет. Но тишина длится недолго: на шум уже бегут новобранцы — орден бросает в бой тех, кого ещё не успел выучить. Будьте готовы их встретить.", ["duration"] = 19, ["cues"] = { { 0, "Ирод падает, и в оружейной становится тихо." }, { 3.78, "Один из вождей монастыря больше не встанет." }, { 7.55, "Но тишина длится недолго: на шум уже бегут новобранцы — орден бросает в бой тех, кого ещё не успел выучить." }, { 16.73, "Будьте готовы их встретить." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scarlet_monastery_fairbanks_pull", ["enc"] = 449, ["track"] = { ["hash"] = "e096dc4e", ["text"] = "Перед вами верховный инквизитор Фэйрбанкс — мертвец, которого орден хотел бы забыть: его казнили за слова, которые здесь не желали слышать. Его проклятие крови цепляется к живым, и пока оно держится, каждая рана болит сильнее.", ["duration"] = 18.5, ["cues"] = { { 0, "Перед вами верховный инквизитор Фэйрбанкс — мертвец, которого орден хотел бы забыть: его казнили за слова, которые здесь не желали слышать." }, { 11.4, "Его проклятие крови цепляется к живым, и пока оно держится, каждая рана болит сильнее." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_scarlet_monastery_fairbanks_res", ["enc"] = 449, ["track"] = { ["hash"] = "aa002bdb", ["text"] = "Фэйрбанкс снова затихает — теперь, наверное, навсегда. Когда-то он был ближайшим советником верховного лорда Могрейна и видел, как тот погиб от руки собственного сына. Он рассказывал об этом всем, кто готов был слушать, — и орден заставил его замолчать.", ["duration"] = 20.3, ["cues"] = { { 0, "Фэйрбанкс снова затихает — теперь, наверное, навсегда." }, { 4.48, "Когда-то он был ближайшим советником верховного лорда Могрейна и видел, как тот погиб от руки собственного сына." }, { 13.58, "Он рассказывал об этом всем, кто готов был слушать, — и орден заставил его замолчать." } } } }, { ["sub"] = "Часовня Ордена", ["role"] = "wing_final", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_scarlet_monastery_whitemane_pod", ["enc"] = 450, ["pos"] = 7, ["track"] = { ["hash"] = "34cf334a", ["text"] = "Часовня Ордена — сердце монастыря, куда крестоносцы приходят молиться. Здесь стоит командир Могрейн, сын великого паладина, и здесь же служит верховный инквизитор Вайтмейн, глава монастыря. Говорят, её молитва поднимает павших.", ["duration"] = 18, ["cues"] = { { 0, "Часовня Ордена — сердце монастыря, куда крестоносцы приходят молиться." }, { 5.71, "Здесь стоит командир Могрейн, сын великого паладина, и здесь же служит верховный инквизитор Вайтмейн, глава монастыря." }, { 15.11, "Говорят, её молитва поднимает павших." } } } }, { ["role"] = "wing_final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scarlet_monastery_whitemane_pull", ["enc"] = 450, ["track"] = { ["hash"] = "087c2398", ["text"] = "Командир Могрейн идёт на вас сам — гордый, как и подобает сыну героя. Но это лишь половина боя: когда он падёт, в бой вступит Вайтмейн. Её молитвы затягивают любые раны, а когда она погрузит всех в сон — павший командир встанет снова.", ["duration"] = 19.4, ["cues"] = { { 0, "Командир Могрейн идёт на вас сам — гордый, как и подобает сыну героя." }, { 5.75, "Но это лишь половина боя: когда он падёт, в бой вступит Вайтмейн." }, { 11.2, "Её молитвы затягивают любые раны, а когда она погрузит всех в сон — павший командир встанет снова." } } } }, { ["role"] = "wing_final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_scarlet_monastery_whitemane_fin", ["enc"] = 450, ["track"] = { ["hash"] = "e82dc0db", ["text"] = "Верховный инквизитор Вайтмейн падает рядом с командиром, и на этот раз поднимать павших некому. В часовне становится тихо — ни молитв, ни приговоров. Алый орден лишился сердца монастыря, но не веры: на востоке, в Чумных землях, ещё горят его костры.", ["duration"] = 21, ["cues"] = { { 0, "Верховный инквизитор Вайтмейн падает рядом с командиром, и на этот раз поднимать павших некому." }, { 8.08, "В часовне становится тихо — ни молитв, ни приговоров." }, { 12.58, "Алый орден лишился сердца монастыря, но не веры: на востоке, в Чумных землях, ещё горят его костры." } } } }, { ["q"] = 1048, ["follows"] = "dm_scarlet_monastery_whitemane_fin", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_scarlet_monastery_fin_1048", ["track"] = { ["hash"] = "a4af7005", ["text"] = "Вайтмейн и Могрейн из списка Вариматраса пали. Если с остальными тоже покончено — он ждёт вас в Подгороде.", ["duration"] = 8.3, ["cues"] = { { 0, "Вайтмейн и Могрейн из списка Вариматраса пали." }, { 3.77, "Если с остальными тоже покончено — он ждёт вас в Подгороде." } } } }, { ["q"] = 1053, ["follows"] = "dm_scarlet_monastery_whitemane_fin", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_scarlet_monastery_fin_1053", ["track"] = { ["hash"] = "490c06f4", ["text"] = "Ролею Благочестивому в Южнобережье будет за что вознести молитву.", ["duration"] = 5.3, ["cues"] = { { 0, "Ролею Благочестивому в Южнобережье будет за что вознести молитву." } } } } }, ["bosses"] = { { ["id"] = 444, ["npcs"] = { 3983 }, ["name"] = "Interrogator Vishas", ["required"] = nil, ["token"] = "vishas", ["names335"] = { "Interrogator Vishas" } }, { ["id"] = 2779, ["npcs"] = { 4543 }, ["name"] = "Bloodmage Thalnos", ["required"] = nil, ["token"] = "thalnos", ["names335"] = { "Bloodmage Thalnos" } }, { ["id"] = 446, ["npcs"] = { 3974 }, ["name"] = "Houndmaster Loksey", ["required"] = nil, ["token"] = "loksey", ["names335"] = { "Houndmaster Loksey" } }, { ["id"] = 447, ["npcs"] = { 6487 }, ["name"] = "Arcanist Doan", ["required"] = nil, ["token"] = "doan", ["names335"] = { "Arcanist Doan" } }, { ["id"] = 448, ["npcs"] = { 3975 }, ["name"] = "Herod", ["required"] = nil, ["token"] = "herod", ["names335"] = { "Herod" } }, { ["id"] = 449, ["npcs"] = { 4542 }, ["name"] = "High Inquisitor Fairbanks", ["required"] = nil, ["token"] = "fairbanks", ["names335"] = { "High Inquisitor Fairbanks" } }, { ["id"] = 450, ["npcs"] = { 3976, 3977 }, ["name"] = "High Inquisitor Whitemane", ["required"] = { 3977 }, ["token"] = "whitemane", ["names335"] = { "Scarlet Commander Mograine", "High Inquisitor Whitemane" } } } },
[209] = { ["key"] = "zulfarrak", ["order"] = { 598, 599, 600 }, ["layout"] = "linear_with_side", ["alias"] = {  }, ["name"] = "Зул'Фаррак", ["events"] = { { ["id"] = "dm_zulfarrak_prolog", ["k"] = "prolog", ["trig"] = "prolog", ["track"] = { ["hash"] = "952975ff", ["text"] = "Вы в Зул'Фарраке — городе троллей посреди раскалённых песков Танариса. Когда-то здесь шумели джунгли империи Гурубаши, но Великий Раскол превратил их в пустыню, а здешние тролли стали племенем Песчаной Бури — жестоким, как солнце над головой. Здесь всё под открытым небом: площади, гробницы, ступени пирамиды и священный пруд. Говорят, в его водах спит чудовище, которое лучше не будить, а на кладбищах здешние знахари поднимают мёртвых из могил. На вершине пирамиды тролли держат в клетках пленников — наёмников сержанта Блая, что пришли сюда из Прибамбасска за сокровищами.", ["duration"] = 44.7, ["cues"] = { { 0, "Вы в Зул'Фарраке — городе троллей посреди раскалённых песков Танариса." }, { 5.48, "Когда-то здесь шумели джунгли империи Гурубаши, но Великий Раскол превратил их в пустыню, а здешние тролли стали племенем Песчаной Бури — жестоким, как солнце над головой." }, { 18.99, "Здесь всё под открытым небом: площади, гробницы, ступени пирамиды и священный пруд." }, { 25.46, "Говорят, в его водах спит чудовище, которое лучше не будить, а на кладбищах здешние знахари поднимают мёртвых из могил." }, { 34.84, "На вершине пирамиды тролли держат в клетках пленников — наёмников сержанта Блая, что пришли сюда из Прибамбасска за сокровищами." } } } }, { ["id"] = "dm_zulfarrak_prolog_repeat", ["k"] = "prolog", ["trig"] = "repeat", ["track"] = { ["hash"] = "ed4cd742", ["text"] = "Снова Зул'Фаррак. Песок замёл ваши следы, но тролли Песчаной Бури вас не забыли.", ["duration"] = 7.6, ["cues"] = { { 0, "Снова Зул'Фаррак." }, { 1.73, "Песок замёл ваши следы, но тролли Песчаной Бури вас не забыли." } } } }, { ["q"] = 3527, ["prio"] = 0, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_zulfarrak_hook_3527", ["track"] = { ["hash"] = "01fa2e10", ["text"] = "Йе'кинья ждёт таблички Мошару. Первая — у Теки Мученика, вторая — у гидромантки Велраты возле священного пруда.", ["duration"] = 9.1, ["cues"] = { { 0, "Йе'кинья ждёт таблички Мошару." }, { 2.54, "Первая — у Теки Мученика, вторая — у гидромантки Велраты возле священного пруда." } } } }, { ["q"] = 2768, ["prio"] = 1, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_zulfarrak_hook_2768", ["track"] = { ["hash"] = "d4826d02", ["text"] = "Главный инженер Чепухастер ищет свой изыскательский стержень. Его прихватил сержант Блай — тот самый наёмник с пирамиды.", ["duration"] = 9.2, ["cues"] = { { 0, "Главный инженер Чепухастер ищет свой изыскательский стержень." }, { 4.82, "Его прихватил сержант Блай — тот самый наёмник с пирамиды." } } } }, { ["q"] = 3042, ["prio"] = 2, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_zulfarrak_hook_3042", ["track"] = { ["hash"] = "f148a959", ["text"] = "Трентону Молоту Света нужно двадцать фиалов тролльего месива. Тролли Песчаной Бури носят его с собой — считайте каждого.", ["duration"] = 9.3, ["cues"] = { { 0, "Трентону Молоту Света нужно двадцать фиалов тролльего месива." }, { 4.82, "Тролли Песчаной Бури носят его с собой — считайте каждого." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_zulfarrak_zumrah_pull", ["enc"] = 597, ["track"] = { ["hash"] = "ee697cba", ["text"] = "Знахарь Зум'ра вскидывает руки, и мёртвые в здешних могилах начинают шевелиться. Его оберег поднимает мертвецов одного за другим, и вскоре против вас встанет всё кладбище. А с губ знахаря срываются то тёмные залпы, то целебные напевы.", ["duration"] = 19.8, ["cues"] = { { 0, "Знахарь Зум'ра вскидывает руки, и мёртвые в здешних могилах начинают шевелиться." }, { 6.87, "Его оберег поднимает мертвецов одного за другим, и вскоре против вас встанет всё кладбище." }, { 14.67, "А с губ знахаря срываются то тёмные залпы, то целебные напевы." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_zulfarrak_zumrah_res", ["enc"] = 597, ["track"] = { ["hash"] = "f9e7249f", ["text"] = "Зум'ра падает среди могил, которые сам и тревожил. Это он поднимал здешних мертвецов из песка. Знахарь мёртв, но кладбище осталось, а в этом городе всегда найдётся, кому его разбудить. Песок здесь помнит слишком много похорон.", ["duration"] = 19.4, ["cues"] = { { 0, "Зум'ра падает среди могил, которые сам и тревожил." }, { 4.41, "Это он поднимал здешних мертвецов из песка." }, { 8.21, "Знахарь мёртв, но кладбище осталось, а в этом городе всегда найдётся, кому его разбудить." }, { 15.88, "Песок здесь помнит слишком много похорон." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_zulfarrak_theka_pull", ["enc"] = 596, ["track"] = { ["hash"] = "e9b4fa7e", ["text"] = "Тека Мученик поднимается у своей гробницы, и по плитам шуршат скарабеи — говорят, это его былые мучители. Его касание несёт моровую лихорадку, что тлеет в крови долго после удара. А когда Тека сменит облик — праздновать рано.", ["duration"] = 19.4, ["cues"] = { { 0, "Тека Мученик поднимается у своей гробницы, и по плитам шуршат скарабеи — говорят, это его былые мучители." }, { 9.14, "Его касание несёт моровую лихорадку, что тлеет в крови долго после удара." }, { 15.52, "А когда Тека сменит облик — праздновать рано." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_zulfarrak_theka_res", ["enc"] = 596, ["track"] = { ["hash"] = "92b296ba", ["text"] = "Тека затихает у гробницы, которую стерёг. Его прозвали Мучеником, и даже смерть не дала ему покоя. Теперь, может быть, даст.", ["duration"] = 11.1, ["cues"] = { { 0, "Тека затихает у гробницы, которую стерёг." }, { 3.76, "Его прозвали Мучеником, и даже смерть не дала ему покоя." }, { 8.99, "Теперь, может быть, даст." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_zulfarrak_velratha_pull", ["enc"] = 593, ["track"] = { ["hash"] = "c2bcd769", ["text"] = "Гидромантка Велрата поднимает руки над священным прудом. Её напевы затягивают раны, и каждая волна исцеления, которую она успеет допеть, отнимает у вас то, что вы уже отвоевали.", ["duration"] = 14.5, ["cues"] = { { 0, "Гидромантка Велрата поднимает руки над священным прудом." }, { 4.68, "Её напевы затягивают раны, и каждая волна исцеления, которую она успеет допеть, отнимает у вас то, что вы уже отвоевали." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_zulfarrak_velratha_res", ["enc"] = 593, ["track"] = { ["hash"] = "4ba69575", ["text"] = "Велрата падает у кромки пруда, и вода на миг замирает. Это её подручные когда-то выкрали у волшебницы Табеты Тиару Глубин. Над пустыней снова висит тишина, только вода тихо плещет о камни.", ["duration"] = 16.3, ["cues"] = { { 0, "Велрата падает у кромки пруда, и вода на миг замирает." }, { 4.74, "Это её подручные когда-то выкрали у волшебницы Табеты Тиару Глубин." }, { 10.65, "Над пустыней снова висит тишина, только вода тихо плещет о камни." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_zulfarrak_gahzrilla_pull", ["enc"] = 594, ["track"] = { ["hash"] = "c865d8c6", ["text"] = "Газ'рилла поднимается из пруда, и с её чешуи сыплются искры. Кого она коснётся холодом, тот застынет ледяной глыбой, а от удара её тела о землю не устоит никто рядом.", ["duration"] = 13.8, ["cues"] = { { 0, "Газ'рилла поднимается из пруда, и с её чешуи сыплются искры." }, { 5.07, "Кого она коснётся холодом, тот застынет ледяной глыбой, а от удара её тела о землю не устоит никто рядом." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_zulfarrak_gahzrilla_res", ["enc"] = 594, ["track"] = { ["hash"] = "861a99c9", ["text"] = "Газ'рилла падает у кромки пруда. Песчаная Буря чтила её как полубога и держала способ её призыва в тайне. Теперь у священного пруда нет хозяйки, а у племени стало на одно чудо меньше.", ["duration"] = 15.1, ["cues"] = { { 0, "Газ'рилла падает у кромки пруда." }, { 2.76, "Песчаная Буря чтила её как полубога и держала способ её призыва в тайне." }, { 8.79, "Теперь у священного пруда нет хозяйки, а у племени стало на одно чудо меньше." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_zulfarrak_antusul_pull", ["enc"] = 595, ["track"] = { ["hash"] = "b21c7dad", ["text"] = "Анту'сул стучит посохом, и из песка вырастают тотемы: один лечит своих, другой хватает чужих за ноги. Шаман не жалеет целебных волн ни для себя, ни для своих, а почуяв беду, созовёт приспешников — и тогда песок оживёт вокруг вас.", ["duration"] = 19, ["cues"] = { { 0, "Анту'сул стучит посохом, и из песка вырастают тотемы: один лечит своих, другой хватает чужих за ноги." }, { 8.65, "Шаман не жалеет целебных волн ни для себя, ни для своих, а почуяв беду, созовёт приспешников — и тогда песок оживёт вокруг вас." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_zulfarrak_antusul_res", ["enc"] = 595, ["track"] = { ["hash"] = "bb11049f", ["text"] = "Анту'сул затихает посреди своего логова. Шаман держал при себе василисков, как пастух держит стадо, и стадо слушалось только его. Без пастуха это просто голодные звери. Песчаная Буря потеряла ещё одного из тех, кто говорил с духами.", ["duration"] = 18.7, ["cues"] = { { 0, "Анту'сул затихает посреди своего логова." }, { 3.34, "Шаман держал при себе василисков, как пастух держит стадо, и стадо слушалось только его." }, { 10.6, "Без пастуха это просто голодные звери." }, { 13.79, "Песчаная Буря потеряла ещё одного из тех, кто говорил с духами." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_zulfarrak_nekrum_pull", ["enc"] = 598, ["track"] = { ["hash"] = "0b2ccd70", ["text"] = "На ступени выходит Некрум Кишкожуй — мёртвый тролль, гниющий и голодный. Тот, кого он заденет, подхватит моровую лихорадку, — а за его спиной стоит жрец, готовый латать его раны снова и снова.", ["duration"] = 16.6, ["cues"] = { { 0, "На ступени выходит Некрум Кишкожуй — мёртвый тролль, гниющий и голодный." }, { 6.2, "Тот, кого он заденет, подхватит моровую лихорадку, — а за его спиной стоит жрец, готовый латать его раны снова и снова." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_zulfarrak_nekrum_res", ["enc"] = 598, ["track"] = { ["hash"] = "c9c99f42", ["text"] = "Некрум падает на ступени пирамиды. Кишкожуем его прозвали не за манеры: мёртвые тролли Песчаной Бури не знают сытости. Внизу ещё кричат, но боевой клич племени звучит уже не так уверенно. Таких, как он, Песчаная Буря поднимала из могил десятками, но этот был самым голодным.", ["duration"] = 22.9, ["cues"] = { { 0, "Некрум падает на ступени пирамиды." }, { 2.96, "Кишкожуем его прозвали не за манеры: мёртвые тролли Песчаной Бури не знают сытости." }, { 10, "Внизу ещё кричат, но боевой клич племени звучит уже не так уверенно." }, { 15.76, "Таких, как он, Песчаная Буря поднимала из могил десятками, но этот был самым голодным." } } } }, { ["q"] = 2991, ["follows"] = "dm_zulfarrak_nekrum_res", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_zulfarrak_hook_2991", ["track"] = { ["hash"] = "cad476a3", ["text"] = "Медальон Некрума — Тадиусу Мрачной Тени в Выжженные земли. За него Тадиус обещал найти Остроклюва.", ["duration"] = 9, ["cues"] = { { 0, "Медальон Некрума — Тадиусу Мрачной Тени в Выжженные земли." }, { 5.42, "За него Тадиус обещал найти Остроклюва." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_zulfarrak_sezzziz_pull", ["enc"] = 599, ["track"] = { ["hash"] = "bf3ad060", ["text"] = "Жрец Тьмы Шезз'зиз не лезет в драку: его молитвы затягивают раны союзников, пока их не оборвут. А его крик гонит прочь даже бывалых бойцов, и строй рассыпается, как песок.", ["duration"] = 14.3, ["cues"] = { { 0, "Жрец Тьмы Шезз'зиз не лезет в драку: его молитвы затягивают раны союзников, пока их не оборвут." }, { 8.12, "А его крик гонит прочь даже бывалых бойцов, и строй рассыпается, как песок." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_zulfarrak_sezzziz_res", ["enc"] = 599, ["track"] = { ["hash"] = "f94c6f18", ["text"] = "Шезз'зиз затихает, так и не дошептав молитву. Жрецы Песчаной Бури говорили с тёмными силами, и теперь одним голосом во тьме меньше. Тёмные молитвы ещё звучат эхом между ступенями, но ответить на них уже некому.", ["duration"] = 18.2, ["cues"] = { { 0, "Шезз'зиз затихает, так и не дошептав молитву." }, { 3.95, "Жрецы Песчаной Бури говорили с тёмными силами, и теперь одним голосом во тьме меньше." }, { 11.45, "Тёмные молитвы ещё звучат эхом между ступенями, но ответить на них уже некому." } } } }, { ["q"] = 2936, ["follows"] = "dm_zulfarrak_sezzziz_res", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_zulfarrak_hook_2936", ["track"] = { ["hash"] = "735c0a7d", ["text"] = "Имя паучьей богини начертано на табличке у гробницы, которую стережёт Тека Мученик. Прочтите его для мастера Гадрина.", ["duration"] = 9.2, ["cues"] = { { 0, "Имя паучьей богини начертано на табличке у гробницы, которую стережёт Тека Мученик." }, { 6.64, "Прочтите его для мастера Гадрина." } } } }, { ["q"] = 2865, ["follows"] = "dm_zulfarrak_sezzziz_res", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_zulfarrak_hook_2865", ["track"] = { ["hash"] = "65d051a6", ["text"] = "Тран'реку нужны целые панцири скарабеев — они ползают у святилища Теки Мученика.", ["duration"] = 6.5, ["cues"] = { { 0, "Тран'реку нужны целые панцири скарабеев — они ползают у святилища Теки Мученика." } } } }, { ["q"] = 96770, ["follows"] = "dm_zulfarrak_sezzziz_res", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_zulfarrak_hook_96770", ["track"] = { ["hash"] = "9edf4c57", ["text"] = "Голову знахаря Зум'ры ждёт верховный маг Лан'далок в Даларане — у мага с ним давние счёты.", ["duration"] = 7.2, ["cues"] = { { 0, "Голову знахаря Зум'ры ждёт верховный маг Лан'далок в Даларане — у мага с ним давние счёты." } } } }, { ["q"] = 96775, ["follows"] = "dm_zulfarrak_sezzziz_res", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_zulfarrak_hook_96775", ["track"] = { ["hash"] = "992e720f", ["text"] = "Голову Зум'ры ждёт Мазу'кон в Мулгоре: он обещал насадить её на копьё у своей хижины.", ["duration"] = 7, ["cues"] = { { 0, "Голову Зум'ры ждёт Мазу'кон в Мулгоре: он обещал насадить её на копьё у своей хижины." } } } }, { ["q"] = 2846, ["follows"] = "dm_zulfarrak_sezzziz_res", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_zulfarrak_hook_2846", ["track"] = { ["hash"] = "f01db69c", ["text"] = "Тиара Глубин — у гидромантки Велраты возле священного пруда. Табета ждёт её в Пылевых топях.", ["duration"] = 7.7, ["cues"] = { { 0, "Тиара Глубин — у гидромантки Велраты возле священного пруда." }, { 5.17, "Табета ждёт её в Пылевых топях." } } } }, { ["q"] = 2770, ["follows"] = "dm_zulfarrak_sezzziz_res", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_zulfarrak_hook_2770", ["track"] = { ["hash"] = "c835d398", ["text"] = "Искрящую чешую Газ'риллы ждёт Виззл Медноштиф на Мерцающей равнине. Чудовище спит в священном пруду, а способ его призвать тролли держат в тайне.", ["duration"] = 13.2, ["cues"] = { { 0, "Искрящую чешую Газ'риллы ждёт Виззл Медноштиф на Мерцающей равнине." }, { 6.14, "Чудовище спит в священном пруду, а способ его призвать тролли держат в тайне." } } } }, { ["role"] = "final", ["k"] = "pod", ["trig"] = "after", ["id"] = "dm_zulfarrak_ukorz_pod", ["enc"] = 600, ["pos"] = 8, ["track"] = { ["hash"] = "d3122c8d", ["text"] = "За запертой дверью ждёт тот, кому служит весь этот город, — вождь Укорз Песчаный Череп. Это он ведёт Песчаную Бурю. Рядом с ним — Руузлу. Вождь не вышел к пирамиде: он ждёт, что гости сами придут к нему.", ["duration"] = 17.6, ["cues"] = { { 0, "За запертой дверью ждёт тот, кому служит весь этот город, — вождь Укорз Песчаный Череп." }, { 7.69, "Это он ведёт Песчаную Бурю." }, { 10.15, "Рядом с ним — Руузлу." }, { 12.05, "Вождь не вышел к пирамиде: он ждёт, что гости сами придут к нему." } } } }, { ["role"] = "final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_zulfarrak_ukorz_pull", ["enc"] = 600, ["track"] = { ["hash"] = "12f87826", ["text"] = "Вождь Укорз рычит и вскидывает оружие, а Руузлу встаёт у него за плечом. Чем сильнее вы раните вождя, тем злее он рубит: раненый, он впадает в исступление, и горе тому, кто стоит у него на пути.", ["duration"] = 16, ["cues"] = { { 0, "Вождь Укорз рычит и вскидывает оружие, а Руузлу встаёт у него за плечом." }, { 6.01, "Чем сильнее вы раните вождя, тем злее он рубит: раненый, он впадает в исступление, и горе тому, кто стоит у него на пути." } } } }, { ["role"] = "final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_zulfarrak_ukorz_fin", ["enc"] = 600, ["track"] = { ["hash"] = "b5cb7b01", ["text"] = "Вождь Укорз Песчаный Череп падает, и над Зул'Фарраком повисает тишина — только ветер гонит песок по ступеням. Песчаная Буря потеряла голову. Город останется стоять, как стоял веками. Но командовать в нём больше некому.", ["duration"] = 19.4, ["cues"] = { { 0, "Вождь Укорз Песчаный Череп падает, и над Зул'Фарраком повисает тишина — только ветер гонит песок по ступеням." }, { 9.84, "Песчаная Буря потеряла голову." }, { 12.66, "Город останется стоять, как стоял веками." }, { 16.45, "Но командовать в нём больше некому." } } } }, { ["q"] = 3527, ["follows"] = "dm_zulfarrak_ukorz_fin", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_zulfarrak_fin_3527", ["track"] = { ["hash"] = "8fca6684", ["text"] = "Если таблички Мошару при вас, Йе'кинья ждёт их в Танарисе. Пророчество в них касается куда большего, чем один город.", ["duration"] = 8.7, ["cues"] = { { 0, "Если таблички Мошару при вас, Йе'кинья ждёт их в Танарисе." }, { 4.43, "Пророчество в них касается куда большего, чем один город." } } } } }, ["bosses"] = { { ["id"] = 597, ["npcs"] = { 7271 }, ["name"] = "Witch Doctor Zum'rah", ["required"] = nil, ["token"] = "zumrah", ["names335"] = { "Witch Doctor Zum'rah" } }, { ["id"] = 596, ["npcs"] = { 7272 }, ["name"] = "Theka the Martyr", ["required"] = nil, ["token"] = "theka", ["names335"] = { "Theka the Martyr" } }, { ["id"] = 593, ["npcs"] = { 7795 }, ["name"] = "Hydromancer Velratha", ["required"] = nil, ["token"] = "velratha", ["names335"] = { "Hydromancer Velratha" } }, { ["id"] = 594, ["npcs"] = { 7273 }, ["name"] = "Ghaz'rilla", ["required"] = nil, ["token"] = "gahzrilla", ["names335"] = { "Gahz'rilla" } }, { ["id"] = 595, ["npcs"] = { 8127 }, ["name"] = "Antu'sul", ["required"] = nil, ["token"] = "antusul", ["names335"] = { "Antu'sul" } }, { ["id"] = 598, ["npcs"] = { 7796 }, ["name"] = "Nekrum Gutchewer", ["required"] = nil, ["token"] = "nekrum", ["names335"] = { "Nekrum Gutchewer" } }, { ["id"] = 599, ["npcs"] = { 7275 }, ["name"] = "Shadowpriest Sezz'ziz", ["required"] = nil, ["token"] = "sezzziz", ["names335"] = { "Shadowpriest Sezz'ziz" } }, { ["id"] = 600, ["npcs"] = { 7267, 7797 }, ["name"] = "ukorz", ["required"] = { 7267, 7797 }, ["token"] = "ukorz", ["names335"] = { "Chief Ukorz Sandscalp", "Ruuzlu" } } } },
[229] = { ["key"] = "blackrock_spire", ["order"] = { 275, 3062, 3063, 3069 }, ["layout"] = "wings", ["alias"] = {  }, ["name"] = "Вершина Черной горы", ["events"] = { { ["id"] = "dm_blackrock_spire_prolog", ["k"] = "prolog", ["trig"] = "prolog", ["track"] = { ["hash"] = "76834a3b", ["text"] = "Вы на Вершине Черной горы. Эту крепость высекли в сердце горы дворфы Черного Железа, но хозяйничают здесь теперь другие. Нижний город занял вождь Ренд Чернорук со своей Ордой: орки клана Черной горы, наёмные огры и тролли, стаи воргов. Над ними, в верхней крепости, стоят драконы, а ещё выше, в Логове Крыла Тьмы, сидит чёрный дракон Нефариан, сын Смертокрыла. Ренд называет себя вождём, но служит ему. Дверь наверх, в драконью часть, открывает только печать Вознесения.", ["duration"] = 41.2, ["cues"] = { { 0, "Вы на Вершине Чёрной горы." }, { 2.32, "Эту крепость высекли в сердце горы дворфы Чёрного Железа, но хозяйничают здесь теперь другие." }, { 10.62, "Нижний город занял вождь Ренд Чернорук со своей Ордой: орки клана Чёрной горы, наёмные огры и тролли, стаи воргов." }, { 20.84, "Над ними, в верхней крепости, стоят драконы, а ещё выше, в Логове Крыла Тьмы, сидит чёрный дракон Нефариан, сын Смертокрыла." }, { 31.78, "Ренд называет себя вождём, но служит ему." }, { 35.45, "Дверь наверх, в драконью часть, открывает только печать Вознесения." } } } }, { ["id"] = "dm_blackrock_spire_prolog_repeat", ["k"] = "prolog", ["trig"] = "repeat", ["track"] = { ["hash"] = "9292a063", ["text"] = "Снова Черная гора. Ренд уже поставил новых бойцов на место павших — у Орды Нефариана нет недостатка в мясе.", ["duration"] = 8.9, ["cues"] = { { 0, "Снова Чёрная гора." }, { 1.58, "Ренд уже поставил новых бойцов на место павших — у Орды Нефариана нет недостатка в мясе." } } } }, { ["q"] = 5081, ["prio"] = 0, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_blackrock_spire_hook_5081", ["track"] = { ["hash"] = "910d17e6", ["text"] = "Маршал Максвелл ждёт три смерти: воеводы Вуна, вождя Омокка и властителя Змейталака. Без них Черная гора лишится планов, огров и наместника.", ["duration"] = 12.8, ["cues"] = { { 0, "Маршал Максвелл ждёт три смерти: воеводы Вуна, вождя Омокка и властителя Змейталака." }, { 7.86, "Без них Чёрная гора лишится планов, огров и наместника." } } } }, { ["q"] = 4903, ["prio"] = 1, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_blackrock_spire_hook_4903", ["track"] = { ["hash"] = "904875c3", ["text"] = "Полководец Клинозуб приговорил троих: Омокка, Вуна и Змейталака. И просил принести все бумаги, что найдутся при них.", ["duration"] = 10, ["cues"] = { { 0, "Полководец Клинозуб приговорил троих: Омокка, Вуна и Змейталака." }, { 5.71, "И просил принести все бумаги, что найдутся при них." } } } }, { ["q"] = 4742, ["prio"] = 2, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_blackrock_spire_hook_4742", ["track"] = { ["hash"] = "e5c2d721", ["text"] = "Для печати Вознесения нужны три самоцвета, и носят их трое вожаков нижнего города. Соберите камни — это первый шаг к ключу от верхней двери.", ["duration"] = 11.9, ["cues"] = { { 0, "Для печати Вознесения нужны три самоцвета, и носят их трое вожаков нижнего города." }, { 7.08, "Соберите камни — это первый шаг к ключу от верхней двери." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_spire_omokk_pull", ["enc"] = 267, ["track"] = { ["hash"] = "91a8ffcb", ["text"] = "Вождь Омокк, хозяин огров Черной Вершины, вскидывает дубину над головой. Огры привыкли, что их вождь не падает, — пора их разочаровать.", ["duration"] = 11.2, ["cues"] = { { 0, "Вождь Омокк, хозяин огров Чёрной Вершины, вскидывает дубину над головой." }, { 6.14, "Огры привыкли, что их вождь не падает, — пора их разочаровать." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_spire_omokk", ["enc"] = 267, ["track"] = { ["hash"] = "743ffbb8", ["text"] = "Омокк падает, и в Мок'Думе становится тихо. Огры не служат Ренду, они служат плате, а плата у Черной горы щедрая: огры стоят в первых рядах и умирают первыми. Теперь огры Черной Вершины остались без вождя.", ["duration"] = 18.4, ["cues"] = { { 0, "Омокк падает, и в Мок'Думе становится тихо." }, { 3.94, "Огры не служат Ренду, они служат плате, а плата у Чёрной горы щедрая: огры стоят в первых рядах и умирают первыми." }, { 14.38, "Теперь огры Чёрной Вершины остались без вождя." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_spire_voshgajin_pull", ["enc"] = 268, ["track"] = { ["hash"] = "9aa459b2", ["text"] = "Темная охотница Вос'гаджин поднимает руки и заводит недобрый напев. Её сглаз обращает в беспомощных лягушек всех, кто стоит рядом, а проклятие делает каждую рану глубже. Горе тому, кто подойдёт к ведьме вплотную.", ["duration"] = 18.6, ["cues"] = { { 0, "Тёмная охотница Вос'гаджин поднимает руки и заводит недобрый напев." }, { 6.03, "Её сглаз обращает в беспомощных лягушек всех, кто стоит рядом, а проклятие делает каждую рану глубже." }, { 15.02, "Горе тому, кто подойдёт к ведьме вплотную." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_spire_voshgajin", ["enc"] = 268, ["track"] = { ["hash"] = "be0f7a2d", ["text"] = "Вос'гаджин затихает. Тролли Тлеющего Терновника встали под знамя Ренда, и она была одной из их колдуний. Теперь у них одной колдуньей меньше, а у Ренда — одним союзником.", ["duration"] = 14.7, ["cues"] = { { 0, "Вос'гаджин затихает." }, { 1.8, "Тролли Тлеющего Терновника встали под знамя Ренда, и она была одной из их колдуний." }, { 9.16, "Теперь у них одной колдуньей меньше, а у Ренда — одним союзником." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_spire_voone_pull", ["enc"] = 269, ["track"] = { ["hash"] = "a8e624c0", ["text"] = "Воевода Вун, жестокий и беспощадный тролль, выходит навстречу с оружием наготове. Это он водит Тлеющий Терновник в бой, и своё место без боя не отдаст.", ["duration"] = 13.3, ["cues"] = { { 0, "Воевода Вун, жестокий и беспощадный тролль, выходит навстречу с оружием наготове." }, { 7.21, "Это он водит Тлеющий Терновник в бой, и своё место без боя не отдаст." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_spire_voone", ["enc"] = 269, ["track"] = { ["hash"] = "d82fdcf8", ["text"] = "Воевода Вун падает. У троллей он был не шаманом, а полководцем, и без его боевых планов нижний город теряет порядок. Это он когда-то держал в плену и пытал Мора Серое Копыто, пока за тем не пришли призрачные убийцы. Теперь пленников здесь пытать некому.", ["duration"] = 20.1, ["cues"] = { { 0, "Воевода Вун падает." }, { 1.58, "У троллей он был не шаманом, а полководцем, и без его боевых планов нижний город теряет порядок." }, { 9.25, "Это он когда-то держал в плену и пытал Мора Серое Копыто, пока за тем не пришли призрачные убийцы." }, { 17.22, "Теперь пленников здесь пытать некому." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_spire_smolderweb_pull", ["enc"] = 270, ["track"] = { ["hash"] = "d56183ac", ["text"] = "Из глубины логова выходит Мать Дымная Паутина — огромная паучиха, хозяйка этих туннелей. Её яд расходится по всем, кто рядом, и то и дело сковывает отравленного вместе с соседями, а тот, кто стоит у неё перед жвалами, рискует застыть, как муха в янтаре.", ["duration"] = 21.4, ["cues"] = { { 0, "Из глубины логова выходит Мать Дымная Паутина — огромная паучиха, хозяйка этих туннелей." }, { 7.66, "Её яд расходится по всем, кто рядом, и то и дело сковывает отравленного вместе с соседями, а тот, кто стоит у неё перед жвалами, рискует застыть, как муха в янтаре." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_spire_smolderweb", ["enc"] = 270, ["track"] = { ["hash"] = "2f084734", ["text"] = "Мать Дымная Паутина замирает, и туннели стихают. Орки Черной горы зовут её яд «материнским молоком» и говорят о нём с опаской. Логово опустело, но кладки ещё долго будут лопаться в темноте.", ["duration"] = 17.1, ["cues"] = { { 0, "Мать Дымная Паутина замирает, и туннели стихают." }, { 4.47, "Орки Чёрной горы зовут её яд «материнским молоком» и говорят о нём с опаской." }, { 11.49, "Логово опустело, но кладки ещё долго будут лопаться в темноте." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_spire_urok_pull", ["enc"] = 271, ["track"] = { ["hash"] = "26ed978f", ["text"] = "Над грудой даров разносится вой, и из глубины зала выходит Аррок Смертный Вопль — тот, кому огры несут свои дары. Его позвала голова Омокка, и он не уйдёт без крови.", ["duration"] = 15.4, ["cues"] = { { 0, "Над грудой даров разносится вой, и из глубины зала выходит Аррок Смертный Вопль — тот, кому огры несут свои дары." }, { 10.72, "Его позвала голова Омокка, и он не уйдёт без крови." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_spire_urok", ["enc"] = 271, ["track"] = { ["hash"] = "46af0a66", ["text"] = "Аррок затихает над грудой даров, и вой больше не катится по Черной горе. Огры несли ему черепа и железо, но спасти его не смогли. Варош получит свой амулет. Сегодня даров не будет.", ["duration"] = 16.6, ["cues"] = { { 0, "Аррок затихает над грудой даров, и вой больше не катится по Чёрной горе." }, { 6.65, "Огры несли ему черепа и железо, но спасти его не смогли." }, { 12.06, "Варош получит свой амулет." }, { 14.56, "Сегодня даров не будет." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_spire_zigris_pull", ["enc"] = 272, ["track"] = { ["hash"] = "9c2fed62", ["text"] = "Интендант Зигрис отрывается от ящиков и тянется к оружию. Он знает каждую бочку пороха и каждую стрелу на этих полках — и не отдаст ни одной без боя, а за спиной у него целый арсенал.", ["duration"] = 14.7, ["cues"] = { { 0, "Интендант Зигрис отрывается от ящиков и тянется к оружию." }, { 4.64, "Он знает каждую бочку пороха и каждую стрелу на этих полках — и не отдаст ни одной без боя, а за спиной у него целый арсенал." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_spire_zigris", ["enc"] = 272, ["track"] = { ["hash"] = "1b6d3d9e", ["text"] = "Интендант Зигрис падает среди своих ящиков. Вокруг припасы на целую армию: доспехи, стрелы, порох, мешки с зерном. Орда Ренда готовится не к обороне — она готовится к долгой войне.", ["duration"] = 15.2, ["cues"] = { { 0, "Интендант Зигрис падает среди своих ящиков." }, { 3.76, "Вокруг припасы на целую армию: доспехи, стрелы, порох, мешки с зерном." }, { 9.79, "Орда Ренда готовится не к обороне — она готовится к долгой войне." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_spire_halycon_pull", ["enc"] = 274, ["track"] = { ["hash"] = "96d26eca", ["text"] = "Халикон, огромная праматерь воргов, поднимается во весь рост, и щенки высыпают из углов. Все ворги, на которых ездят орки Черной горы, — её потомство, и сколько их ни бей, меньше их не становится. А в этом логове она живёт не одна.", ["duration"] = 18.8, ["cues"] = { { 0, "Халикон, огромная праматерь воргов, поднимается во весь рост, и щенки высыпают из углов." }, { 7.27, "Все ворги, на которых ездят орки Чёрной горы, — её потомство, и сколько их ни бей, меньше их не становится." }, { 16.03, "А в этом логове она живёт не одна." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_spire_halycon", ["enc"] = 274, ["track"] = { ["hash"] = "504f41ca", ["text"] = "Халикон падает с глухим рыком, и щенки разбегаются по углам. Орки ещё будут ездить на её детях, но новых уже не будет. А стая без матери — просто голодные звери.", ["duration"] = 13.9, ["cues"] = { { 0, "Халикон падает с глухим рыком, и щенки разбегаются по углам." }, { 5.29, "Орки ещё будут ездить на её детях, но новых уже не будет." }, { 10.34, "А стая без матери — просто голодные звери." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_spire_gizrul_pull", ["enc"] = 273, ["track"] = { ["hash"] = "f7cfa1d8", ["text"] = "Из дальнего прохода с рёвом вылетает Гизрул Поработитель, самец Халикон. Говорят, мало кто из видевших его выжил, чтобы рассказать об этом.", ["duration"] = 11.1, ["cues"] = { { 0, "Из дальнего прохода с рёвом вылетает Гизрул Поработитель, самец Халикон." }, { 5.82, "Говорят, мало кто из видевших его выжил, чтобы рассказать об этом." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_spire_gizrul", ["enc"] = 273, ["track"] = { ["hash"] = "ba01435d", ["text"] = "Гизрул Поработитель затихает. Логово наконец смолкает: ни рыка, ни воя. Стая Черной горы осталась без вожаков.", ["duration"] = 11.4, ["cues"] = { { 0, "Гизрул Поработитель затихает." }, { 3.09, "Логово наконец смолкает: ни рыка, ни воя." }, { 7.5, "Стая Чёрной горы осталась без вожаков." } } } }, { ["sub"] = "Чертог Битвы", ["role"] = "wing_final", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_blackrock_spire_wyrmthalak_intro", ["enc"] = 275, ["pos"] = 9, ["track"] = { ["hash"] = "176a34f8", ["text"] = "Чертог Битвы. Здесь, в глубине нижнего города, держит двор властитель Змейталак — чёрный драконоид, владыка нижней крепости и наместник Нефариана над Ордой Ренда. Огры, тролли и орки стоят тут бок о бок и слушают одного хозяина. Он один из немногих чёрных драконов, способных закалить в своём пламени печать, что открывает дверь наверх.", ["duration"] = 28.1, ["cues"] = { { 0, "Чертог Битвы." }, { 1.22, "Здесь, в глубине нижнего города, держит двор властитель Змейталак — чёрный драконоид, владыка нижней крепости и наместник Нефариана над Ордой Ренда." }, { 13.66, "Огры, тролли и орки стоят тут бок-о-бок и слушают одного хозяина." }, { 19.31, "Он один из немногих чёрных драконов, способных закалить в своём пламени печать, что открывает дверь наверх." } } } }, { ["role"] = "wing_final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_spire_wyrmthalak_pull", ["enc"] = 275, ["track"] = { ["hash"] = "dc3764ca", ["text"] = "Змейталак выпрямляется во весь драконий рост, и его клинок разом достаёт всех, кто стоит перед ним. Почуяв слабость, он позовёт гвардию, и та не заставит себя ждать.", ["duration"] = 12.2, ["cues"] = { { 0, "Змейталак выпрямляется во весь драконий рост, и его клинок разом достаёт всех, кто стоит перед ним." }, { 7.48, "Почуяв слабость, он позовёт гвардию, и та не заставит себя ждать." } } } }, { ["role"] = "wing_final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_blackrock_spire_wyrmthalak", ["enc"] = 275, ["track"] = { ["hash"] = "f0a7b832", ["text"] = "Властитель Змейталак падает, и Чертог Битвы затихает. Нижний город лишился хозяина: огры, тролли и орки снова сами по себе, и надолго их союз не переживёт. Но Змейталак был лишь наместником Нефариана, а тот сидит выше, над дымом кузниц.", ["duration"] = 21.3, ["cues"] = { { 0, "Властитель Змейталак падает, и Чертог Битвы затихает." }, { 4.91, "Нижний город лишился хозяина: огры, тролли и орки снова сами по себе, и надолго их союз не переживёт." }, { 14.24, "Но Змейталак был лишь наместником Нефариана, а тот сидит выше, над дымом кузниц." } } } }, { ["role"] = "wing_final", ["k"] = "bag", ["trig"] = "bag", ["id"] = "dm_blackrock_spire_orders", ["item"] = 12780, ["track"] = { ["hash"] = "d1fb5a9d", ["text"] = "При Змейталаке были распоряжения генерала Драккисата. Маршал Максвелл в Пылающих степях захочет их прочесть.", ["duration"] = 8.6, ["cues"] = { { 0, "При Змейталаке были распоряжения генерала Драккисата." }, { 4.28, "Маршал Максвелл в Пылающих степях захочет их прочесть." } } } }, { ["q"] = 4867, ["follows"] = "dm_blackrock_spire_orders", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_spire_hook_4867", ["track"] = { ["hash"] = "9acfdf9e", ["text"] = "Варош ждёт свой амулет, а он у Аррока Смертного Вопля. Голова Омокка и Копье грубой силы у груды даров огров позовут Аррока.", ["duration"] = 11.4, ["cues"] = { { 0, "Варош ждёт свой амулет, а он у Аррока Смертного Вопля." }, { 5.01, "Голова Омокка и Копьё грубой силы у груды даров огров позовут Аррока." } } } }, { ["q"] = 4866, ["follows"] = "dm_blackrock_spire_orders", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_spire_hook_4866", ["track"] = { ["hash"] = "7d46c683", ["text"] = "Джону-Оборванцу нужно «материнское молоко» — яд Матери Дымной Паутины, и не в мешочке, а в ваших собственных венах. Паучиха живёт в одной из пещер Лабиринта: дайте ей себя отравить и не медлите на обратном пути.", ["duration"] = 16.9, ["cues"] = { { 0, "Джону-Оборванцу нужно «материнское молоко» — яд Матери Дымной Паутины, и не в мешочке, а в ваших собственных венах." }, { 9.32, "Паучиха живёт в одной из пещер Лабиринта: дайте ей себя отравить и не медлите на обратном пути." } } } }, { ["q"] = 4701, ["follows"] = "dm_blackrock_spire_orders", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_spire_hook_4701", ["track"] = { ["hash"] = "c8b0fc7b", ["text"] = "Хелендис Речной Мыс просил найти, откуда берутся ворги Черной горы. Их источник — праматерь Халикон, и её логово — здесь, в нижней крепости. Уничтожьте его.", ["duration"] = 13.7, ["cues"] = { { 0, "Хелендис Речной Мыс просил найти, откуда берутся ворги Чёрной горы." }, { 6.08, "Их источник — праматерь Халикон, и её логово — здесь, в нижней крепости." }, { 12.4, "Уничтожьте его." } } } }, { ["q"] = 4724, ["follows"] = "dm_blackrock_spire_orders", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_spire_hook_4724", ["track"] = { ["hash"] = "d98649a0", ["text"] = "Галамав Стрелок ждёт вести о Халикон, праматери воргов Черной горы. Её логово — в нижней крепости: нанесите удар в самое сердце стаи.", ["duration"] = 10.8, ["cues"] = { { 0, "Галамав Стрелок ждёт вести о Халикон, праматери воргов Чёрной горы." }, { 5.51, "Её логово — в нижней крепости: нанесите удар в самое сердце стаи." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_spire_emberseer_pull", ["enc"] = 3062, ["track"] = { ["hash"] = "8371e494", ["text"] = "Оковы трещат, и тюремщики бросаются на вас, пока пленник рвётся на волю. Пиростраж Углевзор — слуга огня, которого орки Черной горы изловили и держат здесь в цепях чар. Когда он вырвется, весь его жар обрушится на тех, кто его разбудил.", ["duration"] = 20.2, ["cues"] = { { 0, "Оковы трещат, и тюремщики бросаются на вас, пока пленник рвётся на волю." }, { 6.25, "Пиростраж Углевзор — слуга огня, которого орки Чёрной горы изловили и держат здесь в цепях чар." }, { 14.54, "Когда он вырвется, весь его жар обрушится на тех, кто его разбудил." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_spire_emberseer", ["enc"] = 3062, ["track"] = { ["hash"] = "020bacb2", ["text"] = "Пиростраж Углевзор гаснет, и в зале становится темно и холодно. Зачем оркам пленный слуга огня, знают только их чародеи и те, кто ими правит. Пленник ушёл туда, откуда его не вызовет ни один чародей.", ["duration"] = 17.9, ["cues"] = { { 0, "Пиростраж Углевзор гаснет, и в зале становится темно и холодно." }, { 5.73, "Зачем оркам пленный слуга огня, знают только их чародеи и те, кто ими правит." }, { 12.83, "Пленник ушёл туда, откуда его не вызовет ни один чародей." } } } }, { ["q"] = 6821, ["follows"] = "dm_blackrock_spire_emberseer", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_spire_hook_6821", ["track"] = { ["hash"] = "09ab6a7c", ["text"] = "Герцог Гидраксис ждёт доказательства, что слуга огня повержен. Возьмите с тела глаз Углевзора.", ["duration"] = 7.8, ["cues"] = { { 0, "Герцог Гидраксис ждёт доказательства, что слуга огня повержен." }, { 5.25, "Возьмите с тела глаз Углевзора." } } } }, { ["q"] = 4734, ["follows"] = "dm_blackrock_spire_emberseer", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_spire_hook_4734", ["track"] = { ["hash"] = "2735eb98", ["text"] = "Где-то в верхней крепости — Гнездовье, драконий питомник, полный яиц. Тинки Кипеллер ждёт, сработает ли её яйцехладоскоп: заморозьте яйцо, пока оно не вылупилось.", ["duration"] = 13.9, ["cues"] = { { 0, "Где-то в верхней крепости — Гнездовье, драконий питомник, полный яиц." }, { 6.1, "Тинки Кипеллер ждёт, сработает ли её яйцехладоскоп: заморозьте яйцо, пока оно не вылупилось." } } } }, { ["sub"] = "Стадион Черной горы", ["role"] = "main", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_blackrock_spire_rend_intro", ["enc"] = 3063, ["pos"] = 11, ["track"] = { ["hash"] = "f25acb7e", ["text"] = "Стадион Черной горы. Здесь орки смотрят бои, а на высоком балконе стоит сам Ренд Чернорук, сын Чернорука — первого вождя Орды. Он назвал себя вождём и не признаёт Тралла. Рядом с ним — лорд Виктор Нефарий, сам Нефариан в людском облике: он любит смотреть, как умирают гости.", ["duration"] = 24.5, ["cues"] = { { 0, "Стадион Чёрной горы." }, { 1.88, "Здесь орки смотрят бои, а на высоком балконе стоит сам Ренд Чернорук, сын Чернорука — первого вождя Орды." }, { 11.46, "Он назвал себя вождём и не признаёт Тралла." }, { 15.31, "Рядом с ним — лорд Виктор Нефарий, сам Нефариан в людском облике: он любит смотреть, как умирают гости." } } } }, { ["q"] = 4974, ["follows"] = "dm_blackrock_spire_rend_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_spire_hook_4974", ["track"] = { ["hash"] = "adc50443", ["text"] = "Тралл ждёт голову Ренда. Пусть самозваный вождь узнает, что такое Орда.", ["duration"] = 6.6, ["cues"] = { { 0, "Тралл ждёт голову Ренда." }, { 2.36, "Пусть самозваный вождь узнает, что такое Орда." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_spire_rend_pull", ["enc"] = 3063, ["track"] = { ["hash"] = "d8d6896c", ["text"] = "С балкона сыплются насмешки, а на арену волна за волной выходят дракончики и драконоиды. Ренд не спешит: он спустится сам, верхом на своём драконе, когда хозяин потеряет терпение. Главный бой начнётся не сразу, и тот, кто растратит силы на первые волны, встретит вождя пустым.", ["duration"] = 22.2, ["cues"] = { { 0, "С балкона сыплются насмешки, а на арену волна за волной выходят дракончики и драконоиды." }, { 7.24, "Ренд не спешит: он спустится сам, верхом на своём драконе, когда хозяин потеряет терпение." }, { 14.56, "Главный бой начнётся не сразу, и тот, кто растратит силы на первые волны, встретит вождя пустым." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_spire_rend", ["enc"] = 3063, ["track"] = { ["hash"] = "7e73261a", ["text"] = "Ренд Чернорук падает на песок арены, и трибуны смолкают. Сын первого вождя Орды хотел вернуть оркам старую жестокость, а стал слугой чёрного дракона. Нефариан не станет его оплакивать: у него найдутся другие слуги.", ["duration"] = 18, ["cues"] = { { 0, "Ренд Чернорук падает на песок арены, и трибуны смолкают." }, { 4.79, "Сын первого вождя Орды хотел вернуть оркам старую жестокость, а стал слугой чёрного дракона." }, { 12.61, "Нефариан не станет его оплакивать: у него найдутся другие слуги." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_spire_beast_pull", ["enc"] = 3068, ["track"] = { ["hash"] = "d68fbcf9", ["text"] = "Из жара поднимается Зверь, огромная огненная тварь на службе у драконов, и ревёт так, что у самых храбрых подкашиваются ноги. Его рёв гонит прочь всех, кто рядом, — и убегающий в страхе легко приведёт за собой тех, кого вы ещё не убили.", ["duration"] = 20.2, ["cues"] = { { 0, "Из жара поднимается Зверь, огромная огненная тварь на службе у драконов, и ревёт так, что у самых храбрых подкашиваются ноги." }, { 10.84, "Его рёв гонит прочь всех, кто рядом, — и убегающий в страхе легко приведёт за собой тех, кого вы ещё не убили." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_spire_beast", ["enc"] = 3068, ["track"] = { ["hash"] = "dce0bc87", ["text"] = "Зверь затихает, и жар вокруг понемногу остывает. Самый страшный сторож Вершины больше не поднимется. Драконам Нефариана придётся искать нового.", ["duration"] = 12.5, ["cues"] = { { 0, "Зверь затихает, и жар вокруг понемногу остывает." }, { 4.24, "Самый страшный сторож Вершины больше не поднимется." }, { 8.88, "Драконам Нефариана придётся искать нового." } } } }, { ["role"] = "rare", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_spire_valthalak_pull", ["enc"] = 3070, ["track"] = { ["hash"] = "a9f722bb", ["text"] = "Из дыма жаровни поднимается призрак лорда Вальтхалака — того, чей разбитый амулет вы собирали по всему свету. Он дерётся не один: из теней к нему выходят призрачные убийцы, и их клинки не ждут, пока вы закончите с хозяином.", ["duration"] = 17.5, ["cues"] = { { 0, "Из дыма жаровни поднимается призрак лорда Вальтхалака — того, чей разбитый амулет вы собирали по всему свету." }, { 8.76, "Он дерётся не один: из теней к нему выходят призрачные убийцы, и их клинки не ждут, пока вы закончите с хозяином." } } } }, { ["role"] = "rare", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_spire_valthalak", ["enc"] = 3070, ["track"] = { ["hash"] = "c80a604a", ["text"] = "Лорд Вальтхалак рассеивается вместе с дымом жаровни. Отряд Бодли когда-то выкрал его книгу заклинаний и амулет и по жадности расколол амулет на три части, не зная о проклятии. Призрачные убийцы настигали их одного за другим, и первым пал Мор Серое Копыто. Теперь осколок души владыки больше никого не потянет за собой.", ["duration"] = 25.2, ["cues"] = { { 0, "Лорд Вальтхалак рассеивается вместе с дымом жаровни." }, { 4.15, "Отряд Бодли когда-то выкрал его книгу заклинаний и амулет и по жадности расколол амулет на три части, не зная о проклятии." }, { 13.96, "Призрачные убийцы настигали их одного за другим, и первым пал Мор Серое Копыто." }, { 20.27, "Теперь осколок души владыки больше никого не потянет за собой." } } } }, { ["sub"] = "Верховный трон", ["role"] = "wing_final", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_blackrock_spire_drakkisath_intro", ["enc"] = 3069, ["pos"] = 14, ["track"] = { ["hash"] = "baa67fea", ["text"] = "Верховный трон. Отсюда генерал Драккисат правит всей Вершиной Черной горы — чёрный драконоид, командир армий Нефариана, над которым только хозяева из Логова Крыла Тьмы. Рядом с троном стоит его гвардия. Кто хочет войти к Нефариану или к Ониксии, должен сначала разобраться с генералом.", ["duration"] = 22.7, ["cues"] = { { 0, "Верховный трон." }, { 1.23, "Отсюда генерал Драккисат правит всей Вершиной Чёрной горы — чёрный драконоид, командир армий Нефариана, над которым только хозяева из Логова Крыла Тьмы." }, { 13.39, "Рядом с троном стоит его гвардия." }, { 16.21, "Кто хочет войти к Нефариану или к Ониксии, должен сначала разобраться с генералом." } } } }, { ["q"] = 5102, ["follows"] = "dm_blackrock_spire_drakkisath_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_spire_hook_5102", ["track"] = { ["hash"] = "332f1fd3", ["text"] = "Маршал Максвелл ждёт вести о кончине генерала: это армии Драккисата жгут Пылающие степи.", ["duration"] = 7.5, ["cues"] = { { 0, "Маршал Максвелл ждёт вести о кончине генерала: это армии Драккисата жгут Пылающие степи." } } } }, { ["q"] = 6602, ["follows"] = "dm_blackrock_spire_drakkisath_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_spire_hook_6602", ["track"] = { ["hash"] = "7dc3ec4f", ["text"] = "Рексару нужна кровь могучего черного дракона — кровь этого генерала. Без неё амулет не откроет путь к Ониксии.", ["duration"] = 8.8, ["cues"] = { { 0, "Рексару нужна кровь могучего чёрного дракона — кровь этого генерала." }, { 5.6, "Без неё амулет не откроет путь к Ониксии." } } } }, { ["role"] = "wing_final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_spire_drakkisath_pull", ["enc"] = 3069, ["track"] = { ["hash"] = "6cbbd4e2", ["text"] = "Драккисат поднимается с трона, и гвардия встаёт рядом. Его пламя охватывает одного из вас и горит ещё долго, опаляя каждого, кто окажется рядом с вспыхнувшим.", ["duration"] = 13.4, ["cues"] = { { 0, "Драккисат поднимается с трона, и гвардия встаёт рядом." }, { 4.63, "Его пламя охватывает одного из вас и горит ещё долго, опаляя каждого, кто окажется рядом с вспыхнувшим." } } } }, { ["role"] = "wing_final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_blackrock_spire_drakkisath", ["enc"] = 3069, ["track"] = { ["hash"] = "c2eb8785", ["text"] = "Генерал Драккисат падает у подножия трона, и гвардия смолкает. Армии Нефариана в Черной горе остались без командира. Но генерал был только привратником: путь наверх, в Логово Крыла Тьмы, теперь открыт тем, кто осмелится. Нефариан и его сестра Ониксия узнают об этом очень скоро.", ["duration"] = 22.7, ["cues"] = { { 0, "Генерал Драккисат падает у подножия трона, и гвардия смолкает." }, { 5.2, "Армии Нефариана в Чёрной горе остались без командира." }, { 9.58, "Но генерал был только привратником: путь наверх, в Логово Крыла Тьмы, теперь открыт тем, кто осмелится." }, { 17.97, "Нефариан и его сестра Ониксия узнают об этом очень скоро." } } } }, { ["q"] = 7761, ["follows"] = "dm_blackrock_spire_drakkisath", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_spire_fin_7761", ["track"] = { ["hash"] = "0388f086", ["text"] = "Ренд Чернорук писал, что Драккисат сам охраняет своё клеймо, — ищите его здесь, в зале генерала. Только отмеченный клеймом сможет пользоваться сферой, что переносит прямо в Логово Крыла Тьмы.", ["duration"] = 14.7, ["cues"] = { { 0, "Ренд Чернорук писал, что Драккисат сам охраняет своё клеймо, — ищите его здесь, в зале генерала." }, { 7.47, "Только отмеченный клеймом сможет пользоваться сферой, что переносит прямо в Логово Крыла Тьмы." } } } } }, ["bosses"] = { { ["id"] = 267, ["npcs"] = { 9196 }, ["name"] = "Highlord Omokk", ["required"] = nil, ["token"] = "omokk", ["names335"] = { "Highlord Omokk" } }, { ["id"] = 268, ["npcs"] = { 9236 }, ["name"] = "Shadow Hunter Vosh'gajin", ["required"] = nil, ["token"] = "voshgajin", ["names335"] = { "Shadow Hunter Vosh'gajin" } }, { ["id"] = 269, ["npcs"] = { 9237 }, ["name"] = "War Master Voone", ["required"] = nil, ["token"] = "voone", ["names335"] = { "War Master Voone" } }, { ["id"] = 270, ["npcs"] = { 10596 }, ["name"] = "Mother Smolderweb", ["required"] = nil, ["token"] = "smolderweb", ["names335"] = { "Mother Smolderweb" } }, { ["id"] = 271, ["npcs"] = { 10584 }, ["name"] = "Urok Doomhowl", ["required"] = nil, ["token"] = "urok", ["names335"] = { "Urok Doomhowl" } }, { ["id"] = 272, ["npcs"] = { 9736 }, ["name"] = "Quartermaster Zigris", ["required"] = nil, ["token"] = "zigris", ["names335"] = { "Quartermaster Zigris" } }, { ["id"] = 274, ["npcs"] = { 10220 }, ["name"] = "Halycon", ["required"] = nil, ["token"] = "halycon", ["names335"] = { "Halycon" } }, { ["id"] = 273, ["npcs"] = { 10268 }, ["name"] = "Gizrul the Slavener", ["required"] = nil, ["token"] = "gizrul", ["names335"] = { "Gizrul the Slavener" } }, { ["id"] = 275, ["npcs"] = { 9568 }, ["name"] = "Overlord Wyrmthalak", ["required"] = nil, ["token"] = "wyrmthalak", ["names335"] = { "Overlord Wyrmthalak" } }, { ["id"] = 3062, ["npcs"] = { 9816 }, ["name"] = "Pyroguard Emberseer", ["required"] = nil, ["token"] = "emberseer", ["names335"] = { "Pyroguard Emberseer" } }, { ["id"] = 3063, ["npcs"] = { 10429, 10339 }, ["name"] = "rend", ["required"] = { 10429 }, ["token"] = "rend", ["names335"] = { "Warchief Rend Blackhand", "Gyth" } }, { ["id"] = 3068, ["npcs"] = { 10430 }, ["name"] = "The Beast", ["required"] = nil, ["token"] = "beast", ["names335"] = { "The Beast" } }, { ["id"] = 3070, ["npcs"] = { 16042 }, ["name"] = "valthalak", ["required"] = nil, ["token"] = "valthalak", ["names335"] = { "Lord Valthalak" } }, { ["id"] = 3069, ["npcs"] = { 10363 }, ["name"] = "General Drakkisath", ["required"] = nil, ["token"] = "drakkisath", ["names335"] = { "General Drakkisath" } } } },
[230] = { ["key"] = "blackrock_depths", ["order"] = { 244, 2790 }, ["layout"] = "hub", ["alias"] = {  }, ["name"] = "Глубины Черной горы", ["events"] = { { ["id"] = "dm_blackrock_depths_prolog", ["k"] = "prolog", ["trig"] = "prolog", ["track"] = { ["hash"] = "4f81f4e2", ["text"] = "Вы в Глубинах Черной горы — в столице дворфов Черного Железа, высеченной в самом сердце вулкана. Больше двух веков назад их чародей-тан Тауриссан, проигрывая войну Бронзобородам, призвал из недр владыку огня Рагнароса. Пламя выжгло земли наверху, а клан Черного Железа с тех пор служит тому, кого сам позвал. Теперь здесь правит император Дагран Тауриссан, и о нём ходят тревожные слухи: говорят, при его дворе видели пропавшую дочь короля Магни. Город огромен — тюрьма, арена, кузни, трактир, тронный зал, — и дорог в нём много.", ["duration"] = 45, ["cues"] = { { 0, "Вы в Глубинах Чёрной горы — в столице дворфов Чёрного Железа, высеченной в самом сердце вулкана." }, { 8.2, "Больше двух веков назад их чародей-тан Тауриссан, проигрывая войну Бронзобородам, призвал из недр владыку огня Рагнароса." }, { 18.57, "Пламя выжгло земли наверху, а клан Чёрного Железа с тех пор служит тому, кого сам позвал." }, { 26.24, "Теперь здесь правит император Дагран Тауриссан, и о нём ходят тревожные слухи: говорят, при его дворе видели пропавшую дочь короля Магни." }, { 38.08, "Город огромен — тюрьма, арена, кузни, трактир, тронный зал, — и дорог в нём много." } } } }, { ["id"] = "dm_blackrock_depths_prolog_repeat", ["k"] = "prolog", ["trig"] = "repeat", ["track"] = { ["hash"] = "41ad26e3", ["text"] = "Снова Глубины Черной горы. Горны гудят, как прежде, а у императора, судя по всему, уже новая стража.", ["duration"] = 9, ["cues"] = { { 0, "Снова Глубины Чёрной горы." }, { 2.42, "Горны гудят, как прежде, а у императора, судя по всему, уже новая стража." } } } }, { ["q"] = 4362, ["prio"] = 0, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_blackrock_depths_hook_4362", ["track"] = { ["hash"] = "b3bef823", ["text"] = "Король Магни Бронзобород ждёт вестей о дочери. Мойра где-то здесь, во власти Даграна Тауриссана, и снять с неё чары можно, только убив императора. Её саму не трогайте.", ["duration"] = 13.6, ["cues"] = { { 0, "Король Магни Бронзобород ждёт вестей о дочери." }, { 3.87, "Мойра где-то здесь, во власти Даграна Тауриссана, и снять с неё чары можно, только убив императора." }, { 12.04, "Её саму не трогайте." } } } }, { ["q"] = 4003, ["prio"] = 1, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_blackrock_depths_hook_4003", ["track"] = { ["hash"] = "07014331", ["text"] = "Тралл хочет, чтобы принцессу Стальгорна освободила Орда. Для этого придётся убить императора, а принцесса, пока она под его чарами, будет драться на его стороне. Ей вредить нельзя.", ["duration"] = 14.2, ["cues"] = { { 0, "Тралл хочет, чтобы принцессу Стальгорна освободила Орда." }, { 4.44, "Для этого придётся убить императора, а принцесса, пока она под его чарами, будет драться на его стороне." }, { 12.81, "Ей вредить нельзя." } } } }, { ["q"] = 3802, ["prio"] = 2, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_blackrock_depths_hook_3802", ["track"] = { ["hash"] = "b883847b", ["text"] = "Призрак Франклорна Искусника обещал вам Ключ Тенегорна. Для этого нужен его молот, Железный Друг, — он у Финия Темностроя в Зале Ремесла.", ["duration"] = 11.4, ["cues"] = { { 0, "Призрак Франклорна Искусника обещал вам Ключ Тенегорна." }, { 4.62, "Для этого нужен его молот, Железный Друг, — он у Финия Темностроя в Зале Ремесла." } } } }, { ["sub"] = "Тюремный блок", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_blackrock_depths_gerstahn_intro", ["enc"] = 227, ["pos"] = 1, ["track"] = { ["hash"] = "45801c1d", ["text"] = "Тюремный блок. Ряды камер, цепи на стенах, запах сырости и страха. Сюда бросают всех, кто попался дворфам Черного Железа: разведчиков Орды, солдат Альянса, случайных бродяг. Хозяйка блока — верховный дознаватель Герштан, женщина из людей, которая служит императору и знает толк в допросах. Ключ от всех камер она носит при себе.", ["duration"] = 27.7, ["cues"] = { { 0, "Тюремный блок." }, { 1.22, "Ряды камер, цепи на стенах, запах сырости и страха." }, { 5.74, "Сюда бросают всех, кто попался дворфам Чёрного Железа: разведчиков Орды, солдат Альянса, случайных бродяг." }, { 14.76, "Хозяйка блока — верховный дознаватель Герштан, женщина из людей, которая служит императору и знает толк в допросах." }, { 24.55, "Ключ от всех камер она носит при себе." } } } }, { ["q"] = 4341, ["follows"] = "dm_blackrock_depths_gerstahn_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_hook_4341", ["track"] = { ["hash"] = "8b937263", ["text"] = "Где-то здесь, за решёткой, сидит Каран Могучий Молот — тот, кто должен был охранять принцессу Мойру. Король Магни хочет услышать его ответ.", ["duration"] = 12.2, ["cues"] = { { 0, "Где-то здесь, за решёткой, сидит Каран Могучий Молот — тот, кто должен был охранять принцессу Мойру." }, { 8.74, "Король Магни хочет услышать его ответ." } } } }, { ["q"] = 3981, ["follows"] = "dm_blackrock_depths_gerstahn_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_hook_3981", ["track"] = { ["hash"] = "cf8c4732", ["text"] = "В одной из камер ждёт командир Гор'шак: это он прислал записку на стреле. Ключ от решётки — у дознавателя.", ["duration"] = 8.2, ["cues"] = { { 0, "В одной из камер ждёт командир Гор'шак: это он прислал записку на стреле." }, { 5.88, "Ключ от решётки — у дознавателя." } } } }, { ["q"] = 4241, ["follows"] = "dm_blackrock_depths_gerstahn_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_hook_4241", ["track"] = { ["hash"] = "933b129a", ["text"] = "Маршал Максвелл хочет знать, жив ли маршал Винздор. Если жив — он в одной из этих камер.", ["duration"] = 6.9, ["cues"] = { { 0, "Маршал Максвелл хочет знать, жив ли маршал Винздор." }, { 4.09, "Если жив — он в одной из этих камер." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_depths_gerstahn_pull", ["enc"] = 227, ["track"] = { ["hash"] = "f9e20999", ["text"] = "Герштан встречает вас улыбкой палача, и в её ладонях сгущается тень. Тёмная магия дознавателя гложет изнутри, а от её крика строй рассыпается: кто стоит рядом, бросится прочь, не помня себя.", ["duration"] = 16.6, ["cues"] = { { 0, "Герштан встречает вас улыбкой палача, и в её ладонях сгущается тень." }, { 6.03, "Тёмная магия дознавателя гложет изнутри, а от её крика строй рассыпается: кто стоит рядом, бросится прочь, не помня себя." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_gerstahn", ["enc"] = 227, ["track"] = { ["hash"] = "e2bb3307", ["text"] = "Верховный дознаватель Герштан затихает среди своих инструментов. На поясе у неё звенит ключ от тюремной камеры. Узники за решётками поднимают головы: впервые за долгое время шаги в коридоре не сулят им боли. Кого-то из них дома, наверное, давно оплакали.", ["duration"] = 19.9, ["cues"] = { { 0, "Верховный дознаватель Герштан затихает среди своих инструментов." }, { 5.14, "На поясе у неё звенит ключ от тюремной камеры." }, { 8.79, "Узники за решётками поднимают головы: впервые за долгое время шаги в коридоре не сулят им боли." }, { 16.36, "Кого-то из них дома, наверное, давно оплакали." } } } }, { ["sub"] = "Галереи Правосудия", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_blackrock_depths_roccor_intro", ["enc"] = 228, ["pos"] = 2, ["track"] = { ["hash"] = "e9416109", ["text"] = "Галереи Правосудия. Кольцевой коридор огибает арену, и из-за стены доносится гул толпы. По дальней половине галерей бродит лорд Роккор — живая глыба раскалённого камня, порождение огня, что течёт под городом. А где-то в этих же галереях держит свою свору псарь Гребмар.", ["duration"] = 22.7, ["cues"] = { { 0, "Галереи Правосудия." }, { 1.69, "Кольцевой коридор огибает арену, и из-за стены доносится гул толпы." }, { 7.52, "По дальней половине галерей бродит лорд Роккор — живая глыба раскалённого камня, порождение огня, что течёт под городом." }, { 17.66, "А где-то в этих же галереях держит свою свору псарь Гребмар." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_depths_roccor_pull", ["enc"] = 228, ["track"] = { ["hash"] = "56777a8d", ["text"] = "Лорд Роккор поднимается во весь рост, и от него пышет жаром. Когда он топает, земля вздрагивает так, что заклинания обрываются на полуслове, а огонь, которым он плюётся, ещё долго жжёт после удара.", ["duration"] = 16.1, ["cues"] = { { 0, "Лорд Роккор поднимается во весь рост, и от него пышет жаром." }, { 4.98, "Когда он топает, земля вздрагивает так, что заклинания обрываются на полуслове, а огонь, которым он плюётся, ещё долго жжёт после удара." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_roccor", ["enc"] = 228, ["track"] = { ["hash"] = "bbd84458", ["text"] = "Лорд Роккор рассыпается грудой остывающего камня. В трещинах ещё тлеет жар, но жизни в нём больше нет. Огонь этих глубин не умирает — он лишь уходит обратно в камень и ждёт.", ["duration"] = 15.2, ["cues"] = { { 0, "Лорд Роккор рассыпается грудой остывающего камня." }, { 4.45, "В трещинах ещё тлеет жар, но жизни в нём больше нет." }, { 9.05, "Огонь этих глубин не умирает — он лишь уходит обратно в камень и ждёт." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_depths_grebmar_pull", ["enc"] = 229, ["track"] = { ["hash"] = "02730b21", ["text"] = "Псарь Гребмар свистит, и собаки бросаются вперёд. Дворф рявкает так, что у бойцов опускаются руки, а его рык разжигает в зверях ярость: пока хозяин подаёт голос, свора не знает устали. Когда дело запахнет жареным, он попробует удрать.", ["duration"] = 19.6, ["cues"] = { { 0, "Псарь Гребмар свистит, и собаки бросаются вперёд." }, { 4.12, "Дворф рявкает так, что у бойцов опускаются руки, а его рык разжигает в зверях ярость: пока хозяин подаёт голос, свора не знает устали." }, { 15.48, "Когда дело запахнет жареным, он попробует удрать." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_grebmar", ["enc"] = 229, ["track"] = { ["hash"] = "a5687894", ["text"] = "Псарь Гребмар падает среди своих псов. Других родных у него, похоже, и не было — только звери, которых он выкормил сам. За стеной по-прежнему ревёт арена, и никто там не заметит, что в галереях стало тише.", ["duration"] = 16.5, ["cues"] = { { 0, "Псарь Гребмар падает среди своих псов." }, { 3.15, "Других родных у него, похоже, и не было — только звери, которых он выкормил сам." }, { 9.75, "За стеной по-прежнему ревёт арена, и никто там не заметит, что в галереях стало тише." } } } }, { ["sub"] = "Зал Правосудия", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_blackrock_depths_ring_intro", ["enc"] = 230, ["pos"] = 4, ["track"] = { ["hash"] = "8c488662", ["text"] = "Зал Правосудия. Круглая арена, решётки по краям, а над ней — ярусы, набитые зрителями. У дворфов Черного Железа за преступление против клана одно наказание — смерть, и исполняют его здесь, на потеху толпе. Стоит ступить в центр круга, как ворота закроются, а верховный судья Мрачнокамень зачитает приговор. Через арену лежит путь в город.", ["duration"] = 28.6, ["cues"] = { { 0, "Зал Правосудия." }, { 1.32, "Круглая арена, решётки по краям, а над ней — ярусы, набитые зрителями." }, { 7.3, "У дворфов Чёрного Железа за преступление против клана одно наказание — смерть, и исполняют его здесь, на потеху толпе." }, { 17.39, "Стоит ступить в центр круга, как ворота закроются, а верховный судья Мрачнокамень зачитает приговор." }, { 26, "Через арену лежит путь в город." } } } }, { ["q"] = 9015, ["follows"] = "dm_blackrock_depths_ring_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_hook_9015", ["track"] = { ["hash"] = "3470f1b4", ["text"] = "Знамя Вызова, что дал вам Фалрин Садовник, при вас. Когда судья Мрачнокамень начнёт зачитывать приговор, вонзите его в землю — и вместо зверей на арену выйдет Телдрен со своими бойцами.", ["duration"] = 14.1, ["cues"] = { { 0, "Знамя Вызова, что дал вам Фалрин Садовник, при вас." }, { 3.89, "Когда судья Мрачнокамень начнёт зачитывать приговор, вонзите его в землю — и вместо зверей на арену выйдет Телдрен со своими бойцами." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_depths_ring_pull", ["enc"] = 230, ["track"] = { ["hash"] = "676ec89d", ["text"] = "Это суд Черного Железа над чужаками, и приговор у него один. Толпа ревёт, из клеток выпускают зверьё — волну за волной. Последним выходит чемпион арены: кто именно, решает жребий судьи. На арене не спрятаться, и тот, кто отобьётся от своих, встретит зверьё один.", ["duration"] = 23.1, ["cues"] = { { 0, "Это суд Чёрного Железа над чужаками, и приговор у него один." }, { 5.43, "Толпа ревёт, из клеток выпускают зверьё — волну за волной." }, { 10.63, "Последним выходит чемпион арены: кто именно, решает жребий судьи." }, { 16.63, "На арене не спрятаться, и тот, кто отобьётся от своих, встретит зверьё один." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_ring", ["enc"] = 230, ["track"] = { ["hash"] = "3ce2337d", ["text"] = "Чемпион арены рухнул на песок, и ярусы на миг замолкают. Приговор верховного судьи Мрачнокамня исполнить не удалось. Ворота арены снова открыты, и за ними лежит дорога дальше, в город.", ["duration"] = 15.8, ["cues"] = { { 0, "Чемпион арены рухнул на песок, и ярусы на миг замолкают." }, { 4.87, "Приговор верховного судьи Мрачнокамня исполнить не удалось." }, { 9.97, "Ворота арены снова открыты, и за ними лежит дорога дальше, в город." } } } }, { ["sub"] = "Святилище Тауриссана", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_blackrock_depths_loregrain_intro", ["enc"] = 231, ["pos"] = 5, ["track"] = { ["hash"] = "0c5a5404", ["text"] = "Святилище Тауриссана. Над залом возвышается статуя Франклорна Искусника — великого зодчего, что построил этот город. Перед ней стоит на коленях пиромант Зерно Мудрости, таурен, который служит огню. Что таурену нужно в святилище дворфов, неясно, но к статуе он относится с подозрительным интересом. Дворфы его не гонят: огню здесь служат все.", ["duration"] = 28.3, ["cues"] = { { 0, "Святилище Тауриссана." }, { 1.8, "Над залом возвышается статуя Франклорна Искусника — великого зодчего, что построил этот город." }, { 9.69, "Перед ней стоит на коленях пиромант Зерно Мудрости, таурен, который служит огню." }, { 16.53, "Что таурену нужно в святилище дворфов, неясно, но к статуе он относится с подозрительным интересом." }, { 24.71, "Дворфы его не гонят: огню здесь служат все." } } } }, { ["q"] = 3802, ["follows"] = "dm_blackrock_depths_loregrain_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_hook_3802_shrine", ["track"] = { ["hash"] = "13a819a4", ["text"] = "Это та самая статуя. Вложите ей в руки Железный Друг — и откроется тайник с Ключом Тенегорна.", ["duration"] = 8, ["cues"] = { { 0, "Это та самая статуя." }, { 1.88, "Вложите ей в руки Железный Друг — и откроется тайник с Ключом Тенегорна." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_depths_loregrain_pull", ["enc"] = 231, ["track"] = { ["hash"] = "c209baf9", ["text"] = "Пиромант поднимается с колен, и у его ног вспыхивает тотем, плюющийся огнём. Сам он бьёт лавой и огненным шоком, а пока тотем стоит, его пламя будет находить каждого из вас по очереди.", ["duration"] = 14.6, ["cues"] = { { 0, "Пиромант поднимается с колен, и у его ног вспыхивает тотем, плюющийся огнём." }, { 6.06, "Сам он бьёт лавой и огненным шоком, а пока тотем стоит, его пламя будет находить каждого из вас по очереди." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_loregrain", ["enc"] = 231, ["track"] = { ["hash"] = "c289f4e0", ["text"] = "Пиромант Зерно Мудрости падает к подножию статуи. Таурены — народ земли и ветра, и видеть одного из них слугой огня тяжело. Каменный Франклорн смотрит поверх его тела в пустоту: зодчий видел в этих стенах и не такое. Чего пиромант хотел от статуи, он унёс с собой.", ["duration"] = 22.6, ["cues"] = { { 0, "Пиромант Зерно Мудрости падает к подножию статуи." }, { 4.28, "Таурены — народ земли и ветра, и видеть одного из них слугой огня тяжело." }, { 10.63, "Каменный Франклорн смотрит поверх его тела в пустоту: зодчий видел в этих стенах и не такое." }, { 18.66, "Чего пиромант хотел от статуи, он унёс с собой." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_depths_incendius_pull", ["enc"] = 232, ["track"] = { ["hash"] = "50a91f53", ["text"] = "Лорд Опалитель, огненный прислужник Рагнароса, разворачивается от Черной наковальни, и воздух вокруг начинает плавиться. С потолка рушатся огненные столбы, и горе тому, кто замешкается в горящем круге, а удар его кулака отшвыривает назад даже самого стойкого.", ["duration"] = 20.4, ["cues"] = { { 0, "Лорд Опалитель, огненный прислужник Рагнароса, разворачивается от Чёрной наковальни, и воздух вокруг начинает плавиться." }, { 9.38, "С потолка рушатся огненные столбы, и горе тому, кто замешкается в горящем круге, а удар его кулака отшвыривает назад даже самого стойкого." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_incendius", ["enc"] = 232, ["track"] = { ["hash"] = "0613eca0", ["text"] = "Лорд Опалитель гаснет у Черной наковальни. Только на ней дворфы Черного Железа куют черное железо, и Рагнарос держал при ней своего огненного лорда. Теперь у наковальни нет стража, и кузнецы Черного Железа работают без присмотра.", ["duration"] = 18.2, ["cues"] = { { 0, "Лорд Опалитель гаснет у Чёрной наковальни." }, { 3.37, "Только на ней дворфы Чёрного Железа куют чёрное железо, и Рагнарос держал при ней своего огненного лорда." }, { 11.87, "Теперь у наковальни нет стража, и кузнецы Чёрного Железа работают без присмотра." } } } }, { ["sub"] = "Тракт Черного Железа", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_blackrock_depths_baelgar_intro", ["enc"] = 235, ["pos"] = 7, ["track"] = { ["hash"] = "cbf5473a", ["text"] = "Тракт Черного Железа. Широкая мощёная дорога тянется через пещеру, и по ней ходят патрули дворфов с псами. В дальнем конце тракта стоит Бейл'Гор — огненный великан, воплощение пламени, порождённое огнём Рагнароса. Камень под его ногами раскалён докрасна, и патрули стараются не задерживаться рядом с ним.", ["duration"] = 24.6, ["cues"] = { { 0, "Тракт Чёрного Железа." }, { 1.71, "Широкая мощёная дорога тянется через пещеру, и по ней ходят патрули дворфов с псами." }, { 8.71, "В дальнем конце тракта стоит Бейл'Гор — огненный великан, воплощение пламени, порождённое огнём Рагнароса." }, { 17.42, "Камень под его ногами раскалён докрасна, и патрули стараются не задерживаться рядом с ним." } } } }, { ["q"] = 4024, ["follows"] = "dm_blackrock_depths_baelgar_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_hook_4024", ["track"] = { ["hash"] = "77f2a89f", ["text"] = "Цирус Раскаиватель ждёт частицу огня Бейл'Гора. Берите её из останков великана драконьей шкурой — иначе обожжётесь.", ["duration"] = 9.5, ["cues"] = { { 0, "Цирус Раскаиватель ждёт частицу огня Бейл'Гора." }, { 4.04, "Берите её из останков великана драконьей шкурой — иначе обожжётесь." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_depths_baelgar_pull", ["enc"] = 235, ["track"] = { ["hash"] = "9dc42bc3", ["text"] = "Бейл'Гор поднимает раскалённые кулаки, и брызги магмы прожигают броню до кожи. Время от времени великан рождает из лавы своих отпрысков — огненных тварей, которые спешат защитить отца.", ["duration"] = 14.9, ["cues"] = { { 0, "Бейл'Гор поднимает раскалённые кулаки, и брызги магмы прожигают броню до кожи." }, { 6.35, "Время от времени великан рождает из лавы своих отпрысков — огненных тварей, которые спешат защитить отца." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_baelgar", ["enc"] = 235, ["track"] = { ["hash"] = "72206b96", ["text"] = "Бейл'Гор оседает грудой застывающего камня, и на тракте становится непривычно тихо. Великан не был живым в привычном смысле — просто огонь, которому придали форму. Из его останков ещё сочится жар, и его хватит, чтобы обжечь неосторожную руку.", ["duration"] = 20, ["cues"] = { { 0, "Бейл'Гор оседает грудой застывающего камня, и на тракте становится непривычно тихо." }, { 6.92, "Великан не был живым в привычном смысле — просто огонь, которому придали форму." }, { 13.61, "Из его останков ещё сочится жар, и его хватит, чтобы обжечь неосторожную руку." } } } }, { ["sub"] = "Зал Ремесла", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_blackrock_depths_fineous_intro", ["enc"] = 234, ["pos"] = 8, ["track"] = { ["hash"] = "c5b5aa1e", ["text"] = "Зал Ремесла. Каменная лестница поднимается от Черной наковальни к городу, и на каждом пролёте — големы и мастеровые. Здесь хозяйничает Финий Темнострой, главный зодчий Тенегорна. Должность он унаследовал от Франклорна Искусника, а вместе с ней — и его молот, Железный Друг. Призрак старого мастера до сих пор не может этого простить.", ["duration"] = 27.4, ["cues"] = { { 0, "Зал Ремесла." }, { 1.06, "Каменная лестница поднимается от Чёрной наковальни к городу, и на каждом пролёте — големы и мастеровые." }, { 9.58, "Здесь хозяйничает Финий Темнострой, главный зодчий Тенегорна." }, { 14.75, "Должность он унаследовал от Франклорна Искусника, а вместе с ней — и его молот, Железный Друг." }, { 22.58, "Призрак старого мастера до сих пор не может этого простить." } } } }, { ["q"] = 4263, ["follows"] = "dm_blackrock_depths_fineous_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_hook_4263", ["track"] = { ["hash"] = "60d2a47f", ["text"] = "Джалинда Тирлипунька права: это Опалитель раз за разом поднимает Подчинителя Пирона из пепла. Он ходит у Черной наковальни, от которой поднимается эта лестница.", ["duration"] = 12.2, ["cues"] = { { 0, "Джалинда Тирлипунька права: это Опалитель раз за разом поднимает Подчинителя Пирона из пепла." }, { 7.28, "Он ходит у Чёрной наковальни, от которой поднимается эта лестница." } } } }, { ["q"] = 3907, ["follows"] = "dm_blackrock_depths_fineous_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_hook_3907", ["track"] = { ["hash"] = "7c173a1a", ["text"] = "Громосерд чувствовал, что Опалитель — лишь орудие в чужих руках. Найдите его у Черной наковальни и узнайте, кто им повелевает.", ["duration"] = 10.5, ["cues"] = { { 0, "Громосерд чувствовал, что Опалитель — лишь орудие в чужих руках." }, { 5.47, "Найдите его у Чёрной наковальни и узнайте, кто им повелевает." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_depths_fineous_pull", ["enc"] = 234, ["track"] = { ["hash"] = "51d60f0b", ["text"] = "Финий Темнострой перехватывает молот покрепче. Он дерётся как паладин: оружие вспыхивает святым светом, а раненый зодчий шепчет молитвы, и каждая, договорённая до конца, затягивает его раны.", ["duration"] = 15.1, ["cues"] = { { 0, "Финий Темнострой перехватывает молот покрепче." }, { 3.78, "Он дерётся как паладин: оружие вспыхивает святым светом, а раненый зодчий шепчет молитвы, и каждая, договорённая до конца, затягивает его раны." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_fineous", ["enc"] = 234, ["track"] = { ["hash"] = "42ddc2e4", ["text"] = "Финий Темнострой падает на ступени Зала Ремесла. Должность главного зодчего ему досталась, а слава — нет: всё, чем славится этот город, построил Франклорн. Молот старого мастера звенит о камень. Теперь он свободен, и где-то в Святилище Тауриссана статуя ждёт, когда он вернётся в её руки.", ["duration"] = 23.6, ["cues"] = { { 0, "Финий Темнострой падает на ступени Зала Ремесла." }, { 4.1, "Должность главного зодчего ему досталась, а слава — нет: всё, чем славится этот город, построил Франклорн." }, { 12.88, "Молот старого мастера звенит о камень." }, { 16.16, "Теперь он свободен, и где-то в Святилище Тауриссана статуя ждёт, когда он вернётся в её руки." } } } }, { ["role"] = "side", ["k"] = "bag", ["trig"] = "bag", ["id"] = "dm_blackrock_depths_bag_ironfel", ["item"] = 10999, ["track"] = { ["hash"] = "ff8ecfdd", ["text"] = "Молот «Железный Друг» добыт. Отнесите его в Святилище Тауриссана и вложите в руки статуи Франклорна — тайник откроется.", ["duration"] = 9.7, ["cues"] = { { 0, "Молот «Железный Друг» добыт." }, { 2.37, "Отнесите его в Святилище Тауриссана и вложите в руки статуи Франклорна — тайник откроется." } } } }, { ["sub"] = "Черное Хранилище", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_blackrock_depths_stilgiss_intro", ["enc"] = 233, ["pos"] = 9, ["track"] = { ["hash"] = "60ff7bc8", ["text"] = "Черное Хранилище. Здесь клан Черного Железа держит свои сокровища: двенадцать запертых ларцов и каменные стражи по углам. Хранилище стережёт тюремщик Стилгисс, маг императора, а рядом с ним рычит его пёс Верек. Говорят, где-то в стенах спрятан тайный сейф, и откроется он лишь тому, кто вскроет все ларцы до одного.", ["duration"] = 26.7, ["cues"] = { { 0, "Чёрное Хранилище." }, { 1.48, "Здесь клан Чёрного Железа держит свои сокровища: двенадцать запертых ларцов и каменные стражи по углам." }, { 10.36, "Хранилище стережёт тюремщик Стилгисс, маг императора, а рядом с ним рычит его пёс Верек." }, { 17.92, "Говорят, где-то в стенах спрятан тайный сейф, и откроется он лишь тому, кто вскроет все ларцы до одного." } } } }, { ["q"] = 4123, ["follows"] = "dm_blackrock_depths_stilgiss_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_hook_4123", ["track"] = { ["hash"] = "f3025fb2", ["text"] = "Максворт Суперблеск ждёт Сердце Горы — оно в тайном сейфе этого хранилища. Сейф откроется, когда будут вскрыты все двенадцать ларцов.", ["duration"] = 10.8, ["cues"] = { { 0, "Максворт Суперблеск ждёт Сердце Горы — оно в тайном сейфе этого хранилища." }, { 6.18, "Сейф откроется, когда будут вскрыты все двенадцать ларцов." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_depths_stilgiss_pull", ["enc"] = 233, ["track"] = { ["hash"] = "1e41d75e", ["text"] = "Стилгисс вскидывает руки, и по полу расползается иней. Кольцо льда приковывает к месту всех, кто стоит рядом, ледяная стрела замедляет того, кто бежит, а пока маг колдует, Верек рвёт ближнего.", ["duration"] = 15.9, ["cues"] = { { 0, "Стилгисс вскидывает руки, и по полу расползается иней." }, { 4.6, "Кольцо льда приковывает к месту всех, кто стоит рядом, ледяная стрела замедляет того, кто бежит, а пока маг колдует, Верек рвёт ближнего." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_stilgiss", ["enc"] = 233, ["track"] = { ["hash"] = "56c32516", ["text"] = "Тюремщик Стилгисс падает посреди хранилища. Сокровища клана остались без главного сторожа. Впрочем, дворфы Черного Железа никогда не доверяли одному замку: в этих стенах спрятано что-то ещё. Верный Верек лежит рядом с хозяином.", ["duration"] = 18.8, ["cues"] = { { 0, "Тюремщик Стилгисс падает посреди хранилища." }, { 3.66, "Сокровища клана остались без главного сторожа." }, { 7.54, "Впрочем, дворфы Чёрного Железа никогда не доверяли одному замку: в этих стенах спрятано что-то ещё." }, { 15.82, "Верный Верек лежит рядом с хозяином." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_depths_vault_pull", ["enc"] = 2791, ["track"] = { ["hash"] = "5deb5d0e", ["text"] = "Последний ларец открыт — и хранилище оживает: каменные стражи сходят с мест, а за сокровища клана встаёт сторож Хватка Смерти. Посреди боя он не прочь отхлебнуть целебного зелья, и каждая передышка возвращает ему силы.", ["duration"] = 18.1, ["cues"] = { { 0, "Последний ларец открыт — и хранилище оживает: каменные стражи сходят с мест, а за сокровища клана встаёт сторож Хватка Смерти." }, { 10.5, "Посреди боя он не прочь отхлебнуть целебного зелья, и каждая передышка возвращает ему силы." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_vault", ["enc"] = 2791, ["track"] = { ["hash"] = "23a89b9c", ["text"] = "Сторож Хватка Смерти затихает, и путь к тайному сейфу свободен. Внутри — то, ради чего клан строил это хранилище. Даже в городе, где всё из черного железа, есть вещи, которые прячут лучше остальных.", ["duration"] = 16.1, ["cues"] = { { 0, "Сторож Хватка Смерти затихает, и путь к тайному сейфу свободен." }, { 5.24, "Внутри — то, ради чего клан строил это хранилище." }, { 9.37, "Даже в городе, где всё из чёрного железа, есть вещи, которые прячут лучше остальных." } } } }, { ["sub"] = "Западный гарнизон", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_blackrock_depths_angerforge_intro", ["enc"] = 236, ["pos"] = 11, ["track"] = { ["hash"] = "e7c3df03", ["text"] = "Западный гарнизон. Казармы, оружейные стойки, строй за строем — здесь стоит армия императора. Командует ею генерал Кузня Гнева, старый вояка, знающий о войне всё, что написано в книгах, и кое-что сверх того. Его солдаты вырезали сто девятое подразделение Каргатского экспедиционного корпуса, и Орда этого не забыла.", ["duration"] = 26.4, ["cues"] = { { 0, "Западный гарнизон." }, { 1.6, "Казармы, оружейные стойки, строй за строем — здесь стоит армия императора." }, { 7.84, "Командует ею генерал Кузня Гнева, старый вояка, знающий о войне всё, что написано в книгах, и кое-что сверх того." }, { 17.5, "Его солдаты вырезали сто девятое подразделение Каргатского экспедиционного корпуса, и Орда этого не забыла." } } } }, { ["q"] = 4132, ["follows"] = "dm_blackrock_depths_angerforge_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_hook_4132", ["track"] = { ["hash"] = "896fe4ba", ["text"] = "Полководец Клинозуб ждёт вести о смерти генерала Кузни Гнева. За сто девятое подразделение.", ["duration"] = 7.3, ["cues"] = { { 0, "Полководец Клинозуб ждёт вести о смерти генерала Кузни Гнева." }, { 5.08, "За сто девятое подразделение." } } } }, { ["q"] = 4282, ["follows"] = "dm_blackrock_depths_angerforge_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_hook_4282", ["track"] = { ["hash"] = "dcef7251", ["text"] = "Записи маршала Винздора — у генерала Кузни Гнева и у повелителя големов Аргелмаха. Без боя они их не отдадут.", ["duration"] = 9.4, ["cues"] = { { 0, "Записи маршала Винздора — у генерала Кузни Гнева и у повелителя големов Аргелмаха." }, { 7.24, "Без боя они их не отдадут." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_depths_angerforge_pull", ["enc"] = 236, ["track"] = { ["hash"] = "27d2c216", ["text"] = "Генерал встречает вас как подобает воину — ни шагу назад. Чем больнее его бьют, тем злее он рубит, а когда станет совсем туго, поднимет тревогу, и из казарм хлынут резервисты с лекарями.", ["duration"] = 15.5, ["cues"] = { { 0, "Генерал встречает вас как подобает воину — ни шагу назад." }, { 4.82, "Чем больнее его бьют, тем злее он рубит, а когда станет совсем туго, поднимет тревогу, и из казарм хлынут резервисты с лекарями." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_angerforge", ["enc"] = 236, ["track"] = { ["hash"] = "d2762933", ["text"] = "Генерал Кузня Гнева падает, так и не отступив. При нём — бумаги, карты, донесения: всё, что армия Черного Железа знает о своих врагах. Тауриссан потерял своего лучшего полководца, а армия — того, кто водил её в бой. Казармы ещё полны солдат, но приказы им теперь отдавать некому.", ["duration"] = 23.8, ["cues"] = { { 0, "Генерал Кузня Гнева падает, так и не отступив." }, { 4.04, "При нём — бумаги, карты, донесения: всё, что армия Чёрного Железа знает о своих врагах." }, { 11.49, "Тауриссан потерял своего лучшего полководца, а армия — того, кто водил её в бой." }, { 18.4, "Казармы ещё полны солдат, но приказы им теперь отдавать некому." } } } }, { ["role"] = "side", ["k"] = "bag", ["trig"] = "bag", ["id"] = "dm_blackrock_depths_bag_note", ["item"] = 11446, ["track"] = { ["hash"] = "ecc392e2", ["text"] = "Среди добычи — измятая записка, подписанная самим императором Даграном Тауриссаном. Почерк едва читается, но имена Кузни Гнева и Аргелмаха видны ясно. Маршал Винздор должен это увидеть.", ["duration"] = 16.1, ["cues"] = { { 0, "Среди добычи — измятая записка, подписанная самим императором Даграном Тауриссаном." }, { 7.23, "Почерк едва читается, но имена Кузни Гнева и Аргелмаха видны ясно." }, { 13.13, "Маршал Винздор должен это увидеть." } } } }, { ["sub"] = "Фабрика", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_blackrock_depths_argelmach_intro", ["enc"] = 237, ["pos"] = 12, ["track"] = { ["hash"] = "0e970957", ["text"] = "Фабрика. Стучат молоты, шипит пар: дворфы Черного Железа собирают здесь големов — каменных и железных солдат, которые не устают и не боятся. Хозяин цехов — повелитель големов Аргелмах. Лотвиль Вериатус клянётся, что убил его своими руками десять лет назад. Тот, кто стоит сейчас посреди Фабрики, с этим явно не согласен.", ["duration"] = 27.8, ["cues"] = { { 0, "Фабрика." }, { 0.79, "Стучат молоты, шипит пар: дворфы Чёрного Железа собирают здесь големов — каменных и железных солдат, которые не устают и не боятся." }, { 12.22, "Хозяин цехов — повелитель големов Аргелмах." }, { 16.09, "Лотвиль Вериатус клянётся, что убил его своими руками десять лет назад." }, { 22.4, "Тот, кто стоит сейчас посреди Фабрики, с этим явно не согласен." } } } }, { ["q"] = 4063, ["follows"] = "dm_blackrock_depths_argelmach_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_hook_4063", ["track"] = { ["hash"] = "05ac545a", ["text"] = "Лотвиль Вериатус хочет, чтобы Аргелмах был уничтожен — на этот раз окончательно.", ["duration"] = 6.7, ["cues"] = { { 0, "Лотвиль Вериатус хочет, чтобы Аргелмах был уничтожен — на этот раз окончательно." } } } }, { ["q"] = 4282, ["follows"] = "dm_blackrock_depths_argelmach_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_hook_4282_argelmach", ["track"] = { ["hash"] = "92af4f29", ["text"] = "Вторая половина записей маршала Винздора — у Аргелмаха.", ["duration"] = 4.4, ["cues"] = { { 0, "Вторая половина записей маршала Винздора — у Аргелмаха." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_depths_argelmach_pull", ["enc"] = 237, ["track"] = { ["hash"] = "10ead035", ["text"] = "Аргелмах окутывается шарами молний и бьёт цепной молнией сразу по нескольким. Первым делом он бросится будить своих големов: если Фабрика не зачищена, бой станет очень людным.", ["duration"] = 13.6, ["cues"] = { { 0, "Аргелмах окутывается шарами молний и бьёт цепной молнией сразу по нескольким." }, { 6.03, "Первым делом он бросится будить своих големов: если Фабрика не зачищена, бой станет очень людным." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_argelmach", ["enc"] = 237, ["track"] = { ["hash"] = "fc560441", ["text"] = "Повелитель големов Аргелмах замирает, и вместе с ним затихают ближние машины. Сколько его големов уже ушло наверх, в Тлеющее ущелье, не знает никто. Но новых здесь больше не соберут — по крайней мере, пока не найдётся новый повелитель.", ["duration"] = 19.1, ["cues"] = { { 0, "Повелитель големов Аргелмах замирает, и вместе с ним затихают ближние машины." }, { 6.33, "Сколько его големов уже ушло наверх, в Тлеющее ущелье, не знает никто." }, { 12.29, "Но новых здесь больше не соберут — по крайней мере, пока не найдётся новый повелитель." } } } }, { ["sub"] = "Трактир \"Угрюмый обжора\"", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_blackrock_depths_guzzler_intro", ["enc"] = 239, ["pos"] = 13, ["track"] = { ["hash"] = "2a93f31d", ["text"] = "«Угрюмый обжора». После кузниц и казарм — вдруг музыка, гомон и запах эля. Здесь дворфы Черного Железа пьют, поют и дерутся, и пока вы никого не трогаете, никто не трогает вас. У входа сидит гоблин Риббли Крутипроб с дружками, за стойкой — хозяин, Штоппор Наливалс, у лестницы — голем-вышибала Фаланг. А в пустой комнате у входа стоят бочки с элем Харли Чернопыха, укравшего рецепт громоварского.", ["duration"] = 33.6, ["cues"] = { { 0, "«Угрюмый обжора»." }, { 1.53, "После кузниц и казарм — вдруг музыка, гомон и запах эля." }, { 6.44, "Здесь дворфы Чёрного Железа пьют, поют и дерутся, и пока вы никого не трогаете, никто не трогает вас." }, { 14.96, "У входа сидит гоблин Риббли Крутипроб с дружками, за стойкой — хозяин, Штоппор Наливалс, у лестницы — голем-вышибала Фаланг." }, { 25.62, "А в пустой комнате у входа стоят бочки с элем Харли Чернопыха, укравшего рецепт громоварского." } } } }, { ["q"] = 4201, ["follows"] = "dm_blackrock_depths_guzzler_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_hook_4201", ["track"] = { ["hash"] = "40cc7720", ["text"] = "Госпожа Нагмара, суккуб, влюблённая в рядового Камнеузла, ищет помощи с приворотным зельем. Если зелье подействует, она сама откроет вам заднюю дверь.", ["duration"] = 12.3, ["cues"] = { { 0, "Госпожа Нагмара, суккуб, влюблённая в рядового Камнеузла, ищет помощи с приворотным зельем." }, { 7.54, "Если зелье подействует, она сама откроет вам заднюю дверь." } } } }, { ["q"] = 4126, ["follows"] = "dm_blackrock_depths_guzzler_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_hook_4126", ["track"] = { ["hash"] = "ec1f3158", ["text"] = "Рагнар Громовар ждёт свой рецепт — и чтобы от украденного эля не осталось ни бочонка. Разбейте бочки в комнате у входа, и Харли Чернопых явится сам.", ["duration"] = 11.9, ["cues"] = { { 0, "Рагнар Громовар ждёт свой рецепт — и чтобы от украденного эля не осталось ни бочонка." }, { 6.92, "Разбейте бочки в комнате у входа, и Харли Чернопых явится сам." } } } }, { ["q"] = 4134, ["follows"] = "dm_blackrock_depths_guzzler_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_hook_4134", ["track"] = { ["hash"] = "5a407123", ["text"] = "Темный маг Вивиана Лягроб ждёт рецепт громоварского светлого. Чтобы выманить Харли Чернопыха, пригрозите его драгоценному элю.", ["duration"] = 10.6, ["cues"] = { { 0, "Тёмный маг Вивиана Лягроб ждёт рецепт громоварского светлого." }, { 5.13, "Чтобы выманить Харли Чернопыха, пригрозите его драгоценному элю." } } } }, { ["q"] = 4136, ["follows"] = "dm_blackrock_depths_guzzler_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_hook_4136", ["track"] = { ["hash"] = "f1bc8770", ["text"] = "Голова Риббли нужна Юке Крутипроб. Сам Риббли с дружками — тут же, у входа. В семье Крутипробов братскую любовь меряют золотом.", ["duration"] = 10.4, ["cues"] = { { 0, "Голова Риббли нужна Юке Крутипроб." }, { 2.95, "Сам Риббли с дружками — тут же, у входа." }, { 6.2, "В семье Крутипробов братскую любовь меряют золотом." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_depths_phalanx_pull", ["enc"] = 239, ["track"] = { ["hash"] = "7afd29c6", ["text"] = "Голем-вышибала Фаланг разворачивается к вам: в «Угрюмом обжоре» буянов не терпят. Его кулак отбрасывает на несколько шагов, раскат грома бьёт всех рядом, а град огненных шаров достаёт и тех, кто держится в стороне.", ["duration"] = 16.6, ["cues"] = { { 0, "Голем-вышибала Фаланг разворачивается к вам: в «Угрюмом обжоре» буянов не терпят." }, { 6.4, "Его кулак отбрасывает на несколько шагов, раскат грома бьёт всех рядом, а град огненных шаров достаёт и тех, кто держится в стороне." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_phalanx", ["enc"] = 239, ["track"] = { ["hash"] = "ed323218", ["text"] = "Фаланг с грохотом валится на пол, и кружки на столах подпрыгивают. Завсегдатаи на миг замолкают, а потом возвращаются к элю: в этом трактире видали драки и похуже. Голем был последним, кто следил здесь за порядком, и теперь трактиру придётся обходиться без него.", ["duration"] = 19.7, ["cues"] = { { 0, "Фаланг с грохотом валится на пол, и кружки на столах подпрыгивают." }, { 5.04, "Завсегдатаи на миг замолкают, а потом возвращаются к элю: в этом трактире видали драки и похуже." }, { 12.44, "Голем был последним, кто следил здесь за порядком, и теперь трактиру придётся обходиться без него." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_depths_hurley_pull", ["enc"] = 238, ["track"] = { ["hash"] = "0fed608b", ["text"] = "Разбитые бочки не остались незамеченными: Харли Чернопых с дружками уже здесь. Пьяный дворф дышит огнём на тех, кто стоит перед ним, а в хмельной ярости бьёт куда чаще и злее — горе тому, кто тогда окажется у него на пути.", ["duration"] = 18.3, ["cues"] = { { 0, "Разбитые бочки не остались незамеченными: Харли Чернопых с дружками уже здесь." }, { 6.53, "Пьяный дворф дышит огнём на тех, кто стоит перед ним, а в хмельной ярости бьёт куда чаще и злее — горе тому, кто тогда окажется у него на пути." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_hurley", ["enc"] = 238, ["track"] = { ["hash"] = "b2d0fe6b", ["text"] = "Харли Чернопых падает в лужу собственного эля. Ради этого эля он однажды обокрал самих Громоваров и с тех пор ни с кем не делился. Рецепт громоварского светлого при нём, и за этим листком охотятся и Альянс, и Орда. Говорят, кто выпьет этого эля, не боится ничего на свете.", ["duration"] = 21.8, ["cues"] = { { 0, "Харли Чернопых падает в лужу собственного эля." }, { 3.86, "Ради этого эля он однажды обокрал самих Громоваров и с тех пор ни с кем не делился." }, { 10.56, "Рецепт громоварского светлого при нём, и за этим листком охотятся и Альянс, и Орда." }, { 17.26, "Говорят, кто выпьет этого эля, не боится ничего на свете." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_depths_ribbly_pull", ["enc"] = 240, ["track"] = { ["hash"] = "1af45714", ["text"] = "Гоблин понимает, зачем вы пришли, раньше, чем вы откроете рот. Риббли с дружками бросается в драку: подрезает ноги, оглушает подлым ударом, а как запахнет жареным — попробует сбежать.", ["duration"] = 13.8, ["cues"] = { { 0, "Гоблин понимает, зачем вы пришли, раньше, чем вы откроете рот." }, { 4.73, "Риббли с дружками бросается в драку: подрезает ноги, оглушает подлым ударом, а как запахнет жареным — попробует сбежать." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_ribbly", ["enc"] = 240, ["track"] = { ["hash"] = "fedf2a3a", ["text"] = "Риббли Крутипроб растягивается на полу «Угрюмого обжоры». Всю жизнь он тянул деньги из родни и спускал их на сомнительные затеи, и последняя кончилась наградой за его голову от барона Ревилгаза. Родственники, похоже, рыдать не станут: наконец-то и Риббли хоть чего-то стоит.", ["duration"] = 20.6, ["cues"] = { { 0, "Риббли Крутипроб растягивается на полу «Угрюмого обжоры»." }, { 4.39, "Всю жизнь он тянул деньги из родни и спускал их на сомнительные затеи, и последняя кончилась наградой за его голову от барона Ревилгаза." }, { 14.67, "Родственники, похоже, рыдать не станут: наконец-то и Риббли хоть чего-то стоит." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_depths_plugger_pull", ["enc"] = 241, ["track"] = { ["hash"] = "cfe90c4c", ["text"] = "Штоппор Наливалс не любит, когда трогают его товар. Хозяин трактира подаёт знак, и весь «Угрюмый обжора», от пьяниц за столами до стражи у дверей, поднимается на его защиту.", ["duration"] = 13.3, ["cues"] = { { 0, "Штоппор Наливалс не любит, когда трогают его товар." }, { 4.13, "Хозяин трактира подаёт знак, и весь «Угрюмый обжора», от пьяниц за столами до стражи у дверей, поднимается на его защиту." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_plugger", ["enc"] = 241, ["track"] = { ["hash"] = "3c31fc5e", ["text"] = "Штоппор Наливалс падает за собственной стойкой, и кран бочонка ещё долго капает на пол. Трактир затихает: хозяина здесь любили, ведь у него ни одна кружка не пустела. Ключ от задней двери был при нём. Завтра здесь снова будут пить — но наливать будет уже кто-то другой.", ["duration"] = 21.5, ["cues"] = { { 0, "Штоппор Наливалс падает за собственной стойкой, и кран бочонка ещё долго капает на пол." }, { 7.03, "Трактир затихает: хозяина здесь любили, ведь у него ни одна кружка не пустела." }, { 13.4, "Ключ от задней двери был при нём." }, { 16.04, "Завтра здесь снова будут пить — но наливать будет уже кто-то другой." } } } }, { ["sub"] = "Колдовской чертог", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_blackrock_depths_flamelash_intro", ["enc"] = 242, ["pos"] = 17, ["track"] = { ["hash"] = "3d5f2bc2", ["text"] = "Колдовской чертог. Огромная пустая площадка, по краям — семь огненных рун. Посреди неё стоит посол Огнехлыст — огненный посланник Рагнароса при дворе Черного Железа. Когда он вспыхнет, руны откликнутся.", ["duration"] = 18.1, ["cues"] = { { 0, "Колдовской чертог." }, { 1.71, "Огромная пустая площадка, по краям — семь огненных рун." }, { 6.68, "Посреди неё стоит посол Огнехлыст — огненный посланник Рагнароса при дворе Чёрного Железа." }, { 14.82, "Когда он вспыхнет, руны откликнутся." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_depths_flamelash_pull", ["enc"] = 242, ["track"] = { ["hash"] = "527f65e1", ["text"] = "Посол Огнехлыст вспыхивает, и руны по краям зала загораются одна за другой. Из них выходят пылающие духи и плывут к послу: каждый, кто дойдёт, отдаст ему свой огонь, и с каждым посол разгорается всё жарче.", ["duration"] = 17.3, ["cues"] = { { 0, "Посол Огнехлыст вспыхивает, и руны по краям зала загораются одна за другой." }, { 6.5, "Из них выходят пылающие духи и плывут к послу: каждый, кто дойдёт, отдаст ему свой огонь, и с каждым посол разгорается всё жарче." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_flamelash", ["enc"] = 242, ["track"] = { ["hash"] = "67b308ad", ["text"] = "Посол Огнехлыст гаснет, и руны вокруг тускнеют. Рагнарос лишился своего голоса при дворе Черного Железа. Огонь в рунах ещё теплится, но духи из них больше не приходят.", ["duration"] = 14.1, ["cues"] = { { 0, "Посол Огнехлыст гаснет, и руны вокруг тускнеют." }, { 4.13, "Рагнарос лишился своего голоса при дворе Чёрного Железа." }, { 8.96, "Огонь в рунах ещё теплится, но духи из них больше не приходят." } } } }, { ["sub"] = "Гробница Заклинателей", ["role"] = "side", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_blackrock_depths_seven_intro", ["enc"] = 243, ["pos"] = 18, ["track"] = { ["hash"] = "90cefb90", ["text"] = "Гробница Заклинателей. Здесь тихо, и это настораживает больше любого шума. Вдоль стен стоят семь призраков — те самые дворфы Черного Железа, что вместе с чародеем-таном Тауриссаном призвали в мир Рагнароса. Они до сих пор стерегут этот зал. Пока вы их не тронете, они не тронут вас, а Мрак'нел даже готов научить рудокопа плавить черное железо.", ["duration"] = 28.6, ["cues"] = { { 0, "Гробница Заклинателей." }, { 1.9, "Здесь тихо, и это настораживает больше любого шума." }, { 6.32, "Вдоль стен стоят семь призраков — те самые дворфы Чёрного Железа, что вместе с чародеем-таном Тауриссаном призвали в мир Рагнароса." }, { 17.22, "Они до сих пор стерегут этот зал." }, { 20.04, "Пока вы их не тронете, они не тронут вас, а Мрак'нел даже готов научить рудокопа плавить чёрное железо." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_depths_seven_pull", ["enc"] = 243, ["track"] = { ["hash"] = "f6bbd5b2", ["text"] = "Рок'рел принимает вызов, и призраки один за другим сходят со своих мест. Каждый из семерых — свой бой: воин, маг, разбойник, чернокнижник… Когда один падает, вперёд выходит следующий, и передышки не будет.", ["duration"] = 17, ["cues"] = { { 0, "Рок'рел принимает вызов, и призраки один за другим сходят со своих мест." }, { 6.13, "Каждый из семерых — свой бой: воин, маг, разбойник, чернокнижник…" }, { 11.51, "Когда один падает, вперёд выходит следующий, и передышки не будет." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_seven", ["enc"] = 243, ["track"] = { ["hash"] = "0e30dea2", ["text"] = "Последний из Семерых развеивается, и в гробнице становится по-настоящему тихо. Два века они хранили верность владыке огня, которого сами же и призвали, и платили за это посмертием в камне. У стены появляется сундук Семерых — всё, что осталось от их былого величия.", ["duration"] = 22, ["cues"] = { { 0, "Последний из Семерых развеивается, и в гробнице становится по-настоящему тихо." }, { 6.53, "Два века они хранили верность владыке огня, которого сами же и призвали, и платили за это посмертием в камне." }, { 15.86, "У стены появляется сундук Семерых — всё, что осталось от их былого величия." } } } }, { ["sub"] = "Железный зал", ["role"] = "main", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_blackrock_depths_magmus_intro", ["enc"] = 244, ["pos"] = 19, ["track"] = { ["hash"] = "61020e8c", ["text"] = "Железный зал. Вдоль стен выстроились исполинские статуи дворфов. Дорогу к трону стережёт Магмус — огненный великан, последний страж перед покоями императора. Тауриссан боится убийц, и, судя по всему, не зря. Говорят, статуи в этом зале оживают по одному слову великана.", ["duration"] = 22.6, ["cues"] = { { 0, "Железный зал." }, { 1.15, "Вдоль стен выстроились исполинские статуи дворфов." }, { 5.37, "Дорогу к трону стережёт Магмус — огненный великан, последний страж перед покоями императора." }, { 13.2, "Тауриссан боится убийц, и, судя по всему, не зря." }, { 17.42, "Говорят, статуи в этом зале оживают по одному слову великана." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_depths_magmus_pull", ["enc"] = 244, ["track"] = { ["hash"] = "b7630758", ["text"] = "Магмус ревёт, и статуи вдоль стен оживают: из их ртов бьют струи пламени, и достаются они тем, кто стоит прямо перед каменными лицами. Когда великан топает, всех вокруг сбивает с ног.", ["duration"] = 14.6, ["cues"] = { { 0, "Магмус ревёт, и статуи вдоль стен оживают: из их ртов бьют струи пламени, и достаются они тем, кто стоит прямо перед каменными лицами." }, { 10.82, "Когда великан топает, всех вокруг сбивает с ног." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_magmus", ["enc"] = 244, ["track"] = { ["hash"] = "2569add1", ["text"] = "Магмус падает, и статуи вдоль стен больше не плюются огнём. В зале становится тихо. Великан стерёг эти двери, не зная ни сна, ни усталости, и ни разу не отступил. Не отступил он и сегодня — просто на этот раз этого оказалось мало.", ["duration"] = 20.2, ["cues"] = { { 0, "Магмус падает, и статуи вдоль стен больше не плюются огнём." }, { 5.24, "В зале становится тихо." }, { 7.42, "Великан стерёг эти двери, не зная ни сна, ни усталости, и ни разу не отступил." }, { 14.35, "Не отступил он и сегодня — просто на этот раз этого оказалось мало." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_moira", ["enc"] = 2789, ["track"] = { ["hash"] = "97088c90", ["text"] = "Принцесса Мойра Бронзобород падает рядом с троном. Дочь короля Магни, которую весь Стальгорн надеялся вернуть домой, домой уже не вернётся. Чары это были или её собственный выбор, теперь не узнает никто. Есть победы, о которых в Стальгорне лучше не рассказывать.", ["duration"] = 21.5, ["cues"] = { { 0, "Принцесса Мойра Бронзобород падает рядом с троном." }, { 4.26, "Дочь короля Магни, которую весь Стальгорн надеялся вернуть домой, домой уже не вернётся." }, { 11.51, "Чары это были или её собственный выбор, теперь не узнает никто." }, { 16.97, "Есть победы, о которых в Стальгорне лучше не рассказывать." } } } }, { ["sub"] = "Императорский Трон", ["role"] = "final", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_blackrock_depths_emperor_intro", ["enc"] = 2790, ["pos"] = 21, ["track"] = { ["hash"] = "d108fcae", ["text"] = "Императорский Трон. Зал полон придворных и стражи, а в конце, на троне, сидит император Дагран Тауриссан — наследник того самого чародея-тана, что призвал Рагнароса. Рядом с ним — принцесса Мойра Бронзобород, дочь короля Магни. Стальгорн уверен, что её похитили и держат под чарами. Сама принцесса смотрит на императора совсем не как пленница.", ["duration"] = 27.8, ["cues"] = { { 0, "Императорский Трон." }, { 1.56, "Зал полон придворных и стражи, а в конце, на троне, сидит император Дагран Тауриссан — наследник того самого чародея-тана, что призвал Рагнароса." }, { 13.59, "Рядом с ним — принцесса Мойра Бронзобород, дочь короля Магни." }, { 18.64, "Стальгорн уверен, что её похитили и держат под чарами." }, { 23.02, "Сама принцесса смотрит на императора совсем не как пленница." } } } }, { ["q"] = 4362, ["follows"] = "dm_blackrock_depths_emperor_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_hook_4362_emperor", ["track"] = { ["hash"] = "1972c557", ["text"] = "Помните просьбу короля Магни: убейте императора, но не трогайте Мойру. Пока она под его властью, она будет сражаться за него.", ["duration"] = 10.3, ["cues"] = { { 0, "Помните просьбу короля Магни: убейте императора, но не трогайте Мойру." }, { 5.83, "Пока она под его властью, она будет сражаться за него." } } } }, { ["q"] = 4003, ["follows"] = "dm_blackrock_depths_emperor_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_hook_4003_emperor", ["track"] = { ["hash"] = "94cec2fc", ["text"] = "Тралл ждёт принцессу живой. Убейте императора, а Мойру не трогайте, что бы она ни делала.", ["duration"] = 7.2, ["cues"] = { { 0, "Тралл ждёт принцессу живой." }, { 2.25, "Убейте императора, а Мойру не трогайте, что бы она ни делала." } } } }, { ["role"] = "final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_blackrock_depths_emperor_pull", ["enc"] = 2790, ["track"] = { ["hash"] = "6254904d", ["text"] = "Император поднимается с трона и зовёт на помощь весь двор — каждый, кто ещё остался в зале, встанет за своего повелителя. Его рука бьёт пламенем и валит с ног, а порой он сам становится живым огнём. Если принцесса Мойра рядом, она будет его лечить.", ["duration"] = 19.8, ["cues"] = { { 0, "Император поднимается с трона и зовёт на помощь весь двор — каждый, кто ещё остался в зале, встанет за своего повелителя." }, { 9.59, "Его рука бьёт пламенем и валит с ног, а порой он сам становится живым огнём." }, { 15.7, "Если принцесса Мойра рядом, она будет его лечить." } } } }, { ["role"] = "final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_blackrock_depths_emperor", ["enc"] = 2790, ["track"] = { ["hash"] = "d178f12b", ["text"] = "Император Дагран Тауриссан падает у подножия собственного трона, и тронный зал затихает. Клан Черного Железа потерял правителя, а Стальгорн — своего давнего врага. Двор, который ещё миг назад сбегался на его зов, остался без господина. А Рагнарос в своих Огненных Недрах вряд ли заметил, что одним слугой стало меньше.", ["duration"] = 25.9, ["cues"] = { { 0, "Император Дагран Тауриссан падает у подножия собственного трона, и тронный зал затихает." }, { 7.32, "Клан Чёрного Железа потерял правителя, а Стальгорн — своего давнего врага." }, { 13.37, "Двор, который ещё миг назад сбегался на его зов, остался без господина." }, { 19.2, "А Рагнарос в своих Огненных Недрах вряд ли заметил, что одним слугой стало меньше." } } } }, { ["q"] = 4362, ["follows"] = "dm_blackrock_depths_emperor", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_fin_4362", ["track"] = { ["hash"] = "bed63c6d", ["text"] = "Поговорите с принцессой Мойрой. Король Магни должен услышать то, что она скажет.", ["duration"] = 6.2, ["cues"] = { { 0, "Поговорите с принцессой Мойрой." }, { 2.45, "Король Магни должен услышать то, что она скажет." } } } }, { ["q"] = 4003, ["follows"] = "dm_blackrock_depths_emperor", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_blackrock_depths_fin_4003", ["track"] = { ["hash"] = "83fd2629", ["text"] = "Поговорите с принцессой. Тралл ждёт её ответа.", ["duration"] = 4.1, ["cues"] = { { 0, "Поговорите с принцессой." }, { 2.29, "Тралл ждёт её ответа." } } } } }, ["bosses"] = { { ["id"] = 227, ["npcs"] = { 9018 }, ["name"] = "High Interrogator Gerstahn", ["required"] = nil, ["token"] = "gerstahn", ["names335"] = { "High Interrogator Gerstahn" } }, { ["id"] = 228, ["npcs"] = { 9025 }, ["name"] = "Lord Roccor", ["required"] = nil, ["token"] = "roccor", ["names335"] = { "Lord Roccor" } }, { ["id"] = 229, ["npcs"] = { 9319 }, ["name"] = "Houndmaster Grebmar", ["required"] = nil, ["token"] = "grebmar", ["names335"] = { "Houndmaster Grebmar" } }, { ["id"] = 230, ["npcs"] = { 9027, 9028, 9029, 9030, 9031, 9032 }, ["name"] = "ring", ["required"] = nil, ["token"] = "ring", ["names335"] = { "Gorosh the Dervish", "Grizzle", "Eviscerator", "Ok'thor the Breaker", "Anub'shiah", "Hedrum the Creeper" } }, { ["id"] = 231, ["npcs"] = { 9024 }, ["name"] = "Pyromancer Loregrain", ["required"] = nil, ["token"] = "loregrain", ["names335"] = { "Pyromancer Loregrain" } }, { ["id"] = 232, ["npcs"] = { 9017 }, ["name"] = "Lord Incendius", ["required"] = nil, ["token"] = "incendius", ["names335"] = { "Lord Incendius" } }, { ["id"] = 235, ["npcs"] = { 9016 }, ["name"] = "Bael'Gar", ["required"] = nil, ["token"] = "baelgar", ["names335"] = { "Bael'Gar" } }, { ["id"] = 234, ["npcs"] = { 9056 }, ["name"] = "Fineous Darkvire", ["required"] = nil, ["token"] = "fineous", ["names335"] = { "Fineous Darkvire" } }, { ["id"] = 233, ["npcs"] = { 9041 }, ["name"] = "Warder Stilgiss", ["required"] = nil, ["token"] = "stilgiss", ["names335"] = { "Warder Stilgiss" } }, { ["id"] = 2791, ["npcs"] = { 9476 }, ["name"] = "vault", ["required"] = nil, ["token"] = "vault", ["names335"] = { "Watchman Doomgrip" } }, { ["id"] = 236, ["npcs"] = { 9033 }, ["name"] = "General Angerforge", ["required"] = nil, ["token"] = "angerforge", ["names335"] = { "General Angerforge" } }, { ["id"] = 237, ["npcs"] = { 8983 }, ["name"] = "Golem Lord Argelmach", ["required"] = nil, ["token"] = "argelmach", ["names335"] = { "Golem Lord Argelmach" } }, { ["id"] = 239, ["npcs"] = { 9502 }, ["name"] = "Phalanx", ["required"] = nil, ["token"] = "phalanx", ["names335"] = { "Phalanx" } }, { ["id"] = 238, ["npcs"] = { 9537 }, ["name"] = "Hurley Blackbreath", ["required"] = nil, ["token"] = "hurley", ["names335"] = { "Hurley Blackbreath" } }, { ["id"] = 240, ["npcs"] = { 9543 }, ["name"] = "Ribbly Screwspigot", ["required"] = nil, ["token"] = "ribbly", ["names335"] = { "Ribbly Screwspigot" } }, { ["id"] = 241, ["npcs"] = { 9499 }, ["name"] = "Plugger Spazzring", ["required"] = nil, ["token"] = "plugger", ["names335"] = { "Plugger Spazzring" } }, { ["id"] = 242, ["npcs"] = { 9156 }, ["name"] = "Ambassador Flamelash", ["required"] = nil, ["token"] = "flamelash", ["names335"] = { "Ambassador Flamelash" } }, { ["id"] = 243, ["npcs"] = { 9034, 9035, 9036, 9037, 9038, 9039, 9040 }, ["name"] = "seven", ["required"] = { 9034, 9035, 9036, 9037, 9038, 9039, 9040 }, ["token"] = "seven", ["names335"] = { "Hate'rel", "Anger'rel", "Vile'rel", "Gloom'rel", "Seeth'rel", "Doom'rel", "Dope'rel" } }, { ["id"] = 244, ["npcs"] = { 9938 }, ["name"] = "Magmus", ["required"] = nil, ["token"] = "magmus", ["names335"] = { "Magmus" } }, { ["id"] = 2790, ["npcs"] = { 9019 }, ["name"] = "Emperor Dagran Thaurissan", ["required"] = nil, ["token"] = "emperor", ["names335"] = { "Emperor Dagran Thaurissan" } }, { ["id"] = 2789, ["npcs"] = { 8929 }, ["name"] = "Принцесса Мойра Бронзобород", ["required"] = nil, ["token"] = "moira", ["names335"] = { "Princess Moira Bronzebeard" } } } },
[289] = { ["key"] = "scholomance", ["order"] = { 2811, 2808, 2806, 2802, 2807, 2803, 2812, 2801 }, ["layout"] = "hub", ["alias"] = {  }, ["name"] = "Некроситет", ["events"] = { { ["id"] = "dm_scholomance_prolog", ["k"] = "prolog", ["trig"] = "prolog", ["track"] = { ["hash"] = "eafe18a6", ["text"] = "Вы в Некроситете — школе некромантии в склепах под Каэр Дарроу. Когда-то замком и его склепами владели Баровы, знатный род Лордерона. Они отдали их Культу Проклятых Кел'Тузада в обмен на обещанное бессмертие — и получили его, только не такое, какого ждали. Теперь здесь учат поднимать мёртвых, растят чумных драконов и готовят новых слуг Плети. Каэр Дарроу именем Плети стережёт лич, а школой заправляет директор — темный магистр Гандлинг. Здесь, посреди озера Дарроумир, Культ годами втайне от всего Лордерона растил своих некромантов.", ["duration"] = 44.4, ["cues"] = { { 0, "Вы в Некроситете — школе некромантии в склепах под Каэр Дарроу." }, { 5.26, "Когда-то замком и его склепами владели Баровы, знатный род Лордерона." }, { 11.12, "Они отдали их Культу Проклятых Кел'Тузада в обмен на обещанное бессмертие — и получили его, только не такое, какого ждали." }, { 21.41, "Теперь здесь учат поднимать мёртвых, растят чумных драконов и готовят новых слуг Плети." }, { 28.7, "Каэр Дарроу именем Плети стережёт лич, а школой заправляет директор — тёмный магистр Гандлинг." }, { 36.52, "Здесь, посреди озера Дарроумир, Культ годами втайне от всего Лордерона растил своих некромантов." } } } }, { ["id"] = "dm_scholomance_prolog_repeat", ["k"] = "prolog", ["trig"] = "repeat", ["track"] = { ["hash"] = "48d5413d", ["text"] = "Снова Некроситет. Новые ученики уже заняли места убитых: эта школа никогда не пустует.", ["duration"] = 8, ["cues"] = { { 0, "Снова Некроситет." }, { 1.65, "Новые ученики уже заняли места убитых: эта школа никогда не пустует." } } } }, { ["q"] = 5466, ["prio"] = 0, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_scholomance_hook_5466", ["track"] = { ["hash"] = "855d7a2c", ["text"] = "Мировой судья Мардук ждёт голову лича. Когда тот вступит в бой, обратите против него Книгу души: только став смертным, он может умереть.", ["duration"] = 12.2, ["cues"] = { { 0, "Мировой судья Мардук ждёт голову лича." }, { 3.57, "Когда тот вступит в бой, обратите против него Книгу души: только став смертным, он может умереть." } } } }, { ["q"] = 5384, ["prio"] = 1, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_scholomance_hook_5384", ["track"] = { ["hash"] = "83af7178", ["text"] = "Ева Саркофф дала вам кровь невинных. Поставьте её в жаровню на балконе — и Киртонос явится на зов.", ["duration"] = 8.4, ["cues"] = { { 0, "Ева Саркофф дала вам кровь невинных." }, { 3.25, "Поставьте её в жаровню на балконе — и Киртонос явится на зов." } } } }, { ["q"] = 5343, ["prio"] = 2, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_scholomance_hook_5343", ["track"] = { ["hash"] = "5adb3e61", ["text"] = "Вэлдон Баров ждёт документы на земли своего рода. Они где-то здесь, в Некроситете, — найдите их раньше, чем брат Вэлдона.", ["duration"] = 9.4, ["cues"] = { { 0, "Вэлдон Баров ждёт документы на земли своего рода." }, { 3.97, "Они где-то здесь, в Некроситете, — найдите их раньше, чем брат Вэлдона." } } } }, { ["q"] = 5341, ["prio"] = 3, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_scholomance_hook_5341", ["track"] = { ["hash"] = "06cbc17b", ["text"] = "Алексий Баров ждёт документы на земли своего рода. Они где-то здесь, и брат Алексия тоже хочет их получить.", ["duration"] = 8.5, ["cues"] = { { 0, "Алексий Баров ждёт документы на земли своего рода." }, { 4.1, "Они где-то здесь, и брат Алексия тоже хочет их получить." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scholomance_kirtonos_pull", ["enc"] = 2805, ["track"] = { ["hash"] = "ae1d9ad2", ["text"] = "Жаровня вспыхивает, и на балкон с неба падает Киртонос — то крылатая горгулья, то человек в чёрном. В людском облике он сыплет проклятиями, в зверином просто рвёт когтями.", ["duration"] = 13.8, ["cues"] = { { 0, "Жаровня вспыхивает, и на балкон с неба падает Киртонос — то крылатая горгулья, то человек в чёрном." }, { 8.07, "В людском облике он сыплет проклятиями, в зверином просто рвёт когтями." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_scholomance_kirtonos", ["enc"] = 2805, ["track"] = { ["hash"] = "29189aa5", ["text"] = "Киртонос падает на камни балкона и больше не поднимается. Он был глашатаем школы и хозяином Крастинова: это ему несли кровь невинных. Ева Саркофф дождалась своей мести.", ["duration"] = 14.2, ["cues"] = { { 0, "Киртонос падает на камни балкона и больше не поднимается." }, { 4.9, "Он был глашатаем школы и хозяином Крастинова: это ему несли кровь невинных." }, { 11.33, "Ева Саркофф дождалась своей мести." } } } }, { ["sub"] = "Главный склеп", ["role"] = "main", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_scholomance_rattlegore_intro", ["enc"] = 2811, ["pos"] = 2, ["track"] = { ["hash"] = "513e0ec1", ["text"] = "Главный склеп. Внизу, в подвале, свалены кости, и среди них стоит самый грозный из костяных стражей школы — Громоклин. Ключ от смотровой у него. Без этого ключа дорога вглубь школы закрыта.", ["duration"] = 16.9, ["cues"] = { { 0, "Главный склеп." }, { 1.3, "Внизу, в подвале, свалены кости, и среди них стоит самый грозный из костяных стражей школы — Громоклин." }, { 10.71, "Ключ от смотровой у него." }, { 12.98, "Без этого ключа дорога вглубь школы закрыта." } } } }, { ["q"] = 5529, ["follows"] = "dm_scholomance_rattlegore_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_scholomance_hook_5529", ["track"] = { ["hash"] = "8c288965", ["text"] = "Бетина Биггльцинк просила убить как можно больше зачумлённых детёнышей. Некроманты выращивают их здесь, в Некроситете.", ["duration"] = 9.4, ["cues"] = { { 0, "Бетина Биггльцинк просила убить как можно больше зачумлённых детёнышей." }, { 5.8, "Некроманты выращивают их здесь, в Некроситете." } } } }, { ["q"] = 5515, ["follows"] = "dm_scholomance_rattlegore_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_scholomance_hook_5515", ["track"] = { ["hash"] = "8d80b697", ["text"] = "В затопленных коридорах Некроситета прячется Джандис Барова. У неё мешок ужасов Крастинова, который ждёт Ева Саркофф.", ["duration"] = 10.2, ["cues"] = { { 0, "В затопленных коридорах Некроситета прячется Джандис Барова." }, { 5.32, "У неё мешок ужасов Крастинова, который ждёт Ева Саркофф." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scholomance_rattlegore_pull", ["enc"] = 2811, ["track"] = { ["hash"] = "60197486", ["text"] = "Громоклин идёт на вас — костяной страж школы, гора чужих рёбер и черепов, сшитая злой волей, и ключ от смотровой у него. Удары у него тяжёлые, и тот, кто встанет перед ним первым, почувствует каждый.", ["duration"] = 17.1, ["cues"] = { { 0, "Громоклин идёт на вас — костяной страж школы, гора чужих рёбер и черепов, сшитая злой волей, и ключ от смотровой у него." }, { 10.43, "Удары у него тяжёлые, и тот, кто встанет перед ним первым, почувствует каждый." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_scholomance_rattlegore", ["enc"] = 2811, ["track"] = { ["hash"] = "1ab1512d", ["text"] = "Громоклин рассыпается грудой костей, и среди них остаётся ключ от смотровой. Школа лишилась одного из своих костяных стражей. Теперь дорога вглубь Некроситета открыта.", ["duration"] = 14.3, ["cues"] = { { 0, "Громоклин рассыпается грудой костей, и среди них остаётся ключ от смотровой." }, { 6.53, "Школа лишилась одного из своих костяных стражей." }, { 10.86, "Теперь дорога вглубь Некроситета открыта." } } } }, { ["q"] = 4771, ["follows"] = "dm_scholomance_rattlegore", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_scholomance_hook_4771", ["track"] = { ["hash"] = "1ba88b17", ["text"] = "Смотровая — та самая комната, куда Бетина Биггльцинк просила отнести Рассветный гамбит. Поставьте его там и посмотрите, что станет с учениками Вектуса.", ["duration"] = 11.3, ["cues"] = { { 0, "Смотровая — та самая комната, куда Бетина Биггльцинк просила отнести Рассветный гамбит." }, { 6.67, "Поставьте его там и посмотрите, что станет с учениками Вектуса." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scholomance_jandice_pull", ["enc"] = 2804, ["track"] = { ["hash"] = "770e132e", ["text"] = "Джандис Барова смеётся, и вокруг неё одна за другой встают её двойники, неотличимые от хозяйки. Настоящая лишь одна: потеряете её из виду — будете рубить пустоту.", ["duration"] = 13.8, ["cues"] = { { 0, "Джандис Барова смеётся, и вокруг неё одна за другой встают её двойники, неотличимые от хозяйки." }, { 8.21, "Настоящая лишь одна: потеряете её из виду — будете рубить пустоту." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_scholomance_jandice", ["enc"] = 2804, ["track"] = { ["hash"] = "cac9553f", ["text"] = "Джандис Барова исчезает вместе со своими миражами. Дочь Баровых служила тем, кто погубил её род: носила кровь невинных от мясника его хозяину.", ["duration"] = 12, ["cues"] = { { 0, "Джандис Барова исчезает вместе со своими миражами." }, { 4.41, "Дочь Баровых служила тем, кто погубил её род: носила кровь невинных от мясника его хозяину." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scholomance_vectus_pull", ["enc"] = 2813, ["track"] = { ["hash"] = "65f09560", ["text"] = "Вектус, маг из нежити, оборачивается к вам от своих учеников. Он ведёт здесь учеников Плети и будет вести урок до последнего.", ["duration"] = 9.9, ["cues"] = { { 0, "Вектус, маг из нежити, оборачивается к вам от своих учеников." }, { 4.93, "Он ведёт здесь учеников Плети и будет вести урок до последнего." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_scholomance_vectus", ["enc"] = 2813, ["track"] = { ["hash"] = "80d6bd99", ["text"] = "Вектус оседает на пол смотровой. Ученикам Плети в этой комнате больше некому вести урок.", ["duration"] = 7.4, ["cues"] = { { 0, "Вектус оседает на пол смотровой." }, { 2.73, "Ученикам Плети в этой комнате больше некому вести урок." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scholomance_marduk_pull", ["enc"] = 2809, ["track"] = { ["hash"] = "b5c2036d", ["text"] = "Мардук Блэкпул, страж смотровой, вступает в бой. Плеть держит в этой школе не только магов и учеников, но и бойцов.", ["duration"] = 9.9, ["cues"] = { { 0, "Мардук Блэкпул, страж смотровой, вступает в бой." }, { 4.21, "Плеть держит в этой школе не только магов и учеников, но и бойцов." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_scholomance_marduk", ["enc"] = 2809, ["track"] = { ["hash"] = "0560b59b", ["text"] = "Мардук Блэкпул падает на пол смотровой. Одним бойцом у Плети стало меньше.", ["duration"] = 5.8, ["cues"] = { { 0, "Мардук Блэкпул падает на пол смотровой." }, { 3.14, "Одним бойцом у Плети стало меньше." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scholomance_ras_pull", ["enc"] = 2810, ["track"] = { ["hash"] = "5272baf4", ["text"] = "Лич Рас Ледяной Шепот поворачивается к вам. Это он стережёт Каэр Дарроу именем Плети, и мороз — его оружие.", ["duration"] = 10.2, ["cues"] = { { 0, "Лич Рас Ледяной Шёпот поворачивается к вам." }, { 4.03, "Это он стережёт Каэр Дарроу именем Плети, и мороз — его оружие." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_scholomance_ras", ["enc"] = 2810, ["track"] = { ["hash"] = "8c9baf3f", ["text"] = "Рас Ледяной Шепот повержен. Когда-то он был человеком из Стромгарда, а после смерти стерёг эту школу для Плети.", ["duration"] = 9.5, ["cues"] = { { 0, "Рас Ледяной Шёпот повержен." }, { 2.38, "Когда-то он был человеком из Стромгарда, а после смерти стерёг эту школу для Плети." } } } }, { ["role"] = "rare", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scholomance_kormok_pull", ["enc"] = 3055, ["track"] = { ["hash"] = "69cb3a0c", ["text"] = "На зов жаровни является Кормок — когда-то товарищ Бодли, пока не увлёкся некромантией. Мёртвые встают по его зову один за другим, и чем дольше длится бой, тем их больше.", ["duration"] = 13.8, ["cues"] = { { 0, "На зов жаровни является Кормок — когда-то товарищ Бодли, пока не увлёкся некромантией." }, { 7.11, "Мёртвые встают по его зову один за другим, и чем дольше длится бой, тем их больше." } } } }, { ["role"] = "rare", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_scholomance_kormok", ["enc"] = 3055, ["track"] = { ["hash"] = "3f26b68e", ["text"] = "Кормок повержен. Бодли получит то, за чем вас посылал, а поднятые им мертвецы больше не встанут.", ["duration"] = 8.2, ["cues"] = { { 0, "Кормок повержен." }, { 1.51, "Бодли получит то, за чем вас посылал, а поднятые им мертвецы больше не встанут." } } } }, { ["sub"] = "Зал Тайн", ["role"] = "main", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_scholomance_polkelt_intro", ["enc"] = 2808, ["pos"] = 8, ["track"] = { ["hash"] = "37c7522d", ["text"] = "Зал Тайн. Здесь хранят знания школы, и бережёт их хранитель знаний Полкелт с помощью мертвецов. По залу бродят зомби, и каждый носит в себе заразу. Когда такой мертвец лопается, хворь брызжет во все стороны.", ["duration"] = 17.7, ["cues"] = { { 0, "Зал Тайн." }, { 0.78, "Здесь хранят знания школы, и бережёт их хранитель знаний Полкелт с помощью мертвецов." }, { 8.1, "По залу бродят зомби, и каждый носит в себе заразу." }, { 12.7, "Когда такой мертвец лопается, хворь брызжет во все стороны." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scholomance_polkelt_pull", ["enc"] = 2808, ["track"] = { ["hash"] = "9be0d3c6", ["text"] = "Хранитель знаний Полкелт вступает в бой, и мертвецы зала идут ему на помощь. Один на один он с вами не останется, и горе тому, кого они окружат.", ["duration"] = 11.8, ["cues"] = { { 0, "Хранитель знаний Полкелт вступает в бой, и мертвецы зала идут ему на помощь." }, { 6.33, "Один на один он с вами не останется, и горе тому, кого они окружат." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_scholomance_polkelt", ["enc"] = 2808, ["track"] = { ["hash"] = "4cc0897a", ["text"] = "Хранитель знаний Полкелт… падает. Всё, что школа копила в этом зале, осталось без хранителя. Знания Плети больше некому беречь.", ["duration"] = 11.6, ["cues"] = { { 0, "Хранитель знаний Полкелт… падает." }, { 3.13, "Всё, что школа копила в этом зале, осталось без хранителя." }, { 8.47, "Знания Плети больше некому беречь." } } } }, { ["sub"] = "Склеп Теней", ["role"] = "main", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_scholomance_illucia_intro", ["enc"] = 2806, ["pos"] = 9, ["track"] = { ["hash"] = "45649481", ["text"] = "Склеп Теней. Здесь ждёт леди Иллюсия Барова — жена лорда Алексея и хозяйка Каэр Дарроу. Её семья продала свой дом Плети за обещание вечной жизни. Вечность досталась ей вот такая: нежитью в собственном склепе.", ["duration"] = 18.3, ["cues"] = { { 0, "Склеп Теней." }, { 1.12, "Здесь ждёт леди Иллюсия Барова — жена лорда Алексея и хозяйка Каэр Дарроу." }, { 7.84, "Её семья продала свой дом Плети за обещание вечной жизни." }, { 12.96, "Вечность досталась ей вот такая: нежитью в собственном склепе." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scholomance_illucia_pull", ["enc"] = 2806, ["track"] = { ["hash"] = "a6da2aee", ["text"] = "Леди Иллюсия Барова протягивает руку, и кто-то из вас вдруг поворачивается против своих. Её чары подчиняют разум, но морок не вечен: тот, кто поднял на вас оружие, ещё вернётся к своим.", ["duration"] = 15.1, ["cues"] = { { 0, "Леди Иллюсия Барова протягивает руку, и кто-то из вас вдруг поворачивается против своих." }, { 7.37, "Её чары подчиняют разум, но морок не вечен: тот, кто поднял на вас оружие, ещё вернётся к своим." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_scholomance_illucia", ["enc"] = 2806, ["track"] = { ["hash"] = "7371f8e9", ["text"] = "Леди Иллюсия Барова падает. Хозяйка Каэр Дарроу наконец покинула свой дом. Её замок давно стал школой, а склеп — классом для мёртвых. Теперь здесь просто тихо.", ["duration"] = 14.1, ["cues"] = { { 0, "Леди Иллюсия Барова падает." }, { 2.59, "Хозяйка Каэр Дарроу наконец покинула свой дом." }, { 6.8, "Её замок давно стал школой, а склеп — классом для мёртвых." }, { 11.89, "Теперь здесь просто тихо." } } } }, { ["sub"] = "Зал Проклятых", ["role"] = "main", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_scholomance_krastinov_intro", ["enc"] = 2802, ["pos"] = 10, ["track"] = { ["hash"] = "95d82f78", ["text"] = "Зал Проклятых. Здесь работает доктор Теолен Крастинов, которого зовут Мясником. Годами он резал и пытал живых в этих стенах, и на его счету тысячи смертей. Среди его жертв — Ева Саркофф: её останки до сих пор здесь.", ["duration"] = 18.5, ["cues"] = { { 0, "Зал Проклятых." }, { 1.25, "Здесь работает доктор Теолен Крастинов, которого зовут Мясником." }, { 6.86, "Годами он резал и пытал живых в этих стенах, и на его счету тысячи смертей." }, { 13.57, "Среди его жертв — Ева Саркофф: её останки до сих пор здесь." } } } }, { ["q"] = 5382, ["follows"] = "dm_scholomance_krastinov_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_scholomance_hook_5382", ["track"] = { ["hash"] = "fd778244", ["text"] = "Ева Саркофф просила: когда Мясник умрёт, сожгите её останки. Пусть обратятся в пепел.", ["duration"] = 7.4, ["cues"] = { { 0, "Ева Саркофф просила: когда Мясник умрёт, сожгите её останки." }, { 5.44, "Пусть обратятся в пепел." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scholomance_krastinov_pull", ["enc"] = 2802, ["track"] = { ["hash"] = "f10a36dd", ["text"] = "Крастинов, Мясник Некроситета, идёт на вас. Раненый, он звереет и рубит всё вокруг, и горе тому, у кого броня тонка, если он окажется рядом с мясником.", ["duration"] = 13.2, ["cues"] = { { 0, "Крастинов, Мясник Некроситета, идёт на вас." }, { 3.74, "Раненый, он звереет и рубит всё вокруг, и горе тому, у кого броня тонка, если он окажется рядом с мясником." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_scholomance_krastinov", ["enc"] = 2802, ["track"] = { ["hash"] = "dc34bf87", ["text"] = "Доктор Теолен Крастинов падает. Мясник Некроситета больше никого не разрежет, и кричать в этом зале больше некому. Где-то в Западных Чумных землях призрак Евы Саркофф наконец может перевести дух.", ["duration"] = 15.4, ["cues"] = { { 0, "Доктор Теолен Крастинов падает." }, { 2.55, "Мясник Некроситета больше никого не разрежет, и кричать в этом зале больше некому." }, { 9.14, "Где-то в Западных Чумных землях призрак Евы Саркофф наконец может перевести дух." } } } }, { ["sub"] = "Семейный склеп Баровых", ["role"] = "main", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_scholomance_alexei_intro", ["enc"] = 2807, ["pos"] = 11, ["track"] = { ["hash"] = "253a8848", ["text"] = "Семейный склеп Баровых. Здесь стоит лорд Алексей Баров — тот, кто отдал свой замок Культу Проклятых. Он хотел бессмертия для себя и своей семьи, и Плеть сдержала слово по-своему. Теперь он нежить, а его род служит школе, которую он сам впустил в свой дом.", ["duration"] = 21.1, ["cues"] = { { 0, "Семейный склеп Баровых." }, { 1.98, "Здесь стоит лорд Алексей Баров — тот, кто отдал свой замок Культу Проклятых." }, { 8.36, "Он хотел бессмертия для себя и своей семьи, и Плеть сдержала слово по-своему." }, { 14.89, "Теперь он нежить, а его род служит школе, которую он сам впустил в свой дом." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scholomance_alexei_pull", ["enc"] = 2807, ["track"] = { ["hash"] = "80eaf4d0", ["text"] = "Лорд Баров вступает в бой, и тени в зале сгущаются вокруг хозяина. Его Пелена Тени ложится на бойцов, и под этим проклятием любое лечение едва теплится.", ["duration"] = 13.4, ["cues"] = { { 0, "Лорд Баров вступает в бой, и тени в зале сгущаются вокруг хозяина." }, { 5.85, "Его Пелена Тени ложится на бойцов, и под этим проклятием любое лечение едва теплится." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_scholomance_alexei", ["enc"] = 2807, ["track"] = { ["hash"] = "d739488b", ["text"] = "Лорд Алексей Баров падает в склепе своих предков. Хозяин Каэр Дарроу продал дом, землю и жизни близких за обещание вечности. Вечность кончилась здесь, среди могил его рода.", ["duration"] = 15.3, ["cues"] = { { 0, "Лорд Алексей Баров падает в склепе своих предков." }, { 4.46, "Хозяин Каэр Дарроу продал дом, землю и жизни близких за обещание вечности." }, { 11.14, "Вечность кончилась здесь, среди могил его рода." } } } }, { ["sub"] = "Ведьмин зал", ["role"] = "main", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_scholomance_malicia_intro", ["enc"] = 2803, ["pos"] = 12, ["track"] = { ["hash"] = "7b098484", ["text"] = "Ведьмин зал. Урок здесь ведёт инструктор Коварнесса, наставница тёмной магии. Её ученики осваивают то, что пригодится Плети в войне с живыми.", ["duration"] = 11.6, ["cues"] = { { 0, "Ведьмин зал." }, { 1.07, "Урок здесь ведёт инструктор Коварнесса, наставница тёмной магии." }, { 6.41, "Её ученики осваивают то, что пригодится Плети в войне с живыми." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scholomance_malicia_pull", ["enc"] = 2803, ["track"] = { ["hash"] = "587257c3", ["text"] = "Коварнесса заводит заклинание. Она бьёт чарами, а не клинком, и каждое заклинание, оборванное на полуслове, приближает конец урока.", ["duration"] = 10.9, ["cues"] = { { 0, "Коварнесса заводит заклинание." }, { 2.59, "Она бьёт чарами, а не клинком, и каждое заклинание, оборванное на полуслове, приближает конец урока." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_scholomance_malicia", ["enc"] = 2803, ["track"] = { ["hash"] = "5c2334e5", ["text"] = "Инструктор Коварнесса падает. Её урок оборвался на полуслове, и никто его больше не продолжит. Одной наставницей тёмной магии в Некроситете стало меньше, а ученики так и не сдали экзамен.", ["duration"] = 14.7, ["cues"] = { { 0, "Инструктор Коварнесса падает." }, { 2.37, "Её урок оборвался на полуслове, и никто его больше не продолжит." }, { 7.54, "Одной наставницей тёмной магии в Некроситете стало меньше, а ученики так и не сдали экзамен." } } } }, { ["sub"] = "Склеп Равениана", ["role"] = "main", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_scholomance_ravenian_intro", ["enc"] = 2812, ["pos"] = 13, ["track"] = { ["hash"] = "6d943494", ["text"] = "Склеп Равениана. Здесь обитает Равениан — один из самых могучих слуг Кел'Тузада. Он всегда готов сожрать ученика, который показал слабость. Обычно в этом склепе тихо: громко тут кричат только однажды.", ["duration"] = 17.4, ["cues"] = { { 0, "Склеп Равениана." }, { 1.42, "Здесь обитает Равениан — один из самых могучих слуг Кел'Тузада." }, { 6.94, "Он всегда готов сожрать ученика, который показал слабость." }, { 12.15, "Обычно в этом склепе тихо: громко тут кричат только однажды." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scholomance_ravenian_pull", ["enc"] = 2812, ["track"] = { ["hash"] = "b30223be", ["text"] = "Равениан бросается вперёд, и его удар отшвыривает бойцов. Улетевший в незачищенный угол приведёт за собой новых мертвецов.", ["duration"] = 9.6, ["cues"] = { { 0, "Равениан бросается вперёд, и его удар отшвыривает бойцов." }, { 4.62, "Улетевший в незачищенный угол приведёт за собой новых мертвецов." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_scholomance_ravenian", ["enc"] = 2812, ["track"] = { ["hash"] = "ca0c3738", ["text"] = "Равениан падает, и склеп замирает. Ученики Некроситета больше не будут вздрагивать от его шагов. Кел'Тузад лишился одного из самых могучих своих слуг.", ["duration"] = 13.3, ["cues"] = { { 0, "Равениан падает, и склеп замирает." }, { 3.06, "Ученики Некроситета больше не будут вздрагивать от его шагов." }, { 8.61, "Кел'Тузад лишился одного из самых могучих своих слуг." } } } }, { ["sub"] = "Кабинет Директора", ["role"] = "final", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_scholomance_gandling_intro", ["enc"] = 2801, ["pos"] = 14, ["track"] = { ["hash"] = "8f97d085", ["text"] = "Кабинет Директора. Это сердце Некроситета: вокруг на двух ярусах шесть залов, и в каждом сидит наставник школы. Директор — темный магистр Гандлинг, смертный некромант. Сам он выйдет к вам, только когда падут все шестеро наставников вместе с их учениками.", ["duration"] = 21.5, ["cues"] = { { 0, "Кабинет Директора." }, { 1.63, "Это сердце Некроситета: вокруг на двух ярусах шесть залов, и в каждом сидит наставник школы." }, { 9.6, "Директор — тёмный магистр Гандлинг, смертный некромант." }, { 14.32, "Сам он выйдет к вам, только когда падут все шестеро наставников вместе с их учениками." } } } }, { ["role"] = "final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_scholomance_gandling_pull", ["enc"] = 2801, ["track"] = { ["hash"] = "3dcdc6f8", ["text"] = "Темный магистр Гандлинг выходит принять у вас экзамен. Его Портал Тьмы швыряет кого-то из вас в один из залов, к мертвецам, и назад тому придётся пробиваться в одиночку, пока остальные бьются без него.", ["duration"] = 15, ["cues"] = { { 0, "Тёмный магистр Гандлинг выходит принять у вас экзамен." }, { 4.1, "Его Портал Тьмы швыряет кого-то из вас в один из залов, к мертвецам, и назад тому придётся пробиваться в одиночку, пока остальные бьются без него." } } } }, { ["role"] = "final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_scholomance_gandling", ["enc"] = 2801, ["track"] = { ["hash"] = "292cca7c", ["text"] = "Темный магистр Гандлинг падает посреди своего кабинета. Школа некромантии осталась без директора, и её коридоры впервые за годы молчат. Но Плеть на этом не кончается, а Кел'Тузад по-прежнему служит Королю-личу. Уроки здесь кончились. Война — нет.", ["duration"] = 20.6, ["cues"] = { { 0, "Тёмный магистр Гандлинг падает посреди своего кабинета." }, { 4.74, "Школа некромантии осталась без директора, и её коридоры впервые за годы молчат." }, { 11.47, "Но Плеть на этом не кончается, а Кел'Тузад по-прежнему служит Королю-личу." }, { 17.74, "Уроки здесь кончились." }, { 19.65, "Война — нет." } } } } }, ["bosses"] = { { ["id"] = 2805, ["npcs"] = { 10506 }, ["name"] = "Kirtonos the Herald", ["required"] = nil, ["token"] = "kirtonos", ["names335"] = { "Kirtonos the Herald" } }, { ["id"] = 2811, ["npcs"] = { 11622 }, ["name"] = "Rattlegore", ["required"] = nil, ["token"] = "rattlegore", ["names335"] = { "Rattlegore" } }, { ["id"] = 2804, ["npcs"] = { 10503 }, ["name"] = "Jandice Barov", ["required"] = nil, ["token"] = "jandice", ["names335"] = { "Jandice Barov" } }, { ["id"] = 2813, ["npcs"] = { 10432 }, ["name"] = "Vectus", ["required"] = nil, ["token"] = "vectus", ["names335"] = { "Vectus" } }, { ["id"] = 2809, ["npcs"] = { 10433 }, ["name"] = "Marduk Blackpool", ["required"] = nil, ["token"] = "marduk", ["names335"] = { "Marduk Blackpool" } }, { ["id"] = 2810, ["npcs"] = { 10508 }, ["name"] = "Ras Frostwhisper", ["required"] = nil, ["token"] = "ras", ["names335"] = { "Ras Frostwhisper" } }, { ["id"] = 3055, ["npcs"] = { 16118 }, ["name"] = "kormok", ["required"] = nil, ["token"] = "kormok", ["names335"] = { "Kormok" } }, { ["id"] = 2808, ["npcs"] = { 10901 }, ["name"] = "Lorekeeper Polkelt", ["required"] = nil, ["token"] = "polkelt", ["names335"] = { "Lorekeeper Polkelt" } }, { ["id"] = 2806, ["npcs"] = { 10502 }, ["name"] = "Lady Illucia Barov", ["required"] = nil, ["token"] = "illucia", ["names335"] = { "Lady Illucia Barov" } }, { ["id"] = 2802, ["npcs"] = { 11261 }, ["name"] = "Doctor Theolen Krastinov", ["required"] = nil, ["token"] = "krastinov", ["names335"] = { "Doctor Theolen Krastinov" } }, { ["id"] = 2807, ["npcs"] = { 10504 }, ["name"] = "Lord Alexei Barov", ["required"] = nil, ["token"] = "alexei", ["names335"] = { "Lord Alexei Barov" } }, { ["id"] = 2803, ["npcs"] = { 10505 }, ["name"] = "Instructor Malicia", ["required"] = nil, ["token"] = "malicia", ["names335"] = { "Instructor Malicia" } }, { ["id"] = 2812, ["npcs"] = { 10507 }, ["name"] = "The Ravenian", ["required"] = nil, ["token"] = "ravenian", ["names335"] = { "The Ravenian" } }, { ["id"] = 2801, ["npcs"] = { 1853 }, ["name"] = "Darkmaster Gandling", ["required"] = nil, ["token"] = "gandling", ["names335"] = { "Darkmaster Gandling" } } } },
[329] = { ["key"] = "stratholme", ["order"] = { 478, 480, 479, 481, 483, 484 }, ["layout"] = "wings", ["alias"] = {  }, ["name"] = "Стратхольм", ["events"] = { { ["id"] = "dm_stratholme_prolog", ["k"] = "prolog", ["trig"] = "prolog", ["track"] = { ["hash"] = "8cf27c3a", ["text"] = "Вы в Стратхольме — когда-то жемчужине северного Лордерона. Сюда привезли зерно, отравленное чумой, и принц Артас решил, что спасти горожан уже нельзя: он вырезал город сам, а Утер Светоносный отказался идти за ним. Мёртвые не легли в могилы — теперь улицы принадлежат Плети, и правит ею барон Ривендер. Западную часть руин удерживает Алый орден: его рыцари засели в своём Бастионе и убивают всё, что не похоже на живого человека. Пожары здесь не гаснут уже много лет.", ["duration"] = 37.7, ["cues"] = { { 0, "Вы в Стратхольме — когда-то жемчужине северного Лордерона." }, { 4.68, "Сюда привезли зерно, отравленное чумой, и принц Артас решил, что спасти горожан уже нельзя: он вырезал город сам, а Утер Светоносный отказался идти за ним." }, { 17.34, "Мёртвые не легли в могилы — теперь улицы принадлежат Плети, и правит ею барон Ривендер." }, { 24.51, "Западную часть руин удерживает Алый орден: его рыцари засели в своём Бастионе и убивают всё, что не похоже на живого человека." }, { 34.76, "Пожары здесь не гаснут уже много лет." } } } }, { ["id"] = "dm_stratholme_prolog_repeat", ["k"] = "prolog", ["trig"] = "repeat", ["track"] = { ["hash"] = "adbf5a3a", ["text"] = "Снова Стратхольм. Пожары не погасли, мёртвые не легли, а Алый орден и Плеть всё так же делят город, которого больше нет.", ["duration"] = 10.7, ["cues"] = { { 0, "Снова Стратхольм." }, { 1.65, "Пожары не погасли, мёртвые не легли, а Алый орден и Плеть всё так же делят город, которого больше нет." } } } }, { ["q"] = 5282, ["prio"] = 0, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_stratholme_hook_5282", ["track"] = { ["hash"] = "d75e4248", ["text"] = "Эган дал вам свой излучатель. Призраки горожан бродят по этим улицам с той самой ночи — освободите их, им давно пора на покой.", ["duration"] = 10.2, ["cues"] = { { 0, "Эган дал вам свой излучатель." }, { 2.38, "Призраки горожан бродят по этим улицам с той самой ночи — освободите их, им давно пора на покой." } } } }, { ["q"] = 5212, ["prio"] = 1, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_stratholme_hook_5212", ["track"] = { ["hash"] = "93902fb0", ["text"] = "Бетине Биггльцинк нужны образцы плоти, тронутой чумой совсем недавно. В этом городе за ними далеко ходить не придётся.", ["duration"] = 8.9, ["cues"] = { { 0, "Бетине Биггльцинк нужны образцы плоти, тронутой чумой совсем недавно." }, { 5.36, "В этом городе за ними далеко ходить не придётся." } } } }, { ["q"] = 5243, ["prio"] = 2, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_stratholme_hook_5243", ["track"] = { ["hash"] = "fb8a559c", ["text"] = "Леонид Барталомей Чтимый ждёт святую воду для Серебряного Рассвета. Ищите её в брошенных ящиках с припасами.", ["duration"] = 9, ["cues"] = { { 0, "Леонид Барталомей Чтимый ждёт святую воду для Серебряного Рассвета." }, { 5.75, "Ищите её в брошенных ящиках с припасами." } } } }, { ["q"] = 5214, ["prio"] = 3, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_stratholme_hook_5214", ["track"] = { ["hash"] = "e504dca1", ["text"] = "Дымок ЛаРу мечтает о табаке из лавки, хозяин которой не ушёл, когда город осадила нежить. Говорят, он сторожит свой товар до сих пор.", ["duration"] = 10.4, ["cues"] = { { 0, "Дымок ЛаРу мечтает о табаке из лавки, хозяин которой не ушёл, когда город осадила нежить." }, { 7.15, "Говорят, он сторожит свой товар до сих пор." } } } }, { ["role"] = "rare", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stratholme_skul_pull", ["enc"] = 2799, ["track"] = { ["hash"] = "d4e1342a", ["text"] = "Из-за обгоревшей стены выходит Череп — скелет, которого видит далеко не каждая группа. Кости давно забыли, кем были при жизни, а заклинания — нет.", ["duration"] = 12.3, ["cues"] = { { 0, "Из-за обгоревшей стены выходит Череп — скелет, которого видит далеко не каждая группа." }, { 7.46, "Кости давно забыли, кем были при жизни, а заклинания — нет." } } } }, { ["role"] = "rare", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stratholme_skul", ["enc"] = 2799, ["track"] = { ["hash"] = "29aac74b", ["text"] = "Череп рассыпается грудой костей. Кем он был при жизни, уже не узнать. Плеть не спрашивает имён. Она просто поднимает всех, кто лёг на этих улицах.", ["duration"] = 12, ["cues"] = { { 0, "Череп рассыпается грудой костей." }, { 2.81, "Кем он был при жизни, уже не узнать." }, { 5.85, "Плеть не спрашивает имён." }, { 7.9, "Она просто поднимает всех, кто лёг на этих улицах." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stratholme_ezra_pull", ["enc"] = 2797, ["track"] = { ["hash"] = "9c482bf0", ["text"] = "Стоит тронуть табачную шкатулку, и перед вами появляется Эзра Гримм, хозяин лавки. Он поклялся, что врагу не достанется ни листочка, — и смерть не заставила его передумать.", ["duration"] = 13.5, ["cues"] = { { 0, "Стоит тронуть табачную шкатулку, и перед вами появляется Эзра Гримм, хозяин лавки." }, { 6.69, "Он поклялся, что врагу не достанется ни листочка, — и смерть не заставила его передумать." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stratholme_ezra", ["enc"] = 2797, ["track"] = { ["hash"] = "a163ffdd", ["text"] = "Эзра Гримм падает среди своего товара. Когда город осадила нежить, он не ушёл из лавки и обещал сжечь всё до последнего листа. Сжечь так и не успел. Мёртвый лавочник стерёг свой табак лучше любого замка — теперь сторожить его некому.", ["duration"] = 19.8, ["cues"] = { { 0, "Эзра Гримм падает среди своего товара." }, { 3.41, "Когда город осадила нежить, он не ушёл из лавки и обещал сжечь всё до последнего листа." }, { 10.85, "Сжечь так и не успел." }, { 12.63, "Мёртвый лавочник стерёг свой табак лучше любого замка — теперь сторожить его некому." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stratholme_postmaster_pull", ["enc"] = 2798, ["track"] = { ["hash"] = "beb00b6a", ["text"] = "Третий вскрытый ящик — и на улице появляется Почтальон Мэлоун, а с ним мёртвые разносчики. Ни мор, ни огонь, ни смерть не отменили его службы, и чужую почту он не отдаст без боя.", ["duration"] = 14.8, ["cues"] = { { 0, "Третий вскрытый ящик — и на улице появляется Почтальон Мэлоун, а с ним мёртвые разносчики." }, { 7.59, "Ни мор, ни огонь, ни смерть не отменили его службы, и чужую почту он не отдаст без боя." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stratholme_postmaster", ["enc"] = 2798, ["track"] = { ["hash"] = "5080efc4", ["text"] = "Почтальон Мэлоун падает на мостовую. Когда пришла Плеть, он не успел уйти из города — и с тех пор разносит почту по улицам, где некому её получать. Письма из этих ящиков так и не дошли до адресатов. Теперь уже не дойдут.", ["duration"] = 17.3, ["cues"] = { { 0, "Почтальон Мэлоун падает на мостовую." }, { 2.94, "Когда пришла Плеть, он не успел уйти из города — и с тех пор разносит почту по улицам, где некому её получать." }, { 11.62, "Письма из этих ящиков так и не дошли до адресатов." }, { 15.64, "Теперь уже не дойдут." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stratholme_unforgiven_pull", ["enc"] = 472, ["track"] = { ["hash"] = "3ebf1d10", ["text"] = "Посреди улицы сгущается холод, и из него выступает Непрощенный, а за ним — мстительные призраки. Что он натворил при жизни, не помнит уже никто, но прощения ему нет и после смерти, а гнев его пережил и город, и память о нём.", ["duration"] = 20.8, ["cues"] = { { 0, "Посреди улицы сгущается холод, и из него выступает Непрощенный, а за ним — мстительные призраки." }, { 9, "Что он натворил при жизни, не помнит уже никто, но прощения ему нет и после смерти, а гнев его пережил и город, и память о нём." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stratholme_unforgiven", ["enc"] = 472, ["track"] = { ["hash"] = "a2e58e11", ["text"] = "Непрощенный рассеивается, как дым над пожарищем, и улица затихает. Здесь торговали и праздновали, пока в город не привезли зерно, оказавшееся смертью. Чума и меч принца не оставили здесь живых, а мёртвые так и не нашли покоя. Их тени всё ещё бродят меж лавок.", ["duration"] = 22.9, ["cues"] = { { 0, "Непрощенный рассеивается, как дым над пожарищем, и улица затихает." }, { 5.88, "Здесь торговали и праздновали, пока в город не привезли зерно, оказавшееся смертью." }, { 13.4, "Чума и меч принца не оставили здесь живых, а мёртвые так и не нашли покоя." }, { 20.02, "Их тени всё ещё бродят меж лавок." } } } }, { ["role"] = "rare", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stratholme_forresten_pull", ["enc"] = 473, ["track"] = { ["hash"] = "2ce7e58f", ["text"] = "Сквозь гул пожара пробивается песня: Певчий Форрестен всё ещё поёт для мёртвого города. Его колыбельная чарует и усыпляет, и тот, кто дослушает её до конца, уснёт среди мертвецов.", ["duration"] = 15.9, ["cues"] = { { 0, "Сквозь гул пожара пробивается песня: Певчий Форрестен всё ещё поёт для мёртвого города." }, { 7.79, "Его колыбельная чарует и усыпляет, и тот, кто дослушает её до конца, уснёт среди мертвецов." } } } }, { ["role"] = "rare", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stratholme_forresten", ["enc"] = 473, ["track"] = { ["hash"] = "76071407", ["text"] = "Песня обрывается на полутакте, и Форрестен падает. Наверное, когда-то он пел на здешних праздниках, и весь город подпевал ему. Теперь подпевать некому. Слов его песни уже не вспомнит никто.", ["duration"] = 15.4, ["cues"] = { { 0, "Песня обрывается на полутакте, и Форрестен падает." }, { 4.16, "Наверное, когда-то он пел на здешних праздниках, и весь город подпевал ему." }, { 10.32, "Теперь подпевать некому." }, { 12.4, "Слов его песни уже не вспомнит никто." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stratholme_timmy_pull", ["enc"] = 474, ["track"] = { ["hash"] = "e6556083", ["text"] = "С воплем на площадь вылетает упырь — Тимми Беспощадный, голод на кривых ногах. Ранить его — полдела: почуяв кровь, он впадает в исступление, и удары сыплются куда чаще.", ["duration"] = 14.2, ["cues"] = { { 0, "С воплем на площадь вылетает упырь — Тимми Беспощадный, голод на кривых ногах." }, { 6.74, "Ранить его — полдела: почуяв кровь, он впадает в исступление, и удары сыплются куда чаще." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stratholme_timmy", ["enc"] = 474, ["track"] = { ["hash"] = "589439b4", ["text"] = "Тимми Беспощадный валится на брусчатку Площади рыцарей и больше не встаёт. Здесь начинаются владения Алого ордена: багровые стражи держат площадь, а упырь бродил совсем рядом и ждал, когда их станет меньше. В Стратхольме даже фанатики не могут спать спокойно.", ["duration"] = 20.4, ["cues"] = { { 0, "Тимми Беспощадный валится на брусчатку Площади рыцарей и больше не встаёт." }, { 5.87, "Здесь начинаются владения Алого ордена: багровые стражи держат площадь, а упырь бродил совсем рядом и ждал, когда их станет меньше." }, { 16.4, "В Стратхольме даже фанатики не могут спать спокойно." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stratholme_malor_pull", ["enc"] = 476, ["track"] = { ["hash"] = "8ade5be1", ["text"] = "Малор Ревностный вскидывает руку, и стрелы Тьмы веером летят в ваш строй — странное оружие для рыцаря Света. Только оборванный на замахе залп не долетит, а от грохота земли под его ударом ноги на миг перестают слушаться.", ["duration"] = 17.8, ["cues"] = { { 0, "Малор Ревностный вскидывает руку, и стрелы Тьмы веером летят в ваш строй — странное оружие для рыцаря Света." }, { 8.85, "Только оборванный на замахе залп не долетит, а от грохота земли под его ударом ноги на миг перестают слушаться." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stratholme_malor", ["enc"] = 476, ["track"] = { ["hash"] = "a1cbf34c", ["text"] = "Малор Ревностный падает в своём зале. Ревностным его прозвали в ордене, и рвения ему хватило до последнего вздоха. Он остался в руинах держать оборону — и держал её до конца. Рядом стоит его сундук: то, что Алый орден держит под замком в мёртвом городе, стоит проверить.", ["duration"] = 23, ["cues"] = { { 0, "Малор Ревностный падает в своём зале." }, { 3.24, "Ревностным его прозвали в ордене, и рвения ему хватило до последнего вздоха." }, { 9.86, "Он остался в руинах держать оборону — и держал её до конца." }, { 14.95, "Рядом стоит его сундук: то, что Алый орден держит под замком в мёртвом городе, стоит проверить." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stratholme_willey_pull", ["enc"] = 475, ["track"] = { ["hash"] = "df5b21e1", ["text"] = "Мастер-канонир Вилли рявкает команду, и на его зов один за другим выходят багровые ружейники. Сам Вилли не опаснее любого рыцаря ордена, но пока он жив, стрелки будут прибывать.", ["duration"] = 13.6, ["cues"] = { { 0, "Мастер-канонир Вилли рявкает команду, и на его зов один за другим выходят багровые ружейники." }, { 7.29, "Сам Вилли не опаснее любого рыцаря ордена, но пока он жив, стрелки будут прибывать." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stratholme_willey", ["enc"] = 475, ["track"] = { ["hash"] = "5641db09", ["text"] = "Мастер-канонир Вилли падает, и ружейники больше не придут на его зов. Порох и стволы орден копил не только против упырей. Алый орден давно считает врагом каждого, кто не носит его цветов.", ["duration"] = 14.5, ["cues"] = { { 0, "Мастер-канонир Вилли падает, и ружейники больше не придут на его зов." }, { 5.38, "Порох и стволы орден копил не только против упырей." }, { 9.45, "Алый орден давно считает врагом каждого, кто не носит его цветов." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stratholme_hammersmith_pull", ["enc"] = 2796, ["track"] = { ["hash"] = "05057018", ["text"] = "Стоило тронуть чертежи — и за них уже вступился Молотобоец из Багрового легиона. Кузнечные секреты ордена он охраняет молотом, которым привык бить по наковальне.", ["duration"] = 12.5, ["cues"] = { { 0, "Стоило тронуть чертежи — и за них уже вступился Молотобоец из Багрового легиона." }, { 6.32, "Кузнечные секреты ордена он охраняет молотом, которым привык бить по наковальне." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stratholme_hammersmith", ["enc"] = 2796, ["track"] = { ["hash"] = "8d44ae24", ["text"] = "Молотобоец из Багрового легиона затихает. Багровый легион — воины Алого ордена в Стратхольме, и сталь для них ковали здесь же. Теперь эти чертежи послужат кому-то другому. Может быть, даже тем, против кого их писали.", ["duration"] = 17.7, ["cues"] = { { 0, "Молотобоец из Багрового легиона затихает." }, { 3.43, "Багровый легион — воины Алого ордена в Стратхольме, и сталь для них ковали здесь же." }, { 10.3, "Теперь эти чертежи послужат кому-то другому." }, { 14.1, "Может быть, даже тем, против кого их писали." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stratholme_galford_pull", ["enc"] = 477, ["track"] = { ["hash"] = "4ed64482", ["text"] = "Архивариус Галфорд встречает вас пламенем. Огонь расходится кольцом вокруг него, а горящие ветра обвивают то одного, то другого из вас, и вскоре ожоги будут у каждого.", ["duration"] = 14.8, ["cues"] = { { 0, "Архивариус Галфорд встречает вас пламенем." }, { 3.78, "Огонь расходится кольцом вокруг него, а горящие ветра обвивают то одного, то другого из вас, и вскоре ожоги будут у каждого." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stratholme_galford", ["enc"] = 477, ["track"] = { ["hash"] = "1552da1f", ["text"] = "Архивариус Галфорд падает среди своих бумаг. Он отвечал за самые ценные документы ордена: приговоры, списки еретиков, донесения со всего Лордерона. Сколько имён в них вычеркнуто огнём, знал только он. И он уже ничего не скажет.", ["duration"] = 19.5, ["cues"] = { { 0, "Архивариус Галфорд падает среди своих бумаг." }, { 4, "Он отвечал за самые ценные документы ордена: приговоры, списки еретиков, донесения со всего Лордерона." }, { 12.94, "Сколько имён в них вычеркнуто огнём, знал только он." }, { 17.33, "И он уже ничего не скажет." } } } }, { ["sub"] = "Кровавый трон", ["role"] = "wing_final", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_stratholme_balnazzar_intro", ["enc"] = 478, ["pos"] = 11, ["track"] = { ["hash"] = "9bf520ac", ["text"] = "Кровавый трон. Здесь, в сердце Бастиона, Алый орден слушает своего Верховного рыцаря — Датрохана, одного из первых паладинов Серебряной Длани. Рыцари молятся на него как на святого и исполнят любой его приказ. Слишком уж хорошо он сохранился для своих лет.", ["duration"] = 21.4, ["cues"] = { { 0, "Кровавый трон." }, { 1.22, "Здесь, в сердце Бастиона, Алый орден слушает своего Верховного рыцаря — Датрохана, одного из первых паладинов Серебряной Длани." }, { 12.01, "Рыцари молятся на него как на святого и исполнят любой его приказ." }, { 17.72, "Слишком уж хорошо он сохранился для своих лет." } } } }, { ["role"] = "wing_final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stratholme_balnazzar_pull", ["enc"] = 478, ["track"] = { ["hash"] = "b6acbff7", ["text"] = "Датрохан поднимает молот и бьётся как паладин — пока маска не спадёт и перед вами не встанет повелитель ужаса Балназзар. Демон крадёт разум: подчинённый им повернёт оружие против своих, а от ментального крика остальные бросятся врассыпную.", ["duration"] = 19.6, ["cues"] = { { 0, "Датрохан поднимает молот и бьётся как паладин — пока маска не спадёт и перед вами не встанет повелитель ужаса Балназзар." }, { 10.03, "Демон крадёт разум: подчинённый им повернёт оружие против своих, а от ментального крика остальные бросятся врассыпную." } } } }, { ["role"] = "wing_final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_stratholme_balnazzar", ["enc"] = 478, ["track"] = { ["hash"] = "e77fb6e6", ["text"] = "Балназзар падает, и маска Верховного рыцаря больше никого не обманет. Алый орден годами молился на чудовище и убивал во имя Света по его приказам. Этот повелитель ужаса — брат Вариматраса, правителя Подгорода.", ["duration"] = 17.2, ["cues"] = { { 0, "Балназзар падает, и маска Верховного рыцаря больше никого не обманет." }, { 5.78, "Алый орден годами молился на чудовище и убивал во имя Света по его приказам." }, { 12.24, "Этот повелитель ужаса — брат Вариматраса, правителя Подгорода." } } } }, { ["q"] = 8968, ["follows"] = "dm_stratholme_balnazzar", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_stratholme_hook_8968_fin", ["track"] = { ["hash"] = "80618f9c", ["text"] = "Чертог Датрохана свободен. Самое время вызвать духов Джариен и Сотоса — часть амулета Лорда Вальтхалака, нужная Бодли, ушла в могилу вместе с ними.", ["duration"] = 11.8, ["cues"] = { { 0, "Чертог Датрохана свободен." }, { 2.15, "Самое время вызвать духов Джариен и Сотоса — часть амулета Лорда Вальтхалака, нужная Бодли, ушла в могилу вместе с ними." } } } }, { ["q"] = 5251, ["follows"] = "dm_stratholme_balnazzar", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_stratholme_hook_5251_fin", ["track"] = { ["hash"] = "c4688df8", ["text"] = "Герцог Николас Зверенхофф просил уничтожить архивариуса Галфорда и предать огню архивы ордена. Без пепла этих бумаг к нему лучше не возвращаться.", ["duration"] = 11.3, ["cues"] = { { 0, "Герцог Николас Зверенхофф просил уничтожить архивариуса Галфорда и предать огню архивы ордена." }, { 7.43, "Без пепла этих бумаг к нему лучше не возвращаться." } } } }, { ["q"] = 5848, ["follows"] = "dm_stratholme_balnazzar", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_stratholme_hook_5848_fin", ["track"] = { ["hash"] = "93114fef", ["text"] = "Художница Ренфри спрятала в Бастионе картину с двумя лунами. Снимите с неё лишнюю краску — и откроется её шедевр, «Символ семейной любви».", ["duration"] = 11, ["cues"] = { { 0, "Художница Ренфри спрятала в Бастионе картину с двумя лунами." }, { 4.91, "Снимите с неё лишнюю краску — и откроется её шедевр, «Символ семейной любви»." } } } }, { ["q"] = 5214, ["follows"] = "dm_stratholme_balnazzar", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_stratholme_hook_5214_fin", ["track"] = { ["hash"] = "330a2e76", ["text"] = "И не забудьте про табак для Дымка ЛаРу из лавки Эзры Гримма — старина будет счастлив.", ["duration"] = 6.8, ["cues"] = { { 0, "И не забудьте про табак для Дымка ЛаРу из лавки Эзры Гримма — старина будет счастлив." } } } }, { ["role"] = "wing_final", ["k"] = "bag", ["trig"] = "bag", ["id"] = "dm_stratholme_head", ["item"] = 13250, ["track"] = { ["hash"] = "75f7918f", ["text"] = "Голова повелителя ужаса — в вашей сумке. Без неё никто не поверит, что Верховный рыцарь был демоном. Несите её герцогу Николасу Зверенхоффу.", ["duration"] = 11.4, ["cues"] = { { 0, "Голова повелителя ужаса — в вашей сумке." }, { 3.44, "Без неё никто не поверит, что Верховный рыцарь был демоном." }, { 8.3, "Несите её герцогу Николасу Зверенхоффу." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stratholme_barthilas_pull", ["enc"] = 482, ["track"] = { ["hash"] = "4bb67244", ["text"] = "Бартилас с рёвом бросается на вас. Его кулаки раскидывают толпу, как кегли, а могучий удар отшвыривает того, кто стоит перед ним, — и горе ему, если за спиной окажется не стена, а мертвецы.", ["duration"] = 15.4, ["cues"] = { { 0, "Бартилас с рёвом бросается на вас." }, { 2.73, "Его кулаки раскидывают толпу, как кегли, а могучий удар отшвыривает того, кто стоит перед ним, — и горе ему, если за спиной окажется не стена, а мертвецы." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stratholme_barthilas", ["enc"] = 482, ["track"] = { ["hash"] = "88e169cf", ["text"] = "Мировой судья Бартилас падает, и Ключ от города теперь ваш. Когда-то он был учеником Тириона Фордринга — и свидетелем на суде, где Тириона судили за милость к пленному орку. Плеть не разбирала, кто из горожан был праведником, а кто нет. Она забрала всех.", ["duration"] = 20.3, ["cues"] = { { 0, "Мировой судья Бартилас падает, и Ключ от города теперь ваш." }, { 4.88, "Когда-то он был учеником Тириона Фордринга — и свидетелем на суде, где Тириона судили за милость к пленному орку." }, { 14.12, "Плеть не разбирала, кто из горожан был праведником, а кто нет." }, { 19, "Она забрала всех." } } } }, { ["sub"] = "Улица Испытаний", ["role"] = "main", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_stratholme_nerubenkan_intro", ["enc"] = 480, ["pos"] = 13, ["track"] = { ["hash"] = "5befb5d5", ["text"] = "Улица Испытаний. Над ней поднимаются три зиккурата Плети, и на вершине каждого мерцает кристалл. Пока кристаллы горят, путь к барону закрыт, а сторожат их Неруб'энкан, баронесса Анастари и Малекай Бледный. Над крышами кружат горгульи, по улице ходят некроманты. Один из троих — Неруб'энкан, неруб из павшего подземного царства, поднятый Плетью на службу.", ["duration"] = 29.4, ["cues"] = { { 0, "Улица Испытаний." }, { 1.44, "Над ней поднимаются три зиккурата Плети, и на вершине каждого мерцает кристалл." }, { 8.02, "Пока кристаллы горят, путь к барону закрыт, а сторожат их Неруб'энкан, баронесса Анастари и Малекай Бледный." }, { 17.11, "Над крышами кружат горгульи, по улице ходят некроманты." }, { 21.8, "Один из троих — Неруб'энкан, неруб из павшего подземного царства, поднятый Плетью на службу." } } } }, { ["q"] = 5213, ["follows"] = "dm_stratholme_nerubenkan_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_stratholme_hook_5213", ["track"] = { ["hash"] = "b9b03471", ["text"] = "Бетина Биггльцинк просила осмотреть зиккураты: всё, что вы там увидите, расскажет ей, откуда Плеть черпает силу.", ["duration"] = 9, ["cues"] = { { 0, "Бетина Биггльцинк просила осмотреть зиккураты: всё, что вы там увидите, расскажет ей, откуда Плеть черпает силу." } } } }, { ["q"] = 8945, ["follows"] = "dm_stratholme_nerubenkan_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_stratholme_hook_8945", ["track"] = { ["hash"] = "6050a2a8", ["text"] = "У барона в плену Исида Хармон, жена Антиона. Антион просил её спасти — её держат в Живодёрне.", ["duration"] = 8, ["cues"] = { { 0, "У барона в плену Исида Хармон, жена Антиона." }, { 4, "Антион просил её спасти — её держат в Живодёрне." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stratholme_nerubenkan_pull", ["enc"] = 480, ["track"] = { ["hash"] = "31b416b4", ["text"] = "Неруб'энкан выползает на гребень зиккурата, щёлкая жвалами. Из-под его лап сыплются скарабеи-нежить, а жвалы пробивают броню того, кто стоит впереди, и с каждым укусом его доспех слабеет.", ["duration"] = 14.7, ["cues"] = { { 0, "Неруб'энкан выползает на гребень зиккурата, щёлкая жвалами." }, { 4.62, "Из-под его лап сыплются скарабеи-нежить, а жвалы пробивают броню того, кто стоит впереди, и с каждым укусом его доспех слабеет." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stratholme_nerubenkan", ["enc"] = 480, ["track"] = { ["hash"] = "d07cd373", ["text"] = "Неруб'энкан затихает, поджав лапы. Его народ когда-то воевал с Королём-личом под землёй и проиграл; теперь мёртвые нерубы сторожат башни победителя. Плеть не тратит павших впустую — даже чужих. Один зиккурат лишился хранителя. Внутри ещё остались его служители.", ["duration"] = 22.5, ["cues"] = { { 0, "Неруб'энкан затихает, поджав лапы." }, { 3.04, "Его народ когда-то воевал с Королём-личом под землёй и проиграл; теперь мёртвые нерубы сторожат башни победителя." }, { 12.8, "Плеть не тратит павших впустую — даже чужих." }, { 16.71, "Один зиккурат лишился хранителя." }, { 19.59, "Внутри ещё остались его служители." } } } }, { ["role"] = "rare", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stratholme_stonespine_pull", ["enc"] = 2800, ["track"] = { ["hash"] = "d090631f", ["text"] = "С карниза срывается Каменный Гребень — горгулья, тяжёлая, как обломок стены. Встречается он не каждой группе, а когти у него острее любого клинка.", ["duration"] = 13, ["cues"] = { { 0, "С карниза срывается Каменный Гребень — горгулья, тяжёлая, как обломок стены." }, { 6.85, "Встречается он не каждой группе, а когти у него острее любого клинка." } } } }, { ["role"] = "rare", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stratholme_stonespine", ["enc"] = 2800, ["track"] = { ["hash"] = "296826a0", ["text"] = "Каменный Гребень падает на мостовую и раскалывается, будто статуя с крыши. Горгульи Плети не спят и не устают — они кружат над мёртвым городом днём и ночью, высматривая чужаков. Одним сторожем в небе меньше.", ["duration"] = 17.3, ["cues"] = { { 0, "Каменный Гребень падает на мостовую и раскалывается, будто статуя с крыши." }, { 6.32, "Горгульи Плети не спят и не устают — они кружат над мёртвым городом днём и ночью, высматривая чужаков." }, { 14.85, "Одним сторожем в небе меньше." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stratholme_swordsmith_pull", ["enc"] = 2795, ["track"] = { ["hash"] = "1fb90cb8", ["text"] = "Стоит тронуть чертежи — и за ними является Оружейник Черной Стражи. Черная Стража служит барону, и клинки для неё куют здесь, в мёртвом городе.", ["duration"] = 11.9, ["cues"] = { { 0, "Стоит тронуть чертежи — и за ними является Оружейник Чёрной Стражи." }, { 5.77, "Чёрная Стража служит барону, и клинки для неё куют здесь, в мёртвом городе." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stratholme_swordsmith", ["enc"] = 2795, ["track"] = { ["hash"] = "e906ab2d", ["text"] = "Оружейник Черной Стражи падает. Даже после смерти он помнил своё ремесло — Плеть оставляет мертвецам ровно столько памяти, сколько ей нужно. Чертежи остаются лежать в пыли. Кузнецу из мира живых они ещё пригодятся.", ["duration"] = 17.5, ["cues"] = { { 0, "Оружейник Чёрной Стражи падает." }, { 2.59, "Даже после смерти он помнил своё ремесло — Плеть оставляет мертвецам ровно столько памяти, сколько ей нужно." }, { 11.54, "Чертежи остаются лежать в пыли." }, { 14.2, "Кузнецу из мира живых они ещё пригодятся." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stratholme_anastari_pull", ["enc"] = 479, ["track"] = { ["hash"] = "3b54c754", ["text"] = "Баронесса Анастари с воплем взмывает над зиккуратом. Её проклятие сбивает удар, молчание запечатывает уста заклинателям, а хуже всего — когда банши входит в тело одного из вас: тогда бить придётся своего, пока она не выскочит наружу.", ["duration"] = 18.4, ["cues"] = { { 0, "Баронесса Анастари с воплем взмывает над зиккуратом." }, { 4.15, "Её проклятие сбивает удар, молчание запечатывает уста заклинателям, а хуже всего — когда банши входит в тело одного из вас: тогда бить придётся своего, пока она не выскочит наружу." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stratholme_anastari", ["enc"] = 479, ["track"] = { ["hash"] = "900c0922", ["text"] = "Анастари истаивает с последним стоном. Когда-то она была знатной дамой, и Плеть оставила ей титул, отняв всё остальное. Она входит в чужие тела, потому что своего у неё больше нет. Ещё один зиккурат остался без хранительницы.", ["duration"] = 18, ["cues"] = { { 0, "Анастари истаивает с последним стоном." }, { 3.12, "Когда-то она была знатной дамой, и Плеть оставила ей титул, отняв всё остальное." }, { 9.66, "Она входит в чужие тела, потому что своего у неё больше нет." }, { 14.59, "Ещё один зиккурат остался без хранительницы." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stratholme_maleki_pull", ["enc"] = 481, ["track"] = { ["hash"] = "2da84517", ["text"] = "Малекай Бледный — живой человек среди мертвецов, маг на службе Плети. Он плетёт лёд и тьму, и того, на кого падёт его взгляд, сковывает ледяная могила: пленник на несколько мгновений выпадает из боя.", ["duration"] = 17.4, ["cues"] = { { 0, "Малекай Бледный — живой человек среди мертвецов, маг на службе Плети." }, { 6.27, "Он плетёт лёд и тьму, и того, на кого падёт его взгляд, сковывает ледяная могила: пленник на несколько мгновений выпадает из боя." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stratholme_maleki", ["enc"] = 481, ["track"] = { ["hash"] = "6bcc8602", ["text"] = "Малекай Бледный падает на ступени зиккурата. Он служил Плети по своей воле, с бьющимся сердцем, — и потому его жаль меньше, чем всех мертвецов этого города. Ещё один зиккурат лишился хранителя. Если служители внутри тоже падут, кристаллы погаснут.", ["duration"] = 20.3, ["cues"] = { { 0, "Малекай Бледный падает на ступени зиккурата." }, { 3.71, "Он служил Плети по своей воле, с бьющимся сердцем, — и потому его жаль меньше, чем всех мертвецов этого города." }, { 12.91, "Ещё один зиккурат лишился хранителя." }, { 15.95, "Если служители внутри тоже падут, кристаллы погаснут." } } } }, { ["sub"] = "Площадь Живодёрни", ["role"] = "main", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_stratholme_ramstein_intro", ["enc"] = 483, ["pos"] = 18, ["track"] = { ["hash"] = "f52280dc", ["text"] = "Площадь Живодёрни. Здесь Плеть держит своих поганищ — сшитых из чужих тел великанов, которым не нужны ни сон, ни страх. Самый страшный из них — Рамштайн Ненасытный. Это он когда-то убил следопыта Натаноса Марриса, которого теперь зовут Натанос Гнилостень.", ["duration"] = 21, ["cues"] = { { 0, "Площадь Живодёрни." }, { 1.51, "Здесь Плеть держит своих поганищ — сшитых из чужих тел великанов, которым не нужны ни сон, ни страх." }, { 9.73, "Самый страшный из них — Рамштайн Ненасытный." }, { 13.42, "Это он когда-то убил следопыта Натаноса Марриса, которого теперь зовут Натанос Гнилостень." } } } }, { ["q"] = 6163, ["follows"] = "dm_stratholme_ramstein_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_stratholme_hook_6163", ["track"] = { ["hash"] = "d5e7d593", ["text"] = "Натанос Гнилостень ждёт вести о смерти этой твари. Он ждал её с того дня, как очнулся нежитью.", ["duration"] = 8.4, ["cues"] = { { 0, "Натанос Гнилостень ждёт вести о смерти этой твари." }, { 4.69, "Он ждал её с того дня, как очнулся нежитью." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stratholme_ramstein_pull", ["enc"] = 483, ["track"] = { ["hash"] = "0c7c0290", ["text"] = "Рамштайн выходит на площадь, волоча брюхо, и земля вздрагивает под его шагами. Тяжёлый удар выбивает дух из того, кто стоит перед ним, а топот сбивает с ног всех, кто слишком близко.", ["duration"] = 14.6, ["cues"] = { { 0, "Рамштайн выходит на площадь, волоча брюхо, и земля вздрагивает под его шагами." }, { 6.44, "Тяжёлый удар выбивает дух из того, кто стоит перед ним, а топот сбивает с ног всех, кто слишком близко." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_stratholme_ramstein", ["enc"] = 483, ["track"] = { ["hash"] = "6f88ddda", ["text"] = "Рамштайн падает, и площадь вздрагивает в последний раз. Поганищ собирают из тел тех, кто погиб в Чумных землях, — в этом великане могли быть и соседи Натаноса. На счету Рамштайна тысячи смертей, и теперь к ним прибавилась его собственная.", ["duration"] = 18.4, ["cues"] = { { 0, "Рамштайн падает, и площадь вздрагивает в последний раз." }, { 4.32, "Поганищ собирают из тел тех, кто погиб в Чумных землях, — в этом великане могли быть и соседи Натаноса." }, { 12.39, "На счету Рамштайна тысячи смертей, и теперь к ним прибавилась его собственная." } } } }, { ["q"] = 5463, ["follows"] = "dm_stratholme_ramstein", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_stratholme_hook_5463", ["track"] = { ["hash"] = "080688ed", ["text"] = "Леонид Барталомей рассказывал о Даре Менетила — оскверненной земле, где Рас Снегошепот принял смерть и восстал личем. Это место — в Живодёрне.", ["duration"] = 12.2, ["cues"] = { { 0, "Леонид Барталомей рассказывал о Даре Менетила — осквернённой земле, где Рас Снегошёпот принял смерть и восстал личем." }, { 10.23, "Это место — в Живодёрне." } } } }, { ["sub"] = "Живодёрня", ["role"] = "wing_final", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_stratholme_rivendare_intro", ["enc"] = 484, ["pos"] = 19, ["track"] = { ["hash"] = "0b07fa81", ["text"] = "Живодёрня. Крючья, цепи, разделочные столы — здесь Плеть кроит из мёртвых новых солдат. Среди этой бойни правит барон Ривендер, рыцарь смерти: Кел'Тузад посадил его властвовать над Стратхольмом, и барон правит городом, как мясник своей лавкой. Где-то здесь он держит пленницу — Исиду Хармон, что пошла за Серебряным Рассветом.", ["duration"] = 28, ["cues"] = { { 0, "Живодёрня." }, { 0.86, "Крючья, цепи, разделочные столы — здесь Плеть кроит из мёртвых новых солдат." }, { 7.41, "Среди этой бойни правит барон Ривендер, рыцарь смерти: Кел'Тузад посадил его властвовать над Стратхольмом, и барон правит городом, как мясник своей лавкой." }, { 21.06, "Где-то здесь он держит пленницу — Исиду Хармон, что пошла за Серебряным Рассветом." } } } }, { ["q"] = 5125, ["follows"] = "dm_stratholme_rivendare_intro", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_stratholme_hook_5125", ["track"] = { ["hash"] = "481eb696", ["text"] = "Аурий обещал встать рядом с вами против барона. И слово своё он сдержит.", ["duration"] = 6.2, ["cues"] = { { 0, "Аурий обещал встать рядом с вами против барона." }, { 4.27, "И слово своё он сдержит." } } } }, { ["role"] = "wing_final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_stratholme_rivendare_pull", ["enc"] = 484, ["track"] = { ["hash"] = "fa72a415", ["text"] = "Барон обнажает клинок и поднимает мертвецов из костяных куч. Через несколько мгновений он заключает с ними смертельный союз — пожирает своих же скелетов, чтобы залечить раны, и каждый уцелевший скелет вернёт ему силы.", ["duration"] = 17.8, ["cues"] = { { 0, "Барон обнажает клинок и поднимает мертвецов из костяных куч." }, { 4.96, "Через несколько мгновений он заключает с ними смертельный союз — пожирает своих же скелетов, чтобы залечить раны, и каждый уцелевший скелет вернёт ему силы." } } } }, { ["role"] = "wing_final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_stratholme_rivendare", ["enc"] = 484, ["track"] = { ["hash"] = "8e9904ff", ["text"] = "Барон Ривендер падает посреди своей бойни. Кел'Тузад потерял наместника в Стратхольме, а Плеть — голос, которым она отдавала приказы мёртвому городу. Пожары не погаснут, и мертвецы сами собой не лягут. Но в Чумных землях стало одним палачом меньше.", ["duration"] = 19.4, ["cues"] = { { 0, "Барон Ривендер падает посреди своей бойни." }, { 3.45, "Кел'Тузад потерял наместника в Стратхольме, а Плеть — голос, которым она отдавала приказы мёртвому городу." }, { 11.69, "Пожары не погаснут, и мертвецы сами собой не лягут." }, { 15.78, "Но в Чумных землях стало одним палачом меньше." } } } }, { ["q"] = 5263, ["follows"] = "dm_stratholme_rivendare", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_stratholme_hook_5263_fin", ["track"] = { ["hash"] = "5c5785a2", ["text"] = "Голову барона — герцогу Николасу Зверенхоффу, в Часовню Последней Надежды. Пусть видит, на что способны его орудия.", ["duration"] = 9.4, ["cues"] = { { 0, "Голову барона — герцогу Николасу Зверенхоффу, в Часовню Последней Надежды." }, { 6.22, "Пусть видит, на что способны его орудия." } } } } }, ["bosses"] = { { ["id"] = 2799, ["npcs"] = { 10393 }, ["name"] = "skul", ["required"] = nil, ["token"] = "skul", ["names335"] = { "Skul" } }, { ["id"] = 2797, ["npcs"] = { 11058 }, ["name"] = "ezra", ["required"] = nil, ["token"] = "ezra", ["names335"] = { "Fras Siabi" } }, { ["id"] = 2798, ["npcs"] = { 11143 }, ["name"] = "postmaster", ["required"] = nil, ["token"] = "postmaster", ["names335"] = { "Postmaster Malown" } }, { ["id"] = 472, ["npcs"] = { 10516 }, ["name"] = "The Unforgiven", ["required"] = nil, ["token"] = "unforgiven", ["names335"] = { "The Unforgiven" } }, { ["id"] = 473, ["npcs"] = { 10558 }, ["name"] = "Hearthsinger Forresten", ["required"] = nil, ["token"] = "forresten", ["names335"] = { "Hearthsinger Forresten" } }, { ["id"] = 474, ["npcs"] = { 10808 }, ["name"] = "Timmy the Cruel", ["required"] = nil, ["token"] = "timmy", ["names335"] = { "Timmy the Cruel" } }, { ["id"] = 476, ["npcs"] = { 11032 }, ["name"] = "Malor the Zealous", ["required"] = nil, ["token"] = "malor", ["names335"] = { "Malor the Zealous" } }, { ["id"] = 475, ["npcs"] = { 10997 }, ["name"] = "Cannon Master Willey", ["required"] = nil, ["token"] = "willey", ["names335"] = { "Cannon Master Willey" } }, { ["id"] = 2796, ["npcs"] = { 11120 }, ["name"] = "hammersmith", ["required"] = nil, ["token"] = "hammersmith", ["names335"] = { "Crimson Hammersmith" } }, { ["id"] = 477, ["npcs"] = { 10811 }, ["name"] = "Archivist Galford", ["required"] = nil, ["token"] = "galford", ["names335"] = { "Archivist Galford" } }, { ["id"] = 478, ["npcs"] = { 10813 }, ["name"] = "Balnazzar", ["required"] = nil, ["token"] = "balnazzar", ["names335"] = { "Balnazzar" } }, { ["id"] = 482, ["npcs"] = { 10435 }, ["name"] = "Magistrate Barthilas", ["required"] = nil, ["token"] = "barthilas", ["names335"] = { "Magistrate Barthilas" } }, { ["id"] = 480, ["npcs"] = { 10437 }, ["name"] = "Nerub'enkan", ["required"] = nil, ["token"] = "nerubenkan", ["names335"] = { "Nerub'enkan" } }, { ["id"] = 2800, ["npcs"] = { 10809 }, ["name"] = "stonespine", ["required"] = nil, ["token"] = "stonespine", ["names335"] = { "Stonespine" } }, { ["id"] = 2795, ["npcs"] = { 11121 }, ["name"] = "swordsmith", ["required"] = nil, ["token"] = "swordsmith", ["names335"] = { "Black Guard Swordsmith" } }, { ["id"] = 479, ["npcs"] = { 10436 }, ["name"] = "Baroness Anastari", ["required"] = nil, ["token"] = "anastari", ["names335"] = { "Baroness Anastari" } }, { ["id"] = 481, ["npcs"] = { 10438 }, ["name"] = "Maleki the Pallid", ["required"] = nil, ["token"] = "maleki", ["names335"] = { "Maleki the Pallid" } }, { ["id"] = 483, ["npcs"] = { 10439 }, ["name"] = "Ramnstein the Gorger", ["required"] = nil, ["token"] = "ramstein", ["names335"] = { "Ramstein the Gorger" } }, { ["id"] = 484, ["npcs"] = { 10440 }, ["name"] = "Baron Rivendare", ["required"] = nil, ["token"] = "rivendare", ["names335"] = { "Baron Rivendare" } } } },
[349] = { ["key"] = "maraudon", ["order"] = { 422, 424, 425, 429 }, ["layout"] = "wings", ["alias"] = {  }, ["name"] = "Мародон", ["events"] = { { ["id"] = "dm_maraudon_prolog", ["k"] = "prolog", ["trig"] = "prolog", ["track"] = { ["hash"] = "a548f05a", ["text"] = "Вы в Мародоне — в пещерах под Долиной Копий, в самом сердце Пустошей. Здесь похоронен Зейтар, первый сын Кенария. Он полюбил принцессу земли Терадрас, и от их союза родились кентавры — дикие дети, которые убили собственного отца. Кентавры чтят эти пещеры как святыню и стерегут вход, но внутри давно хозяйничают другие: сатиры, ядовитые твари и сама Терадрас. Кристаллы на стенах светятся лиловым и оранжевым, а глубже шумит вода — чистая, какой в Пустошах больше нигде нет.", ["duration"] = 39.4, ["cues"] = { { 0, "Вы в Мародоне — в пещерах под Долиной Копий, в самом сердце Пустошей." }, { 5.8, "Здесь похоронен Зейтар, первый сын Кенария." }, { 9.41, "Он полюбил принцессу земли Терадрас, и от их союза родились кентавры — дикие дети, которые убили собственного отца." }, { 19.12, "Кентавры чтят эти пещеры как святыню и стерегут вход, но внутри давно хозяйничают другие: сатиры, ядовитые твари и сама Терадрас." }, { 29.96, "Кристаллы на стенах светятся лиловым и оранжевым, а глубже шумит вода — чистая, какой в Пустошах больше нигде нет." } } } }, { ["id"] = "dm_maraudon_prolog_repeat", ["k"] = "prolog", ["trig"] = "repeat", ["track"] = { ["hash"] = "5912f89e", ["text"] = "Снова Мародон. Кристаллы светятся так же ровно, как в прошлый раз: пещерам всё равно, сколько гостей прошло мимо.", ["duration"] = 8.8, ["cues"] = { { 0, "Снова Мародон." }, { 1.21, "Кристаллы светятся так же ровно, как в прошлый раз: пещерам всё равно, сколько гостей прошло мимо." } } } }, { ["q"] = 7044, ["prio"] = 0, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_maraudon_hook_7044", ["track"] = { ["hash"] = "56d8b6e8", ["text"] = "Кавиндра просит найти две части скипетра её брата Келебраса: одну унёс сатир Злоязыкий, другую — Ноксион. Сам Келебрас бродит где-то в этих пещерах, забыв себя.", ["duration"] = 12.9, ["cues"] = { { 0, "Кавиндра просит найти две части скипетра её брата Келебраса: одну унёс сатир Злоязыкий, другую — Ноксион." }, { 8.49, "Сам Келебрас бродит где-то в этих пещерах, забыв себя." } } } }, { ["q"] = 7065, ["prio"] = 1, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_maraudon_hook_7065", ["track"] = { ["hash"] = "72b443f5", ["text"] = "Хранитель Марандис ищет того, кто одолеет принцессу Терадрас и вернёт покой останкам Зейтара. Принцесса ждёт в самой глубине.", ["duration"] = 11.4, ["cues"] = { { 0, "Хранитель Марандис ищет того, кто одолеет принцессу Терадрас и вернёт покой останкам Зейтара." }, { 8.62, "Принцесса ждёт в самой глубине." } } } }, { ["q"] = 7064, ["prio"] = 2, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_maraudon_hook_7064", ["track"] = { ["hash"] = "c2e3a0de", ["text"] = "Селендра ищет того, кто одолеет принцессу Терадрас и вернёт покой останкам Зейтара. Принцесса ждёт в самой глубине.", ["duration"] = 9.8, ["cues"] = { { 0, "Селендра ищет того, кто одолеет принцессу Терадрас и вернёт покой останкам Зейтара." }, { 7.21, "Принцесса ждёт в самой глубине." } } } }, { ["q"] = 7028, ["prio"] = 3, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_maraudon_hook_7028", ["track"] = { ["hash"] = "a681292f", ["text"] = "Ива из Пустошей хочет двадцать пять терадрических хрустальных орнаментов. Их можно добыть здесь, в Мародоне.", ["duration"] = 7.8, ["cues"] = { { 0, "Ива из Пустошей хочет двадцать пять терадрических хрустальных орнаментов." }, { 5.38, "Их можно добыть здесь, в Мародоне." } } } }, { ["q"] = 7067, ["prio"] = 4, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_maraudon_hook_7067", ["track"] = { ["hash"] = "b533ae95", ["text"] = "Кентавр-пария ждёт амулет Соединения из этих залов. Как его добыть, сказано в его инструкциях.", ["duration"] = 7.5, ["cues"] = { { 0, "Кентавр-пария ждёт амулет Соединения из этих залов." }, { 4.2, "Как его добыть, сказано в его инструкциях." } } } }, { ["sub"] = "Ядовитая низина", ["role"] = "main", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_maraudon_noxxion_pod", ["enc"] = 422, ["pos"] = 1, ["track"] = { ["hash"] = "e39aa79e", ["text"] = "Ядовитая низина — самый гнилой угол Мародона. Грибы здесь выдыхают облака спор, в слизи копошатся личинки, а лозы скручены порчей. Это владения Ноксиона — живого символа падения сатира Злоязыкого. Всё, к чему прикасается Ноксион, гниёт. Здесь лучше не дышать глубоко.", ["duration"] = 24.2, ["cues"] = { { 0, "Ядовитая низина — самый гнилой угол Мародона." }, { 4.26, "Грибы здесь выдыхают облака спор, в слизи копошатся личинки, а лозы скручены порчей." }, { 11.96, "Это владения Ноксиона — живого символа падения сатира Злоязыкого." }, { 18.02, "Всё, к чему прикасается Ноксион, гниёт." }, { 21.54, "Здесь лучше не дышать глубоко." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_maraudon_noxxion_pull", ["enc"] = 422, ["track"] = { ["hash"] = "e1803812", ["text"] = "Ноксион, сгусток яда, сотворённый сатиром Злоязыким, вздымается из жижи и бьёт снизу так, что противник взлетает в воздух. А когда ему станет туго, он распадётся на мелкие порождения, и пока они живы, самого Ноксиона не достать.", ["duration"] = 18.2, ["cues"] = { { 0, "Ноксион, сгусток яда, сотворённый сатиром Злоязыким, вздымается из жижи и бьёт снизу так, что противник взлетает в воздух." }, { 9.74, "А когда ему станет туго, он распадётся на мелкие порождения, и пока они живы, самого Ноксиона не достать." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_maraudon_noxxion_res", ["enc"] = 422, ["track"] = { ["hash"] = "a7a76080", ["text"] = "Ноксион расползается лужей и больше не собирается. Вонь понемногу слабеет, и сквозь неё впервые пробивается запах сырого камня. Злоязыкий сотворил его живым символом своего падения. Теперь от этого символа ничего не осталось.", ["duration"] = 18.7, ["cues"] = { { 0, "Ноксион расползается лужей и больше не собирается." }, { 4.23, "Вонь понемногу слабеет, и сквозь неё впервые пробивается запах сырого камня." }, { 10.57, "Злоязыкий сотворил его живым символом своего падения." }, { 15.18, "Теперь от этого символа ничего не осталось." } } } }, { ["q"] = 7044, ["follows"] = "dm_maraudon_noxxion_res", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_maraudon_noxxion_7044", ["track"] = { ["hash"] = "4e402424", ["text"] = "Если вы ищете части скипетра Келебраса, проверьте, что осталось от Ноксиона: одну из них похитил он.", ["duration"] = 8.2, ["cues"] = { { 0, "Если вы ищете части скипетра Келебраса, проверьте, что осталось от Ноксиона: одну из них похитил он." } } } }, { ["q"] = 7029, ["follows"] = "dm_maraudon_noxxion_res", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_maraudon_hook_7029", ["track"] = { ["hash"] = "a3aeff7b", ["text"] = "Варк Боевой Шрам ждёт, что вы очистите здешние растения: наполните церуленовый фиал в оранжевом пруду и полейте гнусь-лозу.", ["duration"] = 10.2, ["cues"] = { { 0, "Варк Боевой Шрам ждёт, что вы очистите здешние растения: наполните церуленовый фиал в оранжевом пруду и полейте гнусь-лозу." } } } }, { ["q"] = 7041, ["follows"] = "dm_maraudon_noxxion_res", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_maraudon_hook_7041", ["track"] = { ["hash"] = "61836a14", ["text"] = "Талендрия ждёт, что вы очистите здешние растения: наполните церуленовый фиал в оранжевом пруду и полейте гнусь-лозу.", ["duration"] = 9.3, ["cues"] = { { 0, "Талендрия ждёт, что вы очистите здешние растения: наполните церуленовый фиал в оранжевом пруду и полейте гнусь-лозу." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_maraudon_razorlash_pull", ["enc"] = 423, ["track"] = { ["hash"] = "9af7e5c3", ["text"] = "Из грибной чащи поднимается Бритвохлест — одна из лоз, которых порча Злоязыкого обратила в хищников. Он выбрасывает плети, усеянные шипами, и свистит ими, как кнутом. Он не думает и не боится — просто рвёт всё, что движется.", ["duration"] = 19, ["cues"] = { { 0, "Из грибной чащи поднимается Бритвохлест — одна из лоз, которых порча Злоязыкого обратила в хищников." }, { 8.63, "Он выбрасывает плети, усеянные шипами, и свистит ими, как кнутом." }, { 14.3, "Он не думает и не боится — просто рвёт всё, что движется." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_maraudon_razorlash_res", ["enc"] = 423, ["track"] = { ["hash"] = "b3a2c76f", ["text"] = "Бритвохлест обмякает, и его плети падают на землю, как обрубленные канаты. Когда-то это было просто растение, тянувшееся к свету. Порча Злоязыкого сделала из него хищника, и хищник проиграл. В пещере становится тихо, только с потолка капает ядовитая вода.", ["duration"] = 22.1, ["cues"] = { { 0, "Бритвохлест обмякает, и его плети падают на землю, как обрубленные канаты." }, { 6.45, "Когда-то это было просто растение, тянувшееся к свету." }, { 11.27, "Порча Злоязыкого сделала из него хищника, и хищник проиграл." }, { 16.56, "В пещере становится тихо, только с потолка капает ядовитая вода." } } } }, { ["sub"] = "Палата Злоязыкого", ["role"] = "main", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_maraudon_vyletongue_pod", ["enc"] = 424, ["pos"] = 3, ["track"] = { ["hash"] = "bd9c23b6", ["text"] = "Палата Злоязыкого, в глубине Оскверненного грота. Лиловые кристаллы растут прямо из стен, между ними вьются узловатые корни, а в тенях крадутся сатиры. Здесь хозяйничает лорд Злоязыкий — сатир, от которого по Мародону расходится порча. Его яд травит растения и сводит с ума всех, кто задерживается здесь слишком долго. Говорят, это он похитил скипетр Келебраса.", ["duration"] = 29.5, ["cues"] = { { 0, "Палата Злоязыкого, в глубине Осквернённого грота." }, { 4.03, "Лиловые кристаллы растут прямо из стен, между ними вьются узловатые корни, а в тенях крадутся сатиры." }, { 12.53, "Здесь хозяйничает лорд Злоязыкий — сатир, от которого по Мародону расходится порча." }, { 19.31, "Его яд травит растения и сводит с ума всех, кто задерживается здесь слишком долго." }, { 26.1, "Говорят, это он похитил скипетр Келебраса." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_maraudon_vyletongue_pull", ["enc"] = 424, ["track"] = { ["hash"] = "60dbd93d", ["text"] = "Лорд Злоязыкий, повелитель здешних сатиров, смеётся и швыряет под ноги дымовую шашку — миг, и он уже в другом конце зала. Из теней выходят его стражи, а сам сатир не стоит на месте: его смех звучит в одном углу, а клинок блестит в другом.", ["duration"] = 19.5, ["cues"] = { { 0, "Лорд Злоязыкий, повелитель здешних сатиров, смеётся и швыряет под ноги дымовую шашку — миг, и он уже в другом конце зала." }, { 9.95, "Из теней выходят его стражи, а сам сатир не стоит на месте: его смех звучит в одном углу, а клинок блестит в другом." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_maraudon_vyletongue_res", ["enc"] = 424, ["track"] = { ["hash"] = "53aa01cd", ["text"] = "Лорд Злоязыкий падает, и лиловый свет в палате тускнеет. Сатиры — бывшие высокорожденные, продавшие себя Легиону десять тысяч лет назад, — несут порчу везде, где ступают. Этот выбрал для своей порчи святое место кентавров. Грот ещё долго будет отмываться от его яда.", ["duration"] = 22.2, ["cues"] = { { 0, "Лорд Злоязыкий падает, и лиловый свет в палате тускнеет." }, { 4.69, "Сатиры — бывшие высокорождённые, продавшие себя Легиону десять тысяч лет назад, — несут порчу везде, где ступают." }, { 14.22, "Этот выбрал для своей порчи святое место кентавров." }, { 18.69, "Грот ещё долго будет отмываться от его яда." } } } }, { ["q"] = 7044, ["follows"] = "dm_maraudon_vyletongue_res", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_maraudon_vyletongue_7044", ["track"] = { ["hash"] = "018d0ead", ["text"] = "Если вы ищете скипетр Келебраса, одна из его частей была у Злоязыкого.", ["duration"] = 6.2, ["cues"] = { { 0, "Если вы ищете скипетр Келебраса, одна из его частей была у Злоязыкого." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_maraudon_gizlock_pull", ["enc"] = 427, ["track"] = { ["hash"] = "e12689db", ["text"] = "Ремонтник Гизлок, гоблин, невесть как забравшийся в эти пещеры, вскидывает драконье ружьё, и из ствола вырывается струя огня. Ружьё бьёт вперёд широким конусом, так что тем, кто стоит перед ним кучей, достанется всем сразу.", ["duration"] = 17.1, ["cues"] = { { 0, "Ремонтник Гизлок, гоблин, невесть как забравшийся в эти пещеры, вскидывает драконье ружьё, и из ствола вырывается струя огня." }, { 9.84, "Ружьё бьёт вперёд широким конусом, так что тем, кто стоит перед ним кучей, достанется всем сразу." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_maraudon_gizlock_res", ["enc"] = 427, ["track"] = { ["hash"] = "6be6c8d5", ["text"] = "Гизлок валится рядом со своими железками, и что-то в них ещё долго щёлкает и шипит. Что гоблин искал в Мародоне, теперь не узнать, но здешние кристаллы манят многих. Его машины ненадолго переживут хозяина.", ["duration"] = 16.6, ["cues"] = { { 0, "Гизлок валится рядом со своими железками, и что-то в них ещё долго щёлкает и шипит." }, { 6.74, "Что гоблин искал в Мародоне, теперь не узнать, но здешние кристаллы манят многих." }, { 13.41, "Его машины ненадолго переживут хозяина." } } } }, { ["sub"] = "Ядопады", ["role"] = "wing_final", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_maraudon_celebras_pod", ["enc"] = 425, ["pos"] = 5, ["track"] = { ["hash"] = "0b002793", ["text"] = "Ядопады. Вода здесь срывается со скал мутной зелёной струёй, и даже брызги жгут кожу. Где-то у водопада бродит Келебрас — он пришёл в Мародон, чтобы успокоить дух своего дяди Зейтара, а пещеры сломали его самого. Злоязыкий отравил его разум и отнял скипетр. Келебрас больше не помнит, кем был, и встречает гостей как врагов.", ["duration"] = 27.4, ["cues"] = { { 0, "Ядопады." }, { 0.77, "Вода здесь срывается со скал мутной зелёной струёй, и даже брызги жгут кожу." }, { 7.15, "Где-то у водопада бродит Келебрас — он пришёл в Мародон, чтобы успокоить дух своего дяди Зейтара, а пещеры сломали его самого." }, { 17.99, "Злоязыкий отравил его разум и отнял скипетр." }, { 21.91, "Келебрас больше не помнит, кем был, и встречает гостей как врагов." } } } }, { ["role"] = "wing_final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_maraudon_celebras_pull", ["enc"] = 425, ["track"] = { ["hash"] = "d175b924", ["text"] = "Келебрас Проклятый вскидывает руки, и пещера отвечает ему: из земли лезут оскверненные силы природы, а корни обвивают ноги. Его гнев бьёт больно, и каждое заклинание, что он успеет договорить, отзывается болью.", ["duration"] = 17.8, ["cues"] = { { 0, "Келебрас Проклятый вскидывает руки, и пещера отвечает ему: из земли лезут осквернённые силы природы, а корни обвивают ноги." }, { 10.66, "Его гнев бьёт больно, и каждое заклинание, что он успеет договорить, отзывается болью." } } } }, { ["role"] = "wing_final", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_maraudon_celebras_res", ["enc"] = 425, ["track"] = { ["hash"] = "3bacf094", ["text"] = "Келебрас опускается на колени, и проклятие отпускает его. Взгляд снова ясен, и на месте проклятого стоит тот, кто вспомнил, кем был. Порча Злоязыкого не всесильна: иногда достаточно победить, чтобы вернуть пленника самому себе. Ядопады шумят всё так же, но вода в них будто становится светлее.", ["duration"] = 24, ["cues"] = { { 0, "Келебрас опускается на колени, и проклятие отпускает его." }, { 4.79, "Взгляд снова ясен, и на месте проклятого стоит тот, кто вспомнил, кем был." }, { 10.84, "Порча Злоязыкого не всесильна: иногда достаточно победить, чтобы вернуть пленника самому себе." }, { 18.77, "Ядопады шумят всё так же, но вода в них будто становится светлее." } } } }, { ["q"] = 7046, ["follows"] = "dm_maraudon_celebras_res", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_maraudon_hook_7046", ["track"] = { ["hash"] = "ed46e131", ["text"] = "Если обе части скипетра при вас, Селебрас Искупленный поможет соединить их. Идите за ним и делайте, что он скажет.", ["duration"] = 9.5, ["cues"] = { { 0, "Если обе части скипетра при вас, Селебрас Искупленный поможет соединить их." }, { 6.45, "Идите за ним и делайте, что он скажет." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_maraudon_landslide_pull", ["enc"] = 426, ["track"] = { ["hash"] = "f094150e", ["text"] = "Обвал, горный великан из глубин Мародона, поднимается во весь рост, и с его плеч сыплются камни. Удар отбрасывает того, кто стоит перед ним, топот сбивает с ног всех вокруг, а время от времени великан зовёт осколыши — оживших каменных малышей.", ["duration"] = 20.6, ["cues"] = { { 0, "Обвал, горный великан из глубин Мародона, поднимается во весь рост, и с его плеч сыплются камни." }, { 8.19, "Удар отбрасывает того, кто стоит перед ним, топот сбивает с ног всех вокруг, а время от времени великан зовёт осколыши — оживших каменных малышей." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_maraudon_landslide_res", ["enc"] = 426, ["track"] = { ["hash"] = "bbdade2f", ["text"] = "Обвал оседает грудой камня, и водопады снова слышны громче его шагов. Каменные осколыши вокруг рассыпаются в обычный щебень. Здесь, в глубине, живая сама земля, и одна её частица наконец затихла.", ["duration"] = 17.8, ["cues"] = { { 0, "Обвал оседает грудой камня, и водопады снова слышны громче его шагов." }, { 6.55, "Каменные осколыши вокруг рассыпаются в обычный щебень." }, { 11.54, "Здесь, в глубине, живая сама земля, и одна её частица наконец затихла." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_maraudon_rotgrip_pull", ["enc"] = 428, ["track"] = { ["hash"] = "ccb6a218", ["text"] = "Из воды поднимается Гнилопасть — огромный кроколиск здешних заводей. Его смертельный укус рвёт так глубоко, что рана долго не затянется, а сам зверь каждым таким укусом залечивает свои раны.", ["duration"] = 16.1, ["cues"] = { { 0, "Из воды поднимается Гнилопасть — огромный кроколиск здешних заводей." }, { 5.85, "Его смертельный укус рвёт так глубоко, что рана долго не затянется, а сам зверь каждым таким укусом залечивает свои раны." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_maraudon_rotgrip_res", ["enc"] = 428, ["track"] = { ["hash"] = "dae0d27f", ["text"] = "Гнилопасть затихает на мелководье, и вода вокруг медленно успокаивается. Он не служил ни сатиру, ни принцессе — просто жил в заводи под Могилой Зейтара и ел всех, кто подходил к берегу. Даже в самых чистых водах Мародона есть свои хищники. Этим берегам станет чуть спокойнее.", ["duration"] = 23.3, ["cues"] = { { 0, "Гнилопасть затихает на мелководье, и вода вокруг медленно успокаивается." }, { 6.19, "Он не служил ни сатиру, ни принцессе — просто жил в заводи под Могилой Зейтара и ел всех, кто подходил к берегу." }, { 15.62, "Даже в самых чистых водах Мародона есть свои хищники." }, { 20.34, "Этим берегам станет чуть спокойнее." } } } }, { ["sub"] = "Могила Зейтара", ["role"] = "final", ["k"] = "pod", ["trig"] = "sub", ["id"] = "dm_maraudon_theradras_pod", ["enc"] = 429, ["pos"] = 8, ["track"] = { ["hash"] = "2466a32b", ["text"] = "Могила Зейтара. После ядовитых пещер здесь словно другой мир: чистая вода срывается со скал, вокруг зелень, а внизу, в заводи, бродят гидры. Здесь покоятся останки Зейтара, и над ними властвует та, кого он когда-то любил, — принцесса Терадрас. Она — сама земля, живой камень, и эти пещеры повинуются ей. Кентавры, их общие дети, убили Зейтара, а его останки остались во власти Терадрас.", ["duration"] = 35.8, ["cues"] = { { 0, "Могила Зейтара." }, { 1.5, "После ядовитых пещер здесь словно другой мир: чистая вода срывается со скал, вокруг зелень, а внизу, в заводи, бродят гидры." }, { 13.09, "Здесь покоятся останки Зейтара, и над ними властвует та, кого он когда-то любил, — принцесса Терадрас." }, { 22.5, "Она — сама земля, живой камень, и эти пещеры повинуются ей." }, { 28.17, "Кентавры, их общие дети, убили Зейтара, а его останки остались во власти Терадрас." } } } }, { ["q"] = 93404, ["follows"] = "dm_maraudon_theradras_pod", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_maraudon_hook_93404", ["track"] = { ["hash"] = "e0d46d39", ["text"] = "Вещедрев просит флакон воды из Поющих водопадов — чистейшей воды, которая погасит его вечный огонь.", ["duration"] = 8.6, ["cues"] = { { 0, "Вещедрев просит флакон воды из Поющих водопадов — чистейшей воды, которая погасит его вечный огонь." } } } }, { ["role"] = "final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_maraudon_theradras_pull", ["enc"] = 429, ["track"] = { ["hash"] = "569f0842", ["text"] = "Терадрас, принцесса земли и мать кентавров, поднимается над землёй, и пещера отзывается гулом. Её взгляд гонит прочь в ужасе, валуны летят в тех, кто держится поодаль, а когда под ногами вздымается пылевое поле, горе тому, кто в нём задержится.", ["duration"] = 20.2, ["cues"] = { { 0, "Терадрас, принцесса земли и мать кентавров, поднимается над землёй, и пещера отзывается гулом." }, { 7.84, "Её взгляд гонит прочь в ужасе, валуны летят в тех, кто держится поодаль, а когда под ногами вздымается пылевое поле, горе тому, кто в нём задержится." } } } }, { ["role"] = "final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_maraudon_theradras_fin", ["enc"] = 429, ["track"] = { ["hash"] = "dfedb06d", ["text"] = "Принцесса Терадрас падает, и камень вокруг затихает впервые за тысячи лет. Над могилой поднимается призрачный свет — дух Зейтара наконец свободен. Кентавры наверху так и будут воевать друг с другом, но их отца больше никто не держит в плену. Мародон снова становится тем, чем был для Зейтара, — местом, полным жизни.", ["duration"] = 26, ["cues"] = { { 0, "Принцесса Терадрас падает, и камень вокруг затихает впервые за тысячи лет." }, { 6.24, "Над могилой поднимается призрачный свет — дух Зейтара наконец свободен." }, { 12.1, "Кентавры наверху так и будут воевать друг с другом, но их отца больше никто не держит в плену." }, { 19.99, "Мародон снова становится тем, чем был для Зейтара, — местом, полным жизни." } } } }, { ["q"] = 7065, ["follows"] = "dm_maraudon_theradras_fin", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_maraudon_fin_7065", ["track"] = { ["hash"] = "b2613448", ["text"] = "Поговорите с духом Зейтара, а потом возвращайтесь к Хранителю Марандису. Пустоши давно ждали этой вести.", ["duration"] = 8.6, ["cues"] = { { 0, "Поговорите с духом Зейтара, а потом возвращайтесь к Хранителю Марандису." }, { 6.01, "Пустоши давно ждали этой вести." } } } }, { ["q"] = 7064, ["follows"] = "dm_maraudon_theradras_fin", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_maraudon_fin_7064", ["track"] = { ["hash"] = "e269b198", ["text"] = "Поговорите с духом Зейтара, а потом возвращайтесь к Селендре. Пустоши давно ждали этой вести.", ["duration"] = 7.8, ["cues"] = { { 0, "Поговорите с духом Зейтара, а потом возвращайтесь к Селендре." }, { 5.13, "Пустоши давно ждали этой вести." } } } }, { ["q"] = 96776, ["follows"] = "dm_maraudon_theradras_fin", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_maraudon_hook_96776", ["track"] = { ["hash"] = "3c162041", ["text"] = "Если правое око Ан'ше ещё не у вас, ищите палату белых кристаллов под охраной великанов — она где-то за Поющими водопадами. Его ждут под открытым небом Мулгора.", ["duration"] = 13, ["cues"] = { { 0, "Если правое око Ан'ше ещё не у вас, ищите палату белых кристаллов под охраной великанов — она где-то за Поющими водопадами." }, { 10.05, "Его ждут под открытым небом Мулгора." } } } } }, ["bosses"] = { { ["id"] = 422, ["npcs"] = { 13282 }, ["name"] = "Noxxion", ["required"] = nil, ["token"] = "noxxion", ["names335"] = { "Noxxion" } }, { ["id"] = 423, ["npcs"] = { 12258 }, ["name"] = "Razorlash", ["required"] = nil, ["token"] = "razorlash", ["names335"] = { "Razorlash" } }, { ["id"] = 424, ["npcs"] = { 12236 }, ["name"] = "Lord Vyletongue", ["required"] = nil, ["token"] = "vyletongue", ["names335"] = { "Lord Vyletongue" } }, { ["id"] = 427, ["npcs"] = { 13601 }, ["name"] = "Tinkerer Gizlock", ["required"] = nil, ["token"] = "gizlock", ["names335"] = { "Tinkerer Gizlock" } }, { ["id"] = 425, ["npcs"] = { 12225 }, ["name"] = "Celebras the Cursed", ["required"] = nil, ["token"] = "celebras", ["names335"] = { "Celebras the Cursed" } }, { ["id"] = 426, ["npcs"] = { 12203 }, ["name"] = "Landslide", ["required"] = nil, ["token"] = "landslide", ["names335"] = { "Landslide" } }, { ["id"] = 428, ["npcs"] = { 13596 }, ["name"] = "Rotgrip", ["required"] = nil, ["token"] = "rotgrip", ["names335"] = { "Rotgrip" } }, { ["id"] = 429, ["npcs"] = { 12201 }, ["name"] = "Princess Theradras", ["required"] = nil, ["token"] = "theradras", ["names335"] = { "Princess Theradras" } } } },
[389] = { ["key"] = "ragefire", ["order"] = { 2735 }, ["layout"] = "linear_with_side", ["alias"] = {  }, ["name"] = "Огненная пропасть", ["events"] = { { ["id"] = "dm_ragefire_prolog", ["k"] = "prolog", ["trig"] = "prolog", ["track"] = { ["hash"] = "cacf133d", ["text"] = "Вы в Огненной пропасти — в лавовых пещерах прямо под Оргриммаром. Город наверху стоит на живом огне, и не всё, что жило в этих глубинах, ушло. Из туннелей лезут трогги, а в дальних пещерах окопались культисты Огненного Клинка — орки, которые снова тянутся к демонам, от которых Тралл когда-то увёл свой народ. Говорят, за культом стоит Совет Теней. Орда хочет знать, кто ещё в её столице служит Пылающему Легиону.", ["duration"] = 33.6, ["cues"] = { { 0, "Вы в Огненной пропасти — в лавовых пещерах прямо под Оргриммаром." }, { 5.32, "Город наверху стоит на живом огне, и не всё, что жило в этих глубинах, ушло." }, { 11.67, "Из туннелей лезут трогги, а в дальних пещерах окопались культисты Огненного Клинка — орки, которые снова тянутся к демонам, от которых Тралл когда-то увёл свой народ." }, { 25.26, "Говорят, за культом стоит Совет Теней." }, { 28.51, "Орда хочет знать, кто ещё в её столице служит Пылающему Легиону." } } } }, { ["id"] = "dm_ragefire_prolog_repeat", ["k"] = "prolog", ["trig"] = "repeat", ["track"] = { ["hash"] = "3ee15ae0", ["text"] = "Снова Огненная пропасть. Жар всё тот же, а культ, похоже, уже нашёл новых учеников.", ["duration"] = 7.4, ["cues"] = { { 0, "Снова Огненная пропасть." }, { 2.31, "Жар всё тот же, а культ, похоже, уже нашёл новых учеников." } } } }, { ["q"] = 5722, ["prio"] = 0, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_ragefire_hook_5722", ["track"] = { ["hash"] = "b49ed3ca", ["text"] = "Магата Зловещий Тотем хочет знать, что нашёл здесь её слуга Маур: он спустился договориться с троггами и не выбрался. Найдите его тело — и то, что он так и не донёс.", ["duration"] = 13.2, ["cues"] = { { 0, "Магата Зловещий Тотем хочет знать, что нашёл здесь её слуга Маур: он спустился договориться с троггами и не выбрался." }, { 9.55, "Найдите его тело — и то, что он так и не донёс." } } } }, { ["q"] = 5723, ["prio"] = 1, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_ragefire_hook_5723", ["track"] = { ["hash"] = "ff2e612b", ["text"] = "Рахауро просит проучить троггов за убитых переговорщиков Магаты: восемь троггов и восемь шаманов. Здесь их хватит с избытком.", ["duration"] = 9.9, ["cues"] = { { 0, "Рахауро просит проучить троггов за убитых переговорщиков Магаты: восемь троггов и восемь шаманов." }, { 7.9, "Здесь их хватит с избытком." } } } }, { ["q"] = 5725, ["prio"] = 2, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_ragefire_hook_5725", ["track"] = { ["hash"] = "47def24b", ["text"] = "Тёмная Госпожа желает две книги Огненного Клинка — «Заклинания Тьмы» и «Заклятия Пустоты». Вариматрас ждёт их в Подгороде.", ["duration"] = 10.3, ["cues"] = { { 0, "Тёмная Госпожа желает две книги Огненного Клинка — «Заклинания Тьмы» и «Заклятия Пустоты»." }, { 7.8, "Вариматрас ждёт их в Подгороде." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_ragefire_oggleflint_pull", ["enc"] = 2732, ["track"] = { ["hash"] = "72e0aa06", ["text"] = "Вожак троггов Огглфлинт рычит и раскручивает дубину: эти пещеры он считает своими, а вас — добычей, которая сама пришла к нему в руки.", ["duration"] = 12.2, ["cues"] = { { 0, "Вожак троггов Огглфлинт рычит и раскручивает дубину: эти пещеры он считает своими, а вас — добычей, которая сама пришла к нему в руки." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_ragefire_oggleflint", ["enc"] = 2732, ["track"] = { ["hash"] = "c0522e5b", ["text"] = "Огглфлинт падает, и трогги вокруг притихают. Трогги — не армия и не культ, просто голодное племя из земных недр. Почему они вдруг полезли из лавовых туннелей наверх, к Оргриммару, не знает никто. Но Магата уже назвала их врагами Орды.", ["duration"] = 19.8, ["cues"] = { { 0, "Огглфлинт падает, и трогги вокруг притихают." }, { 3.83, "Трогги — не армия и не культ, просто голодное племя из земных недр." }, { 9.5, "Почему они вдруг полезли из лавовых туннелей наверх, к Оргриммару, не знает никто." }, { 16.55, "Но Магата уже назвала их врагами Орды." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_ragefire_taragaman_pull", ["enc"] = 2733, ["track"] = { ["hash"] = "036c185a", ["text"] = "Тарагаман Ненасытный, страж Скверны, которого Огненный Клинок почитает как вожака, ревёт, и пламя вокруг взмывает выше. Кто стоит близко — берегитесь: удары его тяжелы, а жар его тела опаляет всех рядом.", ["duration"] = 18.2, ["cues"] = { { 0, "Тарагаман Ненасытный, страж Скверны, которого Огненный Клинок почитает как вожака, ревёт, и пламя вокруг взмывает выше." }, { 10.75, "Кто стоит близко — берегитесь: удары его тяжелы, а жар его тела опаляет всех рядом." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_ragefire_taragaman", ["enc"] = 2733, ["track"] = { ["hash"] = "394017ff", ["text"] = "Тарагаман падает, и пещера на миг стихает. Демон в сердце Оргриммара — не случайность: кто-то открыл ему дорогу и держал его здесь. Тралл увёл орков от демонов. Но не все орки пошли за Траллом.", ["duration"] = 17.4, ["cues"] = { { 0, "Тарагаман падает, и пещера на миг стихает." }, { 3.88, "Демон в сердце Оргриммара — не случайность: кто-то открыл ему дорогу и держал его здесь." }, { 12.07, "Тралл увёл орков от демонов." }, { 14.63, "Но не все орки пошли за Траллом." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_ragefire_jergosh_pull", ["enc"] = 2734, ["track"] = { ["hash"] = "a108d8bb", ["text"] = "Жергош, чернокнижник Огненного Клинка, поднимает посох и шепчет на демоническом. Его проклятие высасывает силу из рук, а огонь, которым он метит врагов, сам собой не гаснет — тлеет на коже, пока чьи-то чары его не погасят.", ["duration"] = 17.8, ["cues"] = { { 0, "Жергош, чернокнижник Огненного Клинка, поднимает посох и шепчет на демоническом." }, { 6.46, "Его проклятие высасывает силу из рук, а огонь, которым он метит врагов, сам собой не гаснет — тлеет на коже, пока чьи-то чары его не погасят." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_ragefire_jergosh", ["enc"] = 2734, ["track"] = { ["hash"] = "e70d4937", ["text"] = "Жергош Призыватель Духов затихает, и шёпот на демоническом обрывается. Огненный Клинок — секта Совета Теней, а Совет Теней не умер вместе с Гул'даном. Он просто ушёл под землю и ждал, когда орки снова заскучают по силе Скверны. Сегодня у него стало одним голосом меньше.", ["duration"] = 23, ["cues"] = { { 0, "Жергош Призыватель Духов затихает, и шёпот на демоническом обрывается." }, { 5.91, "Огненный Клинок — секта Совета Теней, а Совет Теней не умер вместе с Гул'даном." }, { 12.83, "Он просто ушёл под землю и ждал, когда орки снова заскучают по силе Скверны." }, { 19.35, "Сегодня у него стало одним голосом меньше." } } } }, { ["role"] = "final", ["k"] = "pod", ["trig"] = "after", ["id"] = "dm_ragefire_bazzalan_intro", ["enc"] = 2735, ["pos"] = 4, ["track"] = { ["hash"] = "e09124c0", ["text"] = "Последним ждёт Баззалан — сатир, один из вожаков Огненного Клинка. Сатиры — бывшие высокорожденные, продавшие себя Легиону десять тысяч лет назад. Что сатир делает под столицей Орды и почему орки идут за ним, — вопрос, на который Тралл очень хочет услышать ответ.", ["duration"] = 21.4, ["cues"] = { { 0, "Последним ждёт Баззалан — сатир, один из вожаков Огненного Клинка." }, { 5.45, "Сатиры — бывшие высокорождённые, продавшие себя Легиону десять тысяч лет назад." }, { 11.94, "Что сатир делает под столицей Орды и почему орки идут за ним, — вопрос, на который Тралл очень хочет услышать ответ." } } } }, { ["role"] = "final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_ragefire_bazzalan_pull", ["enc"] = 2735, ["track"] = { ["hash"] = "88a1fa92", ["text"] = "Баззалан скалится и выхватывает клинки, смазанные ядом. Сатиры дерутся грязно: кого он заденет, тому яд в крови не даст покоя, пока его не выведут.", ["duration"] = 12.4, ["cues"] = { { 0, "Баззалан скалится и выхватывает клинки, смазанные ядом." }, { 4.72, "Сатиры дерутся грязно: кого он заденет, тому яд в крови не даст покоя, пока его не выведут." } } } }, { ["role"] = "final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_ragefire_bazzalan", ["enc"] = 2735, ["track"] = { ["hash"] = "dfd6014e", ["text"] = "Баззалан падает, и копыта сатира в последний раз скребут по камню. Огненный Клинок обезглавлен, пещеры под Оргриммаром затихают. Но культ не рождается сам по себе. Кто-то наверху, в городе, давал им приют, золото и новых учеников. Тралл узнает кто.", ["duration"] = 21.8, ["cues"] = { { 0, "Баззалан падает, и копыта сатира в последний раз скребут по камню." }, { 5.96, "Огненный Клинок обезглавлен, пещеры под Оргриммаром затихают." }, { 11.44, "Но культ не рождается сам по себе." }, { 14.43, "Кто-то наверху, в городе, давал им приют, золото и новых учеников." }, { 20.47, "Тралл узнает кто." } } } }, { ["q"] = 5728, ["follows"] = "dm_ragefire_bazzalan", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_ragefire_fin_5728", ["track"] = { ["hash"] = "355118ae", ["text"] = "Тралл ждёт в Оргриммаре вестей о Баззалане и Жергоше. И ни слова Нииру.", ["duration"] = 5.8, ["cues"] = { { 0, "Тралл ждёт в Оргриммаре вестей о Баззалане и Жергоше." }, { 4.46, "И ни слова Нииру." } } } }, { ["q"] = 5761, ["follows"] = "dm_ragefire_bazzalan", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_ragefire_fin_5761", ["track"] = { ["hash"] = "43b629da", ["text"] = "Нииру Огненный Клинок ждёт в Оргриммаре сердце Тарагамана Ненасытного. Странно, что чернокнижник так желает смерти демону, не правда ли?", ["duration"] = 11.6, ["cues"] = { { 0, "Нииру Огненный Клинок ждёт в Оргриммаре сердце Тарагамана Ненасытного." }, { 6.11, "Странно, что чернокнижник так желает смерти демону, не правда ли?" } } } } }, ["bosses"] = { { ["id"] = 2732, ["npcs"] = { 11517 }, ["name"] = "Oggleflint", ["required"] = nil, ["token"] = "oggleflint", ["names335"] = { "Oggleflint" } }, { ["id"] = 2733, ["npcs"] = { 11520 }, ["name"] = "Taragaman the Hungerer", ["required"] = nil, ["token"] = "taragaman", ["names335"] = { "Taragaman the Hungerer" } }, { ["id"] = 2734, ["npcs"] = { 11518 }, ["name"] = "Жергош Призыватель Духов", ["required"] = nil, ["token"] = "jergosh", ["names335"] = { "Jergosh the Invoker" } }, { ["id"] = 2735, ["npcs"] = { 11519 }, ["name"] = "Bazzalan", ["required"] = nil, ["token"] = "bazzalan", ["names335"] = { "Bazzalan" } } } },
[429] = { ["key"] = "dire_maul", ["order"] = { 343, 346, 361, 368 }, ["layout"] = "wings", ["alias"] = {  }, ["name"] = "Забытый Город", ["events"] = { { ["id"] = "dm_dire_maul_prolog", ["k"] = "prolog", ["trig"] = "prolog", ["track"] = { ["hash"] = "b81fa669", ["text"] = "Вы в Забытом Городе. Когда-то он звался Эльдре'Талас: здесь высокорожденные королевы Азшары хранили самые ценные тайны магии. Раскол мира пощадил его стены, но не его жителей — уцелевшие маги заперлись в сердце города, а руины поделили между собой чужаки. На западе бродят призраки высокорожденных, восток захватили сатиры, а север давно стал вотчиной огров Гордока. Камни здесь до сих пор держатся на древней магии — и всё ещё помнят, кому служили.", ["duration"] = 38.4, ["cues"] = { { 0, "Вы в Забытом Городе." }, { 1.78, "Когда-то он звался Эльдре'Талас: здесь высокорождённые королевы Азшары хранили самые ценные тайны магии." }, { 10.71, "Раскол мира пощадил его стены, но не его жителей — уцелевшие маги заперлись в сердце города, а руины поделили между собой чужаки." }, { 22.11, "На западе бродят призраки высокорождённых, восток захватили сатиры, а север давно стал вотчиной огров Гордока." }, { 31.58, "Камни здесь до сих пор держатся на древней магии — и всё ещё помнят, кому служили." } } } }, { ["id"] = "dm_dire_maul_prolog_repeat", ["k"] = "prolog", ["trig"] = "repeat", ["track"] = { ["hash"] = "7564922c", ["text"] = "Снова Забытый Город. Огры, как водится, успели выбрать себе нового короля, а призраки так и не нашли покоя. Три крыла ждут, как и прежде: восток, запад и север.", ["duration"] = 14.6, ["cues"] = { { 0, "Снова Забытый Город." }, { 1.97, "Огры, как водится, успели выбрать себе нового короля, а призраки так и не нашли покоя." }, { 9.95, "Три крыла ждут, как и прежде: восток, запад и север." } } } }, { ["q"] = 7441, ["prio"] = 0, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_dire_maul_hook_7441", ["track"] = { ["hash"] = "0fe911b0", ["text"] = "Старейший Аж'Тордин просил вернуть книгу заклинаний, которую стащил бес Пузиллин. Бес прячется в Квартале Криводревов, и поймать его непросто: он очень любит, когда за ним гоняются.", ["duration"] = 14.3, ["cues"] = { { 0, "Старейший Аж'Тордин просил вернуть книгу заклинаний, которую стащил бес Пузиллин." }, { 6.55, "Бес прячется в Квартале Криводревов, и поймать его непросто: он очень любит, когда за ним гоняются." } } } }, { ["q"] = 7488, ["prio"] = 1, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_dire_maul_hook_7488", ["track"] = { ["hash"] = "da03db80", ["text"] = "Латроникус Лунное Копье ждёт сеть Лефтендрис. Эльфийка крови выкачивает из этих руин отравленную магию, и ищут её у сатиров, в Квартале Криводревов.", ["duration"] = 12, ["cues"] = { { 0, "Латроникус Лунное Копьё ждёт сеть Лефтендрис." }, { 3.65, "Эльфийка крови выкачивает из этих руин отравленную магию, и ищут её у сатиров, в Квартале Криводревов." } } } }, { ["q"] = 7489, ["prio"] = 2, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_dire_maul_hook_7489", ["track"] = { ["hash"] = "38e83c33", ["text"] = "Тало Терновое Копыто ждёт сеть Лефтендрис. Эльфийка крови копит отравленную магию этих руин против своих врагов, и Орда хочет её остановить раньше, чем она закончит.", ["duration"] = 13.5, ["cues"] = { { 0, "Тало Терновое Копыто ждёт сеть Лефтендрис." }, { 3.46, "Эльфийка крови копит отравленную магию этих руин против своих врагов, и Орда хочет её остановить раньше, чем она закончит." } } } }, { ["q"] = 7482, ["prio"] = 3, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_dire_maul_hook_7482", ["track"] = { ["hash"] = "42dc017f", ["text"] = "Школяр Рунный Шип ищет мастера Кариэля Винтхалуса, который бежал сюда с древними эльфийскими артефактами. Живой он или мёртвый, его знания нужно найти.", ["duration"] = 12.2, ["cues"] = { { 0, "Школяр Рунный Шип ищет мастера Кариэля Винтхалуса, который бежал сюда с древними эльфийскими артефактами." }, { 8.55, "Живой он или мёртвый, его знания нужно найти." } } } }, { ["q"] = 7481, ["prio"] = 4, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_dire_maul_hook_7481", ["track"] = { ["hash"] = "7dfaf515", ["text"] = "Ведун Королуск ищет мастера Кариэля Винтхалуса, который бежал сюда с древними эльфийскими артефактами. Живой он или мёртвый, его знания нужно найти.", ["duration"] = 11.8, ["cues"] = { { 0, "Ведун Королуск ищет мастера Кариэля Винтхалуса, который бежал сюда с древними эльфийскими артефактами." }, { 8.26, "Живой он или мёртвый, его знания нужно найти." } } } }, { ["q"] = 5518, ["prio"] = 5, ["k"] = "hook", ["trig"] = "prologHook", ["id"] = "dm_dire_maul_hook_5518", ["track"] = { ["hash"] = "0ec7df9a", ["text"] = "Пленный гоблин из Гордока обещал сшить вам личину огра — такую, что обманет даже капитана Давигрома. Только носить её придётся быстро: дольше десяти минут она не продержится.", ["duration"] = 13.4, ["cues"] = { { 0, "Пленный гоблин из Гордока обещал сшить вам личину огра — такую, что обманет даже капитана Давигрома." }, { 7.85, "Только носить её придётся быстро: дольше десяти минут она не продержится." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_dire_maul_pusillin_pull", ["enc"] = 2792, ["track"] = { ["hash"] = "0df2f8d1", ["text"] = "Бес, который всю дорогу дразнил вас и удирал, вдруг раздувается вдвое и зовёт подмогу — четырёх огненных бесят. Пузиллин шутник, но шутки у него жгучие: пока на нём эта странная сила, ваши же заклинания могут прилететь обратно.", ["duration"] = 19, ["cues"] = { { 0, "Бес, который всю дорогу дразнил вас и удирал, вдруг раздувается вдвое и зовёт подмогу — четырёх огненных бесят." }, { 9.22, "Пузиллин шутник, но шутки у него жгучие: пока на нём эта странная сила, ваши же заклинания могут прилететь обратно." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_dire_maul_pusillin", ["enc"] = 2792, ["track"] = { ["hash"] = "c94812ae", ["text"] = "Пузиллин хнычет и затихает, а из его лап выпадает ключ. Серповидный ключ когда-то открывал чертоги Эльдре'Таласа, и бес таскал его, как игрушку. Теперь этот ключ отопрёт для вас двери на запад и на север. Игры кончились.", ["duration"] = 19.6, ["cues"] = { { 0, "Пузиллин хнычет и затихает, а из его лап выпадает ключ." }, { 5, "Серповидный ключ когда-то открывал чертоги Эльдре'Таласа, и бес таскал его, как игрушку." }, { 12.96, "Теперь этот ключ отопрёт для вас двери на запад и на север." }, { 18.29, "Игры кончились." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_dire_maul_lethtendris_pull", ["enc"] = 345, ["track"] = { ["hash"] = "136ea52a", ["text"] = "Эльфийка крови поднимает руки, и между пальцами сгущается тьма, а рядом с визгом скачет её бес Пимгиб. Лефтендрис пришла сюда за силой и делиться ею не намерена. Только оборванное на полуслове заклинание рассыплется, не долетев.", ["duration"] = 18.8, ["cues"] = { { 0, "Эльфийка крови поднимает руки, и между пальцами сгущается тьма, а рядом с визгом скачет её бес Пимгиб." }, { 8.54, "Лефтендрис пришла сюда за силой и делиться ею не намерена." }, { 13.49, "Только оборванное на полуслове заклинание рассыплется, не долетев." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_dire_maul_lethtendris", ["enc"] = 345, ["track"] = { ["hash"] = "3e94bb78", ["text"] = "Лефтендрис падает, и сеть, что тянула из руин отравленную магию, гаснет. Эльфийка крови бросила вызов собственным собратьям, лишь бы копить эту силу против своих врагов. Магия Эльдре'Таласа губит тех, кто к ней жаден. Так было и десять тысяч лет назад.", ["duration"] = 20.6, ["cues"] = { { 0, "Лефтендрис падает, и сеть, что тянула из руин отравленную магию, гаснет." }, { 5.92, "Эльфийка крови бросила вызов собственным собратьям, лишь бы копить эту силу против своих врагов." }, { 13.98, "Магия Эльдре'Таласа губит тех, кто к ней жаден." }, { 17.83, "Так было и десять тысяч лет назад." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_dire_maul_hydrospawn_pull", ["enc"] = 344, ["track"] = { ["hash"] = "e21c6325", ["text"] = "Вода в бассейне встаёт стеной и отращивает руки. Гидротварь — элементаль воды, что завёлся в восточном крыле, и чужаков он не терпит. От него отрываются мелкие водяные духи, и о каждом забытом из них вы ещё вспомните.", ["duration"] = 17.4, ["cues"] = { { 0, "Вода в бассейне встаёт стеной и отращивает руки." }, { 3.99, "Гидротварь — элементаль воды, что завёлся в восточном крыле, и чужаков он не терпит." }, { 10.79, "От него отрываются мелкие водяные духи, и о каждом забытом из них вы ещё вспомните." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_dire_maul_hydrospawn", ["enc"] = 344, ["track"] = { ["hash"] = "ab0dce6c", ["text"] = "Гидротварь рассыпается брызгами, и вода в бассейне затихает. В городе, где тысячи лет правила магия, даже вода успела стать чем-то иным. Сатиры приносили жертвы, высокорожденные копили силу, а вода текла сквозь эти камни и впитывала всё. Теперь это снова просто вода.", ["duration"] = 23, ["cues"] = { { 0, "Гидротварь рассыпается брызгами, и вода в бассейне затихает." }, { 5.2, "В городе, где тысячи лет правила магия, даже вода успела стать чем-то иным." }, { 11.79, "Сатиры приносили жертвы, высокорождённые копили силу, а вода текла сквозь эти камни и впитывала всё." }, { 20.4, "Теперь это снова просто вода." } } } }, { ["role"] = "main", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_dire_maul_zevrim_pull", ["enc"] = 343, ["track"] = { ["hash"] = "752cf98d", ["text"] = "Сатир смеётся и указывает когтем на алтарь за спиной. Зеврим Терновое Копыто не столько дерётся, сколько приносит жертвы, и на алтарь отправится кто-то из вас. Кого он выберет, тот почувствует, как жизнь капля за каплей утекает в камень.", ["duration"] = 19.3, ["cues"] = { { 0, "Сатир смеётся и указывает когтем на алтарь за спиной." }, { 4.41, "Зеврим Терновое Копыто не столько дерётся, сколько приносит жертвы, и на алтарь отправится кто-то из вас." }, { 13.08, "Кого он выберет, тот почувствует, как жизнь капля за каплей утекает в камень." } } } }, { ["role"] = "main", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_dire_maul_zevrim", ["enc"] = 343, ["track"] = { ["hash"] = "cce4b8ca", ["text"] = "Зеврим падает у собственного алтаря, и кровь на камне впервые за долгое время стынет без новой. Сатир кормил свой алтарь чужими жизнями и звал это силой. Теперь Древень Железная Кора может открыть вам дорогу дальше.", ["duration"] = 18.5, ["cues"] = { { 0, "Зеврим падает у собственного алтаря, и кровь на камне впервые за долгое время стынет без новой." }, { 8.2, "Сатир кормил свой алтарь чужими жизнями и звал это силой." }, { 13.22, "Теперь Древень Железная Кора может открыть вам дорогу дальше." } } } }, { ["q"] = 7441, ["follows"] = "dm_dire_maul_zevrim", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_dire_maul_hook_7441_res", ["track"] = { ["hash"] = "67c9b67f", ["text"] = "Книгу заклинаний Аж'Тордина бес Пузиллин таскает при себе. Когда она окажется у вас, старейший ждёт её в Фераласе.", ["duration"] = 9.3, ["cues"] = { { 0, "Книгу заклинаний Аж'Тордина бес Пузиллин таскает при себе." }, { 4.87, "Когда она окажется у вас, старейший ждёт её в Фераласе." } } } }, { ["q"] = 7488, ["follows"] = "dm_dire_maul_zevrim", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_dire_maul_hook_7488_res", ["track"] = { ["hash"] = "9232e502", ["text"] = "Сеть Лефтендрис ищите у сатиров, в Квартале Криводревов. Латроникус Лунное Копье ждёт её в Крепости Оперенной Луны.", ["duration"] = 9.4, ["cues"] = { { 0, "Сеть Лефтендрис ищите у сатиров, в Квартале Криводревов." }, { 4.72, "Латроникус Лунное Копьё ждёт её в Крепости Оперённой Луны." } } } }, { ["q"] = 7489, ["follows"] = "dm_dire_maul_zevrim", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_dire_maul_hook_7489_res", ["track"] = { ["hash"] = "0707b035", ["text"] = "Сеть Лефтендрис ищите у сатиров, в Квартале Криводревов. Тало Терновое Копыто ждёт её в Лагере Мохаче.", ["duration"] = 8.5, ["cues"] = { { 0, "Сеть Лефтендрис ищите у сатиров, в Квартале Криводревов." }, { 4.74, "Тало Терновое Копыто ждёт её в Лагере Мохаче." } } } }, { ["q"] = 7463, ["follows"] = "dm_dire_maul_zevrim", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_dire_maul_hook_7463", ["track"] = { ["hash"] = "f2acf150", ["text"] = "Сказитель Лидрос ждёт частицу сущности Гидротвари — элементаля воды, что поселился в этом крыле. Добудете её — научит вас одной полезной штучке.", ["duration"] = 11.6, ["cues"] = { { 0, "Сказитель Лидрос ждёт частицу сущности Гидротвари — элементаля воды, что поселился в этом крыле." }, { 7.86, "Добудете её — научит вас одной полезной штучке." } } } }, { ["role"] = "wing_final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_dire_maul_alzzin_pull", ["enc"] = 346, ["track"] = { ["hash"] = "f1dd46ff", ["text"] = "Сатир, что правит восточным крылом, скалится из-за порченой лозы, которой оплёл весь квартал. Алззин Перевертень недаром носит своё прозвище: обман он любит больше, чем сталь, и подвох у него всегда припасён.", ["duration"] = 17, ["cues"] = { { 0, "Сатир, что правит восточным крылом, скалится из-за порченой лозы, которой оплёл весь квартал." }, { 7.74, "Алззин Перевертень недаром носит своё прозвище: обман он любит больше, чем сталь, и подвох у него всегда припасён." } } } }, { ["role"] = "wing_final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_dire_maul_alzzin", ["enc"] = 346, ["track"] = { ["hash"] = "4bf2e6a2", ["text"] = "Алззин Перевертень падает, и его иллюзии лопаются одна за другой. Когда-то в святилище Элдретарра рос Плод Изобилия, и весь город цвёл от его силы. Сатир превратил его в сквернит — лозу Скверны, что опутала весь квартал. Без хозяина она больше не будет расти. Восточное крыло свободно.", ["duration"] = 24.2, ["cues"] = { { 0, "Алззин Перевертень падает, и его иллюзии лопаются одна за другой." }, { 5.7, "Когда-то в святилище Элдретарра рос Плод Изобилия, и весь город цвёл от его силы." }, { 12.54, "Сатир превратил его в сквернит — лозу Скверны, что опутала весь квартал." }, { 18.78, "Без хозяина она больше не будет расти." }, { 22.17, "Восточное крыло свободно." } } } }, { ["q"] = 5526, ["follows"] = "dm_dire_maul_alzzin", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_dire_maul_hook_5526", ["track"] = { ["hash"] = "221655ed", ["text"] = "Осколки сквернита — там, где стоял Алззин. Закройте их в реликварий: Рабин Сатурна ждёт в Лунной поляне.", ["duration"] = 8.3, ["cues"] = { { 0, "Осколки сквернита — там, где стоял Алззин." }, { 3.46, "Закройте их в реликварий: Рабин Сатурна ждёт в Лунной поляне." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_dire_maul_tendris_pull", ["enc"] = 350, ["track"] = { ["hash"] = "4e28ac62", ["text"] = "Земля вздрагивает: древень распрямляется во весь рост, и кора его скрипит от порчи. Тендрис Криводрев стережёт эти сады и не отличает гостей от врагов. Кто стоит у его корней, рискует оказаться под ними.", ["duration"] = 17.6, ["cues"] = { { 0, "Земля вздрагивает: древень распрямляется во весь рост, и кора его скрипит от порчи." }, { 7.26, "Тендрис Криводрев стережёт эти сады и не отличает гостей от врагов." }, { 13.18, "Кто стоит у его корней, рискует оказаться под ними." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_dire_maul_tendris", ["enc"] = 350, ["track"] = { ["hash"] = "82ffb935", ["text"] = "Тендрис Криводрев оседает грудой мёртвой коры, и в саду становится тихо. Порча этих руин пропитала его насквозь, но он стоял на страже до последнего. Сады Эльдре'Таласа потеряли своего последнего садовника.", ["duration"] = 17.8, ["cues"] = { { 0, "Тендрис Криводрев оседает грудой мёртвой коры, и в саду становится тихо." }, { 6.31, "Порча этих руин пропитала его насквозь, но он стоял на страже до последнего." }, { 13.01, "Сады Эльдре'Таласа потеряли своего последнего садовника." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_dire_maul_illyanna_pull", ["enc"] = 347, ["track"] = { ["hash"] = "623d6e83", ["text"] = "Свистят стрелы, а следом с рёвом бросается медведица Ферра. Призрак Иллианы Вороньей Ольхи не утратил ни меткости, ни зверя. Её залп накрывает целый круг, а одна стрела находит сразу нескольких, если те стоят плечом к плечу.", ["duration"] = 17.7, ["cues"] = { { 0, "Свистят стрелы, а следом с рёвом бросается медведица Ферра." }, { 4.73, "Призрак Иллианы Вороньей Ольхи не утратил ни меткости, ни зверя." }, { 9.88, "Её залп накрывает целый круг, а одна стрела находит сразу нескольких, если те стоят плечом к плечу." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_dire_maul_illyanna", ["enc"] = 347, ["track"] = { ["hash"] = "359a443d", ["text"] = "Иллиана Воронья Ольха падает рядом со своей медведицей — на этот раз насовсем. Смерть не освободила охотницу: она так и осталась в этих залах, на страже чужого бессмертия. Теперь её служба окончена.", ["duration"] = 17.4, ["cues"] = { { 0, "Иллиана Воронья Ольха падает рядом со своей медведицей — на этот раз насовсем." }, { 7.04, "Смерть не освободила охотницу: она так и осталась в этих залах, на страже чужого бессмертия." }, { 15.2, "Теперь её служба окончена." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_dire_maul_kalendris_pull", ["enc"] = 348, ["track"] = { ["hash"] = "f2a107f4", ["text"] = "Призрак в одеждах магистра поднимает руку, и в висках начинает стучать чужая воля. Магистр Календрис всё ещё стережёт эти залы, и кто-то из вас может на миг перестать быть вашим.", ["duration"] = 14.5, ["cues"] = { { 0, "Призрак в одеждах магистра поднимает руку, и в висках начинает стучать чужая воля." }, { 6.91, "Магистр Календрис всё ещё стережёт эти залы, и кто-то из вас может на миг перестать быть вашим." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_dire_maul_kalendris", ["enc"] = 348, ["track"] = { ["hash"] = "4dd3c2ad", ["text"] = "Магистр Календрис рассеивается, и холод в зале отступает. Высокорожденные Эльдре'Таласа платили за бессмертие дорого, и не всем после смерти достался покой. Этот, по крайней мере, его получил.", ["duration"] = 15.9, ["cues"] = { { 0, "Магистр Календрис рассеивается, и холод в зале отступает." }, { 4.85, "Высокорождённые Эльдре'Таласа платили за бессмертие дорого, и не всем после смерти достался покой." }, { 12.97, "Этот, по крайней мере, его получил." } } } }, { ["role"] = "rare", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_dire_maul_tsuzee_pull", ["enc"] = 2794, ["track"] = { ["hash"] = "4e9cb7f5", ["text"] = "Из пустоты за спиной выступает тень с клинками. Цу'зи появляется не каждой группе — сегодня удача на её стороне. Она бьёт туда, куда не смотрят, и горе тому, кто повернётся к ней спиной.", ["duration"] = 15.3, ["cues"] = { { 0, "Из пустоты за спиной выступает тень с клинками." }, { 3.92, "Цу'зи появляется не каждой группе — сегодня удача на её стороне." }, { 9.34, "Она бьёт туда, куда не смотрят, и горе тому, кто повернётся к ней спиной." } } } }, { ["role"] = "rare", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_dire_maul_tsuzee", ["enc"] = 2794, ["track"] = { ["hash"] = "ba8c9e9b", ["text"] = "Цу'зи тает в воздухе, будто её и не было. Кем она была при жизни, в этих залах уже никто не скажет: десять тысяч лет Эльдре'Талас копил своих мертвецов, и не все они служат принцу. Некоторые до сих пор бродят по коридорам — и не всегда их видно.", ["duration"] = 19.8, ["cues"] = { { 0, "Цу'зи тает в воздухе, будто её и не было." }, { 3.44, "Кем она была при жизни, в этих залах уже никто не скажет: десять тысяч лет Эльдре'Талас копил своих мертвецов, и не все они служат принцу." }, { 14.87, "Некоторые до сих пор бродят по коридорам — и не всегда их видно." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_dire_maul_immolthar_pull", ["enc"] = 349, ["track"] = { ["hash"] = "04b6bc9a", ["text"] = "Силовое поле гаснет, и узник впервые за тысячелетия может двинуться. Бессмер'тер долго смотрел, как из него пьют силу, и теперь голоден сам. По залу открываются его глаза, а кого он выдернет к себе, тот окажется с чудовищем один на один.", ["duration"] = 21.2, ["cues"] = { { 0, "Силовое поле гаснет, и узник впервые за тысячелетия может двинуться." }, { 6.23, "Бессмер'тер долго смотрел, как из него пьют силу, и теперь голоден сам." }, { 12.62, "По залу открываются его глаза, а кого он выдернет к себе, тот окажется с чудовищем один на один." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_dire_maul_immolthar", ["enc"] = 349, ["track"] = { ["hash"] = "a331048e", ["text"] = "Бессмер'тер падает, и тяжесть, давившая на зал, уходит. Шен'дралар поймали этого демона, когда лишились Источника Вечности, и тысячи лет пили его силу, чтобы не стареть. Демон, которого держали ради чужого бессмертия, умер первым. Те, кто жил за его счёт, почувствуют это следующими.", ["duration"] = 25, ["cues"] = { { 0, "Бессмер'тер падает, и тяжесть, давившая на зал, уходит." }, { 4.88, "Шен'дралар поймали этого демона, когда лишились Источника Вечности, и тысячи лет пили его силу, чтобы не стареть." }, { 15.12, "Демон, которого держали ради чужого бессмертия, умер первым." }, { 20.64, "Те, кто жил за его счёт, почувствуют это следующими." } } } }, { ["role"] = "wing_final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_dire_maul_tortheldrin_pull", ["enc"] = 361, ["track"] = { ["hash"] = "e8e5aec2", ["text"] = "Принц Тортелдрин, владыка западных залов и последних Шен'дралар, обнажает клинки: чужаки нарушили покой Эльдре'Таласа. Он и маг, и воин разом: клинки вихрем режут всех, кто рядом, а сгусток чистой магии отшвыривает того, в кого попал.", ["duration"] = 20.6, ["cues"] = { { 0, "Принц Тортелдрин, владыка западных залов и последних Шен'дралар, обнажает клинки: чужаки нарушили покой Эльдре'Таласа." }, { 10.44, "Он и маг, и воин разом: клинки вихрем режут всех, кто рядом, а сгусток чистой магии отшвыривает того, в кого попал." } } } }, { ["role"] = "wing_final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_dire_maul_tortheldrin", ["enc"] = 361, ["track"] = { ["hash"] = "b75910a8", ["text"] = "Принц Тортелдрин падает среди книг, которые его народ берёг десять тысяч лет. Он спас город от Раскола — и сам же его погубил: когда сила демона начала иссякать, принц стал убивать своих, чтобы забрать их долю. Последние Шен'дралар больше ему не служат. Читальня Эльдре'Таласа снова открыта для тех, кто пришёл за знанием.", ["duration"] = 26.1, ["cues"] = { { 0, "Принц Тортелдрин падает среди книг, которые его народ берёг десять тысяч лет." }, { 6.36, "Он спас город от Раскола — и сам же его погубил: когда сила демона начала иссякать, принц стал убивать своих, чтобы забрать их долю." }, { 17.22, "Последние Шен'дралар больше ему не служат." }, { 20.77, "Читальня Эльдре'Таласа снова открыта для тех, кто пришёл за знанием." } } } }, { ["q"] = 7461, ["follows"] = "dm_dire_maul_tortheldrin", ["k"] = "hook", ["trig"] = "follows", ["id"] = "dm_dire_maul_hook_7461", ["track"] = { ["hash"] = "53ed8038", ["text"] = "Прародительница Шен'дралар просила о двух смертях — Бессмер'тера и принца. Когда свершатся обе, возвращайтесь к ней: духи этого города наконец смогут упокоиться.", ["duration"] = 13.5, ["cues"] = { { 0, "Прародительница Шен'дралар просила о двух смертях — Бессмер'тера и принца." }, { 6.22, "Когда свершатся обе, возвращайтесь к ней: духи этого города наконец смогут упокоиться." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_dire_maul_helnurath_pull", ["enc"] = 2793, ["track"] = { ["hash"] = "919dc57f", ["text"] = "Ритуал завершён, и из разрыва в мир шагает Лорд Хел'нурат, владыка Зорота, — узнать, кто посмел увести его скакуна. Демон не прощает воров, а скакун ещё не повержен — сражаться придётся с обоими.", ["duration"] = 17.5, ["cues"] = { { 0, "Ритуал завершён, и из разрыва в мир шагает Лорд Хел'нурат, владыка Зорота, — узнать, кто посмел увести его скакуна." }, { 10.49, "Демон не прощает воров, а скакун ещё не повержен — сражаться придётся с обоими." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_dire_maul_helnurath", ["enc"] = 2793, ["track"] = { ["hash"] = "4edd4cbb", ["text"] = "Лорд Хел'нурат падает, и разрыв в Зорот гаснет. Хозяин конюшен Зорота пришёл вернуть своё, а нашёл смерть среди руин чужого города. Его скакун остался без хозяина. Теперь подчините дух коня погибели — и тот, кто прошёл ради него весь этот долгий путь, получит своё.", ["duration"] = 22.5, ["cues"] = { { 0, "Лорд Хел'нурат падает, и разрыв в Зорот гаснет." }, { 4.11, "Хозяин конюшен Зорота пришёл вернуть своё, а нашёл смерть среди руин чужого города." }, { 11.24, "Его скакун остался без хозяина." }, { 14.03, "Теперь подчините дух коня погибели — и тот, кто прошёл ради него весь этот долгий путь, получит своё." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_dire_maul_moldar_pull", ["enc"] = 362, ["track"] = { ["hash"] = "750dc9b4", ["text"] = "Огр-стражник ревёт и опускает щит, как таран. Мол'дар стережёт двери клана Гордок и чужаков не пропускает. Горе тому, кто окажется у него на пути: этот щит отшвыривает так, что ноги не касаются пола.", ["duration"] = 16.8, ["cues"] = { { 0, "Огр-стражник ревёт и опускает щит, как таран." }, { 3.79, "Мол'дар стережёт двери клана Гордок и чужаков не пропускает." }, { 8.98, "Горе тому, кто окажется у него на пути: этот щит отшвыривает так, что ноги не касаются пола." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_dire_maul_moldar", ["enc"] = 362, ["track"] = { ["hash"] = "9eaa5eed", ["text"] = "Мол'дар грохается на пол, и на его поясе звякает ключ. Огры Гордока не мастера по замкам, но двери у них крепкие, и ключ от внутренней двери теперь ваш. Мол'дар стерёг этот проход, как пёс свою миску. Без него дверь — уже не преграда.", ["duration"] = 18.3, ["cues"] = { { 0, "Мол'дар грохается на пол, и на его поясе звякает ключ." }, { 4.31, "Огры Гордока не мастера по замкам, но двери у них крепкие, и ключ от внутренней двери теперь ваш." }, { 12, "Мол'дар стерёг этот проход, как пёс свою миску." }, { 15.81, "Без него дверь — уже не преграда." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_dire_maul_kreeg_pull", ["enc"] = 363, ["track"] = { ["hash"] = "c0bcbbed", ["text"] = "Топотун Криг продирает глаза, и первое, что он видит, — вас рядом с его кружкой. Это ошибка. Пьяный огр крутится волчком и плюётся таким пойлом, что после него в цель не попасть. Кто стоит близко — берегитесь его вихря.", ["duration"] = 17.8, ["cues"] = { { 0, "Топотун Криг продирает глаза, и первое, что он видит, — вас рядом с его кружкой." }, { 6.56, "Это ошибка." }, { 7.59, "Пьяный огр крутится волчком и плюётся таким пойлом, что после него в цель не попасть." }, { 14.52, "Кто стоит близко — берегитесь его вихря." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_dire_maul_kreeg", ["enc"] = 363, ["track"] = { ["hash"] = "7b4da21c", ["text"] = "Криг валится на спину, и кружка наконец выпадает из его лапы. Он был самым весёлым из стражей Гордока — пока никто не трогал его выпивку. Огрское пойло растекается по камням, и даже вам его немного жаль.", ["duration"] = 16, ["cues"] = { { 0, "Криг валится на спину, и кружка наконец выпадает из его лапы." }, { 4.93, "Он был самым весёлым из стражей Гордока — пока никто не трогал его выпивку." }, { 10.93, "Огрское пойло растекается по камням, и даже вам его немного жаль." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_dire_maul_fengus_pull", ["enc"] = 364, ["track"] = { ["hash"] = "d7e7974d", ["text"] = "Фенгус обходит эти залы день и ночь и бросается на всякого, кто сюда сунется. Огр бьёт так, что отлетаешь к стене, а разозлившись, бьёт ещё чаще.", ["duration"] = 12.2, ["cues"] = { { 0, "Фенгус обходит эти залы день и ночь и бросается на всякого, кто сюда сунется." }, { 6.75, "Огр бьёт так, что отлетаешь к стене, а разозлившись, бьёт ещё чаще." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_dire_maul_fengus", ["enc"] = 364, ["track"] = { ["hash"] = "e5d5f548", ["text"] = "Фенгус падает, и в зале становится непривычно тихо. В сундуке, который он стерёг, лежит ключ от внутреннего двора клана Гордок. Огры никогда не прятали ничего надёжнее, чем под носом у самого бдительного из своих.", ["duration"] = 17.2, ["cues"] = { { 0, "Фенгус падает, и в зале становится непривычно тихо." }, { 4.28, "В сундуке, который он стерёг, лежит ключ от внутреннего двора клана Гордок." }, { 10.41, "Огры никогда не прятали ничего надёжнее, чем под носом у самого бдительного из своих." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_dire_maul_slipkik_pull", ["enc"] = 365, ["track"] = { ["hash"] = "015b9d7e", ["text"] = "Слип'кик хитрее прочих стражей, но ловушку рядом с собой так и не удосужился починить. Огр бросается на кого-то одного со щитом, как таран, и отшвыривает прочь, словно тряпичную куклу.", ["duration"] = 14.2, ["cues"] = { { 0, "Слип'кик хитрее прочих стражей, но ловушку рядом с собой так и не удосужился починить." }, { 6.77, "Огр бросается на кого-то одного со щитом, как таран, и отшвыривает прочь, словно тряпичную куклу." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_dire_maul_slipkik", ["enc"] = 365, ["track"] = { ["hash"] = "2f03572a", ["text"] = "Слип'кик падает рядом со своей сломанной ловушкой. Хитрость его не спасла, а ловушка так и не сработала. Удобного случая не бывает. Бывает только ваш.", ["duration"] = 12.2, ["cues"] = { { 0, "Слип'кик падает рядом со своей сломанной ловушкой." }, { 4.23, "Хитрость его не спасла, а ловушка так и не сработала." }, { 8.61, "Удобного случая не бывает." }, { 10.84, "Бывает только ваш." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_dire_maul_kromcrush_pull", ["enc"] = 366, ["track"] = { ["hash"] = "d401e019", ["text"] = "Капитан Давигром ревёт так, что дрожат своды: никто не смеет входить к королю без спросу. Он командует отборной стражей Гордока и, когда станет туго, позовёт её на помощь. А после его тяжёлого удара раны плохо принимают лечение.", ["duration"] = 17.8, ["cues"] = { { 0, "Капитан Давигром ревёт так, что дрожат своды: никто не смеет входить к королю без спросу." }, { 7.01, "Он командует отборной стражей Гордока и, когда станет туго, позовёт её на помощь." }, { 13.38, "А после его тяжёлого удара раны плохо принимают лечение." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_dire_maul_kromcrush", ["enc"] = 366, ["track"] = { ["hash"] = "c9cec7b7", ["text"] = "Давигром падает поперёк прохода, который сторожил. Капитан не прощал оскорблений королю и не терпел чужаков у трона. Отборная стража Гордока осталась без командира, а проход к трону — без сторожа.", ["duration"] = 15.7, ["cues"] = { { 0, "Давигром падает поперёк прохода, который сторожил." }, { 4.09, "Капитан не прощал оскорблений королю и не терпел чужаков у трона." }, { 9.41, "Отборная стража Гордока осталась без командира, а проход к трону — без сторожа." } } } }, { ["role"] = "side", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_dire_maul_chorush_pull", ["enc"] = 367, ["track"] = { ["hash"] = "7746f040", ["text"] = "Двухголовый огр-маг у трона ни во что не вмешивается — пока не трогают его короля. Чо'Раш Наблюдатель лечит своего господина и бьёт чарами тех, кто мешает. Пока он колдует, короля не свалить.", ["duration"] = 15.5, ["cues"] = { { 0, "Двухголовый огр-маг у трона ни во что не вмешивается — пока не трогают его короля." }, { 6.73, "Чо'Раш Наблюдатель лечит своего господина и бьёт чарами тех, кто мешает." }, { 12.64, "Пока он колдует, короля не свалить." } } } }, { ["role"] = "side", ["k"] = "res", ["trig"] = "kill", ["id"] = "dm_dire_maul_chorush", ["enc"] = 367, ["track"] = { ["hash"] = "c110d5ad", ["text"] = "Чо'Раш падает, и обе его головы умолкают разом. Наблюдатель привык смотреть со стороны, но этого исхода не разглядела ни одна из его голов.", ["duration"] = 11.4, ["cues"] = { { 0, "Чо'Раш падает, и обе его головы умолкают разом." }, { 4.03, "Наблюдатель привык смотреть со стороны, но этого исхода не разглядела ни одна из его голов." } } } }, { ["role"] = "wing_final", ["k"] = "pull", ["trig"] = "start", ["id"] = "dm_dire_maul_gordok_pull", ["enc"] = 368, ["track"] = { ["hash"] = "1ed34757", ["text"] = "Король Гордок, владыка огров северного крыла, поднимается с трона, и огры вокруг расступаются. Закон Гордока прост: королём становится тот, кто убил короля. Удар у него тяжёлый, а топот сбивает с ног всех, кто рядом.", ["duration"] = 18.9, ["cues"] = { { 0, "Король Гордок, владыка огров северного крыла, поднимается с трона, и огры вокруг расступаются." }, { 8.48, "Закон Гордока прост: королём становится тот, кто убил короля." }, { 13.84, "Удар у него тяжёлый, а топот сбивает с ног всех, кто рядом." } } } }, { ["anyKill"] = { 362, 363, 364, 365, 366, 367 }, ["role"] = "wing_final", ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_dire_maul_gordok", ["enc"] = 368, ["track"] = { ["hash"] = "3494bb64", ["text"] = "Король Гордок падает, и в зале повисает тишина. Потом кто-то из огров первым преклоняет колено — перед вами. Закон есть закон: кто убил короля, тот и король. Теперь вы — Король клана Гордок, и, пока вы в этих стенах, огры будут звать вас боссом. Правда, стоит королю покинуть эти стены, они выберут нового.", ["duration"] = 26.2, ["cues"] = { { 0, "Король Гордок падает, и в зале повисает тишина." }, { 4.13, "Потом кто-то из огров первым преклоняет колено — перед вами." }, { 9.41, "Закон есть закон: кто убил короля, тот и король." }, { 13.54, "Теперь вы — Король клана Гордок, и, пока вы в этих стенах, огры будут звать вас боссом." }, { 21.04, "Правда, стоит королю покинуть эти стены, они выберут нового." } } } }, { ["noKills"] = { 362, 363, 364, 365, 366, 367 }, ["k"] = "fin", ["trig"] = "kill", ["id"] = "dm_dire_maul_gordok_tribute", ["role"] = "wing_final", ["enc"] = 368, ["track"] = { ["hash"] = "a53d8011", ["text"] = "Король Гордок падает, а его стража, живая и целая, не хватается за оружие. Вы прошли мимо неё хитростью, и огры это уважают. Стражи кланяются новому королю, Королю клана Гордок, а клан несёт ему дань — лучшее, что сумел собрать. Закон Гордока соблюдён до последней буквы.", ["duration"] = 23.5, ["cues"] = { { 0, "Король Гордок падает, а его стража, живая и целая, не хватается за оружие." }, { 6.59, "Вы прошли мимо неё хитростью, и огры это уважают." }, { 10.98, "Стражи кланяются новому королю, Королю клана Гордок, а клан несёт ему дань — лучшее, что сумел собрать." }, { 19.99, "Закон Гордока соблюдён до последней буквы." } } } } }, ["bosses"] = { { ["id"] = 2792, ["npcs"] = { 14354 }, ["name"] = "pusillin", ["required"] = nil, ["token"] = "pusillin", ["names335"] = { "Pusillin" } }, { ["id"] = 345, ["npcs"] = { 14327 }, ["name"] = "Lethtendris", ["required"] = nil, ["token"] = "lethtendris", ["names335"] = { "Lethtendris" } }, { ["id"] = 344, ["npcs"] = { 13280 }, ["name"] = "Hydrospawn", ["required"] = nil, ["token"] = "hydrospawn", ["names335"] = { "Hydrospawn" } }, { ["id"] = 343, ["npcs"] = { 11490 }, ["name"] = "Zevrim Thornhoof", ["required"] = nil, ["token"] = "zevrim", ["names335"] = { "Zevrim Thornhoof" } }, { ["id"] = 346, ["npcs"] = { 11492 }, ["name"] = "Alzzin the Wildshaper", ["required"] = nil, ["token"] = "alzzin", ["names335"] = { "Alzzin the Wildshaper" } }, { ["id"] = 350, ["npcs"] = { 11489 }, ["name"] = "Tendris Warpwood", ["required"] = nil, ["token"] = "tendris", ["names335"] = { "Tendris Warpwood" } }, { ["id"] = 347, ["npcs"] = { 11488 }, ["name"] = "Illyanna Ravenoak", ["required"] = nil, ["token"] = "illyanna", ["names335"] = { "Illyanna Ravenoak" } }, { ["id"] = 348, ["npcs"] = { 11487 }, ["name"] = "Magister Kalendris", ["required"] = nil, ["token"] = "kalendris", ["names335"] = { "Magister Kalendris" } }, { ["id"] = 2794, ["npcs"] = { 11467 }, ["name"] = "tsuzee", [